  str_homestory_800201001_14_dialog_content = "히이로 씨는 아주 강하니까... 딱히 고민 같은 건 안 하실 줄 알았거든요.",
  str_homestory_800201001_15_dialog_content = "칭찬으로 듣겠습니다.",
