  str_homestory_800201001_19_dialog_content = "최근 많은 사람들이 이곳으로 소원을 빌러\n온다고 들었습니다.",
  str_homestory_800201001_20_dialog_content = "저는 어쩌면 사람들이 소원을 비는 그 순간에,\n마음속 진정한 소망이 뚜렷해지는 것이\n아닐까 합니다.",
  str_homestory_800201001_21_dialog_content = "그러니 여기서 소원을 빈다면, 저도 스스로가\n무엇을 원하고 있는지 분명히 알 수 있을 것 같다는\n느낌이 듭니다.",
  str_homestory_800201001_22_dialog_content = "아... 이해했어요.",
  str_homestory_800201001_23_dialog_content = "「진정으로 이루고 싶은 일이 무엇인지 찾고 싶다」, 그런 느낌인 거죠?",
  str_homestory_800201001_24_dialog_content = "바로 보셨습니다.",
  str_homestory_800201001_25_dialog_content = "그럼... 혹시 이제 찾으셨나요?",
  str_homestory_800201001_26_dialog_content = "예.",
  str_homestory_800201001_27_dialog_content = "비록 아주 뚜렷한 형태는 아니지만...\n어느 정도 방향은 잡은 것 같습니다.",
  str_homestory_800201001_28_dialog_content = "그럼 지금까지는 방향도 없었다는 건가요?",
