  str_homestory_800201001_30_dialog_content = "하지만 주관적인 방향과 소망은 확실히 조금\n모호한 점이 있었습니다.",
  str_homestory_800201001_31_dialog_content = "그리고 지금은... 왜 사람들이 그토록 소원에\n열중하는지 알 것 같습니다.",
  str_homestory_800201001_32_dialog_content = "그렇군요...",
  str_homestory_800201001_33_dialog_content = "소원을 비는 건 히이로 씨처럼 강한 사람한테는 마음을 다잡는 방법도 될 수 있는 거군요...",
  str_homestory_800201001_34_dialog_content = "반면에 힘들게 살아가는 사람들에겐 경건한 부탁이라 할 수 있겠죠.",
