  str_homestory_802501001_6_dialog_content = "아, PlayerName, 때마침 잘 왔군!",
  str_homestory_802501001_7_dialog_content = "이 바람의 탑 밖에 있는 광장을 봐라...",
  str_homestory_802501001_8_dialog_content = "감동적인 연극 한 편을 상연하기에\n얼마나 적합한 장소란 말인가!",
  str_homestory_802501001_9_dialog_content = "PlayerName, 이런 아름다운 공간을\n낭비하는 건 죄악이다!",
  str_homestory_802501001_10_dialog_content = "부탁이다. 내가 이곳에서 천 년간 명작으로\n칭송될 작품을 상연할 수 있도록 해다오!",
  str_homestory_802501001_11_option_content = "(동의한다)",
