  str_homestory_802501001_13_dialog_content = "어찌 그럴 수 있겠나!",
  str_homestory_802501001_14_dialog_content = "전차! 화염! 피로 물든 성배! 메탈!\n레코드판과 우퍼 스피커까지!",
  str_homestory_802501001_15_dialog_content = "내 아름다운 공연은 이 섬 구석구석에\n울려 퍼져야만 한다!",
