  str_homestory_802501001_17_dialog_content = "지금 폐라고 했나?\n설마 이곳 주민들은 예술을 감상할 줄\n모른단 말인가!",
  str_homestory_802501001_18_dialog_content = "그, 그럴 리가요... 아하하...",
  str_homestory_802501001_19_dialog_content = "사실 마이너한 장르는 원래 좋아하는 사람이 적기 마련이잖아요!",
  str_homestory_802501001_20_dialog_content = "그래도 고요한 밤에 감상하는 공연은 왠지 운치 있을 것 같긴 해요.",
  str_homestory_802501001_21_dialog_content = "그래서 말인데요, 카론 씨...",
  str_homestory_802501001_22_option_content = "(거절한다)",
  str_homestory_802501001_23_dialog_content = "어쩌면 좋단 말이냐...",
  str_homestory_802501001_24_dialog_content = "네 차가운 거절이 내 안에 잠자고 있던 예술혼을\n깨워버린 것이다!",
  str_homestory_802501001_25_dialog_content = "아... 영감이 떠오른다...\n갑자기 엄청난 영감이 고삐 풀린 망아지처럼\n미친 듯이 내 머릿속을 휘젓고 있다!",
  str_homestory_802501001_26_dialog_content = "소리 없는 아우성이란 무엇인가...\n그것은 예술, 통제를 벗어나기 위한 몸부림...",
  str_homestory_802501001_27_dialog_content = "바로 지금! 내 영혼의 목소리가 온 헤븐즈 밸리에\n울려 퍼지게 만드는 거다!",
  str_homestory_802501001_28_dialog_content = "(보아하니 거절해도 소용없겠네...)",
  str_homestory_802501001_29_dialog_content = "아니면... 다른 날에 하는 게 어떨까요?",
