  str_homestory_802501001_31_dialog_content = "훗... 갑자기 슬픔이 비수가 되어\n내 가슴을 후벼 파는군.",
  str_homestory_802501001_32_dialog_content = "아무래도 PlayerName 너마저 남을 무시하는\n재주를 배운 모양이로구나.",
  str_homestory_802501001_33_dialog_content = "그렇다면 너를 내 차기작인 「차가운 사람」의\n조연으로 발탁하는 것을 고려하도록 하지.",
  str_homestory_802501001_34_dialog_content = "......",
  str_homestory_810501001_0_dialog_content = "이브, 진짜 바쁜 모양이네!",
  str_homestory_810501001_1_dialog_content = "안녕, 조종사! 언제 왔어?<sprite=emo_aixin size=60 />",
  str_homestory_810501001_2_dialog_content = "조금 있다가 놀아줄게!\n지금은 뭘 골라야 할지 생각 중이거든...",
  str_homestory_810501001_3_dialog_content = "아, 그래! 난 신경 쓰지 마!",
  str_homestory_810501001_4_dialog_content = "근데 뭘 고르는 건데? 내가 좀 도와줄까?",
  str_homestory_810501001_5_dialog_content = "아냐, 아냐! 넌 항상 날 도와줬잖아! 오늘은 괜찮아!",
  str_homestory_810501001_6_dialog_content = "사실 이브가 지금 선물을 만들고 있거든...",
  str_homestory_810501001_7_dialog_content = "옷에 수놓을 꽃이랑 컵홀더를 무슨 색으로 하면\n좋을지 고민하고 있었어.",
  str_homestory_810501001_8_dialog_content = "꽃? 컵홀더?",
  str_homestory_810501001_9_dialog_content = "응!",
  str_homestory_810501001_10_dialog_content = "도엔한테 옷<sprite=emo_qunzi size=60 />을 선물하고 싶은데,\n옷에 새벽꽃이 있으면 예쁠 것 같아서...",
  str_homestory_810501001_11_dialog_content = "그리고 컵 홀더는... 너도 알잖아.\n우리 오빠가 항상 물통을 들고 다니는 거...",
  str_homestory_810501001_12_dialog_content = "그래서 오빠한테는 귀여운 컵홀더를 선물하고 싶어.",
  str_homestory_810501001_13_dialog_content = "헤헤... 조종사 네가 보기엔 어떤 것 같아?",
  str_homestory_810501001_14_dialog_content = "아주 좋아!",
  str_homestory_810501001_15_dialog_content = "정말 딱 좋은 선물 같아. 받는 사람도 분명히 기뻐할 거고.",
  str_homestory_810501001_16_dialog_content = "그래? 헤헤, 다행이다...",
  str_homestory_810501001_17_dialog_content = "그래서 말인데, 장식을 무슨 색으로 하면 좋을까?",
  str_homestory_810501001_18_dialog_content = "원래는 하얀 새벽꽃을 만들고 싶었는데,\n색이 화려하면 더 좋을 것 같기도 하고...",
  str_homestory_810501001_19_dialog_content = "컵홀더는 빨강이랑 검정 중에서 생각 중인데,\n오빠가 무슨 색을 더 좋아할까?",
  str_homestory_810501001_20_dialog_content = "으, 머리야. 도저히 모르겠어.",
  str_homestory_810501001_21_dialog_content = "으음...",
  str_homestory_810501001_22_dialog_content = "도엔한테 선물할 옷은 무슨 색이야?",
  str_homestory_810501001_23_dialog_content = "검은색!",
  str_homestory_810501001_24_dialog_content = "그럼 새벽꽃의 하얀색이 잘 어울리지 않을까?",
  str_homestory_810501001_25_dialog_content = "여기에 새벽꽃을 좀 입체적으로 만들어서 도엔이 감촉을\n느낄 수 있게 하면 더 좋을 것 같아. 어때?",
  str_homestory_810501001_26_dialog_content = "하얀색... 입체적으로...",
  str_homestory_810501001_27_dialog_content = "아... 정말 좋은 생각이야!",
  str_homestory_810501001_28_dialog_content = "도움이 됐다니 다행이네.",
  str_homestory_810501001_29_dialog_content = "그럼... 오빠의 컵홀더는 무슨 색으로 할까?\n또 좋은 아이디어 있어?",
  str_homestory_810501001_30_option_content = "있어.",
  str_homestory_810501001_31_dialog_content = "검정이랑 빨강 중에서 고민하는 거라면, 아예 두 색을 패턴으로 교차하는 건 어때?",
  str_homestory_810501001_32_dialog_content = "근데 말이지, 이브...",
  str_homestory_810501001_33_option_content = "잘 모르겠어.",
  str_homestory_810501001_34_dialog_content = "근데 솔직히 말해서...",
  str_homestory_810501001_35_dialog_content = "사메야마는 네가 무슨 선물을 주든지 다 기뻐할걸.",
  str_homestory_810501001_36_dialog_content = "설령 발에 차이는 나뭇잎이나 흙을 주워다 줘도\n보물처럼 끌어안고서 동네방네 떠벌릴 게 분명해.",
  str_homestory_810501001_37_dialog_content = "으음...",
  str_homestory_810501001_38_dialog_content = "맞아, 조종사 네 말도 일리가 있는 것 같아...",
  str_homestory_810501001_39_dialog_content = "그래, 결심했어!\n그럼 내가 좋아하는 색으로 고를래! 헤헤.",
  str_homestory_810501001_40_dialog_content = "응, 그게 좋을 것 같아.",
  str_homestory_810501001_41_dialog_content = "근데 이브... 도엔이랑 사메야마한테는 이렇게 신경을 쓰면서,\n왜 널 위해서는 아무것도 선물하지 않는 거야?",
  str_homestory_810501001_42_dialog_content = "응...? 미안해, 조종사. 무슨 말인지 잘 모르겠어.",
  str_homestory_810501001_43_dialog_content = "나한테도 뭘 준비해야 하는 거야?",
  str_homestory_810501001_44_dialog_content = "내 말은 그러니까...",
  str_homestory_810501001_45_dialog_content = "봐, 저번에 나더러 거름흙이랑 새벽꽃 씨앗을 구해 달라 한 것도\n다 도엔을 위해서였지?",
  str_homestory_810501001_46_dialog_content = "도엔이 즐겁게 꽃을 기를 수 있도록 말이야.",
  str_homestory_810501001_47_dialog_content = "그리고 바이스한테 레디젤 렌치에서 간식을 사다 달라 한 것도\n사메야마가 안주 없이 술만 마실까 그런 거잖아.",
  str_homestory_810501001_48_dialog_content = "아... 조종사 넌 다 알고 있었구나...",
  str_homestory_810501001_49_dialog_content = "네 말이 맞아...",
  str_homestory_810501001_50_dialog_content = "근데...",
  str_homestory_810501001_51_dialog_content = "넌 뭐 갖고 싶은 거 없어?",
  str_homestory_810501001_52_dialog_content = "음... 오빠랑 도엔한테 선물을 준비한 건\n두 사람이 여기서 즐겁게 지내길 바라니까\n그런 거야~",
  str_homestory_810501001_53_dialog_content = "그리고 이브는...\n두 사람이랑 같이 있는 것만으로 이미 즐거워.",
  str_homestory_810501001_54_dialog_content = "아, 그리고 조종사 너랑 바이스도!",
  str_homestory_810501001_55_dialog_content = "이렇게 모두 함께할 수 있어서 이브는 정말 행복해!",
  str_homestory_810501001_56_dialog_content = "그러니까... 이브는 딱히 뭐가 더 필요하진 않아.",
  str_homestory_810501001_57_dialog_content = "그...그렇구나.",
  str_homestory_810501001_58_dialog_content = "이브는 정말 자상하네...",
  str_homestory_810501001_59_dialog_content = "조종사 너도 자상해!",
  str_homestory_810501001_60_dialog_content = "흑... 흑흑...",
  str_homestory_810501001_61_dialog_content = "왜, 왜 그래?",
  str_homestory_810501001_62_dialog_content = "조종사, 갑자기 왜 우는 건데?",
  str_homestory_810501001_63_dialog_content = "흑흑... 나도 이브 같은 여동생이 있었으면 좋겠어...<sprite=emo_daku size=60 />",
  str_homestory_811201001_0_dialog_content = "스모키?!",
  str_homestory_811201001_1_dialog_content = "왜, 왜 그래...?",
  str_homestory_811201001_2_dialog_content = "왜 화가 잔뜩 난 건데?",
  str_homestory_811201001_3_dialog_content = "야, 조종사.",
  str_homestory_811201001_4_dialog_content = "이 가게에 물건이 너무 없다고 생각하지 않아?<sprite=emo_shengqi size=60 />",
  str_homestory_811201001_5_dialog_content = "아! 그거 때문에 화가 난 거였어?",
  str_homestory_811201001_6_dialog_content = "어떤 물건이 부족한 것 같은데? 말해 줄 수 있어?",
  str_homestory_811201001_7_dialog_content = "진짜로 말하라고?",
  str_homestory_811201001_8_dialog_content = "응! 괜찮으니까 말해봐!",
  str_homestory_811201001_9_dialog_content = "좋아. 그럼 바로 말할게.",
  str_homestory_811201001_10_dialog_content = "첫째, 이 상점엔 액세서리 클리너가 없어.",
  str_homestory_811201001_11_dialog_content = "둘째, 단추의 디자인이 하나같이 너무 투박해!",
  str_homestory_811201001_12_dialog_content = "잘 들어. 이런 단추를 옷에 달고 싶은 사람은\n아무도 없을 거라고.",
  str_homestory_811201001_13_dialog_content = "아, 물론 일루미나 녀석들이라면 모르겠지만.",
  str_homestory_811201001_14_dialog_content = "단추는... 잘 달려 있기만 하면 되는 거 아냐?",
  str_homestory_811201001_15_dialog_content = "뭐, 주변에 패션 피플이 없으면 그런 반응이\n나오는 것도 당연하지.",
  str_homestory_811201001_16_dialog_content = "그래도 자책할 건 없어.\n내가 차근차근 알려 줄 테니까.",
  str_homestory_811201001_17_dialog_content = "...고마...워?",
  str_homestory_811201001_18_dialog_content = "그리고 여긴 움브라톤보다 햇볕이 강한 곳이야.",
  str_homestory_811201001_19_dialog_content = "이 가게엔 양산은 있지만, 휴대용 선크림이나\n선글라스 같은 자외선 차단 용품은 없어.",
  str_homestory_811201001_20_dialog_content = "아, 그러고 보니 그렇네...",
  str_homestory_811201001_21_dialog_content = "(어쩌면 스모키 외에도 물건이 부족하다고 느끼는 오로리안이 더 있을지도 몰라.)",
  str_homestory_811201001_22_dialog_content = "(어떡하지... 한 명씩 붙잡고 물어보는 것도 일인데...)",
  str_homestory_811201001_23_dialog_content = "야, 혼자 뭘 중얼거리고 있어?",
  str_homestory_811201001_24_dialog_content = "설마 나 말고도 귀찮게 하는 손님이 있을까\n걱정하는 거야?",
  str_homestory_811201001_25_option_content = "(고개를 끄덕인다)",
  str_homestory_811201001_26_dialog_content = "좋아, 솔직하게 인정할 줄이야.",
  str_homestory_811201001_27_dialog_content = "귀찮다기보다는 고민이 된다고 말하는 게 맞을 것 같은데...",
  str_homestory_811201001_28_option_content = "(고개를 젓는다)",
  str_homestory_811201001_29_dialog_content = "아니야, 스모키. 귀찮은 건 아냐...",
  str_homestory_811201001_30_dialog_content = "사실 이건 귀찮고 말고의 문제가 아니잖아.",
  str_homestory_811201001_31_dialog_content = "만약 너처럼 생각하는 사람이 또 있다면\n어떻게 해야 할까 생각 중이었어...",
  str_homestory_811201001_32_dialog_content = "그럼 헤븐즈 밸리에 상품 주문 시스템을 만들어 봐.",
  str_homestory_811201001_33_dialog_content = "각자 필요한 물건이 있으면 아스트라 대륙 곳곳에\n주문을 넣을 수 있게 하는 거지.",
  str_homestory_811201001_34_dialog_content = "그리고 운송 방식은...\n너희의 특수한 기술을 이용하면 되잖아?",
  str_homestory_811201001_35_dialog_content = "쿠리어 길드<sprite=emo_gezitou size=60 />나, 파이어플라이 같은 거 말이야.",
  str_homestory_811201001_36_dialog_content = "음... 왠지 좋은 생각 같은데...",
  str_homestory_811201001_37_dialog_content = "그렇게 하면 너도 일일이 안 물어봐도 되고,\n다른 손님들도 나처럼 직접 불만을 드러낼\n필요가 없잖아.",
  str_homestory_811201001_38_dialog_content = "게다가 어떤 오로리안은 특수한 니즈가\n있을지도 몰라.",
  str_homestory_811201001_39_dialog_content = "예를 들어 관을 주문하고 싶을 수도 있고,\n다양한 사이즈의 그림붓이 필요할 수도 있어.\n이상한 곤충을 찾는 사람도 있을지도 모르고...",
  str_homestory_811201001_40_dialog_content = "또 어떤 사람은 술 중에서도 진만 좋아하는\n사람도 있겠지.",
  str_homestory_811201001_41_dialog_content = "잠깐만, 진?",
  str_homestory_811201001_42_dialog_content = "그거 혹시... 제네비브 얘기야?",
  str_homestory_811201001_43_dialog_content = "세상에 진 좋아하는 사람이\n제네비브 한 사람뿐이겠어?",
  str_homestory_811201001_44_dialog_content = "...대체 무슨 생각을 하는 거야?!",
  str_homestory_811201001_45_dialog_content = "아, 알았어... 아니면 아닌 거지! 그래, 다른 사람일 거야!",
  str_homestory_811201001_46_dialog_content = "당연하지! 세상에 진을 좋아하는 사람이\n얼마나 많은데!<sprite=emo_nuhuo size=60 />",
  str_homestory_811201001_47_dialog_content = "그, 그래... 흥분하지 마... 불도 지르지 말고...",
  str_homestory_811201001_48_dialog_content = "흥.",
  str_homestory_811201001_49_dialog_content = "아무튼 고마워, 스모키!",
  str_homestory_811201001_50_dialog_content = "정말 유용한 조언이었어!",
  str_homestory_811201001_51_dialog_content = "그럼 간다. 안녕.",
  str_homestory_811201001_52_dialog_content = "아, 안녕!",
  str_homestory_807101001_0_dialog_content = "타키 씨의 연이...",
  str_homestory_807101001_1_dialog_content = "안녕하세요, 타키 씨...",
  str_homestory_807101001_2_dialog_content = "음? PlayerName?",
  str_homestory_807101001_3_dialog_content = "저기... 방금 타키 씨가 연 날리고 있는 걸 봤는데...",
  str_homestory_807101001_4_dialog_content = "땅에 떨어졌네요.",
  str_homestory_807101001_5_dialog_content = "...아.",
  str_homestory_807101001_6_dialog_content = "그래도 재빨리 주웠다고.",
  str_homestory_807101001_7_dialog_content = "...?<sprite=emo_yihuo size=60 />",
  str_homestory_807101001_8_dialog_content = "(포인트가 그게 아니지 않나...?)",
  str_homestory_807101001_9_dialog_content = "음... 그래도 방금 연 날리는 기술을 보니까...",
  str_homestory_807101001_10_option_content = "실력이 좋은 것 같던데요!",
  str_homestory_807101001_11_dialog_content = "애송이... 지금 날 위로하는 거냐?",
  str_homestory_807101001_12_dialog_content = "크흠... 전 그냥 좀 격려해 주고 싶었던 건데요...",
  str_homestory_807101001_13_dialog_content = "네 마음은 알겠다만, 거짓말로 칭찬하는 건\n필요 없다고.",
  str_homestory_807101001_14_dialog_content = "음... 알겠어요. 그래도 타키 씨가 자신감을 잃지만 않았다면...",
  str_homestory_807101001_15_option_content = "전혀 할 줄 모르는 것 같던데요?",
  str_homestory_807101001_16_dialog_content = "사실 제가 좀 가르쳐 드릴 수도 있어요.",
  str_homestory_807101001_17_dialog_content = "음. 그럼 한 수 배워보도록 하지.",
  str_homestory_807101001_18_dialog_content = "네? 이렇게 흔쾌히요?",
  str_homestory_807101001_19_dialog_content = "당연하지.",
  str_homestory_807101001_20_dialog_content = "실력이 더 좋은 사람한테 가르침을 받는 건\n결코 부끄러운 일이 아니다.",
  str_homestory_807101001_21_dialog_content = "모르는 건 바로 물어봐야 불필요한 시간 낭비를\n줄일 수 있다고. 특히 사업하는 사람이라면 말이야.",
  str_homestory_807101001_22_dialog_content = "과연 흥신소의 오너답네요!",
  str_homestory_807101001_23_dialog_content = "그럼 연 날리는 데는 어떤 기술이 필요한 거지?",
  str_homestory_807101001_24_dialog_content = "음, 일단 바람의 방향을 확인하고, 바람이 오는 쪽을 마주 보고 서야 돼요.",
  str_homestory_807101001_25_dialog_content = "역풍이 불 때 연날리기가 더 쉽거든요.",
  str_homestory_807101001_26_dialog_content = "바람이 위로 향하면 천천히 실을 풀고, 풍력이 부족하다 싶으면 재빨리 감아야 해요.",
  str_homestory_807101001_27_dialog_content = "연이 떠오르기 시작하면 천천히 따라가면서 계속 연의 상태를 살피는 거예요.",
  str_homestory_807101001_28_dialog_content = "이때 연이 안정적으로 충분히 높이 올라갔다면...",
  str_homestory_807101001_29_dialog_content = "그 뒤엔 나뭇가지나 표지판 같은 곳에 실을 묶고, 편안한 곳에서 연을 감상하면 돼요.",
  str_homestory_807101001_30_dialog_content = "음... 풍향, 풍력, 추적...\n연과의 상호작용이란 말인가...<sprite=emo_wuyu size=60 />",
  str_homestory_807101001_31_dialog_content = "네? 외우고 있는 건가요?",
  str_homestory_807101001_32_dialog_content = "혹시 필요하면 한 번 더 설명해 줄게요...",
  str_homestory_807101001_33_dialog_content = "아니, 됐다. 이미 기억했다.",
  str_homestory_807101001_34_dialog_content = "음? 그럼 왜 계속 중얼거리는 건데요?",
  str_homestory_807101001_35_dialog_content = "아니면... 제가 말한 대로 직접 해 보는 건 어때요?",
  str_homestory_807101001_36_dialog_content = "난 지금 「연날리기 기술」이라는 책을\n발간했을 때 어떻게 인쇄해야 더 잘 팔릴지\n생각 중이었다.",
  str_homestory_807101001_37_dialog_content = "...하아?",
  str_homestory_807101001_38_dialog_content = "생각해 봐라. 흥신소에서 연을 만들어서 팔고,\n대대적인 홍보를 하는 거지...",
  str_homestory_807101001_39_dialog_content = "연을 사면 연 날리는 방법을 알려준다고 말이야.",
  str_homestory_807101001_40_dialog_content = "만약 강습을 받고도 여전히 날리지 못한다면?\n그땐 이 「연날리기 기술」 책자를 사면 되지.",
  str_homestory_807101001_41_dialog_content = "연의 색과 모양도 종류가 많아야겠지.\n그리고 연에 섀도우마스터의 사진도 넣는다면...",
  str_homestory_807101001_42_dialog_content = "자, 잠깐! 잠깐만요!",
  str_homestory_807101001_43_dialog_content = "그럼 처음부터 연 날리는 걸 배우려던 목적은...",
  str_homestory_807101001_44_dialog_content = "전부 돈을 벌기 위해서였던 거예요?!",
  str_homestory_807101001_45_dialog_content = "당연하지.",
  str_homestory_807101001_46_dialog_content = "애송이, 나는 사업가다.",
  str_homestory_807101001_47_dialog_content = "무슨 문제라도 있나?",
  str_homestory_807101001_48_dialog_content = "아, 아니요...",
  str_homestory_807101001_49_dialog_content = "그냥 그 사업적 감각이 정말 부럽네요!",
  str_homestory_807101001_50_dialog_content = "저한테도 주변의 사물을 가지고 돈을 버는 능력이 있었다면...\n이렇게 매일 적자를 보진 않았겠죠...",
  str_homestory_807101001_51_dialog_content = "아? 그런 말이었나?",
  str_homestory_807101001_52_dialog_content = "그럼 이렇게 하자고.\n어차피 이 아이디어는 너한테서\n영감을 얻은 거니까...",
  str_homestory_807101001_53_dialog_content = "만약 실제로 연을 팔아서 이윤이 생긴다면,\n너한테 절반을 나눠주도록 하지.",
  str_homestory_807101001_54_dialog_content = "...?!",
  str_homestory_807101001_55_dialog_content = "지, 진짜요?!",
  str_homestory_807101001_56_dialog_content = "물론이다. 다만 미리 기대하진 마라.",
  str_homestory_807101001_57_dialog_content = "사업이란 건 어떻게 될지 아무도 모르는 거니까.",
  str_homestory_807101001_58_dialog_content = "괜찮아요! 전 타키 씨를 믿어요!",
  str_homestory_807101001_59_dialog_content = "그럼 난 지금부터 네게 배운 기술을 연마해야겠어.",
  str_homestory_807101001_60_dialog_content = "애송이... 바쁠 텐데 그럼 가서 일 보라고.",
  str_homestory_807101001_61_dialog_content = "네! 타키 씨, 화이팅!",
  str_homestory_807101001_62_dialog_content = "(...그래, 결심했어!)",
  str_homestory_807101001_63_dialog_content = "(앞으로 종종 타키 씨의 진도를 확인하러 와야겠어!\n그래야 나도 돈을 받을 수 있을 테니까!)<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_0_dialog_content = "바이스?",
  str_homestory_803301001_1_dialog_content = "숨을 쉬는 거야... 그래, 난 할 수 있어!",
  str_homestory_803301001_2_dialog_content = "들이마시고... 내쉬고...<sprite=emo_tanqi size=60 />",
  str_homestory_803301001_3_dialog_content = "내쉬고?",
  str_homestory_803301001_4_dialog_content = "바이스, 너 지금... 숨쉬기 연습하는 거야?",
  str_homestory_803301001_5_dialog_content = "아, PlayerName?",
  str_homestory_803301001_6_dialog_content = "...숨쉬기 연습?",
  str_homestory_803301001_7_dialog_content = "아니야, 그런 거...",
  str_homestory_803301001_8_dialog_content = "그럼 뭐 하고 있었어?",
  str_homestory_803301001_9_dialog_content = "그냥 장부를 보고 있었을 뿐이야.",
  str_homestory_803301001_10_dialog_content = "아... 이 지출 항목들만 보면 머리가 아프다니까.",
  str_homestory_803301001_11_dialog_content = "차라리 숨쉬기 연습이었으면 얼마나 좋았겠어...",
  str_homestory_803301001_12_dialog_content = "적어도 숨 쉬는 건 공짜니까.",
  str_homestory_803301001_13_option_content = "(바이스에게 질문한다)",
  str_homestory_803301001_14_dialog_content = "내가 좀 도와줄까?",
  str_homestory_803301001_15_dialog_content = "사실 나도 어제 장부를 봤었어.",
  str_homestory_803301001_16_dialog_content = "비록 난 계산은 잘 못하지만... 그래도 조금은 도움이 될 거야.",
  str_homestory_803301001_17_option_content = "(침묵한다)",
  str_homestory_803301001_18_dialog_content = "응? 왜 말이 없어?",
  str_homestory_803301001_19_dialog_content = "아, 널 탓하려던 건 아니었어...",
  str_homestory_803301001_20_dialog_content = "나도 알아. 난 그저 어떻게 하면 조금이라도 널 도와줄 수 있을까 생각한 거야.",
  str_homestory_803301001_21_dialog_content = "어제 봤더니 확실히 예산이 많이 초과됐더라고...",
  str_homestory_803301001_22_dialog_content = "휴, 바이스... 최근에 정말 고생 많았어!",
  str_homestory_803301001_23_dialog_content = "어제 장부에서 봤던 내용들도 기억해...",
  str_homestory_803301001_24_dialog_content = "「희망의 연못, 광장, 인공산 이 세 곳에 들어가는\n재료만 해도 이미 엄청난 비용이 소모된다.」",
  str_homestory_803301001_25_dialog_content = "「숙소나 전시관에 필요한 물자는 말할 것도 없다.」",
  str_homestory_803301001_26_dialog_content = "「게다가 동료들의 기호도 제각각이다..」",
  str_homestory_803301001_27_dialog_content = "「예를 들면 목마나 그네의자, 조각상...」",
  str_homestory_803301001_28_dialog_content = "「이런 소품들은 비싸진 않지만, 전부 합치면 그것도 무시할 수 없는 지출이 될 거다.」",
  str_homestory_803301001_29_dialog_content = "「게다가 기술자들과 소통하고, 물건을 설치하는 것도 보통 일이 아니다.」",
  str_homestory_803301001_30_dialog_content = "「그래도... 모두가 여기서 편안하게 지낼 수만 있다면\n나와 PlayerName의 노력도 헛되진 않겠지?」",
  str_homestory_803301001_31_dialog_content = "아... 전부 봐 버렸구나.",
  str_homestory_803301001_32_dialog_content = "공책에 아무렇게나 끄적이는 버릇은\n역시 고치기 어렵다니까... 아하하.",
  str_homestory_803301001_33_dialog_content = "사실 내가 하고 싶었던 말은 그러니까... 바이스 넌 최고야!",
  str_homestory_803301001_34_dialog_content = "조종사? 왜... 갑자기 사람을 띄우고 그래?",
  str_homestory_803301001_35_dialog_content = "이건 진심으로 하는 말이야.",
  str_homestory_803301001_36_dialog_content = "넌 설계도 그리는 것부터 시공 계획, 구획 구분까지 못 하는 게 없잖아.",
  str_homestory_803301001_37_dialog_content = "근데 난 설계도는커녕 계획 같은 것도 잘 세우질 못해.",
  str_homestory_803301001_38_dialog_content = "헤븐즈 가든이 지금의 모습이 될 수 있었던 건 전부 네 덕분이야!",
  str_homestory_803301001_39_dialog_content = "...아, 그, 그건...",
  str_homestory_803301001_40_dialog_content = "...우리 사이에 그럴 거 없어!",
  str_homestory_803301001_41_dialog_content = "그러니까 난 네가 다시 기운을 냈으면 좋겠어.",
  str_homestory_803301001_42_dialog_content = "그럼 어떻게 하면 튼튼한 재정을 유지할 수 있을지 같이 연구해 볼까?",
  str_homestory_803301001_43_dialog_content = "응! 대찬성이야! 같이 한번 고민해 보자!",
  str_homestory_803301001_44_dialog_content = "앗... 갑자기 든 생각인데,\n헤븐즈 가든에는 물건을 들여오기가 어렵잖아...",
  str_homestory_803301001_45_dialog_content = "그럼 이참에 상점 물건 가격을\n전부 열 배로 올려 버릴까?<sprite=emo_yaosu size=60 />",
  str_homestory_803301001_46_dialog_content = "그...그럴 필요까지는...",
  str_homestory_803301001_47_dialog_content = "헤헤, 농담이야!",
  str_homestory_803301001_48_dialog_content = "그나저나... 도대체 어디서 돈을 벌어야 하지?\n고민되네...",
  str_homestory_804101001_0_dialog_content = "블랑 씨...",
  str_homestory_804101001_1_dialog_content = "아, PlayerName 씨...",
  str_homestory_804101001_2_dialog_content = "<sprite=emo_pugongying size=60 />오늘은 날씨가 꽤 좋네요.",
  str_homestory_804101001_3_dialog_content = "그러게요.",
  str_homestory_804101001_4_dialog_content = "산책 중이었나요? 아니면 다른 볼일이라도 있나요?",
  str_homestory_804101001_5_option_content = "산책 중이었어요.",
  str_homestory_804101001_6_dialog_content = "좋은 선택이네요.",
  str_homestory_804101001_7_dialog_content = "이곳은 경치도 좋고, 즐길 거리도 많고...",
  str_homestory_804101001_8_dialog_content = "게다가 제가 처음 보는 사람들도 많네요.",
  str_homestory_804101001_9_option_content = "낚시하러 가는 중이었어요.",
  str_homestory_804101001_10_dialog_content = "아, 낚시 실력은 어떤 편인가요?",
  str_homestory_804101001_11_option_content = "끝내주죠!",
  str_homestory_804101001_12_dialog_content = "정말인가요?",
  str_homestory_804101001_13_dialog_content = "정말인지 확인해 봐도 괜찮겠죠?",
  str_homestory_804101001_14_dialog_content = "얼마든지요!",
  str_homestory_804101001_15_dialog_content = "후훗~ 정말 자신감 넘치는 청년이군요.",
  str_homestory_804101001_16_option_content = "보통이에요...",
  str_homestory_804101001_17_dialog_content = "낚시는... 인내심이 많이 필요한 일이죠.",
  str_homestory_804101001_18_dialog_content = "그렇게 젊은 나이에 낚시 같은 취미가\n있었을 줄은 몰랐네요.",
  str_homestory_804101001_19_dialog_content = "음... 집중력을 기르는 데 도움이 될 것 같아서요.",
  str_homestory_804101001_20_dialog_content = "으음...",
  str_homestory_804101001_21_dialog_content = "사람들은 보통 일상생활에서 집중을 못 하겠다는\n느낌이 들었을 때 비로소 집중력에 도움이\n되는 일을 찾는 법이죠.",
  str_homestory_804101001_22_dialog_content = "하지만 오랜 시간 훈련하면\n확실히 도움이 될 거예요.",
  str_homestory_804101001_23_dialog_content = "으음...",
  str_homestory_804101001_24_dialog_content = "근데 블랑 씨는 왜 계속 이 팻말 아래에 서 있던 거예요?",
  str_homestory_804101001_25_dialog_content = "이곳을 관찰하고 있었답니다.",
  str_homestory_804101001_26_dialog_content = "관찰이요?",
  str_homestory_804101001_27_dialog_content = "직업병이라고 할 수 있겠네요.",
  str_homestory_804101001_28_dialog_content = "새로운 건물과 길을 잔뜩 보다 보니까\n저도 모르게 이 모든 걸 머릿속에 집어넣고\n싶어졌지 뭐예요.",
  str_homestory_804101001_29_dialog_content = "그랬군요.",
  str_homestory_804101001_30_dialog_content = "그래도 여긴 길이 복잡한 편은 아니니까, 블랑 씨도 가끔은 쉬는 게 좋지 않을까요?",
  str_homestory_804101001_31_dialog_content = "쉰다고요?",
  str_homestory_804101001_32_dialog_content = "제겐 사치스러운 꿈이네요...",
  str_homestory_804101001_33_dialog_content = "그래도 당신의 제안이니 그렇게 해 볼게요.",
  str_homestory_804101001_34_dialog_content = "대신 PlayerName 씨도 무리하면 안 돼요.",
  str_homestory_804101001_35_dialog_content = "사람은 너무 피곤하게 살면 빨리 늙는다구요~<sprite=emo_guilian size=60 />",
  str_homestory_804101001_36_dialog_content = "아, 알겠어요...",
  str_homestory_804101001_37_dialog_content = "그렇게 할게요! 블랑 씨!",
  str_homestory_813801001_0_dialog_content = "시오반 씨!",
  str_homestory_813801001_1_dialog_content = "PlayerName?",
  str_homestory_813801001_2_dialog_content = "아... 당신이라서 다행이네요...<sprite=emo_tanqi size=60 />",
  str_homestory_813801001_3_dialog_content = "왜 그래? 시오반 씨, 조금 피곤해 보여.",
  str_homestory_813801001_4_dialog_content = "그게... 밤을 새워서 드디어 전시관의\n소장품을 다 봤거든요.",
  str_homestory_813801001_5_dialog_content = "헤븐즈 밸리에 살던 아이테르 일족의 과학 기술을\n잘 보존해 둔 소장품들이었어요...",
  str_homestory_813801001_6_dialog_content = "정말 아이테르 일족은 정말 대단한\n과학 기술을 지니고 있더군요.",
  str_homestory_813801001_7_dialog_content = "에이, 뭘. 일루미나도 대단하지 않아?",
  str_homestory_813801001_8_dialog_content = "왠지는 모르겠지만 그런 느낌이 들어요...",
  str_homestory_813801001_9_dialog_content = "아이테르의 과학 기술은 일루미나와는\n다른 차원의 산물인 것 같아요.",
  str_homestory_813801001_10_dialog_content = "일루미나의 첨단 기술은 정교한 기계를\n바탕으로 해요. 또한, 체계화된 지식과 측량으로\n이루어져 있죠...",
  str_homestory_813801001_11_dialog_content = "하지만 아이테르의 과학 기술은...\n왠지 살아 숨 쉬는 것 같아요.",
  str_homestory_813801001_12_dialog_content = "뭔가... 고대의 과학 기술과 비슷하지만,\n뭔가 다른 오묘함이 있어요.",
  str_homestory_813801001_13_dialog_content = "그건 나도 진짜 모르겠네...",
  str_homestory_813801001_14_dialog_content = "아...",
  str_homestory_813801001_15_dialog_content = "아직도 조금 졸리네요...<sprite=emo_xuanyun size=60 />",
  str_homestory_813801001_16_dialog_content = "그럼 왜 아직도 여기 서 있어? 얼른 돌아가서 쉬어.",
  str_homestory_813801001_17_dialog_content = "견학하면서 적어둔 기록을 정리하고 있거든요.\n예전에 읽었던 자료와 연계해 정리해서\n새로운 발견이 있는지 볼 생각이에요.",
  str_homestory_813801001_18_dialog_content = "오래전 이 대륙의 다른 곳에서도 아이테르의\n발자취를 발견했을지도 모르잖아요...",
  str_homestory_813801001_19_dialog_content = "다만 그때의 사람들은 아이테르 일족에 대해\n몰랐으니까, 고대 기술과 아이테르 과학 기술의\n차이를 구분하지 못했을 거예요.",
  str_homestory_813801001_20_dialog_content = "...아하하하, 됐어요.",
  str_homestory_813801001_21_dialog_content = "역시 너무 비현실적인 생각이었죠?\n너무 졸려서 그런 걸까요?",
  str_homestory_813801001_22_dialog_content = "시오반 씨, 지금 상태가 너무 안 좋아 보여. 좀 걱정돼.",
  str_homestory_813801001_23_dialog_content = "왜 꼭 지금 분석을 마치려는 거야?",
  str_homestory_813801001_24_dialog_content = "그런 상태라면 분석 결과에도 영향을 줄 것 같은데...",
  str_homestory_813801001_25_dialog_content = "이곳엔... 백야성의 사람들도 꽤 있죠?",
  str_homestory_813801001_26_dialog_content = "당신도 있으니까 저들이 이곳의 전시관까지\n파괴하려 들진 않겠죠...",
  str_homestory_813801001_27_dialog_content = "하아, 그래도 역시나 조금 걱정이 되거든요!",
  str_homestory_813801001_28_dialog_content = "그래서 최대한 빨리 보고 기록과 분석을 마쳐야\n안심이 될 것 같아요.",
  str_homestory_813801001_29_dialog_content = "과학 기술을 반대하는 그 녀석들이 여길\n어떻게 여길지 누가 알겠어요?",
  str_homestory_813801001_30_dialog_content = "그랬구나...",
  str_homestory_813801001_31_dialog_content = "그래도 안심해. 백야성에도 전시관이 꽤 많이 있다고 알고 있거든.",
  str_homestory_813801001_32_dialog_content = "게다가 그 사람들도 여기선 손님이니까,\n시오반 씨가 걱정하는 그런 일들은 생기지 않을 거야.",
  str_homestory_813801001_33_dialog_content = "그럼 제가 괜한 걱정을 한 걸까요?",
  str_homestory_813801001_34_dialog_content = "설마... 연장 근무를 너무 오래 해서\n잡생각이 많아진 탓일까요?<sprite=emo_sikao size=60 />",
  str_homestory_813801001_35_dialog_content = "너무 피곤해서 그런 거라 생각해.",
  str_homestory_813801001_36_dialog_content = "좀 쉬었다가 다시 하는 게 어떨까?",
  str_homestory_813801001_37_dialog_content = "네. 아무래도 그렇게 해야겠네요... PlayerName.",
  str_homestory_813801001_38_dialog_content = "저는 이제 쉬러 갈게요. 당신은요?",
  str_homestory_813801001_39_dialog_content = "당신도 요즘 많이 피곤하죠?",
  str_homestory_813801001_40_option_content = "(동의한다)",
  str_homestory_813801001_41_dialog_content = "맞아. 확실히 피곤하지.",
  str_homestory_813801001_42_dialog_content = "그래도...",
  str_homestory_813801001_43_option_content = "(반박한다)",
  str_homestory_813801001_44_dialog_content = "몸은 조금 힘들지만 정신적으로는 아주 만족스러워!",
  str_homestory_813801001_45_dialog_content = "다들 여기서 즐겁게 생활할 수 있다면 조금 힘든 정도는 별거 아니라고 생각해.",
  str_homestory_813801001_46_dialog_content = "당신은 정말 리더십이 넘치는... 소년이군요.",
  str_homestory_813801001_47_dialog_content = "고, 고마워.",
  str_homestory_813801001_48_dialog_content = "아... 왠지 갑자기 강가에도 다녀오고 싶어졌지만,\n그래도 졸려서 우선 좀 쉬어야겠어요.",
  str_homestory_813801001_49_dialog_content = "제가 일어나면 다시 함께 아이테르의 과학 기술에\n대해 얘기하기로 해요.",
  str_homestory_813801001_50_dialog_content = "좋아. 일단 푹 쉬어, 시오반 씨.",
  str_homestory_814501001_0_dialog_content = "뭘 보고 있는 거지?",
  str_homestory_814501001_1_dialog_content = "아메모리?",
  str_homestory_814501001_2_dialog_content = "쉿.<sprite=emo_baiyan size=60 />",
  str_homestory_814501001_3_dialog_content = "......?",
  str_homestory_814501001_4_dialog_content = "뭐 하고 있어?",
  str_homestory_814501001_5_dialog_content = "관찰 중이오.",
  str_homestory_814501001_6_dialog_content = "소생은 이곳저곳을 자세히 관찰하는 것을\n매우 좋아하오.",
  str_homestory_814501001_7_dialog_content = "여기... 혹시 뭐가 있는 건 아니지?",
  str_homestory_814501001_8_dialog_content = "귀공은 헤븐즈 가든이 참으로 정교하고 아름답게\n설계되었다고 생각하지 않소?",
  str_homestory_814501001_9_dialog_content = "소생도 어릴 적에 이런 곳을 세우는 꿈을\n가져본 적이 있소.",
  str_homestory_814501001_10_dialog_content = "공격과 수비에 유리한 지형이니,\n뜻이 맞는 이들과 함께 모여 살 수 있지 않겠소.",
  str_homestory_814501001_11_dialog_content = "아...",
  str_homestory_814501001_12_dialog_content = "아메모리는 어렸을 때부터 그렇게 장기적인 계획을 세웠던 거야?",
  str_homestory_814501001_13_dialog_content = "어쩌면 그 꿈은 소생에게\n「앞으로 계속 살아가게 해 주는」\n동력이었을지도 모르겠소.",
  str_homestory_814501001_14_dialog_content = "허나 지금은 이곳에서 살아갈 수 있으니\n이 또한 나쁘지 않을 듯하오.",
  str_homestory_814501001_15_dialog_content = "아... 미안.",
  str_homestory_814501001_16_dialog_content = "그럼 내가 같이 다니면서 안내해 줄까?",
  str_homestory_814501001_17_dialog_content = "그럴 필요 없소.",
  str_homestory_814501001_18_dialog_content = "이미 이곳에 도착한 날부터 이곳을\n잘 파악해 두었소이다.",
  str_homestory_814501001_19_dialog_content = "무서운 정찰 능력이네!",
  str_homestory_814501001_20_dialog_content = "닌자의 본능일 뿐이외다.",
  str_homestory_814501001_21_dialog_content = "사실 궁금한 게 있소...\n이 신비로운 곳을 설계한 사람은 누구요?",
  str_homestory_814501001_22_dialog_content = "귀공은 알고 있소?",
  str_homestory_814501001_23_option_content = "알고 있어.",
  str_homestory_814501001_24_dialog_content = "바이스가 나랑 기술자들의 의견을 모아서 설계한 거야.",
  str_homestory_814501001_25_option_content = "모르겠어.",
  str_homestory_814501001_26_dialog_content = "대신 바이스한테 물어봐 줄게.",
  str_homestory_814501001_27_dialog_content = "나도 설계에 참여하긴 했지만... 전체적인 건 바이스가 제일 잘 알고 있거든.",
  str_homestory_814501001_28_dialog_content = "근데 아메모리... 누가 설계한 건지는 왜 궁금한 거야?",
  str_homestory_814501001_29_dialog_content = "설마... 운도에도 「헤븐즈 가든」 같은 걸 짓고 싶은 거야?",
  str_homestory_814501001_30_dialog_content = "그런 생각이 있기는 하오.",
  str_homestory_814501001_31_dialog_content = "운도에도 이 정도 수준의 저택이 있다면\n사람들의 삶도 분명 더 나아질 것이오.",
  str_homestory_814501001_32_dialog_content = "물론, 그 외에도...",
  str_homestory_814501001_33_dialog_content = "우리가 이런 첨단 기술을 배우게 된다면,\n적을 상대하는 것도 훨씬 수월해질 것이오.",
  str_homestory_814501001_34_dialog_content = "아이테르의 기술과 이토록 정교한 사고방식은...\n우리가 배울 가치가 있소.",
  str_homestory_814501001_35_dialog_content = "그랬구나... 잘 알았어.",
  str_homestory_814501001_36_dialog_content = "꼭 물어봐 줄게!",
  str_homestory_814501001_37_dialog_content = "감사하오.",
  str_homestory_814601001_0_dialog_content = "어지러워...",
  str_homestory_814601001_1_dialog_content = "많고도 많은 오로리안...",
  str_homestory_814601001_2_dialog_content = "모두 헤븐즈 가든에 있다네.",
  str_homestory_814601001_3_dialog_content = "......?",
  str_homestory_814601001_4_dialog_content = "아치형 문이 공터에 지어지니...",
  str_homestory_814601001_5_dialog_content = "왕만두를 손에 쥐었다네!<sprite=emo_yaosu size=60 />",
  str_homestory_814601001_6_dialog_content = "......",
  str_homestory_814601001_7_dialog_content = "요우... 시 읊고 있는 거야?",
  str_homestory_814601001_8_dialog_content = "앗! 조종사! 왔어?",
  str_homestory_814601001_9_dialog_content = "틀렸어. 그냥 읊은 게 아냐.",
  str_homestory_814601001_10_dialog_content = "내가 직접 한 수 지은 거라구! 어땠어?",
  str_homestory_814601001_11_option_content = "아주 좋아!",
  str_homestory_814601001_12_dialog_content = "정말 잘 지었네!",
  str_homestory_814601001_13_dialog_content = "요우는 최고의 시인이야!",
  str_homestory_814601001_14_option_content = "나, 나쁘진 않았어.",
  str_homestory_814601001_15_dialog_content = "작품 수준은... 카론 씨랑 바이스의 중간 정도?",
  str_homestory_814601001_16_dialog_content = "과하지도 않았고 너무 사실적이지도 않은 데다가,\n언뜻언뜻 작가의 바람을 드러내고 있다는 점이...",
  str_homestory_814601001_17_dialog_content = "크흠, 그나저나 아치형 문이랑 왕만두가 무슨 상관이야?",
  str_homestory_814601001_18_dialog_content = "이 문 좀 봐. 내 미래의 왕만두 가게랑\n비슷하게 생기지 않았어?",
  str_homestory_814601001_19_dialog_content = "또 왕만두 가게를 열고 싶어졌어?",
  str_homestory_814601001_20_dialog_content = "강호에서 협객의 길을 걷는 건 그만두려고?",
  str_homestory_814601001_21_dialog_content = "협객의 길도 해야지. 두 개 다 하고 싶은 거야.",
  str_homestory_814601001_22_dialog_content = "왕만두 가게를 내가 나이가 들었을 때 돌아갈\n장소로 삼는 것도 꽤 괜찮지 않아?",
  str_homestory_814601001_23_dialog_content = "너도 알고 있겠지만, 전설의 협객들은 사람들로\n북적이는 시장 속에 은거하곤 하잖아...?",
  str_homestory_814601001_24_dialog_content = "그리고 시장통에서 강호에 전해지는\n자기 이야기를 엿듣는 거지!",
  str_homestory_814601001_25_dialog_content = "위대한 협객들이... 그렇게 한가하지는 않을 것 같은데...",
  str_homestory_814601001_26_dialog_content = "그 사람들이 한가하든 말든\n일단 내 계획부터 들어 봐!",
  str_homestory_814601001_27_dialog_content = "그래, 그래. 말해 봐.",
  str_homestory_814601001_28_dialog_content = "일단 왕만두 가게는 최소 3층까진 있어야 돼.",
  str_homestory_814601001_29_dialog_content = "1층의 절반은 안즈랑 모모한테 주고\n음식을 팔라고 할 거야. 나머지 반은 나도\n맛있는 걸 팔 거고!",
  str_homestory_814601001_30_dialog_content = "2층은 객잔이야. 이러면 내 친구들이\n머물 곳 걱정 없이 밤새도록 신나게\n이야기를 나눌 수 있을 거야!",
  str_homestory_814601001_31_dialog_content = "그리고 3층은 내 집이야!",
  str_homestory_814601001_32_dialog_content = "물론 내 방만 있는 건 아니야.\n아메모리, 린네, 조종사 너랑, 바이스...",
  str_homestory_814601001_33_dialog_content = "카야노, 린 가문 친구들, 우리 언니,\n그리고 엄마랑 아빠가 쓸 방도 있어야지...",
  str_homestory_814601001_34_dialog_content = "타키한테도 방을 남겨 줘야겠지?\n여자애들이 많아서 오기 싫어하려나?<sprite=emo_sikao size=60 />",
  str_homestory_814601001_35_dialog_content = "그리고 디나랑 로빈 방도 필요하지 않을까?",
  str_homestory_814601001_36_dialog_content = "잠깐만. 요우, 그럼 정작 돈은 하나도 못 벌 거야...",
  str_homestory_814601001_37_dialog_content = "친구들이 쓸 방만 준비해도 엄청난 지출 아냐?",
  str_homestory_814601001_38_dialog_content = "게다가 몇몇 사람들은 남이랑 같이 지내는 것보다\n혼자 지내길 좋아하는 편일 거야...",
  str_homestory_814601001_39_dialog_content = "돈은 별문제가 안 돼!",
  str_homestory_814601001_40_dialog_content = "음... 근데 네가 말한 「개인 취향」은\n확실히 문제긴 하네...",
  str_homestory_814601001_41_dialog_content = "그래도 내 친구들이니까 방은 당연히 준비해 줘야지.",
  str_homestory_814601001_42_dialog_content = "놀러 올지 안 올지는 친구들이 결정할 일이고,\n친구들을 위해 방을 준비하는 건 내가 해야\n할 일이니까!",
  str_homestory_814601001_43_dialog_content = "헤헤, 이게 바로 누이 좋고 매부 좋은 일 아니야?\n누구한테도 강요하지 않고 말이야.",
  str_homestory_814601001_44_dialog_content = "음, 맞는 말이네...",
  str_homestory_814601001_45_dialog_content = "그렇지만 역시 부자나 생각해 낼 방법이랄까...",
  str_homestory_816301001_0_dialog_content = "그림 그리고 있어?",
  str_homestory_816301001_1_dialog_content = "으허허!<sprite=emo_wuzui size=60 /> 비행선의 주인 PlayerName 님 아니십니까?",
  str_homestory_816301001_2_dialog_content = "드디어 만났군요! 찾느라 정말 힘들었습니다...",
  str_homestory_816301001_3_dialog_content = "응? 나한테 무슨 볼일 있었어?",
  str_homestory_816301001_4_dialog_content = "여기저기 사람들을 만나 외주를 맡기던 중\n이곳에 놓인 이젤을 발견했습니다...",
  str_homestory_816301001_5_dialog_content = "바이스 씨 말로는 모두의 반대를 무릅쓰고\n당신이 특별히 구매한 거라고 하더군요.",
  str_homestory_816301001_6_dialog_content = "모두의 반대를 무릅쓰고 강행했다는 건...",
  str_homestory_816301001_7_dialog_content = "드디어 《백XX광》의 일러스트에\n참여할 마음이 생긴 겁니까?<sprite=emo_yaosu size=60 />",
  str_homestory_816301001_8_option_content = "(인정한다)",
  str_homestory_816301001_9_dialog_content = "맞아, 그럴 생각이야.",
  str_homestory_816301001_10_dialog_content = "으허허! 드디어 자신의 재능을 인정하게 된\n모양이군요!",
  str_homestory_816301001_11_dialog_content = "크흠, 그냥 주머니 사정을 좀 개선해 보고 싶었거든.",
  str_homestory_816301001_12_dialog_content = "근데 내 그림 실력은 금방 좋아지긴 힘들 거야.",
  str_homestory_816301001_13_dialog_content = "그러니까 역시 그림 그리는 걸 좋아하는 사람한테\n맡기는 게 좋을 것 같아. 예를 들면 너라든가...",
  str_homestory_816301001_14_option_content = "(부정한다)",
  str_homestory_816301001_15_dialog_content = "크흠, 내 수준은 내가 잘 알아...",
  str_homestory_816301001_16_dialog_content = "이젤을 여기 둔 건 그림을 좋아하는 사람이 마음껏 그림을\n그릴 장소를 만들어 주고 싶어서였어.",
  str_homestory_816301001_17_dialog_content = "비행선의 주인님, 가슴에 손을 올려 보시죠.",
  str_homestory_816301001_18_dialog_content = "그림을 사랑하는 이의 심장이 뛰고 있지 않습니까?",
  str_homestory_816301001_19_dialog_content = "그림에 대한 열정이라면 왠지 널 이길 사람이 없을 것 같은데?",
  str_homestory_816301001_20_dialog_content = "투어독 씨.",
  str_homestory_816301001_21_dialog_content = "......!",
  str_homestory_816301001_22_dialog_content = "밤낮으로 게임 외주를 맡길 사람을 찾아다니더니,\n대체 며칠이나 제대로 못 쉰 거야?",
  str_homestory_816301001_23_dialog_content = "게임 제작을 위해서라면 수면과 휴식은\n없어도 됩니다.",
  str_homestory_816301001_24_dialog_content = "그럼 그림을 마음껏 그려본 지는 얼마나 됐어?",
  str_homestory_816301001_25_dialog_content = "으허허...",
  str_homestory_816301001_26_dialog_content = "설마 제가 당신의 이젤에 그림을 그리게\n만들고 싶으셨던 겁니까?<sprite=emo_yihuo size=60 />",
  str_homestory_816301001_27_dialog_content = "아스트라 대륙의 유명 인사인 투어독 씨가 이곳에 작품을 남겨 준다면...",
  str_homestory_816301001_28_dialog_content = "그것보다 더 좋을 순 없겠지!",
  str_homestory_816301001_29_dialog_content = "상대방의 약점을 파악해서 대화로 달래 준 다음...\n상대를 치켜세우고 마지막으로 요구 사항을\n꺼내다니...<sprite=emo_sikao size=60 />",
  str_homestory_816301001_30_dialog_content = "이게 바로 빈틈없는 심리전이라는 겁니까?",
  str_homestory_816301001_31_dialog_content = "수많은 외주를 맡겨온 제가 하마터면 당신에게\n외주를 받을 뻔했군요. 정말 재밌습니다!",
  str_homestory_816301001_32_dialog_content = "역시 경영진이 선택한 주인공답군요!",
  str_homestory_816301001_33_dialog_content = "당신만 있다면 앞으로 게임의 시나리오가\n따분해질까 걱정하지 않아도 되겠습니다.",
  str_homestory_816301001_34_option_content = "(경영진에 대해 묻는다)",
  str_homestory_816301001_35_dialog_content = "경영진?",
  str_homestory_816301001_36_dialog_content = "큰 힘이 있고, 당신을 좋게 보는 사장님들을\n말하는 겁니다.",
  str_homestory_816301001_37_dialog_content = "그들이 누구인지는 신경 쓰지 않아도 됩니다.",
  str_homestory_816301001_38_option_content = "(주인공에 대해 묻는다)",
  str_homestory_816301001_39_dialog_content = "주인공?",
  str_homestory_816301001_40_dialog_content = "게임 시나리오 속의 중심인물입니다.\n모든 사람이 따르는 절대적인 스타 같은\n존재입니다.",
  str_homestory_816301001_41_dialog_content = "그건 아무나 맡을 수 있는 역할이 아닙니다.",
  str_homestory_816301001_42_dialog_content = "들으면 들을수록 이해가 안 되는데...",
  str_homestory_816301001_43_dialog_content = "아무튼 말입니다, 비행선의 주인님.",
  str_homestory_816301001_44_dialog_content = "제가 무료로 헤븐즈 가든을 그려 드리겠습니다!",
  str_homestory_816301001_45_dialog_content = "당신에게 특별한 외주 의뢰의 심리전을\n배웠으니 말입니다.",
  str_homestory_816301001_46_dialog_content = "자, 우리의 즐거운 협력을 위하여.<sprite=emo_guilian size=60 />",
  str_homestory_816301001_47_dialog_content = "위, 위하여...",
  str_homestory_816301001_48_dialog_content = "자, 이제 그림의 구도를 생각해 봐야겠군요.",
  str_homestory_816301001_49_dialog_content = "평소였다면 3초면 끝났겠지만...\n이번에는 비행선의 주인을 위한 대작이니\n최선을 다하겠습니다.",
  str_homestory_816301001_50_dialog_content = "으음...",
  str_homestory_816301001_51_dialog_content = "어떻게 그려야 좋을까...",
  str_homestory_816301001_52_dialog_content = "그럼... 방해 안 할게...",
  str_homestory_816301001_53_dialog_content = "(이제 내 말은 안 들리는 것 같은데?)",
  str_homestory_816301001_54_dialog_content = "(빨리 도망가자.)",
  str_homestory_814801001_0_dialog_content = "왔구나.",
  str_homestory_814801001_1_dialog_content = "아주르 씨...",
  str_homestory_814801001_2_dialog_content = "으음?",
  str_homestory_814801001_3_dialog_content = "이 귀여운 얼굴 좀 봐.",
  str_homestory_814801001_4_dialog_content = "이리 와. 누나가 볼 좀 만져볼까?",
  str_homestory_814801001_5_dialog_content = "으아아<sprite=emo_yundao size=60 />... 잠깐만요!",
  str_homestory_814801001_6_dialog_content = "저예요! PlayerName!",
  str_homestory_814801001_7_dialog_content = "PlayerName? 익숙한 이름인걸~",
  str_homestory_814801001_8_dialog_content = "오~ 아하하! 기억났어!",
  str_homestory_814801001_9_dialog_content = "우리 아이테르 꼬마 남자친구잖아?",
  str_homestory_814801001_10_option_content = "(인정한다)",
  str_homestory_814801001_11_dialog_content = "...네, 저예요.",
  str_homestory_814801001_12_dialog_content = "어머, 인정하는 거야?",
  str_homestory_814801001_13_dialog_content = "그럼 인정했으니까 책임도 져 줘야 해.",
  str_homestory_814801001_14_option_content = "(부정한다)",
  str_homestory_814801001_15_dialog_content = "아주르 씨... 이상한 얘기하지 마세요...",
  str_homestory_814801001_16_dialog_content = "다른 사람이 들으면 오해할 거라구요.",
  str_homestory_814801001_17_dialog_content = "어머? 뭘 그렇게 무서워하는 거니?",
  str_homestory_814801001_18_dialog_content = "일루미나의 용꼬리 여자애가 들을까 봐 그래?",
  str_homestory_814801001_19_dialog_content = "아니면 백야성의 쌀쌀맞은 공주님이 들을까 봐?",
  str_homestory_814801001_20_dialog_content = "......",
  str_homestory_814801001_21_dialog_content = "어쩔 줄 몰라서 빨갛게 된 얼굴...\n훨씬 더 귀엽네. 아하하.",
  str_homestory_814801001_22_dialog_content = "머, 먼저 가 볼게요...<sprite=emo_hanshui size=60 />",
  str_homestory_814801001_23_dialog_content = "그래그래, 알겠어. 누나도 그만 놀릴게.",
  str_homestory_814801001_24_dialog_content = "무슨 일로 찾아온 거야?",
  str_homestory_814801001_25_dialog_content = "그냥 물어보고 싶은 게 있어서요... 이곳 생활엔 좀 익숙해졌나요?",
  str_homestory_814801001_26_dialog_content = "어머, 우리 꼬마 아이테르가 마음 써 주는\n법도 배웠구나. 누나는 감동했어.",
  str_homestory_814801001_27_dialog_content = "네 덕분에 즐겁게 잘 지내고 있어.",
  str_homestory_814801001_28_dialog_content = "이곳은 메마르고, 덥고, 황량한 사막이랑은 달라.\n초록 식물이 아주 많잖아.",
  str_homestory_814801001_29_dialog_content = "기온도 적당하고, 공기도 촉촉하고,\n심지어 바람까지 부드럽던걸.",
  str_homestory_814801001_30_dialog_content = "짜증 나는 녀석들도 별로 없고.",
  str_homestory_814801001_31_dialog_content = "정말 천연 뷰티샵이 따로 없다니까...",
  str_homestory_814801001_32_dialog_content = "봐, 나 요즘 예뻐진 것 같지 않아?",
  str_homestory_814801001_33_option_content = "(인정한다)",
  str_homestory_814801001_34_dialog_content = "확실히 전보다 더 예뻐진 것 같아요. 더 예뻐질 수 없을 정도로 말이에요...",
  str_homestory_814801001_35_option_content = "(부정한다)",
  str_homestory_814801001_36_dialog_content = "원래부터 예뻤는데 어떻게 더 예뻐지겠어요.",
  str_homestory_814801001_37_dialog_content = "그 조그만 입에 꿀을 얼마나 발라 놨으면\n그렇게 달콤한 말을 할까?",
  str_homestory_814801001_38_dialog_content = "아무래도 당분간 좀 더 머물러야 네 열렬한\n환대에 보답할 수 있겠는걸?",
  str_homestory_814801001_39_dialog_content = "참, 그럼 넌 내가 여기 자주 왔으면 좋겠어?",
  str_homestory_814801001_40_option_content = "(인정한다)",
  str_homestory_814801001_41_dialog_content = "네... 있고 싶은 만큼 있어도 돼요.",
  str_homestory_814801001_42_dialog_content = "이곳의 문은 언제나 아주르 씨한테 활짝 열려 있을 거예요.",
  str_homestory_814801001_43_option_content = "(부정한다)",
  str_homestory_814801001_44_dialog_content = "저, 전 강요하고 싶은 생각은 없어요...",
  str_homestory_814801001_45_dialog_content = "누구나 원할 때 찾아오고, 가고 싶을 때 가면 돼요.",
  str_homestory_814801001_46_dialog_content = "그럼 정말 사양 안 하고 편하게 있을게.",
  str_homestory_814801001_47_dialog_content = "너네 상점에 좋은 술도 좀 더 들여놓자.",
  str_homestory_814801001_48_dialog_content = "누나도 더는 못 기다리겠거든, 알고 있니?",
  str_homestory_814801001_49_dialog_content = "네...",
  str_homestory_814801001_50_dialog_content = "그럼 얼른 안 가고 뭐 해?<sprite=emo_emo size=60 />",
  str_homestory_814801001_51_dialog_content = "지, 지금 바로 갈게요!",
  str_homestory_815001001_0_dialog_content = "꿈쩍도 안 하네...",
  str_homestory_815001001_1_dialog_content = "PlayerName, 안녕하세요.<sprite=emo_heimao size=60 />",
  str_homestory_815001001_2_dialog_content = "레노어는, 당신을 만나서 무척 기뻐요.",
  str_homestory_815001001_3_dialog_content = "레노어, 왜 여기 멍하니 서 있어?",
  str_homestory_815001001_4_dialog_content = "다른 곳들도 구경해 보고 싶지 않아?",
  str_homestory_815001001_5_dialog_content = "구경?",
  str_homestory_815001001_6_dialog_content = "그건 레노어에게 내리는,\nPlayerName의 새로운 명령인가요?",
  str_homestory_815001001_7_dialog_content = "구체적으로 어디를 구경하면 될까요?",
  str_homestory_815001001_8_dialog_content = "레노어, 이건 명령이 아니라 제안이야.",
  str_homestory_815001001_9_dialog_content = "제안과 명령은, 뭐가 다른가요?",
  str_homestory_815001001_10_dialog_content = "음... 생각 좀 해볼게...",
  str_homestory_815001001_11_dialog_content = "명령은... 다른 사람이 너한테 어떤 일을 꼭 하라고 요구하는 거야.",
  str_homestory_815001001_12_dialog_content = "제안은 다른 사람이 너한테 어떤 일을 해도 된다고 알려 주지만,\n네가 하고 싶지 않으면 안 해도 되는 거야.",
  str_homestory_815001001_13_dialog_content = "레노어는 이해했어요.",
  str_homestory_815001001_14_dialog_content = "이곳저곳을 구경해 보라는,\nPlayerName의 제안을 받았어요.",
  str_homestory_815001001_15_dialog_content = "레노어는 구경하러 가도 되고,\n안 가도 되는 거예요.",
  str_homestory_815001001_16_dialog_content = "이렇게 빨리 이해했어? 레노어는 정말 똑똑하네!",
  str_homestory_815001001_17_dialog_content = "칭찬해 줘서 고마워요, PlayerName.",
  str_homestory_815001001_18_dialog_content = "천만에~",
  str_homestory_815001001_19_dialog_content = "......",
  str_homestory_815001001_20_dialog_content = "......",
  str_homestory_815001001_21_dialog_content = "......",
  str_homestory_815001001_22_dialog_content = "저기, 레노어?",
  str_homestory_815001001_23_dialog_content = "구경하러 안 가는 거야?",
  str_homestory_815001001_24_dialog_content = "제안이었잖아요?",
  str_homestory_815001001_25_dialog_content = "레노어는 가지 않아도 돼요.",
  str_homestory_815001001_26_dialog_content = "아, 그건...",
  str_homestory_815001001_27_dialog_content = "요 며칠 동안 예쁜 꽃이랑 나무를 많이 심었어. 게다가 오락시설도 많이 생겼어!",
  str_homestory_815001001_28_dialog_content = "가서 보고 싶지 않아?",
  str_homestory_815001001_29_dialog_content = "레노어가 보러 가고, 싶어 해야 하는 건가요?",
  str_homestory_815001001_30_option_content = "(명령이야)",
  str_homestory_815001001_31_dialog_content = "휴... 어쩔 수 없네.\n그래, 레노어한테 이곳저곳을 구경하라고 명령할게.",
  str_homestory_815001001_32_dialog_content = "알겠습니다. 레노어는 명령을 완수할게요!",
  str_homestory_815001001_33_option_content = "(제안이야)",
  str_homestory_815001001_34_dialog_content = "좀 잘난 척하는 것처럼 들릴 수도 있겠지만... 내가 꽤 잘 꾸며 놓은 것 같거든.",
  str_homestory_815001001_35_dialog_content = "그럼... 너도 구경하고 싶겠지?",
  str_homestory_815001001_36_dialog_content = "PlayerName 당신이 그렇게까지 말한다면,\n레노어도 제안을 승낙할게요.",
  str_homestory_815001001_37_dialog_content = "그래, 가서 한 번 둘러봐.",
  str_homestory_815001001_38_dialog_content = "그런데, 레노어가 어느 곳들을 둘러봐야 하나요?",
  str_homestory_815001001_39_dialog_content = "PlayerName, 제안할 만한 장소가 있나요?",
  str_homestory_815001001_40_dialog_content = "앗!",
  str_homestory_815001001_41_dialog_content = "PlayerName, 왜 그러죠?",
  str_homestory_815001001_42_dialog_content = "아무것도 아니야...",
  str_homestory_815001001_43_dialog_content = "갑자기 레노어가 진짜로 「제안」이 무슨 뜻인지 알게 된 것 같아서...",
  str_homestory_815001001_44_dialog_content = "조금 감동했다고나 할까...",
  str_homestory_801901001_0_dialog_content = "빅토리아 씨...",
  str_homestory_801901001_1_dialog_content = "안녕, PlayerName.",
  str_homestory_801901001_2_dialog_content = "응, 안녕.",
  str_homestory_801901001_3_dialog_content = "즐거움이 가득한 물의 흐름을 감상하던 중이야.\n같이 볼래?",
  str_homestory_801901001_4_dialog_content = "물의 흐름을 감상한다고...?",
  str_homestory_801901001_5_dialog_content = "...돌 위를 흐르는 물에 감상할 만한 게 있는 거야?",
  str_homestory_801901001_6_dialog_content = "이 물은 아무것도 모르는 상황에서\n이런 끝없는 순환에 참여했어.",
  str_homestory_801901001_7_dialog_content = "오로리안과 꽤 비슷한 것 같지 않아?",
  str_homestory_801901001_8_option_content = "(고개를 끄덕인다)",
  str_homestory_801901001_9_dialog_content = "조금 그런 것 같네...",
  str_homestory_801901001_10_dialog_content = "그래도 빅토리아 씨의 생각을 제대로 이해하진 못한 것 같아...",
  str_homestory_801901001_11_option_content = "(고개를 젓는다)",
  str_homestory_801901001_12_dialog_content = "빅토리아 씨, 미안...",
  str_homestory_801901001_13_dialog_content = "이해 못 했어.",
  str_homestory_801901001_14_dialog_content = "괜찮아. 그냥 아무 의미 없는 감상일 뿐이니까.",
  str_homestory_801901001_15_dialog_content = "빅토리아 씨는 어떻게 생각하는데?",
  str_homestory_801901001_16_dialog_content = "물의 흐름은 자신이 어떤 순환을\n따르고 있는지 몰라.",
  str_homestory_801901001_17_dialog_content = "왜냐하면 흐름 자체는 아무런 목적 없이\n이런 행동을 하는 거니까.",
  str_homestory_801901001_18_dialog_content = "순환에 속해야 하는 이유도,\n그 순환에서 벗어날 방법도...\n그리고 그 순환이 언제 끝날지조차 모르지.",
  str_homestory_801901001_19_dialog_content = "이런 점이 우리의 삶과 많이 닮았다고\n생각하지 않니?",
  str_homestory_801901001_20_dialog_content = "당연히 이런 점을 지적하거나\n가엽게 여기는 건 아니야.",
  str_homestory_801901001_21_dialog_content = "내게 있어 삶의 방식이라는 건 모두 똑같거든.",
  str_homestory_801901001_22_dialog_content = "그저 사색을 해 보려던 것뿐이야.",
  str_homestory_801901001_23_dialog_content = "...사색?",
  str_homestory_801901001_24_dialog_content = "그래.",
  str_homestory_801901001_25_dialog_content = "사색은 존중받아야 해.\n왜냐하면 지금은 이해할 수 없는 일들이\n결국 네게 동기를 유발하는 경우가 많으니까.",
  str_homestory_801901001_26_dialog_content = "...미지에 모종의 존경심을 가져야 한다는 뜻이야?",
  str_homestory_801901001_27_dialog_content = "비슷해.",
  str_homestory_801901001_28_dialog_content = "하지만 물의 흐름은 무척 즐거워 보이니까,\n내가 끼어들 필요는 전혀 없어.",
  str_homestory_801901001_29_dialog_content = "이런 순환 속에서 즐겁고 신나는 것도 좋은 일이야.",
  str_homestory_801901001_30_dialog_content = "그 말은... 물의 흐름은 빅토리아 씨랑은 다르게\n이런 일들로 감정이 북받쳐 오르지 않는다는 거지?",
  str_homestory_801901001_31_dialog_content = "후훗~ 그건 누가 알겠어.",
  str_homestory_801901001_32_dialog_content = "그건 그렇고... 여기 진짜 햇볕이 정말 세네<sprite=emo_taiyang size=60 />.",
  str_homestory_801901001_33_dialog_content = "앗, 그럼 저기 파라솔이 있는데, 거기서 쉴래?",
  str_homestory_801901001_34_dialog_content = "신경 써 줘서 고마워, PlayerName.\n하지만 난 이제 가서 좀 쉬어야겠어.",
  str_homestory_801901001_35_dialog_content = "진리가 그대를 축복하길.",
  str_homestory_800901001_0_dialog_content = "파우스트?",
  str_homestory_800901001_1_dialog_content = "조종사, 또 만났네.",
  str_homestory_800901001_2_dialog_content = "그러게.",
  str_homestory_800901001_3_dialog_content = "그래도 낮에 당신을 만나게 될 줄은 몰랐네.",
  str_homestory_800901001_4_dialog_content = "오해하지 마. 개인적으로는 밤을 더 좋아하지만,\n낮이 주는 에너지를 거부하진 않아.",
  str_homestory_800901001_5_dialog_content = "세티도 이곳이 마음에 든 모양이야.",
  str_homestory_800901001_6_dialog_content = "...잠깐만, 세티가 여길 마음에 들어 한다는 건 설마...",
  str_homestory_800901001_7_dialog_content = "여기 수많은 비극과 절망이 있다는 뜻이야?",
  str_homestory_800901001_8_dialog_content = "그 「특별」한 상자가 전에 내가 궁지에 몰린 걸 보고\n군침을 흘리던 게 아직도 기억이 난다고...",
  str_homestory_800901001_9_dialog_content = "어쩌면 다른 게 세티를 기분 좋게 만들어 줬기\n때문일지도 몰라.",
  str_homestory_800901001_10_dialog_content = "아마 「슬픈 기억」, 「악몽」, 「절망적인 신앙」,\n「얼음물」 중 하나겠지...",
  str_homestory_800901001_11_dialog_content = "뭐?!",
  str_homestory_800901001_12_dialog_content = "(전에 세티를 어떻게 돌봤었는지 생각해 보자...<sprite=emo_sikao size=60 />)",
  str_homestory_800901001_13_dialog_content = "(설마 다들 여기서 큰 슬픔을 느끼고... 악몽까지 꾸고 있는 건가?!)",
  str_homestory_800901001_14_dialog_content = "조종사, 그렇게 심각하게 생각하지 마.",
  str_homestory_800901001_15_dialog_content = "세티가 기분이 좋은 이유는...",
  str_homestory_800901001_16_dialog_content = "아마 오로리안들이 과거에 겪었던\n일들 때문일 거야. 지금 그들이 느끼고 있는\n감정 때문이 아니야.",
  str_homestory_800901001_17_dialog_content = "네가 알고 지내는 사람 중엔 참혹하고\n고통스러운 과거를 지닌 사람이 많잖아.",
  str_homestory_800901001_18_dialog_content = "그렇게 말하니까...",
  str_homestory_800901001_19_dialog_content = "음... 확실히 그렇네.",
  str_homestory_800901001_20_dialog_content = "그래도 난 되도록 모두가 여기서 기쁘게 지냈으면 좋겠어.",
  str_homestory_800901001_21_dialog_content = "기억과 감정이라는 건 완벽히\n제어할 수 없는 거야, 조종사.",
  str_homestory_800901001_22_dialog_content = "하지만 다른 사람에게 마음을 쓴다는 건\n좋은 습관이지.",
  str_homestory_800901001_23_dialog_content = "그냥 전부 자연스럽게 흘러가도록 해 봐.",
  str_homestory_800901001_24_dialog_content = "...알겠어.",
  str_homestory_800901001_25_dialog_content = "근데 여긴 왜 서 있던 거야?",
  str_homestory_800901001_26_option_content = "진리를 전파하려고?",
  str_homestory_800901001_27_dialog_content = "그건 아니야.",
  str_homestory_800901001_28_option_content = "세티한테 먹이를 주려고?",
  str_homestory_800901001_29_dialog_content = "맞아.",
  str_homestory_800901001_30_dialog_content = "여긴 세티한테 먹이를 주기에\n가장 좋은 장소거든...",
  str_homestory_800901001_31_dialog_content = "세티한테 오가는 사람들을 마음껏\n느끼게 해 줄 수 있어.",
  str_homestory_800901001_32_dialog_content = "「세티한테 오가는 사람들을 마음껏 느끼게 해 준다...」",
  str_homestory_800901001_33_dialog_content = "음... 설마 모두의 마음속에 말 못 할 고통이 그렇게 많았던 거야?",
  str_homestory_800901001_34_dialog_content = "그건 내가 단언할 수 없는 일이야, 조종사.",
  str_homestory_800901001_35_dialog_content = "하지만... 이거 하나는 확신할 수 있어.",
  str_homestory_800901001_36_dialog_content = "뭔데?",
  str_homestory_800901001_37_dialog_content = "외출하기 전에 세티가 방 안에서\n얼음물을 많이 마셨다는 거.",
  str_homestory_800901001_38_dialog_content = "......?",
  str_homestory_800901001_39_dialog_content = "그럼 세티가 기분 좋아 보였던 이유가...\n사실은 그냥 얼음물을 충분히 마셔서 그랬던 거야?!",
  str_homestory_800901001_40_dialog_content = "그러니까 모두가 슬픔이나 아픔 같은 부정적인 감정을\n품고 있던 건 아니라는 얘기네?",
  str_homestory_800901001_41_dialog_content = "뭐야... 그럼 완전히 보기 좋게... 당했잖아?!",
  str_homestory_800901001_42_dialog_content = "그렇다고 볼 수 있겠지, 조종사.",
  str_homestory_800901001_43_dialog_content = "하지만... 난 그저 네가 너무 걱정하지 않길\n바라는 마음에서 그랬던 거야.",
  str_homestory_800901001_44_dialog_content = "모든 일, 모든 사람을 다 완벽하게 신경 써 줄\n필요는 없거든. 안 그래?",
  str_homestory_800901001_45_dialog_content = "진리가 그대를 축복하길.",
  str_homestory_800901001_46_dialog_content = "...파, 파우스트...!<sprite=emo_shengqi size=60 />",
  str_homestory_815101001_0_dialog_content = "이 동요...",
  str_homestory_815101001_1_dialog_content = "「새까만 어린 양, 이름은 이사악.\n복슬복슬 쓰다듬다가 데어 버렸어...♪」",
  str_homestory_815101001_2_dialog_content = "안녕, 길스!",
  str_homestory_815101001_3_dialog_content = "아~ 우리 조종사였구나.",
  str_homestory_815101001_4_dialog_content = "네가 이 동요를 들어봤었다는 걸 깜빡 잊어버렸네.",
  str_homestory_815101001_5_dialog_content = "그럼 새로운 걸 해 볼 때가 된 건가?",
  str_homestory_815101001_6_dialog_content = "신비로운 아이테르가 주인공이고,\n뭔가 예언하는 느낌의 새로운 작품을 말이야...<sprite=emo_baimao size=60 />",
  str_homestory_815101001_7_dialog_content = "으엑...",
  str_homestory_815101001_8_dialog_content = "왜 마음에 안 든다는 표정일까? 조종사.",
  str_homestory_815101001_9_dialog_content = "그런 표정을 지으면 난 상처받게 될 거야...",
  str_homestory_815101001_10_dialog_content = "전에는 내 동요를 듣는 게\n제일 좋다고 하지 않았어?",
  str_homestory_815101001_11_dialog_content = "(...내가 정말 그런 말을 한 적이 있다고?)",
  str_homestory_815101001_12_option_content = "동요는 다 만들었어?",
  str_homestory_815101001_13_dialog_content = "영감만 받으면 만드는 건 금방이야.",
  str_homestory_815101001_14_dialog_content = "때마침 영감의 근원이 내 눈앞에 있으니까...",
  str_homestory_815101001_15_option_content = "잠깐만 기다려 줄래?",
  str_homestory_815101001_16_dialog_content = "설마 그럴싸한 핑곗거리도 없는 거야?",
  str_homestory_815101001_17_dialog_content = "나한테 그런 말은 깔끔한 거절이나 마찬가지야.",
  str_homestory_815101001_18_dialog_content = "매력적인 아이테르, 날렵한 아이테르,\n쉽게 남의 마음을 무너트리는 아이테르...",
  str_homestory_815101001_19_dialog_content = "...벌써 부르기 시작한 거야?",
  str_homestory_815101001_20_dialog_content = "「라랄라, 라랄라, 아름다운 집엔 꽃이 있다네.」",
  str_homestory_815101001_21_dialog_content = "「아기 물고기, 아기 새우,\n이곳을 집으로 삼았다네.」",
  str_homestory_815101001_22_dialog_content = "「이곳에 살고 있는 동식물과 그녀가\n두려움을 모르는 그를 둘러싸고 있지.」",
  str_homestory_815101001_23_dialog_content = "「후두둑, 주르륵, 시간의 빗방울이\n하나씩 땅에 내려앉고.」",
  str_homestory_815101001_24_dialog_content = "「높은 탑을 짓고, 벽돌과 기와로 무장해\n더 강해질 방법을 찾네.」",
  str_homestory_815101001_25_dialog_content = "「라랄라, 라랄라, 그는 어디에 갔을까?」",
  str_homestory_815101001_26_dialog_content = "「집은 이미 커다래졌는데, 그는 구름 속에서\n눈 하나 깜짝하지 않네.」",
  str_homestory_815101001_27_dialog_content = "「라랄라, 라랄라... 아름다운 집엔 꽃이 있네...」",
  str_homestory_815101001_28_dialog_content = "...그, 그거 예언이야?",
  str_homestory_815101001_29_dialog_content = "그냥 단순한 동요야, 조종사.",
  str_homestory_815101001_30_dialog_content = "겁먹었어? 그냥 동요 한 곡 만든 것뿐인데...",
  str_homestory_815101001_31_dialog_content = "음... 그건 알고 있어.",
  str_homestory_815101001_32_dialog_content = "다만 길스의 동요는... 매번 단순하면서도 난해하다는 느낌이 들거든.",
  str_homestory_815101001_33_dialog_content = "동요는 그저 동요일 뿐이야.",
  str_homestory_815101001_34_dialog_content = "복잡한 의미를 둘 필요는 없다구.",
  str_homestory_815101001_35_dialog_content = "좋아, 그럼 더 현실적인 이야기를 해보자...",
  str_homestory_815101001_36_dialog_content = "여긴 어떤 것 같아? 지낼 만해?",
  str_homestory_815101001_37_dialog_content = "나랑 이사악 둘 다 이곳이 아주 마음에 들어.",
  str_homestory_815101001_38_dialog_content = "이곳에 있으면 항상 창작 욕구가\n불타오르거든... 하하!",
  str_homestory_815101001_39_dialog_content = "오가는 사람들은 물론이고, 조종사 너도...\n내겐 더할 나위 없는 좋은 소재야.<sprite=emo_emo size=60 />",
  str_homestory_815101001_40_dialog_content = "그래...",
  str_homestory_815101001_41_dialog_content = "메에에~ 메에에에에~",
  str_homestory_815101001_42_dialog_content = "잠깐 이사악이랑 둘만 좀 있어야 할 것 같아.",
  str_homestory_815101001_43_dialog_content = "그럼 다음에 또 만날까?",
  str_homestory_815101001_44_dialog_content = "응... 다음에 또 봐.",
  str_homestory_815301001_0_dialog_content = "라인하르트 씨?",
  str_homestory_815301001_1_dialog_content = "이곳은 기초 시설이 잘 갖추어져 있군.<sprite=emo_dianzan size=60 />",
  str_homestory_815301001_2_dialog_content = "치, 칭찬 감사해요! 라인하르트 씨!",
  str_homestory_815301001_3_dialog_content = "일루미나의 정돈되고 획일화된 광장만 보다가\n여길 보니 색다른 느낌이야.",
  str_homestory_815301001_4_dialog_content = "많은 이들이 우리 일루미나는 예술에 조예가 없고\n아름다움을 추구하지 않는다고들 하지.",
  str_homestory_815301001_5_dialog_content = "애석하게도 그렇게 유달리 예술을 추구하는 곳은\n사람들이 밥도 못 먹고 지내는 경우가 많다.",
  str_homestory_815301001_6_dialog_content = "규격화된 물건은 원가가 낮고 효과도\n빠르게 나타난다. 이건 아주 간단한 이치라고.",
  str_homestory_815301001_7_dialog_content = "그래도 역시 이곳은 참 아름답군.",
  str_homestory_815301001_8_dialog_content = "아름답고 정갈해. 바이스와 함께\n상당한 공을 들였겠지.",
  str_homestory_815301001_9_option_content = "(고개를 끄덕인다)",
  str_homestory_815301001_10_dialog_content = "저보다는 바이스가 수고했죠... 저는 건축 쪽으로는 아는 게 별로 없어서요.",
  str_homestory_815301001_11_dialog_content = "음, 자신의 부족한 점을 인정할 줄\n아는 것도 장점이다.",
  str_homestory_815301001_12_option_content = "(고개를 젓는다)",
  str_homestory_815301001_13_dialog_content = "에이, 뭘요. 파이어플라이가 저흴 많이 도와줬어요.\n그리고 쿠리어 길드의 친구들도요.",
  str_homestory_815301001_14_dialog_content = "그래도 다들 즐거우면 그걸로 됐어요.\n사실 저희는 특별히 한 것도 없는걸요.",
  str_homestory_815301001_15_dialog_content = "너희의 그 인품이야말로 가장 가지기\n어려운 것 아니겠나.",
  str_homestory_815301001_16_dialog_content = "내가 보기엔 특별한 점이 없는 것도\n일종의 특별함이다.",
  str_homestory_815301001_17_dialog_content = "네가 정한 대로, 난 이곳에서...",
  str_homestory_815301001_18_dialog_content = "바이스와 같은 방을 사용하고, 같은 식사를 한다.",
  str_homestory_815301001_19_dialog_content = "난 이것이 평소 다른 사람들이 나를 대하는\n태도보다 훨씬 좋다고 생각한다.",
  str_homestory_815301001_20_dialog_content = "신분에 따라 사람을 다르게 대하지 않는 것...\n이런 평등한 방식은 참 드문 것이지.",
  str_homestory_815301001_21_dialog_content = "(일루미나의 대원수가 이런 관점에서 생각할 줄은 몰랐네...)",
  str_homestory_815301001_22_dialog_content = "(사실대로 말해 드려야 하나?)",
  str_homestory_815301001_23_dialog_content = "(그래, 역시 사실을 알려주자...)",
  str_homestory_815301001_24_dialog_content = "크흠, 사실은 그게 말이죠...",
  str_homestory_815301001_25_dialog_content = "더 좋은 방을 만들고 싶었지만 돈이 없었거든요...",
  str_homestory_815301001_26_dialog_content = "음, 알고 있다.",
  str_homestory_815301001_27_dialog_content = "그러나 핵심은 예산이 아니라 계획이다.\n네가 그 돈을 어떻게 쓸지 생각했던 계획 말이다.",
  str_homestory_815301001_28_dialog_content = "왜, 왠지 조금은 이해한 것 같아요.",
  str_homestory_815301001_29_dialog_content = "이해했다면 됐다.",
  str_homestory_815301001_30_dialog_content = "그럼 다른 일루미나 동포들은 뭘 하고 있는지\n좀 둘러봐야겠군.",
  str_homestory_815301001_31_dialog_content = "다음에 또 보도록 하지, PlayerName.",
  str_homestory_815301001_32_dialog_content = "아, 안녕히 가세요!",
  str_homestory_803801001_0_dialog_content = "또 게임이야?",
  str_homestory_803801001_1_dialog_content = "안녕! PlayerName!",
  str_homestory_803801001_2_dialog_content = "헤헤... 이렇게 날 찾아온 걸 보니까\n나랑 게임하고 싶었구나?",
  str_homestory_803801001_3_dialog_content = "그런 거 아냐.",
  str_homestory_803801001_4_dialog_content = "그냥 이곳을 어떻게 생각하는지, 여기 생활엔 익숙해졌는지 물어보려고 왔어.",
  str_homestory_803801001_5_dialog_content = "으음...",
  str_homestory_803801001_6_dialog_content = "오락시설이 좀 적다는 것만 빼면 나쁘지 않아.",
  str_homestory_803801001_7_dialog_content = "아~ 알았어. 친절한 조종사가 심심한 날\n구해주러 온 거지? 그렇지?",
  str_homestory_803801001_8_dialog_content = "아... 그게...",
  str_homestory_803801001_9_dialog_content = "헤헤! 그럼 우리 간단한 게임 한 판 할까?",
  str_homestory_803801001_10_dialog_content = "아주 간단해! 아무런 기기 없이도\n플레이할 수 있는 게임이야!",
  str_homestory_803801001_11_dialog_content = "혹시 그 게임이란 거... 가위바위보야?",
  str_homestory_803801001_12_dialog_content = "아니거든. 퀴즈야!",
  str_homestory_803801001_13_dialog_content = "준비됐어? 이제 바로 시작할 거라구.",
  str_homestory_803801001_14_dialog_content = "알았어... 네가 기대하는 것 같으니까... 한번 해 볼게.",
  str_homestory_803801001_15_dialog_content = "첫 번째 문제! 네 또는 아니요로 대답해야 돼!",
  str_homestory_803801001_16_dialog_content = "「일루미나 연구원장 그로누의 신비한 정체...\n사실 그로누는... 로봇이었다!」",
  str_homestory_803801001_17_option_content = "(네)",
  str_homestory_803801001_18_dialog_content = "뭐라고? 난 로봇 아니거든!",
  str_homestory_803801001_19_option_content = "(아니요)",
  str_homestory_803801001_20_dialog_content = "딩동댕! 정답입니다!<sprite=emo_dianzan size=60 />",
  str_homestory_803801001_21_dialog_content = "두 번째 문제!",
  str_homestory_803801001_22_dialog_content = "라파엘은 전에 「왕좌 토너먼트」에서\n그로누를 쓰러트린 적이 있다!",
  str_homestory_803801001_23_option_content = "(네)",
  str_homestory_803801001_24_dialog_content = "야, 내가 훨씬 더 대단하거든!",
  str_homestory_803801001_25_dialog_content = "라파엘의 장난감들을 업그레이드해 준 것도\n바로 나라구~",
  str_homestory_803801001_26_option_content = "(아니요)",
  str_homestory_803801001_27_dialog_content = "정답이야! 잘했어!",
  str_homestory_803801001_28_dialog_content = "세 번째 문제!",
  str_homestory_803801001_29_dialog_content = "조종사는 이곳의 가동 시스템 권한을\n그로누에게 줄 것이다!",
  str_homestory_803801001_30_dialog_content = "예... 뭐?",
  str_homestory_803801001_31_dialog_content = "잠깐만, 그건 퀴즈에 나올 만한 문제가 전혀 아니잖아?",
  str_homestory_803801001_32_dialog_content = "에이, 안 되는 거야?",
  str_homestory_803801001_33_dialog_content = "크흠... 당연히 안 되지.",
  str_homestory_803801001_34_dialog_content = "흥, 날 거절했다 이거야?",
  str_homestory_803801001_35_dialog_content = "최종 보스한테 조종당하고 있는 게 분명해!",
  str_homestory_803801001_36_dialog_content = "조종? 그게 무슨 말이야?",
  str_homestory_803801001_37_dialog_content = "진정한 아이테르가 어떻게 나한테\n「안 돼」라는 말을 할 수 있어?",
  str_homestory_803801001_38_dialog_content = "상냥하고 친절한 아이테르 소년은 내 수많은\n부탁을 다 들어줬었잖아!",
  str_homestory_803801001_39_dialog_content = "풉...",
  str_homestory_803801001_40_dialog_content = "다른 건 다 되는데 콜로서스랑 여기 권한만큼은 안 돼.",
  str_homestory_803801001_41_dialog_content = "에이... 재미없어...",
  str_homestory_803801001_42_dialog_content = "그래도...",
  str_homestory_803801001_43_dialog_content = "대놓고 연구할 수 없다면 몰래라도\n연구하고 말 거야!",
  str_homestory_803801001_44_dialog_content = "언젠가는... 헤헤, 언젠가는 이곳의 시스템이\n어떻게 작동하는 건지 꼭 밝혀내고 말겠어.",
  str_homestory_803801001_45_dialog_content = "그...그래.",
  str_homestory_803801001_46_dialog_content = "그럼 행운을 빌게.",
  str_homestory_803801001_47_dialog_content = "새 게임이 시작됐네! 정말 기대되는걸...<sprite=emo_yaosu size=60 />",
  str_homestory_802601001_0_dialog_content = "우리엘...",
  str_homestory_802601001_1_dialog_content = "......",
  str_homestory_802601001_2_dialog_content = "............",
  str_homestory_802601001_3_dialog_content = "나한테... 무슨 볼일 있어...?",
  str_homestory_802601001_4_dialog_content = "아, 별일은 아니고... 그냥 얼굴 좀 보러 왔어.",
  str_homestory_802601001_5_dialog_content = "혹시 뭐 불편한 거 있을까 걱정됐거든.\n넌 콜로서스에서도 자주 잠을 못 자고 뒤척였잖아.",
  str_homestory_802601001_6_dialog_content = "딱히 불편한 건 없어...",
  str_homestory_802601001_7_dialog_content = "어차피 내가 익숙해질 수 있는 건\n화염 제어의 환이랑 깃털옷이 전부니까...",
  str_homestory_802601001_8_dialog_content = "으엑... 그럼 혹시 더 필요한 건 없어?",
  str_homestory_802601001_9_dialog_content = "음식이나 장난감... 아니면 뭐 있었으면 좋겠다는 거라든지 말이야.",
  str_homestory_802601001_10_dialog_content = "원하는 게 있으면 나한테 다 말해 줘!",
  str_homestory_802601001_11_dialog_content = "딱히 필요한 건 없어...",
  str_homestory_802601001_12_dialog_content = "어차피 뭘 줘도 모조리<sprite=emo_nuhuo size=60 /> 태워 버릴 테니까...",
  str_homestory_802601001_13_dialog_content = "아, 아니야. 그럴 일 없을 거야, 우리엘.",
  str_homestory_802601001_14_dialog_content = "내가 특별히 방화 시설을 만들어 뒀어.\n그러니까 걱정하지 마. 여기선 그런 걱정 없이 지내도 돼!",
  str_homestory_802601001_15_dialog_content = "그렇구나...",
  str_homestory_802601001_16_dialog_content = "맞아!",
  str_homestory_802601001_17_dialog_content = "그럼 혹시 뭔가 필요한 게 떠올랐어?",
  str_homestory_802601001_18_dialog_content = "......",
  str_homestory_802601001_19_dialog_content = "............없어.",
  str_homestory_802601001_20_dialog_content = "장난감도 그렇고, 오락 시설도 그렇고...\n그런 게 주는 즐거움은 눈 깜짝할 사이에\n사라져 버려...",
  str_homestory_802601001_21_dialog_content = "짧을 뿐만 아니라 아주 하찮아...",
  str_homestory_802601001_22_dialog_content = "몇 분, 몇 초 동안 즐겁게 보내고 나면...\n또다시 끝없는 고통이 찾아 와...",
  str_homestory_802601001_23_dialog_content = "이렇게 고통스러운 화염에 불타오르는 대가가\n고작 그렇게나 짧은 즐거움에 불과하다니...",
  str_homestory_802601001_24_dialog_content = "그런 즐거움은... 차라리 거부할래...",
  str_homestory_802601001_25_dialog_content = "게다가... 고통이 지나갈 때마다 항상\n「즐거움」을 얻을 수 있는 것도 아니잖아...",
  str_homestory_802601001_26_dialog_content = "오히려 이런 짧은 「즐거움」 때문에\n모든 고통이 가치 있다고 오해하게 돼 버려...",
  str_homestory_802601001_27_dialog_content = "사실은 그렇지 않은데 말이야...\n고통은 끝이 없지만,\n「즐거움」은 한계가 있잖아...<sprite=emo_xinsui size=60 />",
  str_homestory_802601001_28_dialog_content = "...내 말이 틀렸어? PlayerName...",
  str_homestory_802601001_29_dialog_content = "(일리가 있는 것 같지만, 왠지 우리엘의 논리를 이해할 수가 없어...)",
  str_homestory_802601001_30_option_content = "그래.",
  str_homestory_802601001_31_dialog_content = "어떤 의미에서는 네 말이 맞을 거야, 우리엘.",
  str_homestory_802601001_32_option_content = "그렇지 않아.",
  str_homestory_802601001_33_dialog_content = "우리엘이 왜 그렇게 생각하는지는 알겠어. 하지만 내 관점은 조금 다른 것 같아...",
  str_homestory_802601001_34_dialog_content = "(어쨌든 일단은 우리엘을 위로하는 게 중요해...)",
  str_homestory_802601001_35_dialog_content = "우리엘은 고통 끝에 오는 즐거움을 짧고 하찮다고 느끼겠지만...",
  str_homestory_802601001_36_dialog_content = "사람들은 바로 그 한 줌의 「즐거움」을 위해서 살아가고 있는걸.",
  str_homestory_802601001_37_dialog_content = "그리고 사람들은 고통을 겪은 후에 얻는 「즐거움」을 「희망」으로 여기기도 해.",
  str_homestory_802601001_38_dialog_content = "그 「희망」은 사람들이 다음, 그리고 그다음 「즐거움」을 기대하게 만드는 거야...",
  str_homestory_802601001_39_dialog_content = "비록 즐거움은 짧고 미미할지도 몰라. 하지만 그것도 그 순간엔 위로가 돼.",
  str_homestory_802601001_40_dialog_content = "「즐거움」은 고통 끝에 오는 보상이 아니야.",
  str_homestory_802601001_41_dialog_content = "반대로 즐거움은 사람이 고통을 참아낼 수 있도록 해 주는 양식인 거야.",
  str_homestory_802601001_42_dialog_content = "......",
  str_homestory_802601001_43_dialog_content = "...양식...",
  str_homestory_802601001_44_dialog_content = "...그럴 수도 있겠네...",
  str_homestory_802601001_45_dialog_content = "(음, 우리엘은 그렇게 생각하지 않는 모양이네...)",
  str_homestory_802601001_46_dialog_content = "아...아무튼, 우리엘이 즐거움을 부담으로 여기지 않았으면 좋겠어!",
  str_homestory_802601001_47_dialog_content = "...응...",
  str_homestory_802601001_48_dialog_content = "...알겠어, PlayerName...",
  str_homestory_802601001_49_dialog_content = "...신경 써 줘서... 고마워...",
  str_homestory_802601001_50_dialog_content = "아니야, 별일도 아닌데 뭐...",
  str_homestory_802601001_51_dialog_content = "아... 즐거움 얘기가 나와서 말인데...",
  str_homestory_802601001_52_dialog_content = "(우리엘은 책 읽는 걸 좋아했던 것 같은데...\n움브라톤에서 유행하는 「문학 작품」 같은 거였나...)",
  str_homestory_802601001_53_dialog_content = "참, 우리엘. 내가 책 좀 빌려다 줄까?",
  str_homestory_802601001_54_dialog_content = "심심하면 여기서 책을 읽어도 좋을 것 같아.",
  str_homestory_802601001_55_dialog_content = "그리고 태워버릴까 걱정 안 해도 돼.\n여긴 사람이 많으니까 한 책을 여러 권씩 준비해 뒀거든...",
  str_homestory_802601001_56_dialog_content = "...책...?",
  str_homestory_802601001_57_dialog_content = "............",
  str_homestory_802601001_58_dialog_content = "...좋아...",
  str_homestory_802601001_59_dialog_content = "읽을게...",
  str_homestory_802601001_60_dialog_content = "휴... 좋아.",
  str_homestory_804401001_0_dialog_content = "비비안 씨?",
  str_homestory_804401001_1_dialog_content = "그네는 정말 재미있네요, PlayerName!",
  str_homestory_804401001_2_dialog_content = "응, 나도 그렇게 생각해.",
  str_homestory_804401001_3_dialog_content = "그저 불어오는 바람을 맞으면서,\n아무 생각도 안 하는 거죠...<sprite=emo_pugongying size=60 />",
  str_homestory_804401001_4_dialog_content = "그네가 몸을 바람 속으로 이끌어 주면...",
  str_homestory_804401001_5_dialog_content = "스트레스가 신기하게도 싹 사라져 버려요.",
  str_homestory_804401001_6_dialog_content = "비비안 씨가 마음이 편해진다니 다행이네.",
  str_homestory_804401001_7_dialog_content = "으음, 대신 그네 타기의 유일한 단점이 있다면...",
  str_homestory_804401001_8_dialog_content = "타고 난 뒤에 머리가 좀 헝클어진다는\n거겠네요~ 아하하.",
  str_homestory_804401001_9_dialog_content = "그랬구나!",
  str_homestory_804401001_10_dialog_content = "그래서 매번 바이스가 그네를 타고 나면 머리를 정리하는 거였어!",
  str_homestory_804401001_11_dialog_content = "어머~ 그럼 이 그네는 당신과 바이스 중에\n누가 만들자고 한 건가요?",
  str_homestory_804401001_12_option_content = "나야.",
  str_homestory_804401001_13_dialog_content = "사실 난 그네를 타 본 적이 별로 없어...",
  str_homestory_804401001_14_dialog_content = "그래서 여기에 그네를 하나 두면 좋지 않을까 싶더라구.",
  str_homestory_804401001_15_option_content = "바이스야.",
  str_homestory_804401001_16_dialog_content = "바이스가 여기 그네를 꼭 하나는 둬야 한다고 주장했었거든!",
  str_homestory_804401001_17_dialog_content = "처음엔 조금 주저했는데...\n바이스가 자신만만하게 시공 도면을 그리는 걸 보고 나니까...",
  str_homestory_804401001_18_dialog_content = "그네 하나 정도 두는 것도 나쁘지 않겠다고 생각했어. 그리고 다들 좋아할 테니까.",
  str_homestory_804401001_19_dialog_content = "어머...",
  str_homestory_804401001_20_dialog_content = "정말 잘 결정하셨네요!",
  str_homestory_804401001_21_dialog_content = "헤헤... 칭찬 고마워, 비비안 씨.",
  str_homestory_804401001_22_dialog_content = "근데 생각해 보니...",
  str_homestory_804401001_23_dialog_content = "일루미나엔 그네가 있는 곳이 드물었던 것 같네요.",
  str_homestory_804401001_24_dialog_content = "아... 그런 것 같기도 하네.",
  str_homestory_804401001_25_dialog_content = "그래서 바이스랑 비비안 씨가 이 그네를 좋아하는 걸까?",
  str_homestory_804401001_26_dialog_content = "맞아요. 아마 별로 본 적이 없는 거라서\n특히 더 좋아하는 걸지도 모르겠어요.",
  str_homestory_804401001_27_dialog_content = "아... 그러고 보니까...",
  str_homestory_804401001_28_dialog_content = "응? 뭔가 생각났어?",
  str_homestory_804401001_29_dialog_content = "음, 아무것도 아니에요.",
  str_homestory_804401001_30_dialog_content = "그냥 이게 필요한 지출<sprite=emo_baiyebi size=60 />인지 생각해 보던 중이었어요.",
  str_homestory_804401001_31_dialog_content = "지출?!",
  str_homestory_804401001_32_dialog_content = "무슨 지출?!",
  str_homestory_804401001_33_dialog_content = "일루미나의 모든 보육원과 학교, 그리고...",
  str_homestory_804401001_34_dialog_content = "관련 기반 시설에 그네를 하나씩 두려면\n비용이 얼마나 들까 해서요.",
  str_homestory_804401001_35_dialog_content = "아... 그랬구나.",
  str_homestory_804401001_36_dialog_content = "살짝 계산해 봤는데,\n예산을 조금 초과할 것 같네요...",
  str_homestory_804401001_37_dialog_content = "만약 이 방안을 실행하려면 다른 항목의\n지출을 줄여야겠죠.",
  str_homestory_804401001_38_dialog_content = "아, 그건 좀 어렵겠네요.",
  str_homestory_804401001_39_dialog_content = "그럼... 다는 말고 몇 군데만 설치한다면?",
  str_homestory_804401001_40_dialog_content = "설치 대수를 줄이는 대신 위치를 잘 따져서 선택하는 방법은 어때?",
  str_homestory_804401001_41_dialog_content = "예를 들면...",
  str_homestory_804401001_42_dialog_content = "모든 사람이 지나다니는 곳에\n설치해 둔다든지 말이야!",
  str_homestory_804401001_43_dialog_content = "각 지하성의 경계 부근이나 몇몇 보육원이나\n학교 같은 곳에 둬도 좋을 것 같고...",
  str_homestory_804401001_44_dialog_content = "정말 좋은 생각이에요, PlayerName!",
  str_homestory_804401001_45_dialog_content = "도움이 됐다니 기뻐.",
  str_homestory_804401001_46_dialog_content = "근데...",
  str_homestory_804401001_47_dialog_content = "방금 제가 지출 얘길 했을 때\n왜 그렇게 긴장한 거죠?",
  str_homestory_804401001_48_dialog_content = "아, 하하...",
  str_homestory_804401001_49_dialog_content = "바이스가 장부를 보면서 하는 말이랑 완전히 똑같아서...",
  str_homestory_804401001_50_dialog_content = "뭔가 조건 반사적으로 긴장해 버렸지 뭐야!",
  str_homestory_804401001_51_dialog_content = "어머, 역시 바이스랑 PlayerName 당신은\n정말 사이가 좋네요...<sprite=emo_guilian size=60 />",
  str_homestory_808501001_0_dialog_content = "제인?",
  str_homestory_808501001_1_dialog_content = "안녕하세요, PlayerName.",
  str_homestory_808501001_2_dialog_content = "응, 안녕!",
  str_homestory_808501001_3_dialog_content = "헤븐즈 가든에 대해... 기록하던 중이었어?",
  str_homestory_808501001_4_dialog_content = "네, 저는 이곳에서 일어나는 모든 일을\n기록할 겁니다.",
  str_homestory_808501001_5_dialog_content = "하지만 지금은 기록하던 중이 아니라,\n단순히 머리를 비우고 쉬던 중이었어요.<sprite=emo_pugongying size=60 />",
  str_homestory_808501001_6_dialog_content = "머리를 비워?",
  str_homestory_808501001_7_dialog_content = "왜? 무슨 안 좋은 일이라도 있었어?",
  str_homestory_808501001_8_dialog_content = "아니면 요즘 스트레스를 많이 받았어?",
  str_homestory_808501001_9_dialog_content = "둘 다라고 할 수 있겠네요.",
  str_homestory_808501001_10_dialog_content = "PlayerName, 저는 「증언자」이기 때문에,\n어떤 일에는 관여할 수 없다는 걸 알고 있겠죠.",
  str_homestory_808501001_11_dialog_content = "응, 들은 적 있어.",
  str_homestory_808501001_12_dialog_content = "그럼...",
  str_homestory_808501001_13_dialog_content = "만약 당신이 「증언자」라면,\n클랜 내부 투쟁의 피해자를 도울 건가요?",
  str_homestory_808501001_14_option_content = "도울 거야.",
  str_homestory_808501001_15_dialog_content = "증언자라고는 해도 직업일 뿐이니까...",
  str_homestory_808501001_16_option_content = "안 도울 거야.",
  str_homestory_808501001_17_dialog_content = "사실 「절대적으로 객관적인 태도를 유지」해야 한다는 건\n나한테는 그렇게 중요하지 않은 것 같아...",
  str_homestory_808501001_18_dialog_content = "어쩌면 바로 다른 사람한테 말해서 도와달라고 했을 것 같아.",
  str_homestory_808501001_19_dialog_content = "타인을 돕기는 하겠지만,\n직접 나서지는 않겠다는 거군요.",
  str_homestory_808501001_20_dialog_content = "맞아.",
  str_homestory_808501001_21_dialog_content = "그럼 제인 넌 어떻게 했는데?",
  str_homestory_808501001_22_dialog_content = "고민 가득한 얼굴로 그런 질문을 한 거 보니까\n진짜 겪은 일 같은데 말이야.",
  str_homestory_808501001_23_dialog_content = "맞습니다. 그리고 저는 그 소녀를 도와줬죠.",
  str_homestory_808501001_24_dialog_content = "게다가 지금은 제가 이미 내린 선택 때문에\n고민하는 중이죠.",
  str_homestory_808501001_25_dialog_content = "뭘 걱정하는 건데?",
  str_homestory_808501001_26_dialog_content = "제가 개입한 탓에 사건이 다르게\n흘러가는 게 걱정입니다.",
  str_homestory_808501001_27_dialog_content = "증언자가 흔들리면 그 증언의 중립성도\n떨어지게 되죠.",
  str_homestory_808501001_28_dialog_content = "아마 그 소녀는 사라져야 했을지도 모릅니다.\n그게 바로 내부 항쟁의 진정한 결과니까요.",
  str_homestory_808501001_29_dialog_content = "하지만 저는 그 소녀를 구했고...",
  str_homestory_808501001_30_dialog_content = "...때문에 중립성을 잃은 증언은\n아무 의미가 없어졌죠.",
  str_homestory_808501001_31_dialog_content = "그렇지만... 「중립」을 유지해야 하는 「증언자」라 해도,\n그게 우선은 아니야. 너도 감정이 있는 사람이잖아.",
  str_homestory_808501001_32_dialog_content = "그건 저도 알고 있습니다.",
  str_homestory_808501001_33_dialog_content = "......",
  str_homestory_808501001_34_dialog_content = "...알겠어.",
  str_homestory_808501001_35_dialog_content = "그렇게 걱정되면 차라리 너 자신에 대해서도 증언에 기록하는 건 어때?",
  str_homestory_808501001_36_dialog_content = "저를 증언에 기록하란 건가요...?",
  str_homestory_808501001_37_dialog_content = "그러니까... 어떤 일이 있었는지 사실대로 적는 거야.",
  str_homestory_808501001_38_dialog_content = "증언자가 감정의 동요로 내부 분열 사건의 사후 처리에 개입을 했고...\n사건에 새로운 영향을 줄지도 모른다... 라고?",
  str_homestory_808501001_39_dialog_content = "...뭐, 아무튼 그런 식으로 기록을 넣는 거지.",
  str_homestory_808501001_40_dialog_content = "......",
  str_homestory_808501001_41_dialog_content = "일리가 없는 말은 아니군요.",
  str_homestory_808501001_42_dialog_content = "이번 일은 그렇게 기록해 보도록 하겠습니다.",
  str_homestory_808501001_43_dialog_content = "고마워요.",
  str_homestory_808801001_0_dialog_content = "마지!",
  str_homestory_808801001_1_dialog_content = "아... 호, 혹시 조종사 씨도 그 이야기를\n들으러 오셨나요?<sprite=emo_wuzui size=60 />",
  str_homestory_808801001_2_dialog_content = "그 이야기? 무슨 이야기?",
  str_homestory_808801001_3_dialog_content = "그냥 너랑 얘기나 좀 하려고 온 건데? 근데 그 이야기라는 게 뭔지도 궁금해졌어.",
  str_homestory_808801001_4_dialog_content = "이, 이런... 제가 괜한 말을 했네요...",
  str_homestory_808801001_5_dialog_content = "응? 나한테는 들려주고 싶지 않은 거야?",
  str_homestory_808801001_6_dialog_content = "그, 그런 게 아니에요...",
  str_homestory_808801001_7_dialog_content = "알겠어요... 어차피 알 사람들은 다 아니까요...",
  str_homestory_808801001_8_dialog_content = "대체 무슨 일인데 그래?",
  str_homestory_808801001_9_dialog_content = "그러니까...\n며칠 전에 제가 사막을 뒤지고 있을 때...",
  str_homestory_808801001_10_dialog_content = "꼬마애 몇 명을 만났거든요.",
  str_homestory_808801001_11_dialog_content = "딱 봐도 집에서 몰래 뛰쳐나와서 사막으로 왔다가\n길을 잃은 애들이라는 걸 알 수 있었어요...",
  str_homestory_808801001_12_dialog_content = "같은 자리를 계속 맴돌길래 혹시 도움이 필요한지\n물어봤어요.",
  str_homestory_808801001_13_dialog_content = "그리고 안전한 곳까지 데려다주고 나니까...\n그, 그 애들이 제 이름을 물어봤어요...\n전 감사 인사를 하려는 줄 알았어요.",
  str_homestory_808801001_14_dialog_content = "그래서 이름을 알려 주려고 했는데\n걔들이 제 꼬리를 본 거예요... 그리고는...",
  str_homestory_808801001_15_option_content = "널 놀렸어?",
  str_homestory_808801001_16_dialog_content = "아, 아니요...",
  str_homestory_808801001_17_dialog_content = "저, 저보고 꼬리가 너무 귀엽다는 거예요!",
  str_homestory_808801001_18_dialog_content = "그럼 좋은 거 아냐?",
  str_homestory_808801001_19_option_content = "네가 누군지 알아봤어?",
  str_homestory_808801001_20_dialog_content = "아니요...",
  str_homestory_808801001_21_dialog_content = "전 플뢰르가 아닌걸요. 하나도 안 유명해요...",
  str_homestory_808801001_22_dialog_content = "그, 그게... 그 애들이 절...",
  str_homestory_808801001_23_dialog_content = "요, 용이라고 생각하더라니까요!",
  str_homestory_808801001_24_dialog_content = "......?",
  str_homestory_808801001_25_dialog_content = "그때 제 반응도 지금 PlayerName 씨 반응이랑\n거의 똑같았어요...",
  str_homestory_808801001_26_dialog_content = "진짜 어이가 없었다니까요!",
  str_homestory_808801001_27_dialog_content = "게다가 저한테 꼬리가 복슬복슬한\n용은 처음 본다면서...",
  str_homestory_808801001_28_dialog_content = "꼬리 좀 만지게 해 주면 안 되겠냐고\n하더라니까요...",
  str_homestory_808801001_29_dialog_content = "전 그때 정말 화가 잔뜩 났어요...!<sprite=emo_wuyun size=60 />",
  str_homestory_808801001_30_dialog_content = "왜 화가 나? 애들한테 바로 설명해 주면 되잖아?",
  str_homestory_808801001_31_dialog_content = "잘못 안 것 때문에 화난 게 아니라\n태도 때문에 화가 났던 거예요!",
  str_homestory_808801001_32_dialog_content = "「꼬리 좀 만지게 해 주세요」...",
  str_homestory_808801001_33_dialog_content = "이게 대체 말이나 되는 소리야?!",
  str_homestory_808801001_34_dialog_content = "날 애완동물처럼 생각하고 있으니까\n그런 말을, 그런 요구를 하는 거 아냐?!",
  str_homestory_808801001_35_dialog_content = "열받아... 열받아 죽겠어...",
  str_homestory_808801001_36_dialog_content = "모든 걸 불태워<sprite=emo_nuhuo size=60 /> 버리겠어! 지금 당장!",
  str_homestory_808801001_37_dialog_content = "(또 이런 상태가 돼버렸잖아?!)",
  str_homestory_808801001_38_dialog_content = "자, 잠깐만, 마지!",
  str_homestory_808801001_39_dialog_content = "그저 꼬리가 귀여워 보여서 그랬을 수도 있잖아?",
  str_homestory_808801001_40_dialog_content = "나, 나도 그렇게 생각하긴 해!",
  str_homestory_808801001_41_dialog_content = "...사실 난 꼬리가 없는 마지는 상상도 못 하겠어.",
  str_homestory_808801001_42_dialog_content = "............",
  str_homestory_808801001_43_dialog_content = "...정, 정말요?",
  str_homestory_808801001_44_dialog_content = "(휴우... 조금 진정된 모양이네...)",
  str_homestory_808801001_45_dialog_content = "정말이야, 마지. 진짜야, 진짜!",
  str_homestory_808801001_46_dialog_content = "...그...그럼 됐어요...",
  str_homestory_808801001_47_dialog_content = "아, 맞다.",
  str_homestory_808801001_48_dialog_content = "왜 아까 어차피 알 사람들은 다 안다고 했던 거야?",
  str_homestory_808801001_49_dialog_content = "내가 알기로는 아는 사람이 몇 명 없는 것 같은데...",
  str_homestory_808801001_50_dialog_content = "그, 그건...",
  str_homestory_808801001_51_dialog_content = "조무가 이 이야기를 자기의 최신 단편 소설집에\n수록해 버렸거든요...",
  str_homestory_808801001_52_dialog_content = "...그랬구나. 진작 그랬을 거라고 생각했어야 했는데...",
  str_homestory_800801001_0_dialog_content = "렉커?",
  str_homestory_800801001_1_dialog_content = "하하! 왔구나!<sprite=emo_yaosu size=60 />",
  str_homestory_800801001_2_dialog_content = "어때? 아까 봤어? 나 멋있지 않냐?",
  str_homestory_800801001_3_dialog_content = "...어느 부분을 말하는 거야?",
  str_homestory_800801001_4_dialog_content = "내 권투 동작 말이야!\n군더더기 없는 깔끔함! 멋지고 세련된 동작!",
  str_homestory_800801001_5_dialog_content = "크흠, 나쁘지는 않았어...",
  str_homestory_800801001_6_dialog_content = "나쁘지는 않다고? 너무 평범한 평가 아냐?",
  str_homestory_800801001_7_dialog_content = "됐어, 어차피 넌 권투도 할 줄 모르니까\n날 질투하는 거겠지.",
  str_homestory_800801001_8_dialog_content = "......?",
  str_homestory_800801001_9_dialog_content = "뭐, 안심해, PlayerName!\n네가 날 질투한다고 해도 난 계속 너한테\n잘해줄 테니까!",
  str_homestory_800801001_10_dialog_content = "너한테 질투 같은 거 안 한다니까...",
  str_homestory_800801001_11_dialog_content = "쉿... 나도 안다고.",
  str_homestory_800801001_12_dialog_content = "나도 네 나이 땐 지금의 나 같은 진정한\n사나이들을 동경했었거든!<sprite=emo_mojing size=60 />",
  str_homestory_800801001_13_dialog_content = "잘 들어, PlayerName!\n뜻이 있는 곳에 길이 있는 거야!",
  str_homestory_800801001_14_dialog_content = "...아, 알겠어. 렉커.",
  str_homestory_800801001_15_dialog_content = "천만에, 헤븐즈 가든에 연료를 공급하는 건\n내가 마땅히 해야 할 일이야.",
  str_homestory_800801001_16_dialog_content = "동생들을 돌보는 건 내가 제일 잘하는 일이니까.",
  str_homestory_800801001_17_dialog_content = "잠깐만... 갑자기 무슨 연료? 뭐가 마땅한데?",
  str_homestory_800801001_18_dialog_content = "뭐야, 아직도 내가 널 위해서 뭘 했는지\n모르는 거야?",
  str_homestory_800801001_19_dialog_content = "...자세히 좀 말해 봐.",
  str_homestory_800801001_20_dialog_content = "그러니까 말이지. 며칠 전에 터빈을 무지개색으로\n만들려고 오디를 찾아갔거든.",
  str_homestory_800801001_21_dialog_content = "근데 오디가 근심 가득한 얼굴로 나한테\n널 도와주라고 부탁하더라고.",
  str_homestory_800801001_22_dialog_content = "뭘 도와주라고 했는데?",
  str_homestory_800801001_23_dialog_content = "오디가 알려줬어...",
  str_homestory_800801001_24_dialog_content = "이 오뚜기 펀치백 안에는 히트 엔진이\n장착돼 있다고 말이야.",
  str_homestory_800801001_25_dialog_content = "......?",
  str_homestory_800801001_26_dialog_content = "그리고 이 히트 엔진이 헤븐즈 가든 전체에\n사용되는 전력을 공급하는 거라면서?",
  str_homestory_800801001_27_dialog_content = "그러니까 내가 매일 이걸 몇천 번은 때려 줘야\n네 헤븐즈 가든이 멈추지 않고 작동할 수\n있다는 거잖아.",
  str_homestory_800801001_28_dialog_content = "하하! 그 표정은 뭔데? 너무 고마워할 거 없어!",
  str_homestory_800801001_29_dialog_content = "널 위해서라면 얼마든지 할 수 있으니까!",
  str_homestory_800801001_30_dialog_content = "...크흠. 저기, 렉커...",
  str_homestory_800801001_31_option_content = "넌 속은 거야.",
  str_homestory_800801001_32_dialog_content = "이 오뚜기 펀치백 안은 충전재로 가득 채워져 있을 뿐이야. 기계 구조 같은 건 없어...",
  str_homestory_800801001_33_dialog_content = "그러니까 사실 헤븐즈 가든이 작동하는 건 이 펀치백이랑은 아무런 상관도 없다는 거지.",
  str_homestory_800801001_34_dialog_content = "크흠... 하지만!",
  str_homestory_800801001_35_dialog_content = "매일 여기서 권투 연습을 하면 네 몸과 마음을 건강하게 만들어 줄 거야.",
  str_homestory_800801001_36_option_content = "정말 고마워!",
  str_homestory_800801001_37_dialog_content = "크흠, 하지만...",
  str_homestory_800801001_38_dialog_content = "아마 오디가 헤븐즈 가든의 구조를 아직 잘 몰라서 그랬던 것 같아.",
  str_homestory_800801001_39_dialog_content = "그러니까... 내 말은...",
  str_homestory_800801001_40_dialog_content = "이 오뚜기 펀치백 안은 충전재로 가득 채워져 있을 뿐이야. 기계 구조 같은 건 없어.",
  str_homestory_800801001_41_dialog_content = "오! 그런 거였어?",
  str_homestory_800801001_42_dialog_content = "하하! 오디도 잘못 알고 있을 때가 있네!",
  str_homestory_800801001_43_dialog_content = "저기, 렉커...",
  str_homestory_800801001_44_dialog_content = "어쩌면 오디가 너한테 장난을 친 건지도 몰라.",
  str_homestory_800801001_45_dialog_content = "내 생각에도 그래. 어차피 다들\n나한테 자주 장난을 치니까.",
  str_homestory_800801001_46_dialog_content = "근데도 화 안 나?",
  str_homestory_800801001_47_dialog_content = "그런 거로 왜 화가 나?",
  str_homestory_800801001_48_dialog_content = "나한테 장난을 친다는 건 다들 날 아주\n좋아한다는 거잖아! 그래서 나랑 놀고 싶어\n한다는 거고!",
  str_homestory_800801001_49_dialog_content = "...음, 그것도 그렇네.",
  str_homestory_800801001_50_dialog_content = "게다가 조금 더 생각해 보면...",
  str_homestory_800801001_51_dialog_content = "다들 날 아주 아끼고 사랑하니까\n그렇게 장난도 치는 거겠지.",
  str_homestory_800801001_52_dialog_content = "...사랑? 확실해?",
  str_homestory_800801001_53_dialog_content = "그게 아니면 다들 왜 사메야마한테는\n장난을 안 치겠어?",
  str_homestory_800801001_54_dialog_content = "봐, 「친화력」 쪽으로는 내 완승 아니냐?\n하하하하!<sprite=emo_dianzan size=60 />",
  str_homestory_806501001_0_dialog_content = "트위티...?",
  str_homestory_806501001_1_dialog_content = "으앗! 오빠야... 오셨심꺼.",
  str_homestory_806501001_2_dialog_content = "왜 그래? 왜 날 보고 그렇게 놀라?",
  str_homestory_806501001_3_dialog_content = "아, 지가예...?",
  str_homestory_806501001_4_dialog_content = "봐, 들고 있던 것들도 다 바닥에 떨어트렸잖아.",
  str_homestory_806501001_5_dialog_content = "하이고! 으데예? 으데예?",
  str_homestory_806501001_6_dialog_content = "네 발밑에 있는 그 하얗고, 복슬복슬한 거...",
  str_homestory_806501001_7_dialog_content = "뭐라꼬예? 함 봅시더...",
  str_homestory_806501001_8_dialog_content = "으앗! 전부 지 몸에서 떨어진 깃털임니꺼?!",
  str_homestory_806501001_9_dialog_content = "아이고... 참말로 사람이 켕기는 짓은\n하면 못 쓰는 모양이라예.",
  str_homestory_806501001_10_dialog_content = "켕기는 짓?",
  str_homestory_806501001_11_dialog_content = "어쩐지 트위티의 꼬리가 축 처져 있다 했네.",
  str_homestory_806501001_12_dialog_content = "히잉...",
  str_homestory_806501001_13_dialog_content = "그래서 대체 무슨 일인데? 말해줄 수 있을까?",
  str_homestory_806501001_14_dialog_content = "역시 오빠야한테는 알려드리는 게 낫겠심더...",
  str_homestory_806501001_15_dialog_content = "지는 오늘 편지를 배달하러 온 왔심더.",
  str_homestory_806501001_16_dialog_content = "그래? 벌써 쿠리어 센터에 배달한 거야? 이따가 가서 확인해 볼게!",
  str_homestory_806501001_17_dialog_content = "아이고... 지금은 안 되고 쪼매 기다려 주시라예.",
  str_homestory_806501001_18_dialog_content = "아직... 배달을 못 했심더.",
  str_homestory_806501001_19_dialog_content = "지가 이번에 이래 와가 함 보니까,\n헤븐즈 가든이 참말로 딴판이 됐다 아입니꺼.",
  str_homestory_806501001_20_dialog_content = "그래가 여도 가 보고, 저도 가 보고 그러다\n편지 배달을 잊아삐릿심더...",
  str_homestory_806501001_21_dialog_content = "그게 트위티가 말한 켕기는 일이야?",
  str_homestory_806501001_22_option_content = "(화를 낸다)",
  str_homestory_806501001_23_dialog_content = "노느라 할일을 미루는 건 보통 잘못이 아니야.",
  str_homestory_806501001_24_dialog_content = "헤븐즈 가든의 주인으로서 너한테 벌을 줘야 할 것 같은데?",
  str_homestory_806501001_25_dialog_content = "하이고! 버, 벌이예?",
  str_homestory_806501001_26_dialog_content = "꼬리에서 깃털이 또 떨어질 것 같심더...",
  str_homestory_806501001_27_dialog_content = "그럼 트위티한테 벌로...",
  str_homestory_806501001_28_option_content = "(위로한다)",
  str_homestory_806501001_29_dialog_content = "괜찮아. 그렇게 급한 일도 아닌걸.",
  str_homestory_806501001_30_dialog_content = "내가 꾸민 헤븐즈 가든을 트위티가 좋아해 주는 건 나한테도 좋은 일이야.",
  str_homestory_806501001_31_dialog_content = "하이고, 고맙심더.\n오빠야는 참말로 좋은 사람임니더!",
  str_homestory_806501001_32_dialog_content = "근데 누가 보낸 편지야?",
  str_homestory_806501001_33_dialog_content = "어디 줘 봐. 확인해 볼게.",
  str_homestory_806501001_34_dialog_content = "하모예! 쿠리어 길드! 절대 안전 배송입니데이!",
  str_homestory_806501001_35_dialog_content = "아이고? 와 편지가 안 보이는 기고...",
  str_homestory_806501001_36_dialog_content = "가방 안에도 없고...",
  str_homestory_806501001_37_dialog_content = "모자 안에도 없네예!",
  str_homestory_806501001_38_dialog_content = "진정해. 어디 떨어트린 거 아니야?",
  str_homestory_806501001_39_dialog_content = "아까 어디 어디 들렀어?",
  str_homestory_806501001_40_dialog_content = "헤븐즈 가든을... 싹 다 돌아봤심더...",
  str_homestory_806501001_41_dialog_content = "...찾아야 할 범위가 꽤 넓긴 하네.",
  str_homestory_806501001_42_dialog_content = "흐아앙! 지는 도브 선배처럼 되기 싫심더...",
  str_homestory_806501001_43_dialog_content = "어? 트위티 너 꼬리에서 또 뭐가 떨어졌는데?",
  str_homestory_806501001_44_dialog_content = "지 꼬리에서 또 깃털이 떨어졌다고예?\n이러다 꼬리 다 뺏기지겠심더!",
  str_homestory_806501001_45_dialog_content = "아니야, 깃털이 아닌 것 같아...",
  str_homestory_806501001_46_dialog_content = "어라...",
  str_homestory_806501001_47_dialog_content = "아! 가가 바로 지가 배달해야 하는 편지라예!",
  str_homestory_806501001_48_dialog_content = "머하다 꼬리에 드갔는지 모르겠심더!",
  str_homestory_805501001_0_dialog_content = "저기...",
  str_homestory_805501001_1_dialog_content = "피트만 씨...?",
  str_homestory_805501001_2_dialog_content = "......!",
  str_homestory_805501001_3_dialog_content = "피트만 씨 맞죠?",
  str_homestory_805501001_4_dialog_content = "크흠, 사람 잘못 보셨습니다.",
  str_homestory_805501001_5_dialog_content = "네? 이 빈틈없이 철저한 차림새에... 다크서클까지!",
  str_homestory_805501001_6_dialog_content = "피트만 씨 맞잖아요.",
  str_homestory_805501001_7_dialog_content = "쉿...",
  str_homestory_805501001_8_dialog_content = "목소리를 낮추십시오.\n다른 사람이 들으면 안 됩니다...",
  str_homestory_805501001_9_option_content = "(의문을 표현한다)",
  str_homestory_805501001_10_dialog_content = "네? 백야성 심판관이 왜 다른 사람한테 들킬까 봐 걱정하는 거죠?",
  str_homestory_805501001_11_option_content = "(이해했다고 한다)",
  str_homestory_805501001_12_dialog_content = "아, 알겠어요.",
  str_homestory_805501001_13_dialog_content = "다른 사람들한테 여기 있다는 사실을 들키고 싶지 않은 거죠?",
  str_homestory_805501001_14_dialog_content = "설마... 백야성에 지명 수배라도 당한 건가요?!",
  str_homestory_805501001_15_dialog_content = "저는 항상 바르고 단정하게 행동합니다.\n경건한 마음으로 빛의 신을 대하고,\n백야성에는 충성을 다합니다.",
  str_homestory_805501001_16_dialog_content = "그런 제가 왜 수배를 당한다는 말입니까?",
  str_homestory_805501001_17_dialog_content = "예를 들면...",
  str_homestory_805501001_18_dialog_content = "혼자 몰래 목마를 타고 논 죄!",
  str_homestory_805501001_19_dialog_content = "그, 그걸 다 본 겁니까?<sprite=emo_daomei size=60 />",
  str_homestory_805501001_20_dialog_content = "헤에~ 진짜로 목마를 타셨나 보네요?",
  str_homestory_805501001_21_dialog_content = "크흠, 그저 목마의 품질이 어떤지 검사해 보려고\n했던 것입니다.",
  str_homestory_805501001_22_dialog_content = "최근 시중에는 품질을 속여 물건을 파는\n자들이 많습니다.",
  str_homestory_805501001_23_dialog_content = "심판관이라면 소비자를 기만하는 행위에\n철퇴를 가해야 마땅합니다.",
  str_homestory_805501001_24_dialog_content = "하지만 이곳의 목마는 좋은 재료로\n정교하게 만들었군요. 최소한 84kg 정도는\n거뜬히 버틸 수 있겠습니다.",
  str_homestory_805501001_25_dialog_content = "안심하고 사용해도 좋습니다.",
  str_homestory_805501001_26_dialog_content = "아, 고마워요...",
  str_homestory_805501001_27_dialog_content = "근데 제가 여기 목마를 둔 건 누구나 목마를 타면서 긴장을 풀길 바랐던 거예요.",
  str_homestory_805501001_28_dialog_content = "그러니까 목마를 타고 싶으시면 몰래 타지 않아도 돼요!",
  str_homestory_805501001_29_dialog_content = "어째서... 그렇게 말씀하시는 겁니까?",
  str_homestory_805501001_30_dialog_content = "얼굴에 다 쓰여 있었거든요.",
  str_homestory_805501001_31_dialog_content = "피트만 씨는 거짓말이 정말 서투르시네요. 하하하.",
  str_homestory_805501001_32_dialog_content = "...알겠습니다.",
  str_homestory_805501001_33_dialog_content = "그렇지만 이 비밀은 꼭 지켜 주시기 바랍니다.",
  str_homestory_805501001_34_dialog_content = "왜죠? 목마를 타는 게 무슨 엄청난 비밀도 아니잖아요...",
  str_homestory_805501001_35_dialog_content = "저도 목마 타는 거 꽤 좋아하는 편이에요.",
  str_homestory_805501001_36_dialog_content = "정의를 지키는 심판관으로서 전 사람들에게 항상\n믿음직한 모습을 보여 주고 싶습니다.",
  str_homestory_805501001_37_dialog_content = "그런데 만약 제게 이런 유치한 취미가 있다는\n사실이 알려진다면...",
  str_homestory_805501001_38_dialog_content = "제가 담당한 안건의 판결을 사람들이 믿지 않게\n될 수도 있습니다.",
  str_homestory_805501001_39_dialog_content = "그런가요...",
  str_homestory_805501001_40_dialog_content = "그러니 이 비밀을 지켜 주시겠습니까?",
  str_homestory_805501001_41_dialog_content = "저는 판결이랑 목마를 타는 거랑은 별 관계가 없다고 생각하지만... 일단 알겠어요...",
  str_homestory_805501001_42_dialog_content = "피트만 씨가 그렇게까지 부탁하시니까 비밀을 지켜 드릴게요!",
  str_homestory_805501001_43_dialog_content = "이해해 주셔서 감사합니다!",
  str_homestory_805501001_44_dialog_content = "그리고...",
  str_homestory_805501001_45_dialog_content = "만약 당신이 가짜 상품을 사게 된다면,\n제가 반드시 정의를 구현하겠습니다!<sprite=emo_qingsong size=60 />",
  str_homestory_815501001_0_dialog_content = "(검을 집어넣는 소리인가?)",
  str_homestory_815501001_1_dialog_content = "헤븐즈 밸리는 대단한 곳이 참 많잖아, PlayerName!",
  str_homestory_815501001_2_dialog_content = "나, 나쁘지는 않죠...",
  str_homestory_815501001_3_dialog_content = "아직 발견하지 못한 아이테르의 비밀은\n대체 얼마나 더 있는 거지?",
  str_homestory_815501001_4_dialog_content = "...금방 알 수 있었으면 좋겠군.",
  str_homestory_815501001_5_dialog_content = "훗, 여긴 확실히 좋은 곳이다. 애송이.",
  str_homestory_815501001_6_dialog_content = "다양한 시설을 완벽히 갖추고 있으면서,\n험한 지형으로 방어까지 할 수 있지.",
  str_homestory_815501001_7_dialog_content = "만약 정말 무슨 일이 일어난다면 이곳을 장기적인\n전진기지로 삼아도 전혀 문제없겠어!",
  str_homestory_815501001_8_dialog_content = "우와... 정말 엄청 멀리까지 생각하셨네요.",
  str_homestory_815501001_9_dialog_content = "당연한 거 아니겠나!",
  str_homestory_815501001_10_dialog_content = "끊임없이 힘을 추구하는 것보다는\n지금 가지고 있는 자원을 잘 계획해서 활용하는\n것도 아주 중요하다.",
  str_homestory_815501001_11_dialog_content = "(바튼 씨, 역시 좀 달라진 것 같네...)",
  str_homestory_815501001_12_dialog_content = "휴, 젊었을 땐 이해하지 못했지.\n이 두 가지가 사실은...",
  str_homestory_815501001_13_dialog_content = "...참, 애송이. 넌 어떻게 생각하지?",
  str_homestory_815501001_14_dialog_content = "강해지는 것과 자원을 활용하는 것 중에서\n어떤 게 더 우선이라고 생각하나?<sprite=emo_sikao size=60 />",
  str_homestory_815501001_15_option_content = "(강해지는 것)",
  str_homestory_815501001_16_dialog_content = "예를 들어서 만약 제가 가진 돈이 10 나이티움밖에 없다면,\n활용하고 싶어도 방법이 없잖아요...",
  str_homestory_815501001_17_dialog_content = "그러니 당연히 강해지는 게 우선이죠. 다시 말해서 돈을 벌어야 한다는 거죠.",
  str_homestory_815501001_18_option_content = "(자원을 활용하는 것)",
  str_homestory_815501001_19_dialog_content = "예를 들어서 만약 제가 가진 돈이 10 나이티움밖에 없다면,\n일단 어떻게 살아남을지부터 생각하고, 그리고 어떻게 돈을 벌지 생각하겠죠...",
  str_homestory_815501001_20_dialog_content = "하아? 설마 진짜는 아니겠지?",
  str_homestory_815501001_21_dialog_content = "정말 수중에 10 나이티움밖에 없는 거냐?",
  str_homestory_815501001_22_dialog_content = "...그냥 예를 든 거라구요!",
  str_homestory_815501001_23_dialog_content = "음, 알겠다.",
  str_homestory_815501001_24_dialog_content = "내 말은 정말 돈이 부족하다면\n내가 빌려줄 수 있다는 얘기였다.",
  str_homestory_815501001_25_dialog_content = "이렇게 보면 그래도 일루미나가 좋군.\n최소한 따로 돈을 쓰지 않아도 되는 물건들이\n많으니까 말이야.",
  str_homestory_815501001_26_dialog_content = "......?",
  str_homestory_815501001_27_dialog_content = "크흠, 내가 또 너무 멀리 갔나...",
  str_homestory_815501001_28_dialog_content = "아무튼 내가 하고 싶었던 말은 이거다.\n지금의 난 힘의 추구와 자원의 활용을\n함께 진행해도 괜찮다고 생각한다.",
  str_homestory_815501001_29_dialog_content = "이 두 가지는 원래부터 모순되는 일이\n아니니 말이야.",
  str_homestory_815501001_30_dialog_content = "예전의 난 힘만을 추구하고, 많은 일의 배후에\n숨은 의미를 무시했었지.",
  str_homestory_815501001_31_dialog_content = "만약 이미 손에 쥐고 있는 자원을 활용한다면,\n우리가 나아갈 방향을 더욱 명확하게\n만들 수 있을 거다!",
  str_homestory_815501001_32_dialog_content = "자기 자신을 철저히 이해해야만 순조롭게\n나아갈 수 있고, 더 강해질 수 있지.",
  str_homestory_815501001_33_dialog_content = "강해져야만 내 말이 더 힘을 갖게 되는 거다.",
  str_homestory_815501001_34_dialog_content = "음... 바튼 씨 말도 어느 정도는 맞는 것 같네요.",
  str_homestory_815501001_35_dialog_content = "그럼 여길 전진기지로 사용할 수 있도록\n빌려주겠다는 말이겠지?",
  str_homestory_815501001_36_dialog_content = "...?!",
  str_homestory_815501001_37_dialog_content = "그런 말은 한 적 없어요!",
  str_homestory_815501001_38_dialog_content = "게다가 전진기지인지 뭔지는 헤븐즈 가든이랑 완전 안 어울리잖아요!",
  str_homestory_815501001_39_dialog_content = "하하, 그건 모르는 일 아닌가?\n언젠가 또 싸움이 벌어질 수도 있다고!",
  str_homestory_815501001_40_dialog_content = "저기요, 제발 그런 불길한 소리 좀 하지 마세요!<sprite=emo_shengqi size=60 />",
  str_homestory_815501001_41_dialog_content = "불길한 소리라니?\n이건 기본적인 위험 대비책을 세우자는 거다!",
  str_homestory_815501001_42_dialog_content = "음, 그렇다면 얼른 날을 잡아서 워게임을\n몇 번 더 진행해야겠군.",
  str_homestory_815501001_43_dialog_content = "지금 내 머리 속에 있는 이 계획들은...\n내일 비비안을 찾아가 설명해 둬야겠어.",
  str_homestory_815501001_44_dialog_content = "쳇, 문서 작성이나 자료 조사 같은 건\n정말 귀찮다고... 그런 걸 내가 할 수는 없지!",
  str_homestory_815501001_45_dialog_content = "(아까 했던 말은 취소야...)",
  str_homestory_815501001_46_dialog_content = "(바튼 씨는 역시나 바튼 씨야. 전이랑 하나도 달라진 게 없어.)",
  str_homestory_801101001_0_dialog_content = "시로나 씨!",
  str_homestory_801101001_1_dialog_content = "저기...",
  str_homestory_801101001_2_dialog_content = "새로운 기술을 연습하고 계신 건가요?",
  str_homestory_801101001_3_dialog_content = "그래, 맞아.",
  str_homestory_801101001_4_dialog_content = "여기서도 훈련이라니<sprite=emo_yaling size=60 />,\n역시 정면 공격을 담당하는 제1군단장다우시네요...",
  str_homestory_801101001_5_dialog_content = "아니. 그건 오해야, PlayerName.",
  str_homestory_801101001_6_dialog_content = "새 기술들을 연습하는 건 이것들을 훈련에\n도입하기 위해서가 아니야.",
  str_homestory_801101001_7_dialog_content = "내가 얼마 전에 읽었던 소설에서 이 기술이\n나왔길래 연습해 본 거지.",
  str_homestory_801101001_8_dialog_content = "시...시로나 씨도 소설을 읽는다구요?",
  str_homestory_801101001_9_dialog_content = "아니지, 잠깐만요... 소설에 나온 기술을 연습하던 거라고요?",
  str_homestory_801101001_10_dialog_content = "제...제가 알던 시로나 씨의 이미지가 아닌데요?!",
  str_homestory_801101001_11_dialog_content = "그게 그렇게 놀랄 일인가?",
  str_homestory_801101001_12_option_content = "(고개를 끄덕인다)",
  str_homestory_801101001_13_dialog_content = "뭔가 항상 중요한 일만 생각하시는 것 같아서,\n아무래도 소설 같은 거랑은 거리가 좀...",
  str_homestory_801101001_14_dialog_content = "아니, 그렇다고 소설을 읽는 게 나쁘다는 건 아니에요!",
  str_homestory_801101001_15_option_content = "(고개를 젓는다)",
  str_homestory_801101001_16_dialog_content = "다시 생각해 보니까, 타인을 어떤 고정된 이미지에 가둬 두면 안 되는 것 같네요...",
  str_homestory_801101001_17_dialog_content = "전 그저 시로나 씨가 항상 바쁘니까,\n소설 읽을 시간은 없을 것 같다고 생각했던 거예요.",
  str_homestory_801101001_18_dialog_content = "음, 확실히 소설 같은 건 많이 읽지 못했어.",
  str_homestory_801101001_19_dialog_content = "근데 책 제목이 「반역의 두 용, 천년의 갈등」\n이었거든. 그래서 읽어 본 거야.",
  str_homestory_801101001_20_dialog_content = "......",
  str_homestory_801101001_21_dialog_content = "화, 확인하고 싶은 게 있는데요... 어디서 그 책을 보신 거죠...?",
  str_homestory_801101001_22_dialog_content = "혹시 어느 오로리안이 시로나 씨한테 그 책을 판 건 아니죠?!",
  str_homestory_801101001_23_dialog_content = "맞아, 움브라톤의 한 상인이 나한테 판 거야.",
  str_homestory_801101001_24_dialog_content = "아주 침착해 보이시네요...",
  str_homestory_801101001_25_dialog_content = "그 책에 뭔가 독특한 내용은 없었나요?",
  str_homestory_801101001_26_dialog_content = "그 사람이 나한테 이 책을 팔 때\n말했던 광고 문구는...",
  str_homestory_801101001_27_dialog_content = "「오래전에 사라진 용족의 비기」,\n「고대 혈족의 러브 스토리」였지...",
  str_homestory_801101001_28_dialog_content = "뭐라고요?! 화, 화는 안 나셨어요?",
  str_homestory_801101001_29_dialog_content = "딱히.",
  str_homestory_801101001_30_dialog_content = "화가 나도 뭘 어쩌겠어.",
  str_homestory_801101001_31_dialog_content = "이 책의 생산, 판매 과정은 애초에 전부\n움브라톤에서 이루어지니까, 내 관할이 아닌걸.",
  str_homestory_801101001_32_dialog_content = "더군다나 나한테 이 책의 내용은 아무래도 좋은\n심심풀이에 불과해.",
  str_homestory_801101001_33_dialog_content = "하지만 작가에게 이 책은 어쩌면 생계를 유지하는\n수단일 수도 있겠지.",
  str_homestory_801101001_34_dialog_content = "...네, 그 말도 맞네요...",
  str_homestory_801101001_35_dialog_content = "시로나 씨는... 정말로 좋은 군단장이세요!",
  str_homestory_801101001_36_dialog_content = "이 책에 나온 「용족의 비기」란 게\n좀 많이 황당하기는 했지만...",
  str_homestory_801101001_37_dialog_content = "그래도 내가 몸을 움직여서 단련하도록\n만들어 줬으니까.",
  str_homestory_801101001_38_dialog_content = "그럼 나랑 같이 해 보겠어?",
  str_homestory_801101001_39_dialog_content = "책에 나온 설명에 따르면 일단 가볍게\n스쿼트 200회부터 하고,그다음엔 가볍게...",
  str_homestory_801101001_40_dialog_content = "아니요. 괜찮아요...",
  str_homestory_801101001_41_dialog_content = "아무래도 저는 아이테르 일족의 능력에 더 집중하는 게 좋을 것 같아요.",
  str_homestory_801101001_42_dialog_content = "하시던 거 마저 하세요. 먼저 갈게요... 안녕히 계세요!",
  str_homestory_801101001_43_dialog_content = "그럼 또 보자고.",
  str_homestory_810301001_0_dialog_content = "엘시, 왔어?",
  str_homestory_810301001_1_dialog_content = "상점 안엔 안 들어가 볼 거야?",
  str_homestory_810301001_2_dialog_content = "너 쇼핑하는 거 좋아했잖아.",
  str_homestory_810301001_3_dialog_content = "PlayerName, 내 취미까지 기억하고 있으면서...",
  str_homestory_810301001_4_dialog_content = "대체 왜 쪼잔하게 상점을 하나만 지은 거야?",
  str_homestory_810301001_5_dialog_content = "그건 말이지. 이유가 많은데...",
  str_homestory_810301001_6_dialog_content = "어디 계속 해명해 봐.",
  str_homestory_810301001_7_dialog_content = "제대로 된 해명을 못 하면, 내가 안대를 벗어서...",
  str_homestory_810301001_8_dialog_content = "「공허의 눈동자」<sprite=emo_baimao size=60 />로 제대로 기억나게 해 줄 테니까.",
  str_homestory_810301001_9_option_content = "(해명한다)",
  str_homestory_810301001_10_dialog_content = "아, 알겠어. 말할게!",
  str_homestory_810301001_11_dialog_content = "가장 큰 원인은 역시 예산이 한정돼 있어서야...",
  str_homestory_810301001_12_dialog_content = "건물을 지을 곳이 이렇게나 많은데, 처음부터 다 완벽하게 갖추긴 어렵잖아.",
  str_homestory_810301001_13_option_content = "(해명하지 않는다)",
  str_homestory_810301001_14_dialog_content = "심문해도 소용없어...",
  str_homestory_810301001_15_dialog_content = "애초에 예산은 한정돼 있어. 상점을 그렇게 많이 만들 수는 없다고...",
  str_homestory_810301001_16_dialog_content = "지금 상점이 하나 있는 것만 해도... 나쁘지 않다고 생각해!",
  str_homestory_810301001_17_dialog_content = "꽤나 당당한데?",
  str_homestory_810301001_18_dialog_content = "비록 작은 상점 하나뿐이지만, 그래도 있을 건 다 있어!",
  str_homestory_810301001_19_dialog_content = "움브라톤의 여러 상회에도 열심히 연락했고...",
  str_homestory_810301001_20_dialog_content = "쿠리어 길드에 부탁해서 비정기적으로 물건을 납품해 달라고도 부탁했어.",
  str_homestory_810301001_21_dialog_content = "못 믿겠으면 들어가서 확인해 볼래? 찾는 게 없으면 내가 구해다 줄게.",
  str_homestory_810301001_22_dialog_content = "됐어, 벌써 구경했어.",
  str_homestory_810301001_23_dialog_content = "그리고 네 기 좀 세워 주려고\n상점에 있는 물건도 전부 다 샀어.",
  str_homestory_810301001_24_dialog_content = "물건을 전부 다?!",
  str_homestory_810301001_25_dialog_content = "응.",
  str_homestory_810301001_26_dialog_content = "오늘 강에서 갓 잡은 물고기도...?",
  str_homestory_810301001_27_dialog_content = "그 알록달록한 물고기 말하는 거지?\n샀어. 꽤 귀엽던데.",
  str_homestory_810301001_28_dialog_content = "근데 사고 보니까 어항이 없더라.\n그래서 근처에 있는 강에 넣어 줬어.",
  str_homestory_810301001_29_dialog_content = "사려는 사람이 없던 그 낡은 구두도...?",
  str_homestory_810301001_30_dialog_content = "낡은 구두? 혹시 그 화분 같은 거 말하는 거야?\n그것도 샀어.",
  str_homestory_810301001_31_dialog_content = "쿠리어 길드에 부탁해서 진리의 결사로\n옮겨 달라고 했어.",
  str_homestory_810301001_32_dialog_content = "그럼... 내가 직접 그린 헤븐즈 밸리 지도도 샀고?",
  str_homestory_810301001_33_dialog_content = "삐뚤빼뚤한 선으로 미궁 같은 걸 그린\n종이 말하는 거지?",
  str_homestory_810301001_34_dialog_content = "네가 직접 그린 거였어?\n그럼 이따가 액자에 잘 담아서 벽에 걸어 둬야겠네.",
  str_homestory_810301001_35_dialog_content = "고마워, 엘시... 넌 우리 상점 역사상 최고의 큰손이야!",
  str_homestory_810301001_36_dialog_content = "고맙긴 뭘. 쇼핑은 원래 시원시원하게 사야\n즐거운 법이잖아?",
  str_homestory_810301001_37_dialog_content = "근데 이 가게를 구경하고 나니까 다른 가게가\n없길래 조금 화가 났던 거야.",
  str_homestory_810301001_38_dialog_content = "그럼 이 근처에 있는 다른 곳들도 구경해 봐.",
  str_homestory_810301001_39_dialog_content = "저쪽의 전시관이나, 희망의 연못이나...",
  str_homestory_810301001_40_dialog_content = "여기서만 볼 수 있는 것들이니까 분명히 볼만할 거야! 내가 장담할게!",
  str_homestory_810301001_41_dialog_content = "좋아, 왠지 가볼 만할 것 같네.",
  str_homestory_810301001_42_dialog_content = "아니면 이건 어떨까? 내가 널 살게<sprite=emo_baiyebi size=60 />.",
  str_homestory_810301001_43_dialog_content = "뭐?! 나를... 산다고?!",
  str_homestory_810301001_44_dialog_content = "오늘 네 하루를 내가 살 테니까,\n네가 안내하면서 구경시켜 줘.",
  str_homestory_810301001_45_dialog_content = "가격은 네가 정해.",
  str_homestory_810301001_46_dialog_content = "아, 알겠어! 지금부터 제가 모시겠습니다!",
  str_homestory_802301001_0_dialog_content = "코놀리...",
  str_homestory_802301001_1_dialog_content = "정말 따스한 빛이네요...",
  str_homestory_802301001_2_dialog_content = "응? 코놀리, 혼자 무슨 말하고 있어?",
  str_homestory_802301001_3_dialog_content = "조, 조종사 씨!<sprite=emo_wuzui size=60 />",
  str_homestory_802301001_4_dialog_content = "그, 그냥 혼자 중얼거린 거예요.\n신경 쓰지 마세요...",
  str_homestory_802301001_5_dialog_content = "...아, 아니, 취소할게요!",
  str_homestory_802301001_6_dialog_content = "신경 써 주셔도 돼요...\n사, 사실 지금 「둔감해지는 훈련」 중이었어요...",
  str_homestory_802301001_7_dialog_content = "「둔감해지는 훈련」?",
  str_homestory_802301001_8_dialog_content = "네... 바, 바이스 씨가 가르쳐 주신 거예요...",
  str_homestory_802301001_9_dialog_content = "여긴 항상 밝은데...\n전 밝은 곳에 익숙하지 않거든요...",
  str_homestory_802301001_10_dialog_content = "그러다 바이스 씨가 구석에 있던 절 발견했고...",
  str_homestory_802301001_11_dialog_content = "도움이 필요해 보였던 모양이네. 그렇지?",
  str_homestory_802301001_12_dialog_content = "네...",
  str_homestory_802301001_13_dialog_content = "바이스 씨는 일단 다른 사람들 신경 쓰지 말고,\n제가 좋아하는 일을 해 보라고 했어요...",
  str_homestory_802301001_14_dialog_content = "아니면 여길 홀리데이 카페라고 생각하고,\n다른 사람들은 손님이라고 여기라고 했죠...",
  str_homestory_802301001_15_dialog_content = "그, 그래서 노력해 보고 있었어요...",
  str_homestory_802301001_16_option_content = "그랬더니 느낌이 어떤데?",
  str_homestory_802301001_17_dialog_content = "전보다는... 조금 나아진 것 같아요...",
  str_homestory_802301001_18_dialog_content = "생각해 보면 콜로서스에도 사람은 많았으니까요...",
  str_homestory_802301001_19_option_content = "너무 무리하진 마.",
  str_homestory_802301001_20_dialog_content = "계속 방에 있는 게 편하면 그렇게 해도 괜찮아.",
  str_homestory_802301001_21_dialog_content = "사, 사실 조종사 씨한테 말해주고\n싶은 게 있었어요...",
  str_homestory_802301001_22_dialog_content = "응? 무슨 일인데?",
  str_homestory_802301001_23_dialog_content = "전 바이스 씨의 제안을 받고 여기서 「안톤」이랑\n같이 음악 한 곡<sprite=emo_yinfu size=60 />을 연주했거든요...",
  str_homestory_802301001_24_dialog_content = "근데... 백야성 사람으로 보이는 어떤 숙녀분이\n절 칭찬해 주셨어요...",
  str_homestory_802301001_25_dialog_content = "전...",
  str_homestory_802301001_26_dialog_content = "아, 그럼 이제 이런 환한 곳도 좀 있을 만해진 거지?",
  str_homestory_802301001_27_dialog_content = "역시 칭찬은 아주 훌륭한 응원 방법이라니까.",
  str_homestory_802301001_28_dialog_content = "코놀리, 난 네가 정말 대단하다고 생각해!",
  str_homestory_802301001_29_dialog_content = "맛있는 커피도 만들 줄 알고, 강력한 전투 능력에 성격도 귀엽잖아...",
  str_homestory_802301001_30_dialog_content = "칭찬해 주셔서 고마워요...\n뭐, 뭐라고 말해야 좋을지 모르겠네요...",
  str_homestory_802301001_31_dialog_content = "다만 그 숙녀분의 칭찬이랑...\n조종사 씨의 칭찬은 달랐어요!",
  str_homestory_802301001_32_dialog_content = "조종사 씨랑 바이스 씨는 모두\n코놀리의 친구니까...",
  str_homestory_802301001_33_dialog_content = "저를 격려해 주려고...\n위로하고 칭찬해 주는 거지만...",
  str_homestory_802301001_34_dialog_content = "그...그 숙녀분은 모르는 사람이었어요...!",
  str_homestory_802301001_35_dialog_content = "그래서 코놀리한테는 그 칭찬이 아주 순수한 긍정의 의미로 느껴졌던 거겠네.",
  str_homestory_802301001_36_dialog_content = "마, 맞아요... 그런 의미였어요...",
  str_homestory_802301001_37_dialog_content = "아무튼... 조종사 씨. 저 대신 바이스 씨한테\n고맙다고 전해줄 수 있을까요?",
  str_homestory_802301001_38_dialog_content = "만약 바이스 씨의 조언이 없었다면...\n전 아직도 방에 틀어박혀서 밖에 나오지\n않았을 거예요...",
  str_homestory_802301001_39_dialog_content = "얼마든지!",
  str_homestory_802301001_40_dialog_content = "그, 그리고 조종사 씨도 고마워요!",
  str_homestory_802301001_41_dialog_content = "그럼 이제... 「안톤」이랑 그 곡을\n좀 더 연습해 볼게요...",
  str_homestory_802301001_42_dialog_content = "새로운 곡을 시도해 봐도 되지 않아?",
  str_homestory_802301001_43_dialog_content = "새로운 곡을 듣게 된다면 그 수수께끼의 숙녀분도 분명히 기뻐할 테니까.",
  str_homestory_802301001_44_dialog_content = "아... 그렇네요...",
  str_homestory_802301001_45_dialog_content = "조, 좋아요! 조종사 씨, 그럼 저 먼저\n연습하러 가 볼게요!",
  str_homestory_802301001_46_dialog_content = "힘내!",
  str_homestory_803001001_0_dialog_content = "사메야마...",
  str_homestory_803001001_1_dialog_content = "안녕, 사메야마!",
  str_homestory_803001001_2_dialog_content = "오호<sprite=emo_yaosu size=60 />, 이거 우리 아이테르 PlayerName 아냐?",
  str_homestory_803001001_3_dialog_content = "잘 지냈냐?",
  str_homestory_803001001_4_dialog_content = "꽤 잘 지내고 있어. 당신은? 여기 생활엔 좀 익숙해졌어?",
  str_homestory_803001001_5_dialog_content = "그럭저럭이다.",
  str_homestory_803001001_6_dialog_content = "뭐 하나 없던 곳을 그 짧은 시간 만에\n이렇게 만들다니...",
  str_homestory_803001001_7_dialog_content = "역시 이 사메야마가 눈여겨 보는\n녀석답단 말이지, 하하하!",
  str_homestory_803001001_8_dialog_content = "그래서, 이제 마음은 좀 정했나?",
  str_homestory_803001001_9_dialog_content = "우리 레디젤 렌치엔 대체 언제쯤 들어올 생각이지?",
  str_homestory_803001001_10_dialog_content = "아... 그게...",
  str_homestory_803001001_11_dialog_content = "근데 말이야. 레디젤 렌치의 기준에서 보자면...",
  str_homestory_803001001_12_dialog_content = "여긴 아직 마음껏 치고받거나\n폭주를 할 곳이 없단 말이지!",
  str_homestory_803001001_13_option_content = "(거절한다)",
  str_homestory_803001001_14_dialog_content = "난 헤븐즈 가든에서는 그 어떤 충돌도 발생하지 않았으면 좋겠어...",
  str_homestory_803001001_15_dialog_content = "그러니까 그런 폭력적인 활동을 위한 장소를 제공할 생각은 없어.",
  str_homestory_803001001_16_dialog_content = "휴, 너한테 매몰차게 거절당한 게\n이번이 대체 몇 번째냐.",
  str_homestory_803001001_17_dialog_content = "하지만 PlayerName,\n내가 보기엔 그건 조금 짧은 생각인 것 같군.",
  str_homestory_803001001_18_dialog_content = "내가 충고 한마디 해 주마.\n어떤 일들은 하면 안 된다고 금지할수록\n더 일어나는 법이다.",
  str_homestory_803001001_19_dialog_content = "내가 그걸 어떻게 아는지는 묻지 마라...",
  str_homestory_803001001_20_dialog_content = "......",
  str_homestory_803001001_21_option_content = "(동의한다)",
  str_homestory_803001001_22_dialog_content = "휴, 원래 나도 딱히 계획 같은 건 없었는데...",
  str_homestory_803001001_23_dialog_content = "근데 만약에 누가 여기서 멋대로 싸우거나 폭주 운전을 한다면...\n내가 힘들게 꾸린 터전이 파괴될 수도 있잖아.",
  str_homestory_803001001_24_dialog_content = "그런 건 역시 나중에 전용 장소를 마련하는 편이 좋을 것 같아...",
  str_homestory_803001001_25_dialog_content = "하하, 애송이 너 요즘 정말 많이 성장했잖아.",
  str_homestory_803001001_26_dialog_content = "조언을 해 주면 들을 줄도 알고 말이야!",
  str_homestory_803001001_27_dialog_content = "참, 그럼 혹시 헤븐즈 가든의 여자 숙소가\n어떻게 생겼는지 둘러보게 네가 안내 좀\n해줄 수 있겠냐?",
  str_homestory_803001001_28_dialog_content = "뭐?!",
  str_homestory_803001001_29_dialog_content = "뭘 그런 놀란 눈으로 쳐다보는 거냐?",
  str_homestory_803001001_30_dialog_content = "여자들 방에는 왜 가려는 건데?",
  str_homestory_803001001_31_dialog_content = "당연히 참관하러 가는 거지.",
  str_homestory_803001001_32_dialog_content = "참관?!",
  str_homestory_803001001_33_dialog_content = "그래<sprite=emo_qingsong size=60 />, 여자 숙소의 룸 컨디션이 어떤지를 봐야\n우리 이브가 지내기 좋은지 어떤지\n알 수 있을 거 아니냐.",
  str_homestory_803001001_34_dialog_content = "휴우... 그런 거였구나.",
  str_homestory_803001001_35_dialog_content = "매트리스가 얼마나 부드러운지도 확인해야 하고...",
  str_homestory_803001001_36_dialog_content = "침대 스탠드의 조명 색상이 시력을\n보호해 줄 수 있는지...",
  str_homestory_803001001_37_dialog_content = "침대 시트에 이브가 좋아하는 그림이\n그려져 있는지...",
  str_homestory_803001001_38_dialog_content = "방에 이브의 예쁜 치마를 넣어 둘 수 있을 만큼\n큰 옷장이 있는지...",
  str_homestory_803001001_39_dialog_content = "아, 그래. 이게 가장 중요하지!\n방에 보온컵이 있는지도 확인해야 한다고!",
  str_homestory_803001001_40_option_content = "(동의한다)",
  str_homestory_803001001_41_dialog_content = "그럼 바이스한테 확인해 달라고 할게...",
  str_homestory_803001001_42_dialog_content = "하하하, 의리 하난 확실하구만!",
  str_homestory_803001001_43_option_content = "(거절한다)",
  str_homestory_803001001_44_dialog_content = "사메야마, 내가 보기에 당신은 이브한테 자기 공간을 주는 법을 배워야 할 것 같아.",
  str_homestory_803001001_45_dialog_content = "그게 무슨 소리냐?!",
  str_homestory_803001001_46_dialog_content = "아, 알겠어! 그럼 바이스한테 확인해 달라고 할게...",
  str_homestory_811601001_0_dialog_content = "이 덜컹거리는 소리는 뭐야?!",
  str_homestory_811601001_1_dialog_content = "조종사, 수리할 게 있어서 온 거야?",
  str_homestory_811601001_2_dialog_content = "마침 잘 왔어! 오늘은 아직 의뢰가 없거든!",
  str_homestory_811601001_3_dialog_content = "수리?",
  str_homestory_811601001_4_dialog_content = "화물역에서... 설마 주문받는 중인 건 아니지?!",
  str_homestory_811601001_5_dialog_content = "맞아. 일단 여기서 손님을 끌어모으고,\n방으로 돌아가서 물건을 고칠 거야.",
  str_homestory_811601001_6_dialog_content = "아, 그래도 안심해. 돈은 안 받을 거거든.",
  str_homestory_811601001_7_dialog_content = "뭐? 그럼 왜...",
  str_homestory_811601001_8_dialog_content = "왜 모두한테 무료로 물건을 고쳐 주냐고?",
  str_homestory_811601001_9_dialog_content = "맞아. 넌 평소라면 방에서 자기가 좋아하는 일에 몰두하는 거 아니었어...?",
  str_homestory_811601001_10_dialog_content = "다양한 부품을 연구한다든지 말이야.",
  str_homestory_811601001_11_dialog_content = "그게, 여긴 저마다 다른 곳에서 온\n사람들이 많잖아?<sprite=emo_sikao size=60 />",
  str_homestory_811601001_12_dialog_content = "그 사람들이 수리해 달리는 물건들도 다 저마다의\n스타일이 있어서 꽤 재미있거든.",
  str_homestory_811601001_13_dialog_content = "예를 들면 전에 카론 씨가 나한테 자기\n턴테이블<sprite=emo_yinfu size=60 />의 음량을 키워달라고 했었는데...",
  str_homestory_811601001_14_dialog_content = "그 턴테이블은 일루미나에서 제작된 거니까\n대충 고치면 되겠다 싶었거든.",
  str_homestory_811601001_15_dialog_content = "근데 이게 웬걸... 그 턴테이블은 일루미나에서\n제작된 게 아니라, 언제 만들어졌는지 알 수도 없는\n엄청난 골동품이었지 뭐야!",
  str_homestory_811601001_16_dialog_content = "하하, 그래서 난 그 턴테이블을\n몇 번이고 꼼꼼히 연구했어!",
  str_homestory_811601001_17_dialog_content = "어... 그럼... 진짜로 카론 씨의 턴테이블 음량을 키워줬어?!",
  str_homestory_811601001_18_dialog_content = "그래, 인정할게. 연구에 새로운 재미를 선사해 준\n보답으로 진짜 조금만 키워줬어...",
  str_homestory_811601001_19_dialog_content = "그, 근데 나도 카론 씨가 가끔 노래를\n너무 크게 트는 건 알아.\n그래서 아주 조금만 키워줬다고!",
  str_homestory_811601001_20_dialog_content = "그래... 아무튼 너도 여기서 만족하며 지내고 있는 모양이네.",
  str_homestory_811601001_21_dialog_content = "당연하지!",
  str_homestory_811601001_22_dialog_content = "수많은 다양한 기술과 새로운 부품,\n그리고 장비가 가득해... 진짜 최고야!<sprite=emo_aixin size=60 />",
  str_homestory_811601001_23_dialog_content = "그래. 여기 생활엔 익숙해졌어?",
  str_homestory_811601001_24_dialog_content = "꽤 익숙해졌어.\n새 메카를 금방 만들 수 있을 것 같아!",
  str_homestory_811601001_25_dialog_content = "...역시 그걸 위해서였던 거지?!",
  str_homestory_811601001_26_dialog_content = "아니야, 너한테도 신경 쓰고 있어!\n네가 오기 전에도 내가 너 대신 화물역의 구조를\n점검해 뒀단 말이야!",
  str_homestory_811601001_27_dialog_content = "렌치랑 드라이버로 좀 두들겨 봤는데,\n여긴 아직 꽤 튼튼해서 내 도움은 필요 없겠더라고.",
  str_homestory_811601001_28_dialog_content = "아무래도 헤븐즈 밸리의 재료를 사용해서 만든 거니까.",
  str_homestory_811601001_29_dialog_content = "그래, 이거 봐. 여기 머물면 헤븐즈 밸리의\n재료들도 연구할 수 있어서 진짜 좋다니까!",
  str_homestory_811601001_30_dialog_content = "알았어, 알았어. 그럼 이제 방해 안 할게...\n그럼 여기서 주문받을 거야?",
  str_homestory_811601001_31_dialog_content = "방해라니, 전혀 아니야.\n그리고 나랑 같이 여기서 주문받아줘도 돼.",
  str_homestory_811601001_32_option_content = "(동의한다)",
  str_homestory_811601001_33_dialog_content = "좋아... 모두가 뭘 수리하려고 하는지 나도 좀 알아봐야겠어.",
  str_homestory_811601001_34_dialog_content = "얼마든지!",
  str_homestory_811601001_35_dialog_content = "...근데 오늘은 좀 한가하네.",
  str_homestory_811601001_36_dialog_content = "...만약에 아무도 수리를 맡기러 안 오면 어떻게 해?",
  str_homestory_811601001_37_option_content = "(거절한다)",
  str_homestory_811601001_38_dialog_content = "됐어, 다른 일도 많거든...",
  str_homestory_811601001_39_dialog_content = "아, 그렇지.",
  str_homestory_811601001_40_dialog_content = "만약에 아무도 수리를 맡기러 안 오면 어떻게 해?",
  str_homestory_811601001_41_dialog_content = "그럼 계속 여기서 멀뚱멀뚱 서 있기만 할 거야?",
  str_homestory_811601001_42_dialog_content = "그렇지.",
  str_homestory_811601001_43_dialog_content = "근데 한 가지 짚고 넘어가야 할 게 있어.",
  str_homestory_811601001_44_dialog_content = "난 여기서 「멀뚱멀뚱 서 있는」 게 아니야.\n내 머릿속에서는 언제나 격렬한 메카 대전이\n벌어지고 있거든.",
  str_homestory_811601001_45_dialog_content = "네가 오기 전에도 PlayerName 호 메카랑\n오디 호 메카의 실전 결과에 대해\n생각하던 중이었어.",
  str_homestory_811601001_46_dialog_content = "PlayerName 호 메카는 가볍고 재빠른\n공격을 하고, 오디 호 메카는 무장을 많이\n갖추고 있어서...",
  str_homestory_811601001_47_dialog_content = "정말 굉장한 격전이었다고!",
  str_homestory_811601001_48_dialog_content = "그래... 지금은 진심으로 널 방해하고 싶지 않아졌어...",
  str_homestory_811701001_0_dialog_content = "그람 씨?",
  str_homestory_811701001_1_dialog_content = "그람 씨, 상점에서 뭐 하세요?",
  str_homestory_811701001_2_dialog_content = "어... 혹시 제가 사색을 방해했나요?",
  str_homestory_811701001_3_dialog_content = "아니면 상점에 뭔가 부족한 건가요?",
  str_homestory_811701001_4_dialog_content = "너였군.",
  str_homestory_811701001_5_dialog_content = "그냥 조미료나 좀 살까 해서 왔다.\n배급 받은 고기 중에 유통기한이 거의 다 된\n것들로 꼬치를 만들 생각이거든.",
  str_homestory_811701001_6_dialog_content = "유통기한이 거의 다 된 고기요<sprite=emo_rou size=60 />...?",
  str_homestory_811701001_7_dialog_content = "유통기한이 거의 다 된 거다. 지났다는 게 아니야.\n그러니 당연히 먹어도 된다.",
  str_homestory_811701001_8_dialog_content = "게다가 요리의 수준이라는 건 식재료의 품질이\n아니라 요리사의 기술에 달린 거다!",
  str_homestory_811701001_9_dialog_content = "네! 그람 씨 말씀이 맞아요!",
  str_homestory_811701001_10_dialog_content = "그건 그렇고, 지금까지 그람 씨가 만드신 꼬치는 먹어 본 적이 없네요...",
  str_homestory_811701001_11_dialog_content = "언젠가는 기회가 있을 거다.",
  str_homestory_811701001_12_dialog_content = "꼬치는 내게 누워서 떡 먹기인 요리니까.",
  str_homestory_811701001_13_dialog_content = "...누워서 떡 먹기요?",
  str_homestory_811701001_14_dialog_content = "역시 그람 씨의 요리 재능은 엄청나군요...",
  str_homestory_811701001_15_dialog_content = "요리가 재능이라고?\n지금껏 듣도 보도 못한 소리로군.",
  str_homestory_811701001_16_dialog_content = "흥, 요즘 젊은이들은 툭하면 재능을 강조하지!",
  str_homestory_811701001_17_dialog_content = "세상의 수많은 성과는 피나는 노력과\n꾸준한 연습을 통해 이룬 거다. 재능만 가지고\n어떻게 할 수 있는 게 아니란 말이다!",
  str_homestory_811701001_18_dialog_content = "내가 만든 요리가 맛있는 건 내가 몇 년간\n주방 생활을 했기 때문이다.",
  str_homestory_811701001_19_dialog_content = "요리 솜씨는 「재능」에 기대는 기술이\n아니란 뜻이다.",
  str_homestory_811701001_20_option_content = "이해가 잘 안 돼요.",
  str_homestory_811701001_21_dialog_content = "저도 요리를 해봤죠. 근데 레시피랑 똑같이 따라서 만들어 봤는데도...",
  str_homestory_811701001_22_dialog_content = "별로 맛이 없더라고요.",
  str_homestory_811701001_23_option_content = "조금은 알 것 같아요.",
  str_homestory_811701001_24_dialog_content = "끊임없는 연습을 통해 요리 솜씨를 높일 수 있다는 거죠...?",
  str_homestory_811701001_25_dialog_content = "요리뿐만이 아니라 모든 일이 다 그렇다.",
  str_homestory_811701001_26_dialog_content = "하지만 음식을 맛있게 만들고 싶다면,\n우선 「마음」이 빠져선 안 되지.",
  str_homestory_811701001_27_dialog_content = "마음이요?",
  str_homestory_811701001_28_dialog_content = "그럼 전에 바이스가 만들었던 음식들은...",
  str_homestory_811701001_29_dialog_content = "마음이 조금도 담겨 있지 않았던 걸까요? 아니면 마음이 넘쳐 버렸던 걸까요?",
  str_homestory_811701001_30_dialog_content = "뻔하지. 요리의 순서와 지시의 중요도가\n마음을 덮어버린 거다.",
  str_homestory_811701001_31_dialog_content = "대신 그 아가씨는 얻고 잃게 될 것을\n매우 신경 쓰고 있는 거겠지.",
  str_homestory_811701001_32_dialog_content = "음, 그건 저도 똑같은걸요.",
  str_homestory_811701001_33_dialog_content = "망칠까 봐 무서우면서도 맛있는 음식은 만들고 싶고...\n그러면서 정신없이 허둥지둥 요리를 하게 되죠...",
  str_homestory_811701001_34_dialog_content = "간단한 예를 들어 보마.",
  str_homestory_811701001_35_dialog_content = "후방 지원을 맡았을 때, 비록 난 전장에 더\n나서고 싶었지만,그래도 맛있는 음식을\n만들 수 있었던 이유는 단 하나뿐이다.",
  str_homestory_811701001_36_dialog_content = "그건 바로 형제들이 든든하게 먹고 더 기운차게\n전투를 할 수 있기를 바랐기 때문이다.",
  str_homestory_811701001_37_dialog_content = "지금 내가 여기서 요리하는 이유도 그때와 같다.",
  str_homestory_811701001_38_dialog_content = "여기 젊은이들이 든든하게 먹을 수 있기를\n바라기 때문이지! 잘 먹어야 전투를 치를\n기운도 생기는 거다!",
  str_homestory_811701001_39_dialog_content = "음식을 맛있게 만드는 건 이처럼 간단한 거다.",
  str_homestory_811701001_40_dialog_content = "순서와 지시에 따라 조리하고,\n어수선한 잡생각은 버리면 된다.",
  str_homestory_811701001_41_dialog_content = "생각이 많으면 오히려 잘못되기도 쉽지. 이해했나?",
  str_homestory_811701001_42_dialog_content = "네! 이해했어요!",
  str_homestory_811701001_43_dialog_content = "정말 맞는 말이에요, 그람 씨!",
  str_homestory_811701001_44_dialog_content = "진짜 그람 씨가 요리 기술을 다루는 책이라도 내셨으면 좋겠다니까요.",
  str_homestory_811701001_45_dialog_content = "레디젤 사막 사람도 책을 냈으니까... 그람 씨도 할 수 있어요!",
  str_homestory_811701001_46_dialog_content = "원하시면 움브라톤 쪽 사람한테 제가 연락해 드릴게요.",
  str_homestory_811701001_47_dialog_content = "그건 나중에 이야기하지. 생각 좀 해 볼 테니까.",
  str_homestory_811701001_48_dialog_content = "꼬치를 다 만들면 같이 먹겠나?",
  str_homestory_811701001_49_dialog_content = "네, 물론이죠!",
  str_homestory_807701001_0_dialog_content = "여왕 폐하?",
  str_homestory_807701001_1_dialog_content = "여왕 폐하...",
  str_homestory_807701001_2_dialog_content = "음, 왔구나. 미래를 가진 자여.",
  str_homestory_807701001_3_option_content = "어서 오세요.",
  str_homestory_807701001_4_dialog_content = "먼 길도 마다 않고 헤븐즈 밸리에 행차해 주셔서 정말 영광이에요.",
  str_homestory_807701001_5_dialog_content = "PlayerName, 그렇게 예의를 차리지 않아도 된다.",
  str_homestory_807701001_6_dialog_content = "방금 전까지 계속 바람의 탑을 보고 있었다.",
  str_homestory_807701001_7_option_content = "제가 방해했나요?",
  str_homestory_807701001_8_dialog_content = "되게 집중하고 계셨던 것 같은데...",
  str_homestory_807701001_9_dialog_content = "그렇다. 바람의 탑을 보고 있었다.",
  str_homestory_807701001_10_dialog_content = "바람의 탑이요? 바람의 탑에 무슨 문제라도 있나요?",
  str_homestory_807701001_11_dialog_content = "음... 바람의 탑은 아이테르에게\n매우 뜻깊은 건축물이라지.",
  str_homestory_807701001_12_dialog_content = "맞아요! 바람의 탑은 사실 엄청 거대한 건물이에요.",
  str_homestory_807701001_13_dialog_content = "여기서 보면 그렇게 느껴지지 않을 수도 있겠지만, 사실은 엄청 크고 내부도 넓어요!",
  str_homestory_807701001_14_dialog_content = "콜로서스를 생산하고 수리하는 기능도 갖추고 있고요.",
  str_homestory_807701001_15_dialog_content = "그리고 자료에 의하면 수많은 아이테르가 여기서 교육을 받았던 모양이에요.",
  str_homestory_807701001_16_dialog_content = "조종사를 육성하는 터전이나 다름없었던 거죠.",
  str_homestory_807701001_17_dialog_content = "터전이라... 그러한가.",
  str_homestory_807701001_18_dialog_content = "보아라. 이 탑은 하늘 아래에서\n유달리 눈부시게 빛나고 있다.",
  str_homestory_807701001_19_dialog_content = "마치 아이테르의... 정신적 토템처럼 말이다.",
  str_homestory_807701001_20_dialog_content = "PlayerName, 그대는 사람들의 결집이\n무엇을 통해 이루어지는지 아는가?",
  str_homestory_807701001_21_dialog_content = "갑자기 그렇게 물어보시면...",
  str_homestory_807701001_22_dialog_content = "죄송해요, 자세히 생각해 본 적은 없어요.",
  str_homestory_807701001_23_dialog_content = "괜찮다. 이건 과거의 그대에게는 그리 중요하지\n않았을 테니 말이다.",
  str_homestory_807701001_24_dialog_content = "그러나 지금은 다르다.\n그대는 완전히 새로운 시각으로 이 대륙을\n관찰하여야 한다.",
  str_homestory_807701001_25_dialog_content = "이곳의 수많은 이들은 몸집도, 힘도,\n나이도 저마다 다르지.",
  str_homestory_807701001_26_dialog_content = "그러나 공통된 믿음과 신념을 가지고 있으면...",
  str_homestory_807701001_27_dialog_content = "결집할 수 있는 것이다.",
  str_homestory_807701001_28_dialog_content = "우리는 자연의 생물들과 홀로 싸워서\n승리할 수는 없다.",
  str_homestory_807701001_29_dialog_content = "우리는 날카로운 이와 발톱이 없고,\n바위처럼 단단한 피부와 하늘을 날 수 있는\n날개도 없다.",
  str_homestory_807701001_30_dialog_content = "그러나 우리는 단결하여 상상 이상의\n힘을 발휘할 수 있다...",
  str_homestory_807701001_31_dialog_content = "그렇게 본다면...",
  str_homestory_807701001_32_dialog_content = "사실 여왕 폐하는 방금 말씀하셨던 「정신적 토템」과 비슷한 분이에요.",
  str_homestory_807701001_33_dialog_content = "......",
  str_homestory_807701001_34_dialog_content = "음, 확실히 그렇구나.",
  str_homestory_807701001_35_dialog_content = "사람들은 신뢰, 흠모 또는 나의 비호를\n필요로 하여 내 곁에 머문다.",
  str_homestory_807701001_36_dialog_content = "이는 결코 나쁜 일이 아니다.",
  str_homestory_807701001_37_dialog_content = "단결한 이들은 그러지 못한 이들보다\n더 강하기 마련이니 말이다.",
  str_homestory_807701001_38_dialog_content = "일루미나든 백야성이든...\n그들은 저마다 옳다고 생각하는 방식으로\n이러한 단결을 유지하고 있다.",
  str_homestory_807701001_39_dialog_content = "맞아요... 그 점은 저도 이제 잘 이해하게 됐어요.",
  str_homestory_807701001_40_dialog_content = "그대도 성장하였구나. 미래를 가진 아이테르여.",
  str_homestory_807701001_41_dialog_content = "이 순백의 탑, 아이테르의 토템은\n바로 그대처럼...",
  str_homestory_807701001_42_dialog_content = "모두를 단결하게 만드는 힘을 지니고 있다.",
  str_homestory_807701001_43_dialog_content = "저도 사람들을 모아 헤븐즈 밸리를 지킬 수 있는 걸까요...\n아, 여왕 폐하. 주제넘은 질문이 하나 있는데요...",
  str_homestory_807701001_44_dialog_content = "괜찮다. 말해 보아라.",
  str_homestory_807701001_45_dialog_content = "폐하께서 미래를 보실 때... 지금의 헤븐즈 밸리도 보셨나요?",
  str_homestory_807701001_46_dialog_content = "...그렇다. 게다가 그것만이 아니었지.",
  str_homestory_804201001_0_dialog_content = "바튼 씨!",
  str_homestory_804201001_1_dialog_content = "어이, 조종사!",
  str_homestory_804201001_2_dialog_content = "바튼 씨...",
  str_homestory_804201001_3_dialog_content = "쉿... 나랑 같이 관찰 좀 해 보자.<sprite=emo_mojing size=60 />",
  str_homestory_804201001_4_dialog_content = "...관찰이요?",
  str_homestory_804201001_5_dialog_content = "뭘 관찰하는데요?",
  str_homestory_804201001_6_dialog_content = "여긴 인재가 꽤 많군! 조종사!",
  str_homestory_804201001_7_dialog_content = "전에 콜로서스에 있었을 때는 어째서 몰랐던 거지?",
  str_homestory_804201001_8_dialog_content = "아, 이곳은 콜로서스보다 훨씬 넓으니까,\n실력을 발휘하는 사람도 많아졌기 때문인가!",
  str_homestory_804201001_9_dialog_content = "...인재요?",
  str_homestory_804201001_10_dialog_content = "사람들을 일루미나에 가입시키려고요...?",
  str_homestory_804201001_11_dialog_content = "가입? 아니, 가입할 필요는 없다.",
  str_homestory_804201001_12_dialog_content = "하나 물어보지. PlayerName,\n넌 내가 몇 군단에 속해있는지 알고 있나?",
  str_homestory_804201001_13_option_content = "제2군단이요.",
  str_homestory_804201001_14_dialog_content = "그래, 맞다!",
  str_homestory_804201001_15_option_content = "제4군단이요.",
  str_homestory_804201001_16_dialog_content = "착각한 거 아니냐?<sprite=emo_shengqi size=60 />\n애송이, 내 휘하의 병력은 그 여자보다\n훨씬 더 많단 말이다!",
  str_homestory_804201001_17_dialog_content = "흥, 레이스의 정예 예비부대는 한주먹 거리도\n안 되는 수준이라고!",
  str_homestory_804201001_18_dialog_content = "내가 이끄는 건 병력이 가장 많은 제2군단이다.\n잘 기억해 뒀겠지?",
  str_homestory_804201001_19_dialog_content = "기, 기억했어요...",
  str_homestory_804201001_20_dialog_content = "대원수가 내게 맡긴 임무가 뭔지 아나?",
  str_homestory_804201001_21_option_content = "신속 지원이죠?",
  str_homestory_804201001_22_dialog_content = "...그건 히이로와 바이스의 일이다.",
  str_homestory_804201001_23_dialog_content = "어이, 애송이. 어떻게 제대로 기억하는 게\n하나도 없는 거냐?",
  str_homestory_804201001_24_dialog_content = "내 임무는 수비다!",
  str_homestory_804201001_25_dialog_content = "...이젠 확실히 알았겠지?",
  str_homestory_804201001_26_dialog_content = "아, 알았어요.",
  str_homestory_804201001_27_option_content = "수비죠?",
  str_homestory_804201001_28_dialog_content = "그래! 평소에 널 가르쳤던 게\n쓸모없진 않았던 모양이군!",
  str_homestory_804201001_29_dialog_content = "그걸 알고 있다면, 이제 내가 여기서\n뭘 하려는 건지도 이해했겠지.",
  str_homestory_804201001_30_dialog_content = "생각해 봐라.\n이곳엔 대단한 능력을 가진 녀석들이 많이 있다...",
  str_homestory_804201001_31_dialog_content = "게다가 시도 때도 없이 큰 싸움을 벌이고 있지...",
  str_homestory_804201001_32_dialog_content = "기습! 암살 무기! 체술 공격까지!",
  str_homestory_804201001_33_dialog_content = "훗, 아주 볼만하다고.",
  str_homestory_804201001_34_dialog_content = "사실 난 저들을 일루미나에 가입시킬 필요가 없다.\n무슨 뜻인지 알겠나?",
  str_homestory_804201001_35_dialog_content = "난 그저 여기서 저들의 공격과 방어의 방식을\n관찰할 수만 있으면 된다.",
  str_homestory_804201001_36_dialog_content = "다른 지역의 사람에게 뭔가 배울 수 있을\n뿐만 아니라, 병사들에게도 전해줄 수 있겠지.",
  str_homestory_804201001_37_dialog_content = "그건 매우 귀중한 정보다!",
  str_homestory_804201001_38_dialog_content = "그랬군요...",
  str_homestory_804201001_39_dialog_content = "잠깐만요, 갑자기 떠오른 건데... 자주 싸움을 벌인다는 건 무슨 말이죠?!",
  str_homestory_804201001_40_dialog_content = "여긴 서로를 껄끄럽게 생각하는\n오로리안들이 꽤 많지 않나.",
  str_homestory_804201001_41_dialog_content = "콜로서스에서 매일 티격태격하니까\n너도 진작에 익숙해진 줄 알았지.",
  str_homestory_804201001_42_dialog_content = "하지만...",
  str_homestory_804201001_43_dialog_content = "그냥 친한 친구끼리 실력을 겨루는 거라고 생각해라!",
  str_homestory_804201001_44_dialog_content = "난 돌아가서 어제 본 그 기술에 대해\n생각을 좀 해 봐야겠어...",
  str_homestory_804201001_45_dialog_content = "그자는 대체 어떻게 그 여자의 발차기를\n막을 수 있었던 거지?",
  str_homestory_804201001_46_dialog_content = "그래, 나도 얼른 그 기술을 익혀야겠어.\n그럼 다음에 레이스가 다시 날 도발할 때...",
  str_homestory_804201001_47_dialog_content = "에잇── 흐아압!<sprite=emo_nuhuo size=60 />",
  str_homestory_804201001_48_dialog_content = "...그래요. 힘내세요, 바튼 씨...",
  str_homestory_807601001_0_dialog_content = "클레이튼...",
  str_homestory_807601001_1_dialog_content = "아, 항해하는 용사가 드디어 착륙한 모양이네.",
  str_homestory_807601001_2_dialog_content = "안녕, 클레이튼.",
  str_homestory_807601001_3_dialog_content = "폭포산 암석이 마음에 들어? 항상 네가 이 근처에서 돌아다니는 걸 본 것 같거든...",
  str_homestory_807601001_4_dialog_content = "이곳엔 드물게도 물이 흐르고 있으니까.",
  str_homestory_807601001_5_dialog_content = "게다가 물줄기가 아주 풍성한 편이잖아.\n감동해서 눈물<sprite=emo_hanshui size=60 />이 다 나올 것 같아.",
  str_homestory_807601001_6_dialog_content = "혹시 비꼬는 거야?",
  str_homestory_807601001_7_dialog_content = "하긴, 이곳의 물줄기는 관상용밖에 없긴 하니까...",
  str_homestory_807601001_8_dialog_content = "네가 평소에 말하는 「바다」니 「침몰」이니 하는 거랑은 전혀 다를 거야.",
  str_homestory_807601001_9_dialog_content = "난 지금 고마워하는 거야.",
  str_homestory_807601001_10_dialog_content = "...뭐 때문에 나한테 고마워하는데?",
  str_homestory_807601001_11_dialog_content = "이제 곧 나의 「정탐술」이 여기서 실현되는\n모습을 볼 수 있을 거야.",
  str_homestory_807601001_12_dialog_content = "그럼 네 그 귀여운 머릿속에서\n네가 요즘 뭘 하고 다녔는지\n볼 수 있게 되겠지...",
  str_homestory_807601001_13_dialog_content = "네 그 빠져들 것만 같은 눈을 바라보면\n답을 얻을 수 있을 것 같아.",
  str_homestory_807601001_14_dialog_content = "내 첫 증인이 돼줘서 고마워.",
  str_homestory_807601001_15_dialog_content = "으엑...",
  str_homestory_807601001_16_option_content = "정탐술?",
  str_homestory_807601001_17_dialog_content = "이제 궁금해지기 시작했구나. 내 꼬마 친구...",
  str_homestory_807601001_18_option_content = "거절해도 돼?",
  str_homestory_807601001_19_dialog_content = "물론이지.",
  str_homestory_807601001_20_dialog_content = "다만 내 뒤에 있는 작고 날렵한 녀석들은\n널 놓아주지 않을 거야.",
  str_homestory_807601001_21_dialog_content = "네가 잠들어 있을 때 널 관찰하는 걸\n제일 좋아하는 녀석들이니까...",
  str_homestory_807601001_22_dialog_content = "(...등골이 오싹해지잖아!)",
  str_homestory_807601001_23_dialog_content = "그래... 그럼 잠깐만이야. 나 많이 바쁘거든.",
  str_homestory_807601001_24_dialog_content = "「정탐술」이 대체 뭐야?",
  str_homestory_807601001_25_dialog_content = "금방 설명해 줄게.",
  str_homestory_807601001_26_dialog_content = "넌 최근에 움브라톤에 간 적이 있을 거야...",
  str_homestory_807601001_27_dialog_content = "그리고 한가하게 거리를 구경하다가\n불쌍한 소녀 한 명을 발견했겠지.",
  str_homestory_807601001_28_dialog_content = "그 소녀는 네게 거리에 있는 레스토랑들의\n요리 가격이 얼마인지 확인해 달라고 했었어.",
  str_homestory_807601001_29_dialog_content = "소녀는 가진 돈이 너무 적어서,\n무턱대고 레스토랑에 들어가서 식사를\n할 수는 없었거든.",
  str_homestory_807601001_30_dialog_content = "그냥 빵 한 조각만 주문하면 웨이터가 어떤\n표정을 지을지 상상하고 싶지도 않았을 거야...",
  str_homestory_807601001_31_dialog_content = "그래서 넌 그 소녀를 데리고 레스토랑에 가서\n요리들의 가격을 알려 줬어.",
  str_homestory_807601001_32_dialog_content = "근데 그 소녀는 계속 고개만 저었지.",
  str_homestory_807601001_33_dialog_content = "결국 넌 참지 못하고 소녀한테\n맛있는 음식을 한 끼 사 줬어...",
  str_homestory_807601001_34_dialog_content = "근데 식사를 마치고 나서 소녀는 너한테\n고맙다는 인사를 하고, 식사 비용도 테이블 위에\n두고는 쏜살같이 달려가 버렸어.",
  str_homestory_807601001_35_dialog_content = "...그걸 어떻게 알았어?!",
  str_homestory_807601001_36_dialog_content = "(...그 「정탐술」이라는 게 이렇게 신기한 거였어?)",
  str_homestory_807601001_37_dialog_content = "아무튼... 그래, 좀 이해하기 어렵긴 했었어.",
  str_homestory_807601001_38_dialog_content = "식사 비용을 가지고 있었다면 대체 왜 바로 레스토랑에 들어가지 않은 거야?",
  str_homestory_807601001_39_dialog_content = "네가 말한 것처럼... 그 애는 움브라톤에 있는 모든 레스토랑의 가격을 전부 봤다니까!",
  str_homestory_807601001_40_dialog_content = "하하... 하하하<sprite=emo_guilian size=60 />...",
  str_homestory_807601001_41_dialog_content = "그거, 내가 그렇게 하라고 시킨 거거든.",
  str_homestory_807601001_42_dialog_content = "원래는 이스타반 님이 내게 맡기신 임무였어...",
  str_homestory_807601001_43_dialog_content = "「움브라톤의 식음료 가격 조사」.",
  str_homestory_807601001_44_dialog_content = "그 소녀는 내가 줄곧 도와줬던 아이거든.\n그래서 이번엔 그 애한테 날 도울 기회를 줬어.\n그럼 그 애도 자신이 쓸모 있다고 느낄 테니까...",
  str_homestory_807601001_45_dialog_content = "게다가 할 일 없는 아이테르가 나 대신 일을\n끝내 줬으니까, 이보다 더 즐거울 수는 없잖아?",
  str_homestory_807601001_46_dialog_content = "그리고... 걷는 건 나한테 아주 힘든 일이거든.",
  str_homestory_807601001_47_dialog_content = "......",
  str_homestory_807601001_48_dialog_content = "이게 바로 「정탐술」의 진실이야, PlayerName.",
  str_homestory_807601001_49_dialog_content = "그렇게나 실망한 표정이라니... 정말 너무 재밌네.",
  str_homestory_804601001_0_dialog_content = "파이구나.",
  str_homestory_804601001_1_dialog_content = "조종사님이 왔네, 조종사님이 도착했네♪",
  str_homestory_804601001_2_dialog_content = "조종사님은 파이를 보고 싱긋♪\n하지만 파이가 원하는 건 시끌♪",
  str_homestory_804601001_3_dialog_content = "상점 구경하고 있었어?",
  str_homestory_804601001_4_dialog_content = "상점 구경♪\n조종사님은 파이가 상점 구경을 한다고 생각해.<sprite=emo_yinfu size=60 />",
  str_homestory_804601001_5_dialog_content = "디암은 아니라고, 카라는 맞다고,\n니엘은 비슷하다고 대답하겠지만...\n파이는 그냥 「꼬꼬!」라고만 해.<sprite=emo_muji size=60 />",
  str_homestory_804601001_6_dialog_content = "그럼 조종사님은 내가 뭐라고 말할\n거라고 생각할까?",
  str_homestory_804601001_7_dialog_content = "...%$#",
  str_homestory_804601001_8_dialog_content = "됐어, 수수께끼는 그냥 포기할게...",
  str_homestory_804601001_9_dialog_content = "난 그냥 여기서 잘 지내고 있냐고 물어보려던 건데...",
  str_homestory_804601001_10_dialog_content = "여전히 어리지만 당찬 네 모습을 봐서 안심했어.",
  str_homestory_804601001_11_dialog_content = "조종사님이 키팅을 신경 써 줘서\n파이는 정말 영광스러워♪",
  str_homestory_804601001_12_dialog_content = "조종사님은 내가 요즘 누굴 만났는지 궁금하지 않아?",
  str_homestory_804601001_13_dialog_content = "...어째 안 좋은 예감이 드는데?<sprite=emo_tanqi size=60 />",
  str_homestory_804601001_14_dialog_content = "누굴 만났는데?",
  str_homestory_804601001_15_dialog_content = "너 말고 다른 애들도 조금은 조심해야 해. 아무나 조롱하면 안 되는 거야...",
  str_homestory_804601001_16_dialog_content = "여긴 백야성이 아니야. 성격이 나쁜 오로리안도 있다고!",
  str_homestory_804601001_17_dialog_content = "그리고 성격이 무척 섬세한 오로리안들도 있어.\n그런 오로리안들은 너희가 한, 두 마디만 해도 바로 울어 버리고 말 거야...",
  str_homestory_804601001_18_dialog_content = "조종사님이 우리를 걱정하네♪\n조종사님이 동료를 걱정하네♪",
  str_homestory_804601001_19_dialog_content = "긴 꼬리의 수리공을 만났네♪\n우린 닭 포획용 로봇손을 만들어 달라고 했지♪",
  str_homestory_804601001_20_dialog_content = "동글동글한 작은 새를 만났네♪\n그녀는 우리에게 데굴데굴 눈덩이를 주었지♪",
  str_homestory_804601001_21_dialog_content = "양복을 입은 멍멍이를 만났네♪\n팔리지 않는 가짜 그림 때문에 고민 중이었지♪",
  str_homestory_804601001_22_dialog_content = "파이가 땅딸막한 조종사님을 만났네♪\n내 맞은편에서 친구 걱정을 하고 있지♪",
  str_homestory_804601001_23_dialog_content = "...그래, 무슨 문제가 있었던 건 아닌 모양이네.",
  str_homestory_804601001_24_dialog_content = "근데 솔직히 말하자면, 방금 그게 네가 그동안 했던 말 중에\n가장 따뜻했던 말이었던 것 같아...",
  str_homestory_804601001_25_dialog_content = "따뜻한 말에는 그 이유가 있는 법이야.",
  str_homestory_804601001_26_dialog_content = "책장에는 디암이 아끼는 책이 있고♪",
  str_homestory_804601001_27_dialog_content = "방에는 니엘이 쓸 안경닦이가 있어♪",
  str_homestory_804601001_28_dialog_content = "식당에는 카라한테 필요한 모자걸이가 있고♪",
  str_homestory_804601001_29_dialog_content = "풀밭에는 꼬꼬랑 파이가 좋아하는 간식이 있지♪",
  str_homestory_804601001_30_dialog_content = "조종사님은 우리한테 다정해♪\n우리 마음을 다 알아 버리지♪",
  str_homestory_804601001_31_dialog_content = "조종사님은 내일의 별이지♪",
  str_homestory_804601001_32_dialog_content = "키가 꼭 자랄 내일의 별이지♪",
  str_homestory_804601001_33_dialog_content = "...마지막 한 줄만 빼도 라임은 잘 맞았을 거라고.",
  str_homestory_804601001_34_dialog_content = "조종사님은 이제 뭘 할 거야?",
  str_homestory_804601001_35_option_content = "가서 쉴 거야.",
  str_homestory_804601001_36_dialog_content = "잠깐 좀 자려고.",
  str_homestory_804601001_37_option_content = "좀 돌아다닐 거야.",
  str_homestory_804601001_38_dialog_content = "다른 사람들은 뭘 하고 있는지도 좀 둘러보려고.",
  str_homestory_804601001_39_dialog_content = "알겠어, 파이도 잘 알았어.",
  str_homestory_804601001_40_dialog_content = "사실 파이는 별 관심 없지만, 그래도 조종사님한테\n할 말이 하나 있어.",
  str_homestory_804601001_41_dialog_content = "꼬꼬가 조종사님의 꽃밭 근처에\n비료를 주고 있어♪ 비료♪",
  str_homestory_804601001_42_dialog_content = "...?!",
  str_homestory_804601001_43_dialog_content = "비료?!",
  str_homestory_804601001_44_dialog_content = "파이가 친절하게 알려줬으니까\n얼른 가서 확인해 봐♪",
  str_homestory_804601001_45_dialog_content = "...그래, 친절하게 알려줘서 차암 고맙다!",
  str_homestory_805701001_0_dialog_content = "이건... 고양이 털?",
  str_homestory_805701001_1_dialog_content = "하아──암──",
  str_homestory_805701001_2_dialog_content = "어라, 필리시?",
  str_homestory_805701001_3_dialog_content = "휴우... 휴우...<sprite=emo_kun size=60 />",
  str_homestory_805701001_4_dialog_content = "...필리시?",
  str_homestory_805701001_5_dialog_content = "휴우...우냐앙!",
  str_homestory_805701001_6_dialog_content = "뭐야, PlayerName 너였냥.",
  str_homestory_805701001_7_dialog_content = "자고 있는 거 안 보이냥?",
  str_homestory_805701001_8_dialog_content = "볼일 있으면... 일어난 다음에 다시 말하라냥.",
  str_homestory_805701001_9_dialog_content = "난 이제부터 따뜻한 풀숲에 들어가서...\n편안하게 한숨 잘꺼다냥...",
  str_homestory_805701001_10_dialog_content = "자, 잠깐만, 필리시! 할 말이 있어!",
  str_homestory_805701001_11_dialog_content = "후...후하암... 냥!",
  str_homestory_805701001_12_dialog_content = "아이, 참... 대체 무슨 말을 하고 싶은거냥.",
  str_homestory_805701001_13_dialog_content = "별거 아닌 일이면 화낼 거다냥!",
  str_homestory_805701001_14_dialog_content = "그게... 사실 다른 오로리안이 날 찾아왔는데...",
  str_homestory_805701001_15_dialog_content = "필리시, 혹시 요즘...",
  str_homestory_805701001_16_option_content = "컨디션이 안 좋아?",
  str_homestory_805701001_17_dialog_content = "예를 들면... 몸이 간지럽다거나...",
  str_homestory_805701001_18_dialog_content = "영 입맛이 없다거나 그런 거 없어?",
  str_homestory_805701001_19_dialog_content = "대체 무슨 소리를 하는 거냥.",
  str_homestory_805701001_20_dialog_content = "필리시는 전혀 이해가 안 된다냥~",
  str_homestory_805701001_21_option_content = "털갈이 시기야?",
  str_homestory_805701001_22_dialog_content = "털가리냥...?",
  str_homestory_805701001_23_dialog_content = "그게 뭐냥?",
  str_homestory_805701001_24_dialog_content = "(모르는 척하는 티가 너무 나잖아!)",
  str_homestory_805701001_25_dialog_content = "아, 아무튼, 필리시 넌 아무렇지도 않아?!",
  str_homestory_805701001_26_dialog_content = "(필리시의 꼬리를 쓰다듬는다)",
  str_homestory_805701001_27_dialog_content = "우냐앙!",
  str_homestory_805701001_28_dialog_content = "PlayerName, 어떻게 갑자기 숙녀의 꼬리를\n만질 수 있는 거냥!",
  str_homestory_805701001_29_dialog_content = "기...기분이 조금 좋긴 하지만...\n그려면 안 되는 거다냥!",
  str_homestory_805701001_30_dialog_content = "필리시 너... 털이 엄청나게 떨어지고 있잖아!",
  str_homestory_805701001_31_dialog_content = "그, 그렇지 않다냥...!",
  str_homestory_805701001_32_dialog_content = "우...우으으냥, 하지만 어쩔 수가 없다냥!",
  str_homestory_805701001_33_dialog_content = "매번 이 계절이 되면...\n털갈이를 하게 되는 거다냥!",
  str_homestory_805701001_34_dialog_content = "이건 털들이 햇볕을 흡수해서 새롭게 진화하는\n과정인 거다냥!",
  str_homestory_805701001_35_dialog_content = "털을 다 갈고 나면...\n슈! 퍼! 필리시가 될 거다냥!",
  str_homestory_805701001_36_dialog_content = "하지만... 털을 이렇게 막 날리게 두면...",
  str_homestory_805701001_37_dialog_content = "알레르기가 있는 오로리안들이 힘들어지지 않을까?",
  str_homestory_805701001_38_dialog_content = "음...그, 그럼 어떻게 하면 좋냥.",
  str_homestory_805701001_39_dialog_content = "필리시도 일부러 이러는 건 아니다냥.<sprite=emo_tanqi size=60 />",
  str_homestory_805701001_40_dialog_content = "하긴 그렇지... 생각 좀 해 볼게...",
  str_homestory_805701001_41_dialog_content = "그렇지! 내가 털을 좀 빗겨 줄게.",
  str_homestory_805701001_42_dialog_content = "빗으면 털도 더 부드러워질 거고, 아무 데나 날리지도 않을 거야.",
  str_homestory_805701001_43_dialog_content = "이스타반 씨가 가르쳐 줬어.",
  str_homestory_805701001_44_dialog_content = "음... 그럼 헤븐즈 밸리에 이렇게 기분 좋은 풀숲도\n만들어 줬으니까...",
  str_homestory_805701001_45_dialog_content = "뭐, 조금은 내 털을 빗기는 걸 허락해 주겠다냥!",
  str_homestory_803601001_0_dialog_content = "휴라드?",
  str_homestory_803601001_1_dialog_content = "뭐 하고 있는 거야?",
  str_homestory_803601001_2_dialog_content = "보면 몰라?",
  str_homestory_803601001_3_dialog_content = "서 있잖아.",
  str_homestory_803601001_4_dialog_content = "...그, 그건 알지.",
  str_homestory_803601001_5_dialog_content = "......",
  str_homestory_803601001_6_dialog_content = "............",
  str_homestory_803601001_7_dialog_content = "어이.",
  str_homestory_803601001_8_dialog_content = "왜?",
  str_homestory_803601001_9_dialog_content = "나 어제 다쳤어.",
  str_homestory_803601001_10_dialog_content = "...?!",
  str_homestory_803601001_11_option_content = "괜찮아?",
  str_homestory_803601001_12_dialog_content = "안 죽었잖아.",
  str_homestory_803601001_13_option_content = "어디 갔었는데?",
  str_homestory_803601001_14_dialog_content = "네가 뭘 걱정하는 건지는 알아.",
  str_homestory_803601001_15_dialog_content = "여기에서 다친 건 아니야.",
  str_homestory_803601001_16_dialog_content = "나...난 그냥 네 건강이 좀 걱정된 거야.",
  str_homestory_803601001_17_dialog_content = "지금은? 다친 데는 좀 나았어?",
  str_homestory_803601001_18_dialog_content = "그럭저럭.",
  str_homestory_803601001_19_dialog_content = "그림자 늑대 덕분에 빨리 회복할 수 있었어.",
  str_homestory_803601001_20_dialog_content = "알겠어... 근데 왜 다친 건지 알려주면 안 될까?",
  str_homestory_803601001_21_dialog_content = "설마 일부러 말 안 해주려는 건 아니지?",
  str_homestory_803601001_22_dialog_content = "남의 물건을 뺐다가 다쳤어.",
  str_homestory_803601001_23_dialog_content = "움브라톤 암시장에서.",
  str_homestory_803601001_24_dialog_content = "무슨 물건이었길래?",
  str_homestory_803601001_25_dialog_content = "고대 문명의 산물이라던데.",
  str_homestory_803601001_26_dialog_content = "「이라던데」?",
  str_homestory_803601001_27_dialog_content = "그러니까 넌 그 물건이 진짜인지 가짜인지도 모른다는 거네?",
  str_homestory_803601001_28_dialog_content = "그래도 시도는 해 봐야지.",
  str_homestory_803601001_29_dialog_content = "...대체 어떤 물건이었길래? 그렇게 중요한 거야?",
  str_homestory_803601001_30_dialog_content = "「환각」이나 「그림자 마법」 같은 영체를\n완전히 실체화시킬 수 있는 장치라고 했어.",
  str_homestory_803601001_31_dialog_content = "음... 근데 그림자 늑대는 항상 네 곁에 있는 거 아니었어?",
  str_homestory_803601001_32_dialog_content = "그래. 하지만 난 매일 녀석들의\n털을 쓰다듬고 싶다고.",
  str_homestory_803601001_33_dialog_content = "털갈이 철에만 떨어지는 그런 자질구레한\n털이 아니라 피부에서 자라난 진짜 털 말이야.",
  str_homestory_803601001_34_dialog_content = "그랬구나...",
  str_homestory_803601001_35_dialog_content = "(설마 휴라드... 조금 외로운 걸까?)",
  str_homestory_803601001_36_dialog_content = "근데 그거 아마 가짜였을 거야.",
  str_homestory_803601001_37_dialog_content = "그 장치가?",
  str_homestory_803601001_38_dialog_content = "그래.",
  str_homestory_803601001_39_dialog_content = "아무튼 나도 살면서 처음 들어보는 물건이었으니까.",
  str_homestory_803601001_40_dialog_content = "(그게 가짜라면 휴라드의 기분이 조금은 나아질까?)",
  str_homestory_803601001_41_dialog_content = "그러게, 나도 가짜일 거라 생각해.",
  str_homestory_803601001_42_dialog_content = "만약에 진짜 그런 게 있었다면 진작에 어느 집의 귀중한 가보가 됐을걸...",
  str_homestory_803601001_43_dialog_content = "암시장에 나올 가능성은 거의 없어.",
  str_homestory_803601001_44_dialog_content = "...그래.",
  str_homestory_803601001_45_dialog_content = "너까지 그렇게 말한다면 정말 그런 거겠지.",
  str_homestory_803601001_46_dialog_content = "그럼 난 가 볼게.",
  str_homestory_803601001_47_dialog_content = "자, 잘 가!",
  str_homestory_803601001_48_dialog_content = "(만약 진짜 그런 장치가 있다면... 난 그걸 가지고 뭘 하려나?)",
  str_homestory_811401001_0_dialog_content = "이 말은...",
  str_homestory_811401001_1_dialog_content = "어머, 조종사잖아.",
  str_homestory_811401001_2_dialog_content = "안나가 길을 막은 거야?",
  str_homestory_811401001_3_dialog_content = "아니면 네가 날 찾아온 걸까?",
  str_homestory_811401001_4_dialog_content = "미안, 이 꽃들의 향기에 매혹되는 바람에\n오래 머물러 버렸지 뭐야...",
  str_homestory_811401001_5_dialog_content = "아니야, 별일 없었어. 꽃은 얼마든지 감상해도 돼.",
  str_homestory_811401001_6_dialog_content = "꽃들이 이렇게 빨리 피었구나...",
  str_homestory_811401001_7_dialog_content = "내가 생각했던 것보다 많이 피었잖아.",
  str_homestory_811401001_8_dialog_content = "응? 조종사, 방금 뭐라고 했어?",
  str_homestory_811401001_9_dialog_content = "아, 이 꽃들 얘기였어.",
  str_homestory_811401001_10_dialog_content = "며칠 전에 쿠리어 길드<sprite=emo_gezitou size=60 />에 부탁해서 가져온 것들이었거든.",
  str_homestory_811401001_11_dialog_content = "여긴 바위랑 나무뿐이니까, 꽃도 좀 있어야 한다고 누가 그랬거든.",
  str_homestory_811401001_12_dialog_content = "어머? 나랑 똑같은 생각을 한 사람이 있었잖아?",
  str_homestory_811401001_13_dialog_content = "며칠 전에 나도 안나한테 여긴 신선한 꽃이\n더 있어야 할 것 같다고 했거든.",
  str_homestory_811401001_14_dialog_content = "그래, 맞아. 그래서 쿠리어 길드에 꽃을 좀 가져다 달라고 한 거야.",
  str_homestory_811401001_15_dialog_content = "근데 지금 이건... 내가 필요하다고 했던 것보다 좀 많은 것 같아...",
  str_homestory_811401001_16_dialog_content = "나도 저번 임무를 마치고 근처에서\n꽃을 좀 사 왔거든. 그래서 그럴 거야.",
  str_homestory_811401001_17_dialog_content = "아, 그랬구나...",
  str_homestory_811401001_18_dialog_content = "그래도 여긴 정말 괜찮은 곳이야, 조종사.",
  str_homestory_811401001_19_dialog_content = "상점에 가 보니까 내가 제일 좋아하는\n진도 팔고 있었어...",
  str_homestory_811401001_20_dialog_content = "게다가 칵테일에 꼭 있어야 하는\n식물, 시럽, 향신료도 있었어.",
  str_homestory_811401001_21_dialog_content = "아하하, 정말 상상도 못 했다니까!",
  str_homestory_811401001_22_dialog_content = "너, 왠지 더 자상해진 것 같잖아?",
  str_homestory_811401001_23_dialog_content = "자, 자상하다니...",
  str_homestory_811401001_24_dialog_content = "예전의 그 꼬맹이가 대체 어떤 일을 겪었길래~\n이렇게나 자상하게 변했을까?",
  str_homestory_811401001_25_dialog_content = "제네비브가 말하는 자상하다는 건... 상점에 진을 가져다 둬서 그런 거지?",
  str_homestory_811401001_26_dialog_content = "그것 때문만은 아니야.\n그 작은 새들한테 부탁해서 숙녀라면 누구나\n좋아하는 신선한 꽃까지 선물해 줬잖아.",
  str_homestory_811401001_27_dialog_content = "그건... 사, 사실...",
  str_homestory_811401001_28_dialog_content = "나한테 상점에 진을 들여놓고 생화를 주문해 두라고 했던 사람은...",
  str_homestory_811401001_29_dialog_content = "...스모키야.",
  str_homestory_811401001_30_dialog_content = ".........응?",
  str_homestory_811401001_31_dialog_content = "뭐, 다른 요구도 많이 하긴 했어...\n아마 전부 제네비브만 생각해서 그런 건 아닐 거야...",
  str_homestory_811401001_32_dialog_content = "그러고 보니까... 그날 여기서 안나랑 이야기할 때,\n주위에서 뭔가 불타오르는 것 같은\n느낌이 들긴 했었어.",
  str_homestory_811401001_33_dialog_content = "하지만 이곳엔 불<sprite=emo_nuhuo size=60 />을 다루는 녀석들이 많으니까,\n그게 스모키일 거라곤 생각 안 했지.",
  str_homestory_811401001_34_dialog_content = "...그 녀석...",
  str_homestory_811401001_35_dialog_content = "아마 내가 이 일을 모르길 바라고 있겠지?",
  str_homestory_811401001_36_dialog_content = "음... 내 생각엔...",
  str_homestory_811401001_37_option_content = "알아줬으면 할 거야.",
  str_homestory_811401001_38_dialog_content = "애초에 스모키는 자기 능력만으로도 여기 진이랑 꽃을 가져올 수 있을 거잖아...",
  str_homestory_811401001_39_dialog_content = "그러니까 굳이 날 통하지 않고서도 할 수 있었던 일이라는 거지.",
  str_homestory_811401001_40_option_content = "몰랐으면 할 거야.",
  str_homestory_811401001_41_dialog_content = "저번에 혹시 진을 들여놓으라는 게 너 때문인 거냐고 물어봤었는데\n엄청 부정하더라고...",
  str_homestory_811401001_42_dialog_content = "그런 거였어?",
  str_homestory_811401001_43_dialog_content = "걔도 참 서투르다니까.",
  str_homestory_811401001_44_dialog_content = "아무튼 오늘 우리가 나눈 대화는\n스모키한테 말하지 말아 줘.",
  str_homestory_811401001_45_dialog_content = "내가 그 애의 호의를 알게 되었다곤 해도,\n만약 다른 사람 앞에서 그 이야기를 꺼냈다간...",
  str_homestory_811401001_46_dialog_content = "녀석은 부끄러운 걸 감추려고 불을 지르고\n화내면서 소리 지를 테니 말이야.",
  str_homestory_811401001_47_dialog_content = "응, 알겠어...",
  str_homestory_811401001_48_dialog_content = "근데 제네비브는 스모키를 정말 잘 알고 있구나!",
  str_homestory_811401001_49_dialog_content = "그래? 딱히 그렇다고 생각하진 않는데.",
  str_homestory_801801001_0_dialog_content = "이 야성적인 분위기는...",
  str_homestory_801801001_1_dialog_content = "신! 경! 쓰! 지! 마──♪",
  str_homestory_801801001_2_dialog_content = "더...!@#$... 말할 것도 없어──♪",
  str_homestory_801801001_3_dialog_content = "멍청한 녀석들은 저렇게나 잔뜩 있잖아!\n타올라라! 불꽃이여!<sprite=emo_nuhuo size=60 />",
  str_homestory_801801001_4_dialog_content = "(내 존재를 아예 잊어버렸잖아!)",
  str_homestory_801801001_5_dialog_content = "안녕, 레지나!",
  str_homestory_801801001_6_dialog_content = "조종사, 어때?\n내가 새로 만든 곡의 데모 버전이야!",
  str_homestory_801801001_7_dialog_content = "아까 발음을 뭉갰던 가사 부분은... 욕이지?",
  str_homestory_801801001_8_dialog_content = "역시 알아차렸구나?",
  str_homestory_801801001_9_dialog_content = "그래!",
  str_homestory_801801001_10_dialog_content = "에이, 아깝네.\n최대한 함축적으로 표현한 건데 말이야!",
  str_homestory_801801001_11_dialog_content = "어떻게 그걸 다 알아차렸지?",
  str_homestory_801801001_12_dialog_content = "이 자식, 누가 너한테 나쁜 물을 들인 게 분명해!",
  str_homestory_801801001_13_dialog_content = "......?",
  str_homestory_801801001_14_dialog_content = "크흠, 그런 거 아니야...",
  str_homestory_801801001_15_dialog_content = "아니면 됐어, 어차피 상관없잖아!",
  str_homestory_801801001_16_dialog_content = "참, 신곡이 아직 미완성인데, 무슨 아이디어 없어?\n강렬한 제안을 해 봐!",
  str_homestory_801801001_17_dialog_content = "소재? 가사? 멜로디?",
  str_homestory_801801001_18_dialog_content = "나... 음악에 대해선 진짜로 잘 몰라.",
  str_homestory_801801001_19_dialog_content = "그게 뭐 어때서? 내가 제일 싫어하는 게 바로\n음악에 기준을 세우려고 하는 고집불통들이라고!",
  str_homestory_801801001_20_dialog_content = "편하게 말해 봐!",
  str_homestory_801801001_21_dialog_content = "......",
  str_homestory_801801001_22_option_content = "바바라 최고!",
  str_homestory_801801001_23_dialog_content = "하아? 뭐라고?!",
  str_homestory_801801001_24_dialog_content = "알겠어. 날 도발하겠다는 거네.",
  str_homestory_801801001_25_option_content = "메탈은 죽지 않는다!",
  str_homestory_801801001_26_dialog_content = "그래야지!",
  str_homestory_801801001_27_dialog_content = "잘 기억해 두겠어!",
  str_homestory_801801001_28_dialog_content = "하하! 신곡 창작에 아이테르가 참여한 이상,\n분명히 다른 녀석들보다 쩔어줄 거라고!",
  str_homestory_801801001_29_dialog_content = "아, 그럼 넌 바바라랑 서로 다른 장르에서 경쟁하는 것 말고,\n같은 장르에서도 다른 사람들이랑 경쟁하는 거였어?",
  str_homestory_801801001_30_dialog_content = "야, 음악 하는 사람들 사이에 리스펙이 어디 있어?<sprite=emo_shengqi size=60 />",
  str_homestory_801801001_31_dialog_content = "특히 같은 업계 놈들 중엔 제대로 알지도 못하면서\n아는 척하는 놈들이 많다고!",
  str_homestory_801801001_32_dialog_content = "만나면 맨날 지들이 록을 가장\n잘 아는 것처럼 굴면서, 막상 곡 하나도 직접\n써 본 적 없는 놈들이라니까!",
  str_homestory_801801001_33_dialog_content = "흥, 매번 볼 때마다 그 가식적인 몰골들을\n전부 태워버리고 싶다고...",
  str_homestory_801801001_34_dialog_content = "그따위 녀석들이랑 「메탈 교류」를 하느니,\n차라리 바바라의 신곡이나 듣는 게 낫지!",
  str_homestory_801801001_35_dialog_content = "...아, 너도 사실 바바라를 그렇게까지 싫어하는 건 아니었구나?",
  str_homestory_801801001_36_dialog_content = "2초.",
  str_homestory_801801001_37_dialog_content = "......?",
  str_homestory_801801001_38_dialog_content = "바바라의 신곡은 딱 2초 참아 줄 수 있어.",
  str_homestory_801801001_39_dialog_content = "아, 알겠어...",
  str_homestory_809201001_0_dialog_content = "너...",
  str_homestory_809201001_1_dialog_content = "너였구나, 펙트.",
  str_homestory_809201001_2_dialog_content = "아니면 누구겠어?<sprite=emo_baiyan size=60 />",
  str_homestory_809201001_3_dialog_content = "크흠. 사실 여기서 그네 타는 걸 좋아하는 사람들이 꽤 많거든...",
  str_homestory_809201001_4_dialog_content = "그래서 너도 그네 타는 걸 좋아하는 거야?",
  str_homestory_809201001_5_dialog_content = "그렇게 물어보면 너무 성의가 없잖아.",
  str_homestory_809201001_6_dialog_content = "일단 「좋아한다」를 자세히 정의해 봐.",
  str_homestory_809201001_7_option_content = "(정의를 내린다)",
  str_homestory_809201001_8_dialog_content = "좋아한다는 건 어떤 일을 자주 하고 싶어지는 거라고 생각해.",
  str_homestory_809201001_9_dialog_content = "「자주」는 어느 정도의 주기를 말하는 거야?\n이 개념도 너무 모호하잖아.",
  str_homestory_809201001_10_dialog_content = "시도 때도 없이 이 일이 하고 싶어지는 걸\n말하는 거야?",
  str_homestory_809201001_11_dialog_content = "아니면 쉴 때만 이 일이 하고 싶어지는 걸\n말하는 거야?",
  str_homestory_809201001_12_dialog_content = "아니면... 자주 생각나는 건 아니지만,\n가끔 생각나면 하게 되는 걸 말하는 거야?",
  str_homestory_809201001_13_dialog_content = "(살려줘... 난 그냥 펙트랑 간단히 인사나 하려고 했던 거라고...)",
  str_homestory_809201001_14_dialog_content = "쉴 때가 되면 꼭 하고 싶어지는 그런 정도를 말하는 거야?",
  str_homestory_809201001_15_option_content = "(거절한다)",
  str_homestory_809201001_16_dialog_content = "좋아하는 건 그냥 좋아하는 거야... 굳이 정의를 내려야 해?",
  str_homestory_809201001_17_dialog_content = "내가 쉴 때면 여기저기 구경 다니는 걸 좋아하는 거랑 같은 거지.",
  str_homestory_809201001_18_dialog_content = "쉴 때가 되면 하고 싶어지는 일이라는 거구나?",
  str_homestory_809201001_19_dialog_content = "알겠어.",
  str_homestory_809201001_20_dialog_content = "그런 차원에서 이해한다면,\n난 그네 타는 걸 좋아하는 게 맞아.",
  str_homestory_809201001_21_dialog_content = "이렇게 매달려 있는 의자는 미묘하게 무중력\n상태에 있는 듯한 기분을 느끼게 해 주거든...",
  str_homestory_809201001_22_dialog_content = "난 그럴 때 말로 표현하기 어려운 희열을 느껴.",
  str_homestory_809201001_23_dialog_content = "정말? 그거 잘됐네!",
  str_homestory_809201001_24_dialog_content = "처음에 그네를 만들 땐 조금 고민했거든.",
  str_homestory_809201001_25_dialog_content = "펙트가 이렇게 마음에 들어 하는 걸 보니까 나도 안심이야!",
  str_homestory_809201001_26_dialog_content = "근데 조금 귀찮을 때도 있어.",
  str_homestory_809201001_27_dialog_content = "「헌터스톤」이 내 뒤에서 밀어줄 때 항상\n힘 조절을 못 한단 말이야.",
  str_homestory_809201001_28_dialog_content = "그래서 한 번은 공중에서 떨어져 버렸다니까!",
  str_homestory_809201001_29_dialog_content = "하하하...",
  str_homestory_809201001_30_dialog_content = "지금 나 비웃은 거야?!<sprite=emo_shengqi size=60 />",
  str_homestory_809201001_31_option_content = "(부정한다)",
  str_homestory_809201001_32_dialog_content = "아, 아니야...",
  str_homestory_809201001_33_dialog_content = "어디서 발뺌이야?\n그럼 네 입꼬리가 대체 왜 올라갔는지\n해명해 줄래?",
  str_homestory_809201001_34_option_content = "(인정한다)",
  str_homestory_809201001_35_dialog_content = "미안...",
  str_homestory_809201001_36_dialog_content = "그때 어떤 모습이었을지 상상해 버렸거든...",
  str_homestory_809201001_37_dialog_content = "크흠, 아무튼 다친 곳은 없지?",
  str_homestory_809201001_38_dialog_content = "네 눈엔 내가 그렇게 쉽게 다칠 사람으로 보여?",
  str_homestory_809201001_39_dialog_content = "안 다쳤으면 됐어! 아무튼 네가 그네 타는 걸 그렇게 좋아한다면...",
  str_homestory_809201001_40_dialog_content = "내가 밀어줄까?",
  str_homestory_809201001_41_dialog_content = "에? 그래도 돼...?",
  str_homestory_809201001_42_dialog_content = "내가 「헌터스톤」보다 힘이 약한 것도 싫지 않다면 말이야.",
  str_homestory_809201001_43_dialog_content = "그건 네가 「싫다」라는 단어를 어떻게 정의하냐에\n따라 다르겠지.",
  str_homestory_809201001_44_dialog_content = "으엑...",
  str_homestory_809201001_45_dialog_content = "자, 그냥 그네나 타러 가자!",
  str_homestory_809201001_46_dialog_content = "음... 어쩔 수 없네.\n네가 그렇게까지 성의를 보인다면, 타러 갈게.",
  str_homestory_809901001_0_dialog_content = "아이리나...",
  str_homestory_809901001_1_dialog_content = "아, PlayerName 씨였군요...",
  str_homestory_809901001_2_dialog_content = "초대해 주셔서 고마워요. 저... 정말 기뻐요!",
  str_homestory_809901001_3_dialog_content = "그렇게 정중할 거 없어!",
  str_homestory_809901001_4_dialog_content = "아직 안 익숙하지? 내가 구경시켜 줄까?",
  str_homestory_809901001_5_dialog_content = "정말 그래도 괜찮을까요?",
  str_homestory_809901001_6_dialog_content = "물론이지. 난 여길 제일 잘 아는 사람이니까.",
  str_homestory_809901001_7_dialog_content = "그래도...",
  str_homestory_809901001_8_dialog_content = "여, 역시 방으로 돌아갈래요.",
  str_homestory_809901001_9_dialog_content = "어? 아이리나는 바깥 경치 별로 안 좋아해?",
  str_homestory_809901001_10_dialog_content = "그건 아니에요...\n이곳 경치는 정말 마음에 들어요!",
  str_homestory_809901001_11_dialog_content = "이렇게 조용하고 쾌적한 곳은 처음인걸요.",
  str_homestory_809901001_12_option_content = "(고맙다고 한다)",
  str_homestory_809901001_13_dialog_content = "여길 좋아해 줘서 고마워!",
  str_homestory_809901001_14_dialog_content = "하지만 여긴 조용하고 쾌적할 뿐만 아니라 즐거움과 열정이 있는 곳이기도 해.",
  str_homestory_809901001_15_dialog_content = "자, 내가 안내해 줄게.",
  str_homestory_809901001_16_dialog_content = "하지만... 조금 무서워요...",
  str_homestory_809901001_17_option_content = "(의문을 표현한다)",
  str_homestory_809901001_18_dialog_content = "근데 왜 급하게 방으로 돌아가려고 하는 거야?",
  str_homestory_809901001_19_dialog_content = "조금... 무서워서요...",
  str_homestory_809901001_20_dialog_content = "제가 가지고 있는 저주와 검은 가시가...\n이곳의 경치를 망쳐버릴지도 모르니까요.",
  str_homestory_809901001_21_dialog_content = "그럼 PlayerName 씨한테 엄청난 폐를\n끼치게 될 거예요...",
  str_homestory_809901001_22_dialog_content = "아이리나, 그렇게까지 날 생각해줘서 고마워.",
  str_homestory_809901001_23_dialog_content = "하지만 난 아이리나가 이곳의 경치를 망친다고 생각하지 않아.",
  str_homestory_809901001_24_dialog_content = "네...?",
  str_homestory_809901001_25_dialog_content = "이렇게 오래 알고 지내면서 네 저주가 나한테 옮겨 온 적 있었어?",
  str_homestory_809901001_26_dialog_content = "하지만 제 몸의 검은 가시가...",
  str_homestory_809901001_27_dialog_content = "그 가시들은 네 몸이 저주에 침식되지 않도록 도와주는 친구들이잖아?",
  str_homestory_809901001_28_dialog_content = "맞아요...",
  str_homestory_809901001_29_dialog_content = "아이리나의 친구는 내 친구이기도 해!",
  str_homestory_809901001_30_dialog_content = "게다가...",
  str_homestory_809901001_31_dialog_content = "아이리나는 계속 저주를 없앨 방법을 찾고 있잖아?",
  str_homestory_809901001_32_dialog_content = "여길 많이 둘러보다 보면 저주를 없앨 방법을 찾아낼 수 있을지도 모르잖아?",
  str_homestory_809901001_33_dialog_content = "후훗... PlayerName 씨가 그렇게 말씀하셔도...\n그건 왠지 어려울 것 같아요.",
  str_homestory_809901001_34_dialog_content = "지금까지 이렇게 오랫동안 찾았는데도\n못 찾았는걸요.\n그렇게 쉽게 찾을 수 있을 리가 없겠죠...",
  str_homestory_809901001_35_dialog_content = "그동안 넌 일 때문에 나가는 거 아니면 외출을 거의 안 했었지?",
  str_homestory_809901001_36_dialog_content = "그렇죠...",
  str_homestory_809901001_37_dialog_content = "사실 밖에서 자연을 가까이하면, 그것만으로도 기분이 좋아지게 돼.",
  str_homestory_809901001_38_dialog_content = "기분이 좋아지면 그 이상한 저주가 정말로 약해질 수도 있잖아!",
  str_homestory_809901001_39_dialog_content = "......",
  str_homestory_809901001_40_dialog_content = "아하하...",
  str_homestory_809901001_41_dialog_content = "고마워요, 지금은 기분이 많이 나아졌어요.<sprite=emo_aixin size=60 />",
  str_homestory_809901001_42_dialog_content = "그럼... 채광을 하는 곳에 가 보고 싶은데요...\n괜찮을까요?",
  str_homestory_809901001_43_dialog_content = "어?",
  str_homestory_801601001_0_dialog_content = "카프카?",
  str_homestory_801601001_1_dialog_content = "잠깐만, 카프카... 여기 바닥에 말라붙은 물웅덩이<sprite=emo_hanshui size=60 />는 대체 뭐야?",
  str_homestory_801601001_2_dialog_content = "아... 미안, 그거 프란츠<sprite=emo_goutou size=60 />가 흘린 침이야.\n내가 방금 다 닦았어.",
  str_homestory_801601001_3_dialog_content = "요즘 조금만 기분이 좋으면 침을 흘리지 뭐야.\n이 새로운 버릇을 고쳐주느라 힘들었다니까.",
  str_homestory_801601001_4_dialog_content = "으, 적어도 내 침대에 침을 흘리는\n횟수는 많이 줄었어.",
  str_homestory_801601001_5_dialog_content = "그래, 정말 수고했네... 근데 프란츠는 항상 말 잘 듣는 거 아니었어?",
  str_homestory_801601001_6_dialog_content = "그렇게 칭찬만 하면 애가 천방지축이 돼버린다고.",
  str_homestory_801601001_7_dialog_content = "그래도 프란츠가 여기서 행복하게\n지내고 있다는 건 알 수 있어.",
  str_homestory_801601001_8_dialog_content = "왜? 여기가 콜로서스보다 넓어서?",
  str_homestory_801601001_9_dialog_content = "아마 항상 이상한 사람들을 만날 수 있어서겠지...",
  str_homestory_801601001_10_dialog_content = "너도 알지? 프란츠는 「이상한」 걸 좋아한다는 거.",
  str_homestory_801601001_11_dialog_content = "이상한 거라면 뭘 말하는 거야?",
  str_homestory_801601001_12_dialog_content = "「이상한 생물」이라고 표현하는 게 더 정확하겠네.",
  str_homestory_801601001_13_dialog_content = "이상한 생물이라...",
  str_homestory_801601001_14_dialog_content = "누구 얘기하는지 알겠어. 그러니까...",
  str_homestory_801601001_15_option_content = "투어독 씨 말하는 거지?",
  str_homestory_801601001_16_dialog_content = "음, 그런 이름이었던 것 같긴 하네.\n난 그 사람이랑 별로 말해본 적 없거든.",
  str_homestory_801601001_17_dialog_content = "아무튼, 프란츠가 그 사람을 보더니\n꼬리를 사정없이 흔들더라고.\n게다가 그 사람의 귀까지 물려고 했었어.",
  str_homestory_801601001_18_dialog_content = "뭐? 그럼 투어독 씨는 어떻게 반응했어?",
  str_homestory_801601001_19_dialog_content = "딱히 특별한 건 없었어.\n그냥 펜을 들고 프란츠를 유심히 쳐다보더니\n뭔가 몇 마디 했던 것 같아.",
  str_homestory_801601001_20_dialog_content = "(...설마 프란츠한테도 그림을 그려 달라고 할 생각은 아니었겠지?!)",
  str_homestory_801601001_21_dialog_content = "근데 마지막엔 프란츠의 발톱을 몇 번 보더니\n엄청 아쉽다는 듯이 고개를 젓고는 가 버렸어.",
  str_homestory_801601001_22_dialog_content = "휴... 그럼 됐어...",
  str_homestory_801601001_23_dialog_content = "말이 나와서 하는 얘긴데,\n그 사람 귀가 엄청 보들보들할 것 같더라고.",
  str_homestory_801601001_24_dialog_content = "다음에 만나면 한 번 만져 봐야겠어...",
  str_homestory_801601001_25_option_content = "호넷이랑 실버 말하는 거지?",
  str_homestory_801601001_26_dialog_content = "아무튼 복슬복슬하고 유치해 보이는\n두 녀석이었어. 성숙해 보이려고 심혈을 기울여\n꾸몄지만 말이야.",
  str_homestory_801601001_27_dialog_content = "두 녀석은 프란츠를 보자마자\n「우와! 진짜 멍멍이잖아!」라고 하더라고.",
  str_homestory_801601001_28_dialog_content = "프란츠도 그 둘을 좋아했던 것 같아.\n둘한테 계속 꼬리를 흔들었거든.",
  str_homestory_801601001_29_dialog_content = "아무리 생각해도 좀 이상해 보이는 장면인데...",
  str_homestory_801601001_30_dialog_content = "왠지는 모르겠지만 직접 보고 싶기도 하네...",
  str_homestory_801601001_31_dialog_content = "아무튼 프란츠는 여기서 잘 지내고 있어.",
  str_homestory_801601001_32_dialog_content = "근데... 너 요즘 계속 프란츠하고 붙어 있었지?",
  str_homestory_801601001_33_dialog_content = "뭐? 아닌데...",
  str_homestory_801601001_34_dialog_content = "그럼 왜 프란츠의 몸에서 항상 네 냄새가 나는데?",
  str_homestory_801601001_35_dialog_content = "프란츠가 네 방에 몰래 들어가기라도 했다는 거야?",
  str_homestory_801601001_36_dialog_content = "음... 그럴 가능성이 없지는 않겠네.",
  str_homestory_801601001_37_dialog_content = "잠깐만...",
  str_homestory_801601001_38_dialog_content = "아까 너 뭐라고 했었지?!",
  str_homestory_801601001_39_dialog_content = "프란츠가 네 침대에 침<sprite=emo_hanshui size=60 />을 흘리는 횟수가 많이 줄었다고...?",
  str_homestory_801601001_40_dialog_content = "으엑... 그럼 설마...",
  str_homestory_801601001_41_dialog_content = "...어쩐지 요즘 내 침대 시트가 맨날 축축하더라!",
  str_homestory_801601001_42_dialog_content = "그랬던 거였네...",
  str_homestory_801601001_43_dialog_content = "역시 프란츠가 널 정말 좋아하나 봐.",
  str_homestory_801601001_44_dialog_content = "...나 지금 기뻐해야 하는 거야?",
  str_homestory_801601001_45_dialog_content = "나보고 조언해 달라는 거지?",
  str_homestory_801601001_46_dialog_content = "음... 일단 당장 가서 침대 시트 세탁부터\n하는 걸 추천할게.",
  str_homestory_804501001_0_dialog_content = "무슨 소리지?",
  str_homestory_804501001_1_dialog_content = "나일즈?",
  str_homestory_804501001_2_dialog_content = "쉿... 잠시만 기다려 주십시오...",
  str_homestory_804501001_3_dialog_content = "아아... 반짝이는 도자기 같은 당신의 얼굴이\n제 더러운 육신을 비추고...",
  str_homestory_804501001_4_dialog_content = "당신의 눈동자는 깊은 밤하늘처럼\n제 마음을 꿰뚫는군요...",
  str_homestory_804501001_5_dialog_content = "제 육신의 죄악을 용서하시길...",
  str_homestory_804501001_6_dialog_content = "그게 아니라면... 저에 대한 용서가 당신께는\n수치가 되는 것일까요?",
  str_homestory_804501001_7_dialog_content = "......",
  str_homestory_804501001_8_dialog_content = "오래 기다리게 해서 죄송합니다.\nPlayerName 씨...",
  str_homestory_804501001_9_dialog_content = "제 목소리 때문에 놀라셨습니까?",
  str_homestory_804501001_10_dialog_content = "정말 죄송합니다. 제 목소리가 그렇게\n들어 주기 힘든 정도였군요. 죄악이\n더 깊어졌습니다...",
  str_homestory_804501001_11_dialog_content = "절대 아니야! 방해도 안 받았고!",
  str_homestory_804501001_12_dialog_content = "그냥 좀 궁금했거든. 대체 누구랑 이야기한 거야?",
  str_homestory_804501001_13_dialog_content = "오해하셨군요. 누군가와 대화를 한 것이 아니라\n죄악을 참회한 것입니다.",
  str_homestory_804501001_14_dialog_content = "그리고 전 당신께 감사해야 합니다.",
  str_homestory_804501001_15_dialog_content = "저희를 위해서 이렇게 참회할 수 있는 장소를\n마련해 주셔서 감사합니다.",
  str_homestory_804501001_16_dialog_content = "덕분에 여기서 빅토리아 님을 놀라시게 만들지\n않는 방식으로... 참회를 할 수 있게 되었습니다.",
  str_homestory_804501001_17_option_content = "(부정한다)",
  str_homestory_804501001_18_dialog_content = "거, 건물들을 지을 때 참회 장소를 지은 기억은 없는데...",
  str_homestory_804501001_19_dialog_content = "겸손해하지 않으셔도 됩니다.\n이 위엄 있는 분수대를 만들기 위해\n분명히 많은 고심을 하셨겠지요.",
  str_homestory_804501001_20_dialog_content = "하지만 이건 희망의 연못이잖아.",
  str_homestory_804501001_21_option_content = "(인정한다)",
  str_homestory_804501001_22_dialog_content = "고마워할 필요 없어. 다들 마음에 든다면 그걸로 됐어...",
  str_homestory_804501001_23_dialog_content = "...잠깐만! 뭐라고?! 참회 장소?",
  str_homestory_804501001_24_dialog_content = "이 희망의 연못 말하는 건 아니지?",
  str_homestory_804501001_25_dialog_content = "희망의 연못, 이 얼마나 따스한 이름이란 말입니까.",
  str_homestory_804501001_26_dialog_content = "저는 모두가 여기서 두 손을 모으고 참회하는\n모습만 보았을 뿐, 이곳의 이름이 무엇이었는지\n전혀 모르고 있었습니다...",
  str_homestory_804501001_27_dialog_content = "저는 죄인입니다. 참회합니다...",
  str_homestory_804501001_28_dialog_content = "아니, 그걸 그렇게 이해할 수도 있단 말이야?\n게다가... 다들 여기서 소원을 빌고 있었을 텐데?",
  str_homestory_804501001_29_dialog_content = "제가 당신을 대신해 참회하겠습니다...",
  str_homestory_804501001_30_dialog_content = "뭐?!",
  str_homestory_804501001_31_dialog_content = "참회라는 것은 방해를 받아서는 안 되는 것입니다.",
  str_homestory_804501001_32_dialog_content = "모두 제가 미리 설명해 드리지 못한 탓입니다.",
  str_homestory_804501001_33_dialog_content = "희망의 연못에 깃든 진리여...",
  str_homestory_804501001_34_dialog_content = "제가 다시금 방해하는 것을 용서해 주십시오...",
  str_homestory_804501001_35_dialog_content = "저는 죄인입니다. 참회합니다.\n제게 벌을 내려 주십시오...",
  str_homestory_804501001_36_option_content = "(벌을 내린다)",
  str_homestory_804501001_37_dialog_content = "앗! 방금 희망의 연못이 대답하는 게 느껴졌어!",
  str_homestory_804501001_38_dialog_content = "대답? 진리가 드디어 강림한 것입니까?!",
  str_homestory_804501001_39_dialog_content = "크흠, 희망의 연못은...",
  str_homestory_804501001_40_option_content = "(위로한다)",
  str_homestory_804501001_41_dialog_content = "나일즈, 내 생각엔 이건 정말 참회할 필요가 없는 일 같아.",
  str_homestory_804501001_42_dialog_content = "여기서 참회하기보다는... 차라리 앞으로 뭘 할지 생각하는 게 좋지 않을까?",
  str_homestory_804501001_43_dialog_content = "!!!",
  str_homestory_804501001_44_dialog_content = "저는 어째서 그런 생각을 하지 못했을까요...",
  str_homestory_804501001_45_dialog_content = "역시... 저의 죄는 깊고도 무겁습니다...",
  str_homestory_804501001_46_dialog_content = "......",
  str_homestory_808601001_0_dialog_content = "어디서 많이 본 하얀 꽃인데...",
  str_homestory_808601001_1_dialog_content = "PlayerName 님.",
  str_homestory_808601001_2_dialog_content = "헤븐즈 밸리가 이렇게 아름다운 곳인\n줄은 정말 몰랐네요.",
  str_homestory_808601001_3_dialog_content = "끝없이 펼쳐진 이 풀밭은...\n백야성에서는 볼 수 없었던 풍경이에요.",
  str_homestory_808601001_4_dialog_content = "심지어는 이 하얀 꽃<sprite=emo_huaduo size=60 />들도 헤븐즈 밸리를\n무척 마음에 들어 하고 있네...",
  str_homestory_808601001_5_dialog_content = "그렇구나... 사실 나도 처음엔 좀 놀랐어.",
  str_homestory_808601001_6_dialog_content = "네? 당신은 헤븐즈 밸리의 일원 아닌가요?",
  str_homestory_808601001_7_dialog_content = "아, 그러고 보니...",
  str_homestory_808601001_8_dialog_content = "저번에 말씀하셨던 게 기억났어요...\n어렸을 때 억지로 헤븐즈 밸리를 떠나야만\n했었다고 하셨죠.",
  str_homestory_808601001_9_dialog_content = "맞아. 스카이워커 선생님한테 배워서 헤븐즈 밸리에 대해 알고 있긴 했지만...",
  str_homestory_808601001_10_dialog_content = "막상 정말로 이곳에 오고 나니까... 이 아름다움이 내 마음을 흔드는 것 같아.<sprite=emo_pugongying size=60 />",
  str_homestory_808601001_11_dialog_content = "몇 번을 봐도 이 느낌은 좀처럼 줄어들지 않아.",
  str_homestory_808601001_12_dialog_content = "아마 이게 바로... 「집」이라는 느낌이겠지.\n헤븐즈 밸리가 나랑 연결되어 있다는 느낌이 들어.",
  str_homestory_808601001_13_dialog_content = "맞아요... 이곳의 모든 것은 영적인 힘으로\n가득 차 있어요. 자연과 아이테르의 건축물이\n조화롭게 공존하고 있고요.",
  str_homestory_808601001_14_dialog_content = "저는 평소에 「떠나간」 것들을 자주 접하기\n때문에 느낄 수 있어요...",
  str_homestory_808601001_15_dialog_content = "여긴 「생명의 근원적인 아름다움」이\n가득한 곳이에요.",
  str_homestory_808601001_16_dialog_content = "생명을 지닌 모든 것들,\n그리고 생명을 노래하는 사람이라면\n모두 헤븐즈 밸리를 좋아할 거예요.",
  str_homestory_808601001_17_dialog_content = "PlayerName 님의 집은 정말 아름다운 곳이네요.",
  str_homestory_808601001_18_dialog_content = "당신이 돌아올 장소로 이런 곳을\n가지고 있어서 기뻐요.",
  str_homestory_808601001_19_dialog_content = "고마워, 우라이아.",
  str_homestory_808601001_20_dialog_content = "헤븐즈 밸리를 그렇게 높게 평가해 주니까 나도 기분 좋네.",
  str_homestory_808601001_21_option_content = "(무언가를 부탁한다)",
  str_homestory_808601001_22_dialog_content = "사실... 나 우라이아한테 부탁하고 싶은 일이 있어.\n우라이아가 도와줄 수 있을진 모르겠지만.",
  str_homestory_808601001_23_dialog_content = "후훗... 갑자기 무척 겸손해지셨네요.",
  str_homestory_808601001_24_dialog_content = "이렇게 진지하고 묘한 분위기라니...",
  str_homestory_808601001_25_dialog_content = "설마 데이트로도 모자라서 이젠 프러포즈를\n하시려는 건가요?",
  str_homestory_808601001_26_dialog_content = "뭐...뭐라고?!",
  str_homestory_808601001_27_dialog_content = "그런 거 아니야!",
  str_homestory_808601001_28_dialog_content = "후후훗... 지금 그 모습 참 귀엽네요.",
  str_homestory_808601001_29_dialog_content = "놀리지 말아줘!",
  str_homestory_808601001_30_option_content = "(환영해 준다)",
  str_homestory_808601001_31_dialog_content = "앞으로도 헤븐즈 밸리에 자주 놀러 와 줘. 여긴 언제나 우라이아를 환영할 테니까.",
  str_homestory_808601001_32_dialog_content = "물론 그래야죠.",
  str_homestory_808601001_33_dialog_content = "여긴 마음을 사로잡는 아름다움이 있는걸요.\n게다가 당신의 터전이기도 하고요.",
  str_homestory_808601001_34_dialog_content = "당신이 여길 얼마나 더 위대한 터전으로\n만들어 나갈지 정말 기대돼요.",
  str_homestory_808601001_35_dialog_content = "음... 우라이아, 넌 떠난 이들을 위해 기도해 주고,\n그들의 영혼이 안식을 취할 수 있도록 해 주는 수녀지?",
  str_homestory_808601001_36_dialog_content = "네, 그게 바로 백야성에서의 제 직책이에요.",
  str_homestory_808601001_37_dialog_content = "...그렇군요, 이해했어요.",
  str_homestory_808601001_38_dialog_content = "맞아. 떠나간 아이테르 동족들이 편히 쉴 수 있도록... 기도를 부탁하고 싶어.",
  str_homestory_808601001_39_dialog_content = "역시 그런 건가요...",
  str_homestory_808601001_40_dialog_content = "당신이 삶과 죽음을 이렇게 담담히 받아들일\n정도로 어른스러워졌을 줄은 몰랐네요.",
  str_homestory_808601001_41_dialog_content = "저, 장례의 기도... 수녀 우라이아는\n반드시 헤븐즈 밸리의 영혼들이 안식하길\n기도하겠습니다.",
  str_homestory_808601001_42_dialog_content = "그들의 영혼이 편히 잠들고,\n헤븐즈 밸리에 하얀 꽃이 만개하도록.",
  str_homestory_808601001_43_dialog_content = "고마워.",
  str_homestory_810201001_0_dialog_content = "이 전류는...",
  str_homestory_810201001_1_dialog_content = "테사?",
  str_homestory_810201001_2_dialog_content = "졸리면 숙소에 가서 쉬어.",
  str_homestory_810201001_3_dialog_content = "하~암<sprite=emo_kun size=60 />.",
  str_homestory_810201001_4_dialog_content = "어야, 어혀후나?",
  str_homestory_810201001_5_dialog_content = "뭐라고?",
  str_homestory_810201001_6_dialog_content = "휴, 꼭 막대사탕을 입에서 꺼내야\n내 말을 알아듣겠어?",
  str_homestory_810201001_7_dialog_content = "음... 난 그냥 밖에서 자면 감기 걸린다고 알려 주려던 거야.",
  str_homestory_810201001_8_dialog_content = "잠은 꼭 집 안에서 자야 한다고\n누가 정해 놓기라도 한 거야?",
  str_homestory_810201001_9_dialog_content = "그런 강제적인 규정은 없지...",
  str_homestory_810201001_10_dialog_content = "설령 그런 규정이 있다고 치더라도, 난 신경 안 써.",
  str_homestory_810201001_11_dialog_content = "난 내가 자고 싶은 데서 잘 거야.",
  str_homestory_810201001_12_option_content = "(동의한다)",
  str_homestory_810201001_13_dialog_content = "그럼, 당연히 그래도 되지!",
  str_homestory_810201001_14_dialog_content = "테사의 그런 생활 방식이 난 정말 부러운걸.",
  str_homestory_810201001_15_dialog_content = "난 그냥 조용한 곳이나 찾고 싶어.\n남의 부러움 같은 건 필요 없다고.",
  str_homestory_810201001_16_option_content = "(동의할 수 없다)",
  str_homestory_810201001_17_dialog_content = "테사의 마음을 이해는 할 수 있어. 그래도...",
  str_homestory_810201001_18_dialog_content = "난 그냥 조용한 곳이나 찾고 싶어.\n남의 이해 같은 건 필요 없다고.",
  str_homestory_810201001_19_dialog_content = "그래...",
  str_homestory_810201001_20_dialog_content = "상점에 파라솔이랑 텐트가 있어. 필요하면 언제든 나한테 말해.",
  str_homestory_810201001_21_dialog_content = "됐어. 나무 그늘도 충분히 좋아.",
  str_homestory_810201001_22_dialog_content = "아, 참. 여기 상점에 막대사탕도 있어?",
  str_homestory_810201001_23_dialog_content = "가지고 있던 건 거의 다 먹었거든.",
  str_homestory_810201001_24_dialog_content = "있긴 한데...",
  str_homestory_810201001_25_dialog_content = "너 숙소에 아직 안 들어가 봤지?",
  str_homestory_810201001_26_dialog_content = "음... 집 안에 답답하게 있는 건 싫다고 말했잖아.",
  str_homestory_810201001_27_dialog_content = "게다가 그거랑 막대사탕이랑 무슨 상관인데?",
  str_homestory_810201001_28_dialog_content = "사실, 테사의 환영 선물로...",
  str_homestory_810201001_29_dialog_content = "특별히 숙소에 막대사탕을 잔뜩 준비해 뒀었거든...",
  str_homestory_810201001_30_dialog_content = "막대사탕을?!",
  str_homestory_810201001_31_dialog_content = "근데 아까 가서 봤는데, 벌써 하나도 안 남아 있더라고.",
  str_homestory_810201001_32_dialog_content = "그래서 난 테사가 가지고 간 줄 알았는데...\n이제 보니까 다른 사람이 선수 쳤던 모양이네.",
  str_homestory_810201001_33_dialog_content = "그렇게 준비해 놓고 왜 진작 말 안 했어?",
  str_homestory_810201001_34_dialog_content = "난 다들 숙소부터 가서 쉴 줄 알았지...",
  str_homestory_810201001_35_dialog_content = "흥, 됐어.",
  str_homestory_810201001_36_dialog_content = "내가 또 사면 되니까.",
  str_homestory_810201001_37_dialog_content = "(테사가 의외로 합리적인 반응을 보이는걸...)",
  str_homestory_810201001_38_dialog_content = "여기 일자리라든가 있어?\n보수를 받을 수 있는 종류로.",
  str_homestory_810201001_39_dialog_content = "어, 쉬려던 거 아니었어? 왜 갑자기 일을 찾으려는 거야?",
  str_homestory_810201001_40_dialog_content = "아까 상점에 가려고 했는데 돈이 없더라고.",
  str_homestory_810201001_41_dialog_content = "일을 못 구한다면 외상을 하는 수밖에 없잖아.",
  str_homestory_810201001_42_dialog_content = "......",
  str_homestory_810201001_43_dialog_content = "그럼 숙소의... 전기 회로 점검 좀 부탁할게.",
  str_homestory_810201001_44_dialog_content = "좋지.",
  str_homestory_801501001_0_dialog_content = "별일이네...",
  str_homestory_801501001_1_dialog_content = "실버랑 안 붙어다니고 혼자라니...",
  str_homestory_801501001_2_dialog_content = "이야~ PlayerName. 너도 맡았어?\n이 냄새 말이야!",
  str_homestory_801501001_3_dialog_content = "나이티움<sprite=emo_baiyebi size=60 />의 냄새야.\n여기저기서 나이티움 냄새가 난다고!",
  str_homestory_801501001_4_option_content = "(의심을 표현한다)",
  str_homestory_801501001_5_dialog_content = "난 못 맡았는데?",
  str_homestory_801501001_6_dialog_content = "게다가 나이티움에 무슨 냄새가 있냐고...",
  str_homestory_801501001_7_dialog_content = "PlayerName, 이건 예술적인 표현 방식이잖아.\n아무튼 중요한 건...",
  str_homestory_801501001_8_dialog_content = "지금 나한테는 너랑 상의할 몇억짜리 프로젝트가\n있다는 거야!",
  str_homestory_801501001_9_dialog_content = "몇억짜리?!",
  str_homestory_801501001_10_option_content = "(냄새를 맡아 본다)",
  str_homestory_801501001_11_dialog_content = "나이티움은 어떤 냄새가 나는데?",
  str_homestory_801501001_12_dialog_content = "30% 정도는 녹슨 철 냄새고,\n40% 정도는 땀 냄새...",
  str_homestory_801501001_13_dialog_content = "그리고 50% 정도는... 킁킁~",
  str_homestory_801501001_14_dialog_content = "깨끗한 과일나무향!",
  str_homestory_801501001_15_dialog_content = "다 합치면 120%아냐?",
  str_homestory_801501001_16_dialog_content = "120%는 바로 너랑 의논하고 싶은 내 진심이야.",
  str_homestory_801501001_17_dialog_content = "아, 그렇지. 일단 미리 말해두는데,\n만점은 10점이지 100점이 아니야.",
  str_homestory_801501001_18_dialog_content = "또 무슨 쓸데없는 수작을 부리려는 거야...?",
  str_homestory_801501001_19_dialog_content = "나도 일단 말해두는데, 내 그림은 안 팔 거야. 베껴 그릴 생각도 하지 마...",
  str_homestory_801501001_20_dialog_content = "PlayerName, 사람은 더 멀리 볼 줄 알아야지.",
  str_homestory_801501001_21_dialog_content = "이렇게 순수한 자연이 가득한 전시장에\n앉아 있으면서,고작 그림 두 점에나\n신경을 쓸 생각이야?",
  str_homestory_801501001_22_dialog_content = "전시장?",
  str_homestory_801501001_23_dialog_content = "드넓은 자연과 인문학적 생태계가 서로 결합한\n가장 좋은 본보기...",
  str_homestory_801501001_24_dialog_content = "여긴 가장 뛰어난 자연 전시장이야.",
  str_homestory_801501001_25_dialog_content = "PlayerName, 나도 실버도 여기가 정말 마음<sprite=emo_aixin size=60 />에 들어.",
  str_homestory_801501001_26_dialog_content = "그래서 방금 난 아주 힘든 결정을 하나 내렸어!",
  str_homestory_801501001_27_dialog_content = "난...",
  str_homestory_801501001_28_dialog_content = "큐레이터로 직업을 바꿀 거야!",
  str_homestory_801501001_29_dialog_content = "큐레이터? 구체적으로 무슨 일을 하는 건데?",
  str_homestory_801501001_30_dialog_content = "크흠, 간단히 말하면 다양한 예술품의\n감정, 연구, 보관, 진열을 담당하는 직업이지...",
  str_homestory_801501001_31_dialog_content = "게다가 특별한 장소에서 열리는\n예술 전시 기획 및 구성도 담당하는\n전문 매니저라고.",
  str_homestory_801501001_32_dialog_content = "이해가 잘 안되긴 하는데, 그래도 뭔가 제대로 된 직업 같긴 하네.",
  str_homestory_801501001_33_dialog_content = "그럼 너도 동의한 거지?",
  str_homestory_801501001_34_dialog_content = "내가 동의하든 안 하든 큐레이터는 할 수 있잖아.",
  str_homestory_801501001_35_dialog_content = "대신 여기 환경을 파괴하진 마... 내가 어렵게 가꾼 거니까.",
  str_homestory_801501001_36_dialog_content = "알겠어.",
  str_homestory_801501001_37_dialog_content = "넌 내가 이곳의 건물과 꽃이나 풀을 바꾸는 걸\n원하지 않는구나.",
  str_homestory_801501001_38_dialog_content = "맞아.",
  str_homestory_801501001_39_dialog_content = "넌 내가 예술적인 전시나 아트 페스티벌을\n기획하고 조직하는 걸 원하지 않는구나.",
  str_homestory_801501001_40_dialog_content = "그래.",
  str_homestory_801501001_41_dialog_content = "넌 전시랑 아트 페스티벌 때문에 관광객이\n몰려오는 걸 원하지 않는구나.",
  str_homestory_801501001_42_dialog_content = "으음...",
  str_homestory_801501001_43_dialog_content = "넌 이 행사들이 가져다줄 두둑한 수입은\n더더욱 원하지 않는구나.",
  str_homestory_801501001_44_dialog_content = "으윽...",
  str_homestory_801501001_45_dialog_content = "넌 재정 상황을 개선하고 싶은 마음이 없구나.",
  str_homestory_801501001_46_dialog_content = "쿠, 쿨럭... 잠깐만.",
  str_homestory_801501001_47_dialog_content = "이번 일은 내가 조금만 더 생각해 볼게.",
  str_homestory_801501001_48_dialog_content = "하하, PlayerName도 드디어 나이티움 냄새를\n맡게 됐나 보네!",
  str_homestory_815401001_0_dialog_content = "또야?",
  str_homestory_815401001_1_dialog_content = "바이스, 요즘 전시관에 엄청 오래 있네.",
  str_homestory_815401001_2_dialog_content = "전시관 안에 돈을 벌 방법이라도 있었어?",
  str_homestory_815401001_3_dialog_content = "너도 참...",
  str_homestory_815401001_4_dialog_content = "지금 우리의 경제 상황을 개선해야 하는 건 맞아.\n근데 그 문제는 이미 같이 논의해서 결정했잖아.",
  str_homestory_815401001_5_dialog_content = "전시관은 사람들한테 헤븐즈 밸리의\n역사와 아이테르의 과학 기술을 알리는\n공익적인 장소니까.",
  str_homestory_815401001_6_dialog_content = "그래서 영리 목적의 운영은커녕,\n입장료도 안 받겠다고...",
  str_homestory_815401001_7_option_content = "(사과한다)",
  str_homestory_815401001_8_dialog_content = "미안, 바이스...",
  str_homestory_815401001_9_dialog_content = "며칠 동안 계속 그 생각만 하느라 머리가 좀 이상해졌나 봐.",
  str_homestory_815401001_10_dialog_content = "아하하, 괜찮아! 나도 그랬던 적이 있는걸.",
  str_homestory_815401001_11_dialog_content = "그럴 땐 제대로 푹 쉬어 줘야 돼!",
  str_homestory_815401001_12_dialog_content = "바이스, 그런 말은 나한테만 하지 말고 너도 좀 푹 쉬고 그래.",
  str_homestory_815401001_13_dialog_content = "며칠 동안 계속 걱정 가득한 모습으로 전시관에만 있었잖아...",
  str_homestory_815401001_14_dialog_content = "제대로 쉬지도 못했지?",
  str_homestory_815401001_15_option_content = "(관심을 표현한다)",
  str_homestory_815401001_16_dialog_content = "걱정하지 마. 난 항상 이렇게 생각해 왔어!",
  str_homestory_815401001_17_dialog_content = "아이테르의 후예로서, 난 아이테르 일족의 문명을 내 대에서 끊어지게 할 순 없어.",
  str_homestory_815401001_18_dialog_content = "근데...",
  str_homestory_815401001_19_dialog_content = "넌 왜 며칠 내내 계속 고민에 잠겨서 전시관에 있던 거야?",
  str_homestory_815401001_20_dialog_content = "휴, 역시 PlayerName 눈은 못 속이겠다니까.<sprite=emo_wuzui size=60 />",
  str_homestory_815401001_21_dialog_content = "요 며칠 동안 계속 전시관의\n전시품들을 조사했거든.",
  str_homestory_815401001_22_dialog_content = "조사? 일루미나에서 의뢰한 새로운 임무야?",
  str_homestory_815401001_23_dialog_content = "아니, 이건 그냥 내가 하고 싶어서 한 일이야.",
  str_homestory_815401001_24_dialog_content = "당연히 제대로 된 조사도 아니었고.",
  str_homestory_815401001_25_dialog_content = "그냥 나를 일깨워 줄 어떤 단서가 있는지\n보려고 했던 거야.",
  str_homestory_815401001_26_dialog_content = "너도 알잖아.\n내 몸에는 이런저런 변화가 있었던 거...",
  str_homestory_815401001_27_dialog_content = "그리고 이것저것 옛날 생각이 나기도 해서...",
  str_homestory_815401001_28_dialog_content = "하지만 내 출신에 대한 정보는 단 하나도\n찾을 수가 없었어...",
  str_homestory_815401001_29_dialog_content = "그러니까... 전시관 안에서 네 출신에 대한 단서를 찾으려고 했었다는 거야?",
  str_homestory_815401001_30_dialog_content = "헤헤헤, 많이 이상해?",
  str_homestory_815401001_31_dialog_content = "하긴 그렇네. 아이테르의 전시관에 내 출신에 대한\n단서가 왜 있겠어?",
  str_homestory_815401001_32_dialog_content = "그건 누가 알겠어.",
  str_homestory_815401001_33_dialog_content = "세상이 넓긴 해도 「우연의 일치」도 적지 않게 일어나잖아.",
  str_homestory_815401001_34_dialog_content = "아하하하, 처음 만났을 때랑은 다르게\n너도 낙관적인 사람이 됐구나.",
  str_homestory_815401001_35_dialog_content = "나도 같이 전시관에 가 줄까?",
  str_homestory_815401001_36_dialog_content = "이번엔 단서를 발견할 수도 있잖아. 예를 들면 가족한테 보낸 편지 같은 거?",
  str_homestory_815401001_37_dialog_content = "좋아.",
  str_homestory_815401001_38_dialog_content = "근데 만약 사실 내가 네 친누나였다면...<sprite=emo_sikao size=60 />",
  str_homestory_815401001_39_dialog_content = "어떻게 할 거야?",
  str_homestory_815401001_40_dialog_content = "왜 네가 누나인데?",
  str_homestory_815401001_41_dialog_content = "어떻게 봐도 네가 날 「오빠」라고 부르는 게 맞잖아!",
  str_homestory_815401001_42_dialog_content = "PlayerName...",
  str_homestory_815401001_43_dialog_content = "으으... 절대 못 믿겠어.",
  str_homestory_815401001_44_dialog_content = "크흠, 그런 「우연의 일치」는 진짜 사절이야!",
  str_homestory_805702001_0_dialog_content = "비가 오나?",
  str_homestory_805702001_1_dialog_content = "우—냐앙—",
  str_homestory_805702001_2_dialog_content = "필리시, 비 오는 거 아니야? 얼른 몸을 피할 만한 곳을 찾아보자.",
  str_homestory_805702001_3_dialog_content = "으음~ 방금은 필리시가 몸에 묻은 물을\n터느라 그런거다냥.",
  str_homestory_805702001_4_dialog_content = "PlayerName, 미안하다냥.\n너한테 튀어버린 거 아니냥?",
  str_homestory_805702001_5_dialog_content = "그랬구나. 어쩐지 방금 계속 머리를 흔든다 했네...",
  str_homestory_805702001_6_dialog_content = "PlayerName, 놀리지 마라냥~",
  str_homestory_805702001_7_dialog_content = "근데 방금 비가 온 것도 아닌데 왜 젖은 거야?",
  str_homestory_805702001_8_dialog_content = "으... 전부 강에서 본\n빛나는 말린 생선 때문이다냥!<sprite=emo_shengqi size=60 />",
  str_homestory_805702001_9_option_content = "빛이 나?",
  str_homestory_805702001_10_dialog_content = "말린 생선이 어떻게 빛이 나?",
  str_homestory_805702001_11_dialog_content = "나도 궁금했다냥. 그래서 잡으려고 했던 거다냥.",
  str_homestory_805702001_12_option_content = "말린 생선?",
  str_homestory_805702001_13_dialog_content = "잠깐만... 강에 왜 말린 생선이 있는 건데?",
  str_homestory_805702001_14_dialog_content = "잡아서 햇볕에 말리면 그게 말린 생선이다냥.",
  str_homestory_805702001_15_dialog_content = "그런데 어떻게 해도 안 잡혀서\n실수로 강에 떨어져 버렸다냥.",
  str_homestory_805702001_16_dialog_content = "엣취! 강물은 너무 차갑다냥~",
  str_homestory_805702001_17_dialog_content = "필리시, 얼른 집에 가서 몸이라도 덥히자. 밖에 있다간 감기 걸릴 거야.",
  str_homestory_805702001_18_dialog_content = "그치만...",
  str_homestory_805702001_19_dialog_content = "아, PlayerName! 넌 이곳의 주인이니까...",
  str_homestory_805702001_20_dialog_content = "네가 그 빛난 말린 생선을 잡아줘라냥!",
  str_homestory_805702001_21_dialog_content = "뭐?",
  str_homestory_805702001_22_dialog_content = "꼭... 햇볕에 말려주는 거... 잊지 말고...\n쿨... 쿠울...<sprite=emo_kun size=60 />",
  str_homestory_805702001_23_dialog_content = "밖에서 자면 감기 걸려... 필리시?",
  str_homestory_805702001_24_dialog_content = "드르렁... 쿨...<sprite=emo_kun size=60 /> 말린 생선...",
  str_homestory_814101001_0_dialog_content = "잔뜩 신났네...",
  str_homestory_814101001_1_dialog_content = "하이~ PlayerName, 너도 탐험하러 나온 거야?",
  str_homestory_814101001_2_option_content = "맞아.",
  str_homestory_814101001_3_dialog_content = "내가 열심히 꾸민 헤븐즈 가든엔 탐험할 만한 곳이 꽤 많을 것 같거든.",
  str_homestory_814101001_4_option_content = "아니야.",
  str_homestory_814101001_5_dialog_content = "그냥 바람이나 쐬러 나온 거야.",
  str_homestory_814101001_6_dialog_content = "헤븐즈 가든이 지금의 모습이 되기까지 정말 많은 일이 있었어.\n그래서 되도록 많이 둘러보고 싶어.",
  str_homestory_814101001_7_dialog_content = "네 말이 맞아!",
  str_homestory_814101001_8_dialog_content = "네가 만든 이 모험의 섬, 정말 최고야!\n마음에 들어!",
  str_homestory_814101001_9_dialog_content = "방금 난 저 옆에 있는 강을 탐험했어.",
  str_homestory_814101001_10_dialog_content = "오, 그래? 뭐 찾은 거라도 있었어?",
  str_homestory_814101001_11_dialog_content = "아하하! 그걸 물어볼 줄 알았어!",
  str_homestory_814101001_12_dialog_content = "난 저 강을 보자마자 눈 깜짝할 사이에\n풍덩하고 뛰어들었어!",
  str_homestory_814101001_13_dialog_content = "그리고 수조를 헤치고 강바닥의 진흙 속에서\n처음 보는 동전을 주웠어<sprite=emo_baiyebi size=60 />...",
  str_homestory_814101001_14_dialog_content = "그리고 뒤로 돌다가 토실토실한 물고기도 잡았고...",
  str_homestory_814101001_15_dialog_content = "얼마 안 가서 신비한 유물도 발견햇어!",
  str_homestory_814101001_16_dialog_content = "그래서 바로 손을 뻗어서 그걸 물에서 건졌어.\n근데 그게 뭐였는지 알아?",
  str_homestory_814101001_17_dialog_content = "뭐... 였는데?",
  str_homestory_814101001_18_dialog_content = "수초가 잔뜩 자란 헌 신발이었지 뭐야! 아하하하하!",
  str_homestory_814101001_19_dialog_content = "그 신발, 상점에 가져가 봤자\n나이티움 한 개도 못 받을걸?\n진짜 웃겼다니까! 아하하!",
  str_homestory_814101001_20_dialog_content = "그 물고기는? 그리고 처음에 주운 동전은?",
  str_homestory_814101001_21_dialog_content = "아, 맞다... 주머니에 넣어 놨었는데...",
  str_homestory_814101001_22_dialog_content = "뭐, 상관없어.\n그 신발을 주울 때 근처에 떨어졌겠지.",
  str_homestory_814101001_23_dialog_content = "관심 있으면 한번 찾아봐!",
  str_homestory_814101001_24_dialog_content = "근데 그 물고기는 이미 멀리 가버렸을 거야.",
  str_homestory_814101001_25_dialog_content = "루비... 넌 정말 엄청난 낙천주의자라니까.",
  str_homestory_814101001_26_dialog_content = "아, 맞다! 이번 일 루즈한테는 절대 말하면 안 돼!",
  str_homestory_814101001_27_dialog_content = "아니면 또 무슨 열감기를 방지하는 쓴 물을\n먹이려고 할 거라구.",
  str_homestory_801001001_0_dialog_content = "아직 잠이 덜 깼어?",
  str_homestory_801001001_1_dialog_content = "루이스, 괜찮아? 왜 이렇게 피곤해 보여?",
  str_homestory_801001001_2_dialog_content = "아, PlayerName 씨였구나.",
  str_homestory_801001001_3_dialog_content = "드디어 온 줄 알았는데 아니었네...",
  str_homestory_801001001_4_dialog_content = "누구 기다리는 건데?",
  str_homestory_801001001_5_dialog_content = "루이스는 강 속에 사는 요정을 기다리고 있어.",
  str_homestory_801001001_6_dialog_content = "요정?",
  str_homestory_801001001_7_dialog_content = "PlayerName 씨,\n그 엄청 유명한 이야기 못 들어봤어?",
  str_homestory_801001001_8_dialog_content = "저 멀리 있는 강에는 엄청 아름다운 요정이 산대.",
  str_homestory_801001001_9_dialog_content = "그리고 지나가던 사람이 실수로 물건을 강에\n떨어트리면 요정이 나타나는 거야.",
  str_homestory_801001001_10_dialog_content = "그리고 요정의 질문에 성실하게 대답하는\n착한 아이는 상을 받아!",
  str_homestory_801001001_11_option_content = "강이라...",
  str_homestory_801001001_12_dialog_content = "그럼 루이스는 이 강에도 요정이 산다고 생각해?",
  str_homestory_801001001_13_dialog_content = "음, 어느 강에나 요정이 있는 게 아닐까...",
  str_homestory_801001001_14_dialog_content = "북방의 강에는 북방의 요정이 살고,\n헤븐즈 밸리의 강에는 헤븐즈 밸리의\n요정이 사는 거야...",
  str_homestory_801001001_15_option_content = "동화라...",
  str_homestory_801001001_16_dialog_content = "그러고 보니 나도 그런 이야기를 들어본 적이 있는 것 같아.",
  str_homestory_801001001_17_dialog_content = "어떤 사람이 철도끼를 강에 빠트렸는데,\n탐욕에 눈이 멀어서 금도끼를 잃어버렸다는 얘기였던가?",
  str_homestory_801001001_18_dialog_content = "근데 지금 중요한 건...",
  str_homestory_801001001_19_dialog_content = "루이스, 혹시 실수로 물건을 강에 떨어트린 거야?",
  str_homestory_801001001_20_dialog_content = "맞아! 근데 그건 루이스의 물건이 아니야.",
  str_homestory_801001001_21_dialog_content = "내가 강가에서 주운 동전이야.\n엄청 복잡한 그림이 그려져 있는 동전...",
  str_homestory_801001001_22_dialog_content = "근데 제대로 살펴보기도 전에 강에 떨어트려 버렸어.",
  str_homestory_801001001_23_dialog_content = "그래서 한참 기다렸는데... 요정이 안 나와.",
  str_homestory_801001001_24_dialog_content = "PlayerName 씨,\n아무래도 이 강에는 정말 요정이 없나 봐...<sprite=emo_sikao size=60 />",
  str_homestory_801001001_25_dialog_content = "내가 건져낼 수 있는지 살펴보고 올게.",
  str_homestory_801001001_26_dialog_content = "아, 요정은 PlayerName 씨였던 거야?!",
  str_homestory_804102001_0_dialog_content = "정말 열심이네...",
  str_homestory_804102001_1_dialog_content = "블랑 씨, 안녕하세요.",
  str_homestory_804102001_2_dialog_content = "안녕하세요.",
  str_homestory_804102001_3_dialog_content = "아직도 헤븐즈 가든의 도로와 건물을 관찰하고 있는 건가요?",
  str_homestory_804102001_4_dialog_content = "제 「직업병」을 기억해 주시다니 정말 기쁘네요.",
  str_homestory_804102001_5_option_content = "역시 대단하시네요!",
  str_homestory_804102001_6_dialog_content = "하지만...",
  str_homestory_804102001_7_option_content = "미안해요!",
  str_homestory_804102001_8_dialog_content = "왜 그런 말씀을 하시는 거죠?",
  str_homestory_804102001_9_dialog_content = "헤븐즈 가든 건설이 아직 진행 중이라 건물과 도로가 계속 늘어나고 있거든요.",
  str_homestory_804102001_10_dialog_content = "이러면 블랑 씨의 업무량도 많아지지 않을까요?",
  str_homestory_804102001_11_dialog_content = "PlayerName 씨, 커리어 우먼의 전문성을\n얕보지 마세요.",
  str_homestory_804102001_12_dialog_content = "머리에 주요 건물과 도로의 방위, 좌표만\n기록할 수 있다면...",
  str_homestory_804102001_13_dialog_content = "아무리 많은 도로와 건물이 생겨도\n쉽게 기억할 수 있으니까요.",
  str_homestory_804102001_14_dialog_content = "그거 정말 대단한 기억력이네요!",
  str_homestory_804102001_15_dialog_content = "그럼... 방금 눈썹을 찌푸리고 있던 건 무슨 문제가 생겨서 그랬던 건가요?",
  str_homestory_804102001_16_dialog_content = "어머, PlayerName 씨한테 들켜버렸네요.",
  str_homestory_804102001_17_dialog_content = "맞아요. 작은 문제가 생겼죠...\n알려드려도 무방한 일이에요.",
  str_homestory_804102001_18_dialog_content = "사실 헤븐즈 가든의 안내 멘트를 어떻게 쓸지\n고민하고 있었어요.",
  str_homestory_804102001_19_dialog_content = "마침 이 근처의 강까지 썼는데...",
  str_homestory_804102001_20_dialog_content = "이 강에는 다양한 물고기 외에도 반짝이는\n무언가가 있는 것 같거든요.",
  str_homestory_804102001_21_dialog_content = "안내 대사의 정확성을 위해 그 반짝이는 게\n대체 뭔지 정말 알고 싶어요...",
  str_homestory_804102001_22_dialog_content = "반짝이는 물건이라...",
  str_homestory_804102001_23_dialog_content = "당신은 헤븐즈 가든의 주인이니까,\n이번 일의 조사를 부탁해도 될까요?",
  str_homestory_804102001_24_dialog_content = "네, 물론이죠!",
  str_homestory_801502001_0_dialog_content = "또 사방을 킁킁거리면서 다니는 거야?",
  str_homestory_801502001_1_dialog_content = "콜록, 콜록... 호넷, 이건...?",
  str_homestory_801502001_2_dialog_content = "아~ 이게 누구야! 우리의 PlayerName 아냐?<sprite=emo_yaosu size=60 />",
  str_homestory_801502001_3_dialog_content = "어때, 잘 생각해 봤어?",
  str_homestory_801502001_4_dialog_content = "뭘 생각해...?",
  str_homestory_801502001_5_dialog_content = "오호, 물론 이해할 수 있지!\n우리 VIP님은 건망증이 심하니까~",
  str_homestory_801502001_6_dialog_content = "그러니까... 헤븐즈 가든을 자연 전시장으로\n만들자는 일 얘기야.",
  str_homestory_801502001_7_option_content = "(아직 고민하는 중이다)",
  str_homestory_801502001_8_dialog_content = "그건... 아직 고민 중이야...",
  str_homestory_801502001_9_option_content = "(역시 그만두자)",
  str_homestory_801502001_10_dialog_content = "네 계획도 나쁘진 않지만, 난 그래도 헤븐즈 가든이\n지금의 깨끗함과 편안함을 잃지 않았으면 좋겠어.",
  str_homestory_801502001_11_dialog_content = "에이, 알겠어.",
  str_homestory_801502001_12_dialog_content = "그래도 잘 생각하는 게 좋을 거야.\n기회는 기다려 주지 않으니까!",
  str_homestory_801502001_13_dialog_content = "으음...",
  str_homestory_801502001_14_dialog_content = "킁~ 크응~",
  str_homestory_801502001_15_dialog_content = "뭘 맡고 있는 거야?",
  str_homestory_801502001_16_dialog_content = "하~ 안 느껴져? 이 돈 냄새가...",
  str_homestory_801502001_17_dialog_content = "또... 「나이티움」<sprite=emo_baiyebi size=60 /> 냄새야?",
  str_homestory_801502001_18_dialog_content = "아니, 이번에는 달라!",
  str_homestory_801502001_19_dialog_content = "완전히 새로운...\n표현할 수 없는 동전의 냄새야... 킁킁~",
  str_homestory_801502001_20_dialog_content = "나이티움보다 짜고 습한 느낌이야.\n만들어진 시간도 훨씬 오래됐고...",
  str_homestory_801502001_21_dialog_content = "무늬도 훨씬 복잡해...",
  str_homestory_801502001_22_dialog_content = "무늬도 냄새로 알 수 있는 거였어?!",
  str_homestory_801502001_23_dialog_content = "멍멍이의 코를 무시하지 말라고.",
  str_homestory_801502001_24_dialog_content = "비즈니스 트렌드든 동전의 냄새든,\n난 언제든 방향을 알려줄 수 있다고. 하하하!",
  str_homestory_801502001_25_dialog_content = "이번엔 말이지...\n이 동전을 찾을 기회를 너한테 양보할게.",
  str_homestory_801502001_26_dialog_content = "뭐?",
  str_homestory_801502001_27_dialog_content = "그러니까 우리의 협력에 대해\n다시 생각해줬으면 좋겠어~",
  str_homestory_805602001_0_dialog_content = "콘스탄틴 씨?",
  str_homestory_805602001_1_dialog_content = "PlayerName, 반갑군.",
  str_homestory_805602001_2_dialog_content = "콘스탄틴 씨, 어디 갔다 오신 건가요?",
  str_homestory_805602001_3_dialog_content = "낚시하다 막 돌아온 참이다.",
  str_homestory_805602001_4_dialog_content = "아, 요즘 자주 낚시하러 가시네요.",
  str_homestory_805602001_5_dialog_content = "콘스탄틴 씨는 프로 사냥꾼이시니까 며칠 동안 물고기도 많이 잡으셨겠네요?",
  str_homestory_805602001_6_dialog_content = "한 마리도 못 잡았다.",
  str_homestory_805602001_7_dialog_content = "으엑, 지...진짜요? 사냥 기술이 엄청나시잖아요...",
  str_homestory_805602001_8_dialog_content = "낚시도 사냥의 일종이긴 하지만\n그 둘은 아주 큰 차이가 있지.<sprite=emo_sikao size=60 />",
  str_homestory_805602001_9_dialog_content = "사냥은 목표로 삼은 사냥감을 쓰러트리는 거야.",
  str_homestory_805602001_10_dialog_content = "하지만 낚시는 가장 깊은 곳까지 내려가서,\n다가오는 녀석들을 거두어야 하는 것이지.",
  str_homestory_805602001_11_option_content = "아, 이해했어요.",
  str_homestory_805602001_12_dialog_content = "낚시할 때는 뭘 낚게 될지 누구도 알 수 없죠.",
  str_homestory_805602001_13_dialog_content = "하지만 사냥은 목표부터 정한 뒤에 움직이잖아요.",
  str_homestory_805602001_14_option_content = "잘 모르겠어요.",
  str_homestory_805602001_15_dialog_content = "근데 사냥에는 인내심이 필요하다고 콘스탄틴 씨가 그랬잖아요.\n낚시도 마찬가지로 인내심이 필요하지 않을까요?",
  str_homestory_805602001_16_dialog_content = "낚시할 때는 언제 뭐가 걸려들지 아무도 모르니까요.",
  str_homestory_805602001_17_dialog_content = "그래. 그 말이 맞다.",
  str_homestory_805602001_18_dialog_content = "솔직히 말하자면 난 낚시를 시작할 때\n큰 실수를 했지.",
  str_homestory_805602001_19_dialog_content = "항상 먼저 목표를 정하고 움직였거든.\n하지만 성과는 적었어.",
  str_homestory_805602001_20_dialog_content = "난 이 교훈을 기억하기 위해\n낚싯바늘을 부러트렸다.",
  str_homestory_805602001_21_dialog_content = "하아? 그럼 낚시를 할 수 있나요?",
  str_homestory_805602001_22_dialog_content = "모르겠구나. 하지만 상관없어.\n난 그저 내 인내심을 단련하고 싶을 뿐이니까.",
  str_homestory_805602001_23_dialog_content = "그럼 계속 이렇게 있을 건가요?",
  str_homestory_805602001_24_dialog_content = "우선 기한을 정해놨다.",
  str_homestory_805602001_25_dialog_content = "강가의 저 동전이 진흙에 덮이거나\n강물에 쓸려갈 때까지... 아니면 누군가 주워가는\n그 순간까지...",
  str_homestory_805602001_26_dialog_content = "난 계속 낚싯대를 드리우고 있을 거다.",
  str_homestory_805602001_27_dialog_content = "(동전...?)",
  str_homestory_805602001_28_dialog_content = "(그럼 나도 동전을 낚을 수 있을지 시도해 보자.)",
  str_homestory_808502001_0_dialog_content = "손이 엄청 빠르네...",
  str_homestory_808502001_1_dialog_content = "제인, 방금 기록을 남긴 거야?",
  str_homestory_808502001_2_dialog_content = "맞아요. 제가 본 헤븐즈 가든을 기록하고 있었어요.",
  str_homestory_808502001_3_dialog_content = "네 직업을 몰랐다면 분명히 그림을 그리고 있다고 생각했을걸!",
  str_homestory_808502001_4_dialog_content = "하지만 방금은 정말 그림을 그렸죠..",
  str_homestory_808502001_5_dialog_content = "아...<sprite=emo_wuzui size=60 />",
  str_homestory_808502001_6_dialog_content = "글로 기록하는 것도 중요하지만,\n그림을 적절하게 넣어주는 것도 중요합니다.",
  str_homestory_808502001_7_dialog_content = "그림은 어떨 때 넣는 건데?",
  str_homestory_808502001_8_dialog_content = "간단합니다. 글로 쉽게 설명할 수 없는 일이라면\n그림의 도움을 받는 거죠.",
  str_homestory_808502001_9_dialog_content = "예를 들어서, 방금 전 강 속에서 본 모든 걸\n기록하고 있었습니다.",
  str_homestory_808502001_10_dialog_content = "문자로만 「레드핀피쉬」의 모습을 설명한다면,\n독자가 한참 상상해 봐도 흐릿한 인상만 남겠죠.",
  str_homestory_808502001_11_dialog_content = "이럴 때 이 물고기의 모습과 색감을\n그림으로 그려두면...",
  str_homestory_808502001_12_dialog_content = "독자는 한눈에 이 물고기에 대한 정보를\n알 수 있을 겁니다.",
  str_homestory_808502001_13_dialog_content = "그렇구나...",
  str_homestory_808502001_14_dialog_content = "하나 더 예시를 들자면,\n제가 「강바닥에는 동전도 하나 있었다」라고\n기록했을 때...",
  str_homestory_808502001_15_dialog_content = "독자는 자신이 사용했던 동전의 형태만\n떠올릴 수 있겠죠.",
  str_homestory_808502001_16_dialog_content = "이럴 땐 누구도 못 봤을 법한 저 동전의 문양도\n함께 그려주는 겁니다.",
  str_homestory_808502001_17_dialog_content = "그렇게 하면 독자들도 대체 어떤 동전이\n헤븐즈 가든의 강바닥에 떨어져 있었는지\n알 수 있겠죠.",
  str_homestory_808502001_18_dialog_content = "그래서... 그 동전은 지금 어디 있는데?",
  str_homestory_808502001_19_dialog_content = "아직 강바닥에 있습니다.",
  str_homestory_808502001_20_dialog_content = "뭐? 모처럼 동전을 발견했는데 왜 안 건졌어?",
  str_homestory_808502001_21_dialog_content = "저는 기록을 담당할 뿐, 이야기를 만드는 건\n제 책임 범위가 아니에요.",
  str_homestory_808502001_22_dialog_content = "마찬가지로 당신이 동전을 건지는 걸\n막을 이유도 없죠.",
  str_homestory_808502001_23_dialog_content = "물론, 이 모든 건 기록으로 남겨둘 겁니다.",
  str_homestory_805502001_0_dialog_content = "(화가 나신 건가...?)",
  str_homestory_805502001_1_dialog_content = "피트만 씨, 무슨 일이에요? 많이 화나신 것 같은데...",
  str_homestory_805502001_2_dialog_content = "PlayerName 님, 마침 잘 오셨습니다.\n안 그래도 찾고 있었습니다!",
  str_homestory_805502001_3_dialog_content = "으엑... 저한테 무슨 일이라도 있나요?",
  str_homestory_805502001_4_dialog_content = "그것은 아직 확실하지 않습니다만...",
  str_homestory_805502001_5_dialog_content = "만물은 백야 아래에!\n백야성 심판관의 이름으로 묻겠습니다...",
  str_homestory_805502001_6_dialog_content = "헤븐즈 가든에서 사적으로 나이티움을 주조했습니까?",
  str_homestory_805502001_7_option_content = "아뇨!",
  str_homestory_805502001_8_dialog_content = "물론 나이티움이 많이 필요한 건 맞지만, 그런 짓까지 할 정도는 아니라구요...",
  str_homestory_805502001_9_option_content = "그러고는 싶지만...",
  str_homestory_805502001_10_dialog_content = "나이티움을 만드는 기술과 기계는 엄청 비싸잖아요...\n돈을 만들려면 우선 돈이 있어야 한다고요.",
  str_homestory_805502001_11_dialog_content = "아시다시피 전 그렇게 풍족하진 않아서요.",
  str_homestory_805502001_12_dialog_content = "맹세하실 수 있습니까?",
  str_homestory_805502001_13_dialog_content = "PlayerName, 나이티움을 멋대로 만들지 않았음을 맹세합니다!",
  str_homestory_805502001_14_dialog_content = "사실이 아니라면... 절 마음대로 처분하세요!",
  str_homestory_805502001_15_dialog_content = "아니면 혹시 헤븐즈 가든에 왔던 다른 사람 중에\n이러한 혐의가 있는 자를 본 적은 없습니까?",
  str_homestory_805502001_16_dialog_content = "특히 그 움브라톤에서 온 사람들이랑\n사막에서 온 사람들 말입니다.",
  str_homestory_805502001_17_dialog_content = "다들 제 친구예요. 전 친구를 의심하고 싶지 않아요...",
  str_homestory_805502001_18_dialog_content = "그 누구라도 법률 앞에서는 평등합니다.",
  str_homestory_805502001_19_dialog_content = "근데... 대체 왜 모두를 의심하시는 거죠?",
  str_homestory_805502001_20_dialog_content = "맹세까지 하셨으니... 좋습니다. 알려드리죠.",
  str_homestory_805502001_21_dialog_content = "방금 강가에서 동전 하나를 주웠습니다.\n재질이 나이티움과 비슷한 동전이었습니다!",
  str_homestory_805502001_22_dialog_content = "그 동전 좀 볼 수 있을까요?",
  str_homestory_805502001_23_dialog_content = "방금 너무 화나서 손을 떨다가\n강 속에 떨어트리고 말았습니다.",
  str_homestory_805502001_24_dialog_content = "음... 이건 제 추측인데요... 어쩌면 그 동전은 아이테르의 것일지도 몰라요.",
  str_homestory_805502001_25_dialog_content = "아... 그, 그렇습니까?",
  str_homestory_805502001_26_dialog_content = "확실히... 저도 동전을 자세히 보지는\n못했으니 말입니다...",
  str_homestory_805502001_27_dialog_content = "만약 그게 사실이라면...\n제 경솔한 행동에 사과드리겠습니다.",
  str_homestory_805502001_28_dialog_content = "죄송합니다!",
  str_homestory_805502001_29_dialog_content = "괜찮아요. 저도 아직 어떻게 된 일인지 모르니까요.",
  str_homestory_805502001_30_dialog_content = "그럼 그 동전을 찾으면 피트만 씨한테도 보여드릴게요.",
  str_homestory_805502001_31_dialog_content = "감사합니다, PlayerName 님!",
  str_homestory_815701001_0_dialog_content = "사나에...",
  str_homestory_815701001_1_dialog_content = "으아아아... PlayerName 님...",
  str_homestory_815701001_2_dialog_content = "전 그저 이 꽃<sprite=emo_huaduo size=60 />들을 감상하고 있었을 뿐이에요!",
  str_homestory_815701001_3_dialog_content = "근처에서 넘어져서 여기서 쉬고 있는게 아니라요...",
  str_homestory_815701001_4_dialog_content = "넘어졌어? 다쳤어?",
  str_homestory_815701001_5_dialog_content = "이미 익숙해요... 아, 들켜버린 건가요?",
  str_homestory_815701001_6_dialog_content = "사실... 사나에는 정말 이해하기 쉽거든.",
  str_homestory_815701001_7_dialog_content = "부디 제가 서툴다고 해고하지 말아 주세요...",
  str_homestory_815701001_8_dialog_content = "아니, 근데... 방금 무슨 생각하고 있었어?",
  str_homestory_815701001_9_dialog_content = "혹시 헤븐즈 가든의 건설에 무슨 제안이 있으면 언제든지 말해줘도 돼.",
  str_homestory_815701001_10_dialog_content = "아... 없어요...",
  str_homestory_815701001_11_dialog_content = "저, 전 PlayerName 님이 왜 여기에 꽃을\n심는지에 대한 상상 같은 건 하나도 안 했어요!",
  str_homestory_815701001_12_dialog_content = "크흠, 네가 그렇게 말하니까 더 수상한데...",
  str_homestory_815701001_13_dialog_content = "네?",
  str_homestory_815701001_14_dialog_content = "PlayerName 님이 사랑하는 사람을\n기리기 위해, 그리운 마음을 담아\n이런 걸 심었다는 사실 같은 건...",
  str_homestory_815701001_15_dialog_content = "저, 전 정말 몰라요...",
  str_homestory_815701001_16_option_content = "사랑하는 사람?",
  str_homestory_815701001_17_dialog_content = "네! 그녀는 우연히 PlayerName 님과 만났겠죠...",
  str_homestory_815701001_18_dialog_content = "그리고 세상의 온갖 족쇄를 깨고\n당신의 곁으로 왔을 거예요...",
  str_homestory_815701001_19_dialog_content = "그 뒤로 당신 곁에서 아스트라 대륙의 모험에 대한\n조언도 해 줬겠죠...",
  str_homestory_815701001_20_dialog_content = "아아, 분명히 정말 멋지고 대단한 아가씨였겠죠!",
  str_homestory_815701001_21_dialog_content = "여기 심은 꽃도...\n분명히 그녀가 가장 좋아하는 꽃이겠죠?",
  str_homestory_815701001_22_option_content = "그리운 마음?",
  str_homestory_815701001_23_dialog_content = "한 때 모든 것을 버리고 당신 곁으로 온 그 사람...",
  str_homestory_815701001_24_dialog_content = "당신의 여행길을 항상 지켜주었던 그 사람...",
  str_homestory_815701001_25_dialog_content = "하지만 지금은 세상의 속박 때문에\n당신과 함께할 수 없는 거겠죠.",
  str_homestory_815701001_26_dialog_content = "그녀에 대한 당신의 마음을 표현하기 위해...",
  str_homestory_815701001_27_dialog_content = "그녀가 가장 좋아하는 꽃을 이 정원에 심은 거겠죠!",
  str_homestory_815701001_28_dialog_content = "대체 무슨 말을 하는 거야... 하나도 모르겠잖아...",
  str_homestory_815701001_29_dialog_content = "그런가요...<sprite=emo_sikao size=60 />!",
  str_homestory_815701001_30_dialog_content = "역시 저 같은 외부인에게는\n쉽게 공개할 수 없는 정보...",
  str_homestory_815701001_31_dialog_content = "이곳에 화단이 있는 이유가 궁금한 거라면...",
  str_homestory_815701001_32_dialog_content = "이건 모종의 조경 설계 때문에 만들어진 거야.",
  str_homestory_815701001_33_dialog_content = "조경 설계? 엄청 복잡한 단어네요...",
  str_homestory_815701001_34_dialog_content = "바이스는 공사 도면을 잘 그리거든.\n그래서 헤븐즈 가든을 디자인할 때 바이스가 도움을 많이 줬어.",
  str_homestory_815701001_35_dialog_content = "그리고 난 식물을 잘 아는 가브리엘, 나시리스, 유라한테도...",
  str_homestory_815701001_36_dialog_content = "어떤 식물을 심어야 더 아름다울지 물어봤어.",
  str_homestory_815701001_37_dialog_content = "그렇게 모두의 지혜를 모아 오늘날 헤븐즈 가든의\n식물과 나무들이 있게 된 거야.",
  str_homestory_815701001_38_dialog_content = "모두의 지혜...",
  str_homestory_815701001_39_dialog_content = "응! 사나에도 자기가 「외부인」처럼 느껴지지 않겠지?",
  str_homestory_815701001_40_dialog_content = "여기 온 순간부터 너도 우리 모두의 친구니까 말이야!",
  str_homestory_815701001_41_dialog_content = "흑, 흑흑흑...",
  str_homestory_815701001_42_dialog_content = "으엑, 왜 울어? 너한테 뭐라고 한 것도 아니잖아...",
  str_homestory_815701001_43_dialog_content = "PlayerName 님은 정말 좋은 사람이에요...",
  str_homestory_815701001_44_dialog_content = "저도... 제 능력으로 힘이 되고 싶어요.",
  str_homestory_815701001_45_dialog_content = "좋아요! 그럼 앞으로 이 「사랑의 꽃밭<sprite=emo_aixin size=60 />」은\n제가 관리할게요!",
  str_homestory_815601001_0_dialog_content = "...잘못 본 거 아니지?",
  str_homestory_815601001_1_dialog_content = "니나, 목마 타고 있었어?",
  str_homestory_815601001_2_dialog_content = "...목마?",
  str_homestory_815601001_3_dialog_content = "난 네가 그런 장난감은 안 좋아할 줄 알았어.",
  str_homestory_815601001_4_dialog_content = "조, 좋아한다고 한 적 없다고...",
  str_homestory_815601001_5_dialog_content = "그저 걷다가 힘들어서 쉴 곳을 찾고 있었을 뿐이야.",
  str_homestory_815601001_6_dialog_content = "난 이런 물건엔 관심 없거든.",
  str_homestory_815601001_7_dialog_content = "그렇겠지...",
  str_homestory_815601001_8_dialog_content = "지금 중요한 건 「내가 힘든데 쉴 곳이 없다」는\n거 아냐?",
  str_homestory_815601001_9_option_content = "(사과한다)",
  str_homestory_815601001_10_dialog_content = "아... 미안!",
  str_homestory_815601001_11_dialog_content = "근처에 돌 벤치를 몇 개 더 갖다 놓을까?",
  str_homestory_815601001_12_dialog_content = "돌 벤치? 아하하, 지금 농담하는 거지?",
  str_homestory_815601001_13_dialog_content = "정말 그런 단단한 물건 위에 앉을 수 있는 사람이\n있단 말이야?",
  str_homestory_815601001_14_dialog_content = "혹시 필요하다면...",
  str_homestory_815601001_15_dialog_content = "내가 당신을 위해 아름답고 편안한\n여행자용 벤치를 디자인해줄 수도 있어.",
  str_homestory_815601001_16_dialog_content = "저 나무토막에 대체 무슨 재미가 있는 건지\n말해준다면 말이야...",
  str_homestory_815601001_17_option_content = "(기분을 묻는다)",
  str_homestory_815601001_18_dialog_content = "오늘 니나는 많은 곳을 다녀온 모양이네.",
  str_homestory_815601001_19_dialog_content = "내 헤븐즈 가든이 우리 니나 아가씨의 마음에 들었으려나?",
  str_homestory_815601001_20_dialog_content = "그럼 당신이 물어본 거니까, 내가 냉정하게\n평가해도 원망하지 하지 마.",
  str_homestory_815601001_21_dialog_content = "당신 땅은 너무 구석진 곳에 있어!",
  str_homestory_815601001_22_dialog_content = "...그건 확실히 반박할 수가 없는 진실이네.",
  str_homestory_815601001_23_dialog_content = "그래도 경치는 나쁘지 않아.\n내 휴양지 리스트에 추가해 줄 순 있어.",
  str_homestory_815601001_24_dialog_content = "내 이런 평가가 움브라톤 신문에 실리면\n많은 사람들한테 영향을 줄 거라구.",
  str_homestory_815601001_25_dialog_content = "대신 그 전에... 저 나무토막에 대체\n무슨 재미가 있는 건지 말해줘...",
  str_homestory_815601001_26_dialog_content = "니나는 목마에 관심 없는 거 아니었어?",
  str_homestory_815601001_27_dialog_content = "...마음이 바뀌었어.",
  str_homestory_815601001_28_dialog_content = "모두의 흥미를 이해하는 것도\n나한테는 공부가 되거든.",
  str_homestory_815601001_29_dialog_content = "이런 불안정한 나무 블록에 앉는다면\n분명히 흔들릴 거야.",
  str_homestory_815601001_30_dialog_content = "뭐? 니나는 목마 타 본 적 없어?",
  str_homestory_815601001_31_dialog_content = "내가 어떻게 목마를 안 타 봤겠어?",
  str_homestory_815601001_32_dialog_content = "근데... 목마를 타는 건 그 흔들림을 느끼려고 타는 거잖아.",
  str_homestory_815601001_33_dialog_content = "아... 그, 그렇구나...\n아, 오해하지 마. 이미 알고 있었으니까!",
  str_homestory_815601001_34_dialog_content = "난 그냥 당신을 시험하고 싶었을 뿐이야!",
  str_homestory_815601001_35_option_content = "(믿는다)",
  str_homestory_815601001_36_dialog_content = "그럼 난 그 시험을 통과한 거겠네...",
  str_homestory_815601001_37_dialog_content = "응! PlayerName 당신 보기보다 똑똑하네, 아하하.",
  str_homestory_815601001_38_option_content = "(믿지 않는다)",
  str_homestory_815601001_39_dialog_content = "못 믿겠는데.",
  str_homestory_815601001_40_dialog_content = "PlayerName... 바보! 흥.",
  str_homestory_815601001_41_dialog_content = "......",
  str_homestory_815601001_42_dialog_content = "그, 근데...",
  str_homestory_815601001_43_dialog_content = "왜 사람들은 진짜 말을 안 타고\n이런 나무로 만든 말을 타는 거야?",
  str_homestory_815601001_44_dialog_content = "그건 나도 잘 모르겠어...",
  str_homestory_815601001_45_dialog_content = "하지만 목마도 나름의 재미가 있거든. 말을 타는 것보다도 훨씬 안전하고...",
  str_homestory_815601001_46_dialog_content = "그리고 모든 사람이 말을 탈 기회가 있는 건 아니야.",
  str_homestory_815601001_47_dialog_content = "네 말은 그러니까...\n다른 사람들은 진짜 말을 살 돈이 없다는 거야?<sprite=emo_wuzui size=60 />",
  str_homestory_815601001_48_dialog_content = "어떤 사람들은 목마조차 살 여유가 없어.",
  str_homestory_815601001_49_dialog_content = "......",
  str_homestory_815601001_50_dialog_content = "...결정했어!",
  str_homestory_815601001_51_dialog_content = "뭘?",
  str_homestory_815601001_52_dialog_content = "난 목공 디자인을 배울 거야.\n그리고 더 재미있는 목마를 만들어서...",
  str_homestory_815601001_53_dialog_content = "목마가 필요한 아이들에게 주겠어!",
  str_homestory_810401001_0_dialog_content = "도엔?",
  str_homestory_810401001_1_dialog_content = "이 발소리는...",
  str_homestory_810401001_2_dialog_content = "PlayerName 너지?",
  str_homestory_810401001_3_dialog_content = "뭐? 내 발소리도 알아챌 수 있는 거야?",
  str_homestory_810401001_4_dialog_content = "그래!<sprite=emo_yaosu size=60 />",
  str_homestory_810401001_5_dialog_content = "여긴 콜로서스보다 더 다양한 소리들이 있지만...",
  str_homestory_810401001_6_dialog_content = "익숙한 사람이 내는 소리는 언제든지\n잘 알아들을 수 있어.",
  str_homestory_810401001_7_dialog_content = "예를 들면 PlayerName 너랑 이브의\n발소리는 조금 달라.",
  str_homestory_810401001_8_dialog_content = "발소리에 차이가 있단 말이야...?",
  str_homestory_810401001_9_option_content = "(자신의 발소리에 대해 묻는다)",
  str_homestory_810401001_10_dialog_content = "넌 걸을 때 조금 급한 편이야.\n하지만 나한테 다가올 때는 오히려 조심스러워.",
  str_homestory_810401001_11_dialog_content = "그렇게 말해도 난 잘 모르겠는데...",
  str_homestory_810401001_12_dialog_content = "어쨌든 난 발소리로 네가 왔다는 걸 알 수 있어!",
  str_homestory_810401001_13_dialog_content = "아, 그리고 한 가지 더...",
  str_homestory_810401001_14_dialog_content = "네가 다가올 때면 즐거운 기분이 들어.",
  str_homestory_810401001_15_dialog_content = "응, 그러니까 즐거운 기분이 들면\nPlayerName 네가 왔다는 거야.",
  str_homestory_810401001_16_option_content = "(이브의 발소리에 대해 묻는다)",
  str_homestory_810401001_17_dialog_content = "이브의 발소리는 정말 귀여워!",
  str_homestory_810401001_18_dialog_content = "「귀엽다」니... 그게 발소리를 형용할 수 있는 표현이었어?",
  str_homestory_810401001_19_dialog_content = "물론이지. 이브는 뭐든지 사랑스러운걸<sprite=emo_aixin size=60 />.",
  str_homestory_810401001_20_dialog_content = "으음...",
  str_homestory_810401001_21_dialog_content = "알았어. 자세히 말하자면 그건 이브의 신체구조가\n조금 특수하기 때문이야...",
  str_homestory_810401001_22_dialog_content = "이브는 걸을 때 발소리가 거의 나지 않아.",
  str_homestory_810401001_23_dialog_content = "하지만 이브가 다가오면 즐거운 기분이 들어.",
  str_homestory_810401001_24_dialog_content = "응, 그러니까 즐거운 기분이 들면\n이브가 왔다는 거야.",
  str_homestory_810401001_25_dialog_content = "그런 거였구나...",
  str_homestory_810401001_26_dialog_content = "정말 대단하네!",
  str_homestory_810401001_27_dialog_content = "보이지 않는 대신 청각이 예민해졌을 뿐이야.",
  str_homestory_810401001_28_dialog_content = "참, 그럼 혹시...",
  str_homestory_810401001_29_dialog_content = "사메야마는?",
  str_homestory_810401001_30_dialog_content = "사메야마도 익숙할 거 아냐? 사메야마의 발소리는 어떤 특징이 있는데?",
  str_homestory_810401001_31_dialog_content = "사메야마라면 소리보다 더 쉬운 방법으로\n판단하고 있어.",
  str_homestory_810401001_32_dialog_content = "어떤 방법인데?",
  str_homestory_810401001_33_dialog_content = "냄새가 좀 나.",
  str_homestory_810401001_34_dialog_content = "......?",
  str_homestory_810401001_35_dialog_content = "아마 평소에 많이 움직여서 그런 거겠지...\n그래서 땀이 많이 날 거야.",
  str_homestory_810401001_36_dialog_content = "그, 그렇구나...",
  str_homestory_810401001_37_dialog_content = "비록 레디젤 렌치 중에서 사메야마가 제일\n냄새가 심한 건 아니지만...",
  str_homestory_810401001_38_dialog_content = "너나 이브에 비하면 확실히 냄새가 나.",
  str_homestory_810401001_39_dialog_content = "넌 그런 냄새가 안 나서 다행이야, 조종사.",
  str_homestory_810401001_40_dialog_content = "응...? 고, 고마워.",
  str_homestory_810401001_41_dialog_content = "근데 난... 사메야마한테서 딱히 무슨 냄새가 나는 건 못 느꼈는데?",
  str_homestory_810401001_42_dialog_content = "그래?",
  str_homestory_810401001_43_dialog_content = "그럼 설마 난 사메야마가 오랫동안 이브를\n독차지하는 게 마음에 안 들어서...<sprite=emo_sikao size=60 />",
  str_homestory_810401001_44_dialog_content = "냄새가 난다고 느낀 걸까?",
  str_homestory_810401001_45_dialog_content = "...그게 진짜 이유겠네!",
  str_homestory_810401001_46_dialog_content = "...상관 안 해. 아무튼 사메야마가 냄새나는 게\n분명하니까.",
  str_homestory_810401001_47_dialog_content = "냄새, 냄새, 사메야마는 냄새나<sprite=emo_kulou size=60 />!",
  str_homestory_809001001_0_dialog_content = "바바라?",
  str_homestory_809001001_1_dialog_content = "사랑♪ 그건 사람을 현혹하는 것일까~",
  str_homestory_809001001_2_dialog_content = "<sprite=emo_aixin size=60 />레디젤 오일이 다 타오르면 진심과 바꿀 수 있어~",
  str_homestory_809001001_3_dialog_content = "아아~ 진심만을 원해~",
  str_homestory_809001001_4_dialog_content = "바바라, 새 싱글 연습 중이야?",
  str_homestory_809001001_5_dialog_content = "헤헤, 싱글? 아니야!",
  str_homestory_809001001_6_dialog_content = "바바라는 새 앨범 준비를 하고 있다구!",
  str_homestory_809001001_7_option_content = "새 앨범?",
  str_homestory_809001001_8_dialog_content = "노래가 여러 곡 있는 디스크 말하는 거야?",
  str_homestory_809001001_9_dialog_content = "맞아~",
  str_homestory_809001001_10_option_content = "레지나를 넘어선 거야?",
  str_homestory_809001001_11_dialog_content = "후후~ 그거야 당연하지!",
  str_homestory_809001001_12_dialog_content = "판매량과 사인회의 성공을 위해서라도\n바바라는 노력할 거야!",
  str_homestory_809001001_13_dialog_content = "정말 고생이네.",
  str_homestory_809001001_14_dialog_content = "요즘은 여기저기서 새로운 음악 스타일이\n탄생하고 있어... 나도 이 정도 노력은 필수야.",
  str_homestory_809001001_15_dialog_content = "바바라는 절대 밀리지 않을 거야!",
  str_homestory_809001001_16_dialog_content = "가요계에서 네 지위가 흔들릴까 봐 걱정하는 거야?",
  str_homestory_809001001_17_dialog_content = "지위가 흔들려...?\n에이, 난 이제 그런 건 걱정 안 해!",
  str_homestory_809001001_18_dialog_content = "더 많은 장르의 음악이나 아티스트가 탄생하는 건\n바바라도 원하는 일이거든~",
  str_homestory_809001001_19_dialog_content = "그럼 「절대 밀리지 않겠다」는 말은 뭔데?",
  str_homestory_809001001_20_dialog_content = "바바라도 더 노력해야 한다는 뜻이야<sprite=emo_yinfu size=60 />~",
  str_homestory_809001001_21_dialog_content = "나도 신인들이랑 같이 성장해서,\n함께 더 좋은 작품을 만들 거야!",
  str_homestory_809001001_22_dialog_content = "바바라는 뒤처지는 게 제일 싫어!",
  str_homestory_809001001_23_dialog_content = "네 말을 들으니까 나도 격려가 되는 것 같아!",
  str_homestory_809001001_24_dialog_content = "그렇지? 뭐, 난 내 인기는 별로 걱정 안 해~",
  str_homestory_809001001_25_dialog_content = "근데 만약 오랫동안 날 응원해준 팬이\n다른 사람의 팬이 된다면...",
  str_homestory_809001001_26_dialog_content = "역시 좌절감을 느낄 것 같아!",
  str_homestory_809001001_27_dialog_content = "레지나 말하는 거야?",
  str_homestory_809001001_28_dialog_content = "PlayerName... 너무 대놓고 말하는 거 아냐?!",
  str_homestory_809001001_29_dialog_content = "역시 너도 속으로는 레지나를 신경 쓰고 있었구나?",
  str_homestory_809001001_30_dialog_content = "음... 뭐라고 해야 하나...",
  str_homestory_809001001_31_dialog_content = "「전혀 신경 쓰지 않는다」고 말하면\n거짓말이겠지<sprite=emo_tanqi size=60 />...",
  str_homestory_809001001_32_dialog_content = "음, 이렇게 말할 수 있을 것 같아.",
  str_homestory_809001001_33_dialog_content = "난 어디까지나 음악의 다양성을 넓히는 차원에서\n레지나의 음악을 듣고 있어.",
  str_homestory_809001001_34_dialog_content = "으음~ 팬 수로 따지면 나보다 적지만,\n레지나의 팬은 다들 열성팬이야~",
  str_homestory_809001001_35_dialog_content = "음악은 원래 퀄리티로 승부하는 거지만,\n그래도 사실 궁금하긴 해...",
  str_homestory_809001001_36_dialog_content = "레지나는 어떻게 팬들의 마음을 계속\n사로잡고 있는 걸까?",
  str_homestory_809001001_37_dialog_content = "그럼 혼자 생각하기보다 레지나한테 직접 물어보는 게 어때?",
  str_homestory_809001001_38_dialog_content = "흐으음~",
  str_homestory_809001001_39_dialog_content = "PlayerName 네가 그렇게 말한다면,\n한번 생각은 해 볼게...",
  str_homestory_809001001_40_dialog_content = "직접 물어보는 것 정도는 별거 아니니까!",
  str_homestory_809001001_41_dialog_content = "음... 대신 한 20년 정도 걸리겠지만 말이야<sprite=emo_emo size=60 />~",
  str_homestory_809001001_42_dialog_content = "...그럼 안 물어보는 거랑 똑같잖아!",
  str_homestory_807001001_0_dialog_content = "레오나 씨...",
  str_homestory_807001001_1_dialog_content = "너였구나, 꼬마야.",
  str_homestory_807001001_2_dialog_content = "무슨 일이니?",
  str_homestory_807001001_3_dialog_content = "미안하지만 난 지금 시간이 없어.",
  str_homestory_807001001_4_dialog_content = "보다시피 난 지금 스트레스를 푸느라 바쁘거든.",
  str_homestory_807001001_5_dialog_content = "아, 샌드백을 두드리면 스트레스 해소가 되는 건가요?",
  str_homestory_807001001_6_dialog_content = "당연하지<sprite=emo_baiyan size=60 />.",
  str_homestory_807001001_7_dialog_content = "들어본 적 없어?",
  str_homestory_807001001_8_dialog_content = "운동에는 스트레스 해소 효과가 있거든.",
  str_homestory_807001001_9_dialog_content = "그거야 들어봤죠.",
  str_homestory_807001001_10_dialog_content = "그럼 지금 레오나 씨가 갖고 있는 스트레스는...",
  str_homestory_807001001_11_option_content = "뭐가 원인인데요?",
  str_homestory_807001001_12_dialog_content = "딱히 원인은 없어.",
  str_homestory_807001001_13_option_content = "해소됐나요?",
  str_homestory_807001001_14_dialog_content = "응, 거의 된 것 같네.",
  str_homestory_807001001_15_dialog_content = "스트레스는 몸속의 「매듭」 같은 거라고\n이해하면 돼.",
  str_homestory_807001001_16_dialog_content = "「매듭」...? 밧줄로 만든 그런 거 말인가요...?",
  str_homestory_807001001_17_dialog_content = "비슷해.",
  str_homestory_807001001_18_dialog_content = "자신이 스트레스를 받고 있다는 걸 발견했다면...",
  str_homestory_807001001_19_dialog_content = "반드시 자신에게 맞는 방법으로\n그걸 몸에서 제거해야만 해.",
  str_homestory_807001001_20_dialog_content = "기분전환을 할 수 있는 거라면 어떤 방법이든 좋아.",
  str_homestory_807001001_21_dialog_content = "그리고 나한테는 이런 싸움에 가까운 방법이\n가장 잘 맞아.",
  str_homestory_807001001_22_dialog_content = "스트레스를 계속 몸속에 쌓아 둔다면,\n그 「매듭」은 점점 더 복잡해질 거야.",
  str_homestory_807001001_23_dialog_content = "최악의 경우에는 목숨까지 영향을 줄 수도 있어.",
  str_homestory_807001001_24_dialog_content = "나도 오랜 시간을 들여서 겨우 깨달은 거야.",
  str_homestory_807001001_25_dialog_content = "증오가 내 마음과 피를 속여 왔으니까...",
  str_homestory_807001001_26_dialog_content = "...이야기가 딴길로 샜네, 꼬마야.",
  str_homestory_807001001_27_dialog_content = "음... 레오나 씨 말도 일리가 있는 것 같아요.",
  str_homestory_807001001_28_dialog_content = "그럼 다음엔 너도 해 봐.",
  str_homestory_807001001_29_dialog_content = "알겠어요!",
  str_homestory_807001001_30_dialog_content = "저번에 시로나 씨도 여기서 전투 연습을 했는데, 그것도 아마 비슷한 이유였겠죠?",
  str_homestory_807001001_31_dialog_content = "...지금 뭐라고 했지?",
  str_homestory_807001001_32_dialog_content = "이 샌드백을 시로나도 썼다고?",
  str_homestory_807001001_33_dialog_content = "아, 아? 아, 잘못 말한 거예요!",
  str_homestory_807001001_34_dialog_content = "(뭔가 해서는 안 될 말을 한 것 같다...)",
  str_homestory_807001001_35_dialog_content = "......",
  str_homestory_807001001_36_dialog_content = "레오나 씨, 왜 그래요? 갑자기...",
  str_homestory_807001001_37_dialog_content = "후후, 또 사랑스러운 여동생과 같은 일을\n해버린 모양이네.",
  str_homestory_807001001_38_dialog_content = "여길 다 불태워<sprite=emo_nuhuo size=60 />버리기 전에...",
  str_homestory_807001001_39_dialog_content = "지금 당장 움브라톤으로 돌아가야겠어.",
  str_homestory_807001001_40_dialog_content = "잘 있어, 꼬마야.",
  str_homestory_807001001_41_dialog_content = "아, 저기...",
  str_homestory_807001001_42_dialog_content = "언제든지 또 오세요...",
  str_homestory_811501001_0_dialog_content = "나로세르!",
  str_homestory_811501001_1_dialog_content = "PlayerName 님, 오셨군요.",
  str_homestory_811501001_2_dialog_content = "분명 자연의 힘이 저와 당신을\n재회하게 한 것이겠지요.",
  str_homestory_811501001_3_dialog_content = "나로세르는 싱이랑 포인터랑 수다 떨고 있었어?",
  str_homestory_811501001_4_dialog_content = "맞아요.",
  str_homestory_811501001_5_dialog_content = "저들의 이름을 아직도 기억하고 계셨다니...",
  str_homestory_811501001_6_dialog_content = "두 아이 모두 기뻐하고 있답니다.",
  str_homestory_811501001_7_dialog_content = "그거야 당연하지.",
  str_homestory_811501001_8_dialog_content = "다시 이 땅에 우뚝 솟은 헤븐즈 밸리를\n보고 있으니, 정말 감회가 새롭네요<sprite=emo_pugongying size=60 />.",
  str_homestory_811501001_9_dialog_content = "헤븐즈 가든이 오늘의 모습을 되찾은 것도...",
  str_homestory_811501001_10_dialog_content = "대자연의 은혜와 PlayerName 님의 큰 노력 덕분이겠지요.",
  str_homestory_811501001_11_dialog_content = "다만... 당신이 조금 걱정입니다.",
  str_homestory_811501001_12_dialog_content = "최근 많은 일을 겪으셨는데, 기분은 괜찮으신가요?",
  str_homestory_811501001_13_option_content = "(고개를 끄덕인다)",
  str_homestory_811501001_14_dialog_content = "그래도 여기서 다들 같이 지낼 수 있어서 무척 기쁜걸.",
  str_homestory_811501001_15_dialog_content = "다만, 가끔은 너무 기대를 받는 것 같아서 조금 부담스러울 때도 있어.",
  str_homestory_811501001_16_option_content = "(고개를 젓는다)",
  str_homestory_811501001_17_dialog_content = "기분이 계속 안 좋았던 건 아니지만...",
  str_homestory_811501001_18_dialog_content = "자꾸 이상한 초조함과 압박감이 느껴지곤 해.",
  str_homestory_811501001_19_dialog_content = "이해했어요.",
  str_homestory_811501001_20_dialog_content = "그럼 지금부터 저와 함께 마음을 편안하게\n만들지 않으시겠어요?",
  str_homestory_811501001_21_dialog_content = "좋아.",
  str_homestory_811501001_22_dialog_content = "자, 그럼 「호흡」 연습을 같이 해 보기로 해요.",
  str_homestory_811501001_23_dialog_content = "「호흡」 연습?",
  str_homestory_811501001_24_dialog_content = "네.",
  str_homestory_811501001_25_dialog_content = "이 호흡을 하면 언제든지 체내에 있는 에너지의\n균형을 맞출 수 있답니다.",
  str_homestory_811501001_26_dialog_content = "쉽게 말씀드리자면...",
  str_homestory_811501001_27_dialog_content = "우리 몸의 에너지를 다시 흐르게\n만드는 것이랍니다.",
  str_homestory_811501001_28_dialog_content = "알겠어! 그럼 시작할까?",
  str_homestory_811501001_29_dialog_content = "네.",
  str_homestory_811501001_30_dialog_content = "우선 두 어깨의 힘을 빼고 심호흡을 하세요.",
  str_homestory_811501001_31_dialog_content = "좋아요. 그럼 이제 코를 잡으세요.",
  str_homestory_811501001_32_dialog_content = "(코를 잡아...? 음...)",
  str_homestory_811501001_33_dialog_content = "처음에는 오른쪽을 꽉 잡고\n왼쪽으로 숨을 마셔 보세요.",
  str_homestory_811501001_34_dialog_content = "그리고 왼쪽을 잡고 오른쪽으로 숨을 내쉬세요.",
  str_homestory_811501001_35_dialog_content = "(마시고, 내쉬고...)",
  str_homestory_811501001_36_dialog_content = "이렇게 천천히 호흡을 가다듬으세요.",
  str_homestory_811501001_37_dialog_content = "고른 호흡을 계속 유지하세요...",
  str_homestory_811501001_38_dialog_content = "이 호흡법이 몸을 풀어주는 걸\n느끼실 수 있을 거예요.",
  str_homestory_811501001_39_dialog_content = "확실히 마음이 가라앉은 것 같아.",
  str_homestory_811501001_40_dialog_content = "조금 졸릴 정도야<sprite=emo_kun size=60 />...",
  str_homestory_811501001_41_dialog_content = "후훗...",
  str_homestory_811501001_42_dialog_content = "이 호흡법은 정서를 편안하게 만들기도 하지만,\n수면을 촉진하는 효과도 있답니다.",
  str_homestory_811501001_43_dialog_content = "주무시기 전에 다시 한번 해 보시는 것도 좋아요.",
  str_homestory_811501001_44_dialog_content = "눈을 감고 호흡하면 효과가 더 좋을 수도 있어요.",
  str_homestory_811501001_45_dialog_content = "응, 기억할게.",
  str_homestory_811501001_46_dialog_content = "고마워, 나로세르!",
  str_homestory_803302001_0_dialog_content = "안녕, 바이스.",
  str_homestory_803302001_1_dialog_content = "PlayerName! 지금 시간 있어?",
  str_homestory_803302001_2_dialog_content = "물론이지. 왜 그래?",
  str_homestory_803302001_3_dialog_content = "물가를 산책하고 있었는데,\n물에 뭔가 있는 것 같더라고.",
  str_homestory_803302001_4_dialog_content = "한참 고생했는데 결국 못 꺼냈어...\n왠지 무슨 도면 같았단 말이야.",
  str_homestory_803302001_5_dialog_content = "혹시 흥미 있으면 한번 보러 가 봐!",
  str_homestory_803302001_6_dialog_content = "응, 알았어.",
  str_homestory_803303001_0_dialog_content = "뭐 해?",
  str_homestory_803303001_1_dialog_content = "생각 중이야...\n어떻게 하면 그걸 잡을 수 있을지...",
  str_homestory_803303001_2_dialog_content = "그거라니?",
  str_homestory_803303001_3_dialog_content = "강물 속에 이상한 게 있길래 너무 궁금했거든<sprite=emo_sikao size=60 />.",
  str_homestory_803303001_4_dialog_content = "근데 손이 저릴 때까지 낚시를 해도\n건질 수가 없더라고.",
  str_homestory_803303001_5_dialog_content = "좀 도와줄래? 저기 있어!",
  str_homestory_803303001_6_dialog_content = "아... 한번 해 볼게.",
  str_homestory_803304001_0_dialog_content = "나 찾았어?",
  str_homestory_803304001_1_dialog_content = "앗, 어떻게 알았어?",
  str_homestory_803304001_2_dialog_content = "내가 재밌는 걸 찾았거든!<sprite=emo_yaosu size=60 />",
  str_homestory_803304001_3_dialog_content = "또 거대한 거미나 춤추는 메뚜기는 아니지?",
  str_homestory_803304001_4_dialog_content = "아니야! 내가 새로운 가구 도면을 찾았어!",
  str_homestory_803304001_5_dialog_content = "근데 강물 밑바닥에 가라앉아 버렸지 뭐야.\n건지기도 힘든 것 같고.",
  str_homestory_803304001_6_dialog_content = "아, 나한테 맡겨. 그런 건 익숙하니까.",
  str_homestory_803304001_7_dialog_content = "응! 바로 저기 있어! 내가 알려줄게!",
  str_homestory_809301001_0_dialog_content = "그 눈빛...",
  str_homestory_809301001_1_dialog_content = "나, 나한테 무슨 볼일 있어?",
  str_homestory_809301001_2_dialog_content = "며칠 못 본 사이에 성장했구나.\n아무 말도 안 했는데 내가 볼일이 있는 걸\n알다니 말이야.",
  str_homestory_809301001_3_dialog_content = "아까 등줄기가 서늘하더니... 누가 날 계속 보는 것 같아서...",
  str_homestory_809301001_4_dialog_content = "고개를 들었더니 미자드 씨가 이쪽을 보고 있더라고.",
  str_homestory_809301001_5_dialog_content = "「고개를 들어?」\n아무래도 키는 여전히 안 큰 모양이구나.",
  str_homestory_809301001_6_option_content = "컸거든!",
  str_homestory_809301001_7_dialog_content = "그래? 난 그렇게 안 보이는데?\n그럼 어디 실험실에서 확인해 볼까?",
  str_homestory_809301001_8_dialog_content = "네 뼈가 자라고 있는지 없는지,\n내가 해부해서 알아봐 줄게.",
  str_homestory_809301001_9_option_content = "맞아...",
  str_homestory_809301001_10_dialog_content = "시원하게 인정하는구나. 정말 마음이 아프네.\n아니면 내 실험실에 같이 가 볼래?",
  str_homestory_809301001_11_dialog_content = "어디 네 뼈에 성장 호르몬이 제대로\n분비되고 있는지 알아봐 줄게.",
  str_homestory_809301001_12_dialog_content = "그, 그럴 필요는 없지 않을까...",
  str_homestory_809301001_13_dialog_content = "걱정 마. 내가 해부하게 해 주면 널 위해서\n전용 키 성장 계획을 만들어 줄 테니까.",
  str_homestory_809301001_14_dialog_content = "난 그냥 순리에 맡길게...",
  str_homestory_809301001_15_dialog_content = "순리에 맡긴다고? 거짓말이지?",
  str_homestory_809301001_16_dialog_content = "헤븐즈 가든에는 유전자를 개량한 나무들이\n많이 있잖아.",
  str_homestory_809301001_17_dialog_content = "게다가 개량에 사용한 기술도...",
  str_homestory_809301001_18_dialog_content = "여러 종류의 종자를 섞어서 독자적인 품종을\n합성하는 생명과학이잖아.",
  str_homestory_809301001_19_dialog_content = "어? 보기만 해도 아는 거야?",
  str_homestory_809301001_20_dialog_content = "어머, 잊었어?\n난 일루미나 생물학 분야의 책임자잖아.",
  str_homestory_809301001_21_dialog_content = "그런 종류의 생물 실험이라면,\n벌써 셀 수 없을 만큼 해왔거든.",
  str_homestory_809301001_22_dialog_content = "근데 너한테도 과학 연구의 재능이 있었다니,\n정말 의외네.",
  str_homestory_809301001_23_dialog_content = "그냥 흉내만 내는 정도야. 그렇게 대단한 것도 아닌걸.",
  str_homestory_809301001_24_dialog_content = "응, 알고 있어.",
  str_homestory_809301001_25_dialog_content = "......",
  str_homestory_809301001_26_dialog_content = "99번의 실패가 없다면,\n한 번의 성공도 얻을 수 없어.",
  str_homestory_809301001_27_dialog_content = "이건 내가 일하면서 배운 거야. 그리고 넌...",
  str_homestory_809301001_28_dialog_content = "희귀 품종을 만들어 내려면,\n이렇게도 하고, 저렇게도 해야 할 거야.",
  str_homestory_809301001_29_dialog_content = "「이렇게도, 저렇게도」라니? 전혀 모르겠는데...",
  str_homestory_809301001_30_dialog_content = "과학 연구 경험이 없으면 확실히 알기 힘들 거야.\n다음에 또 얘기해줄게.",
  str_homestory_809301001_31_dialog_content = "지금 얘기해줘도 괜찮아.",
  str_homestory_809301001_32_dialog_content = "지금? 그럼 난 일단 한숨 잘게.",
  str_homestory_809301001_33_dialog_content = "......",
  str_homestory_809301001_34_dialog_content = "아, 잠깐만. 제일 중요한 걸 잊을 뻔했잖아.",
  str_homestory_809301001_35_dialog_content = "혹시 내 방을 귀여운 여자애들이 많은\n저쪽 숙소로 바꿔줄 수 있을까?",
  str_homestory_809301001_36_option_content = "(동의한다)",
  str_homestory_809301001_37_dialog_content = "뭐, 그래도 되겠지... 대신 다른 사람들이랑 직접 상의해 줘.",
  str_homestory_809301001_38_option_content = "(거절한다)",
  str_homestory_809301001_39_dialog_content = "어디에 사는지는 각자의 자유야. 난 간섭할 수 없어.",
  str_homestory_809301001_40_dialog_content = "대신 미자드 씨가 다른 사람들과 잘 상의한다면 안 되는 건 아냐.",
  str_homestory_809301001_41_dialog_content = "그거 왠지 귀찮을 것 같네.",
  str_homestory_809301001_42_dialog_content = "그래도 시도해 볼 가치는 있겠어.\n안 되면 100번 도전할게.",
  str_homestory_809301001_43_dialog_content = "(그런 일에까지 과학 연구 정신을 발휘할 필요가 있을까...?)",
  str_homestory_815702001_0_dialog_content = "뭐 보고 있어?",
  str_homestory_815702001_1_dialog_content = "으아아아...",
  str_homestory_815702001_2_dialog_content = "미안, 나 때문에 또 놀랐어?",
  str_homestory_815702001_3_dialog_content = "(...근데 난 왜 「또」라고 말한 걸까...)",
  str_homestory_815702001_4_dialog_content = "아니에요. 그냥 제가 생각에 너무 빠져 있어서...",
  str_homestory_815702001_5_dialog_content = "PlayerName 님이 오신 것도 모르고 있었네요...",
  str_homestory_815702001_6_dialog_content = "사과해야 할 건 저예요...",
  str_homestory_815702001_7_dialog_content = "아무 일도 없으면 그걸로 됐어. 너무 신경 쓰지 마.",
  str_homestory_815702001_8_dialog_content = "지금 강 쪽에서 온 거지? 혹시 방금...",
  str_homestory_815702001_9_option_content = "낚시하려던 거야?",
  str_homestory_815702001_10_dialog_content = "낚시를... 하려면 비싼 낚시 도구가 필요하겠죠?",
  str_homestory_815702001_11_dialog_content = "그, 그런 분수에 안 맞는 일은 생각 안 해요...",
  str_homestory_815702001_12_option_content = "수영하려던 거야?",
  str_homestory_815702001_13_dialog_content = "수영을 하려면...\n몸에 딱 맞는 수영복을 입어야 되는 거죠?",
  str_homestory_815702001_14_dialog_content = "조, 조금 부끄러울 것 같아요...",
  str_homestory_815702001_15_dialog_content = "사실 전 다른 생각을 하고 있었어요...",
  str_homestory_815702001_16_dialog_content = "옛날 헤븐즈 밸리에서 밭일을 하던 농민들도...\n운도 농민들처럼 힘들었겠죠?",
  str_homestory_815702001_17_dialog_content = "그건 나도 잘 모르겠네. 하지만 헤븐즈 밸리든 운도든...",
  str_homestory_815702001_18_dialog_content = "풍년이 드는 해는 분명히 다들 똑같이 기뻐했을 거야.",
  str_homestory_815702001_19_dialog_content = "근데 왜 갑자기 그런 생각을 한 건데?",
  str_homestory_815702001_20_dialog_content = "그게... 아까 강가에서 반짝거리는 뭔가를\n주웠는데요. 무슨 동전 같았어요<sprite=emo_baiyebi size=60 />.",
  str_homestory_815702001_21_dialog_content = "동전이 있다는 건 거래가 있다는 거고...\n거래가 있으면 식량이 있겠죠...\n그리고 식량이 있으면 농민도 있을 거예요!",
  str_homestory_815702001_22_dialog_content = "그런 연상까지 할 수 있단 말이야?!",
  str_homestory_815702001_23_dialog_content = "아, 화...화내지 마세요!",
  str_homestory_815702001_24_dialog_content = "저저저저전 동전을 차지할 생각은 없었어요...",
  str_homestory_815702001_25_dialog_content = "지금 바로 동전을 드릴게요...",
  str_homestory_815702001_26_dialog_content = "그런 거 아냐. 당황할 거 없어.",
  str_homestory_815702001_27_dialog_content = "잠깐만요... 좀 찾아볼게요... 어디다 뒀더라...",
  str_homestory_815702001_28_dialog_content = "어라... 왜 보이질 않을까요...",
  str_homestory_815702001_29_dialog_content = "앗!",
  str_homestory_815702001_30_dialog_content = "왜 그래?",
  str_homestory_815702001_31_dialog_content = "그러고 보니까 아까 강가에서 돌아올 때...\n풍덩 소리가 났던 것 같아요.",
  str_homestory_815702001_32_dialog_content = "그때 실수로 동전을 다시 강물에\n빠트린 게 분명해요!",
  str_homestory_815702001_33_dialog_content = "괜찮아, 내가 가서 주울게.",
  str_homestory_815702001_34_dialog_content = "으아아아아... 그, 그래도 되나요?\n그럼 부탁드릴게요!",
  str_homestory_815602001_0_dialog_content = "뭐 찾아?",
  str_homestory_815602001_1_dialog_content = "저기, 얼른 이리 와!",
  str_homestory_815602001_2_dialog_content = "니나?",
  str_homestory_815602001_3_dialog_content = "내가 잘못 본 게 아니라면...\n방금 뭐 찾고 있었어?",
  str_homestory_815602001_4_dialog_content = "그래.",
  str_homestory_815602001_5_dialog_content = "혹시 동글동글한 거 본 적 있어?",
  str_homestory_815602001_6_dialog_content = "좀 더 구체적인 설명은 없을까?",
  str_homestory_815602001_7_dialog_content = "음... 그게 말이지...",
  str_homestory_815602001_8_dialog_content = "그런 프린팅이 된 제품은 나도 처음 보는 거라서...",
  str_homestory_815602001_9_dialog_content = "그래서 방금 손에 꽉 쥐고 있었어!",
  str_homestory_815602001_10_dialog_content = "근데 손을 놨다가 실수로 물에 빠트려 버렸어.",
  str_homestory_815602001_11_dialog_content = "잠깐만, 왠지 그거...",
  str_homestory_815602001_12_dialog_content = "아니, 일단 내 얘기부터 마저 들어.",
  str_homestory_815602001_13_dialog_content = "손을 펴 봤더니 내 손바닥에 이상한 선이 생겼어!",
  str_homestory_815602001_14_option_content = "루미나가 변이한 거야?!",
  str_homestory_815602001_15_dialog_content = "뭐야, 당신 요즘 소설을 너무 많이 읽은 거 아냐?",
  str_homestory_815602001_16_option_content = "니나 너 변신하는 거야?!",
  str_homestory_815602001_17_dialog_content = "무슨 소리야?",
  str_homestory_815602001_18_dialog_content = "그건 「그 물건」의 모양과 문양이\n독특해서 그런 거야!",
  str_homestory_815602001_19_dialog_content = "그러니까 손에 쥐었을 때 똑같은 자국이\n남은 거겠지.",
  str_homestory_815602001_20_dialog_content = "손바닥에 남은 무늬를 봤는데,\n기묘한 디자인 감각이 있었어...",
  str_homestory_815602001_21_dialog_content = "만약 이런 식으로 옷을 디자인한다면...",
  str_homestory_815602001_22_dialog_content = "안 되겠어. 반드시 그 동전을 찾아야 해!",
  str_homestory_815602001_23_dialog_content = "역시 동전이구나!",
  str_homestory_815602001_24_dialog_content = "내가 도와줄게.",
  str_homestory_815602001_25_dialog_content = "그, 그럼 일단 고맙다고 해 둘게...\n앗, 잠깐만!<sprite=emo_wuzui size=60 />",
  str_homestory_815602001_26_dialog_content = "그 동전은 헤븐즈 가든에서 발견한 거니까,\n아마... 당신 재산이겠지?",
  str_homestory_815602001_27_dialog_content = "그럼 혹시 내가 빌려서 좀 연구하고 싶으면...",
  str_homestory_815602001_28_dialog_content = "얼마든지 좋아.\n대신 그 전에 그 동전부터 찾아내야겠지.",
  str_homestory_815602001_29_dialog_content = "우와! 그렇게 빨리 승낙하는 거야?",
  str_homestory_815602001_30_dialog_content = "크흠, 그게... 내가 딱히 그 연구를\n엄청 하고 싶은 건 아니고...",
  str_homestory_815602001_31_dialog_content = "난 그냥 옷을 디자인하고 싶을 뿐이야!",
  str_homestory_815602001_32_dialog_content = "당신도 잘 알고 있겠지?",
  str_homestory_815602001_33_dialog_content = "알고 있어.",
  str_homestory_815602001_34_dialog_content = "후후, 그럼 됐어.",
  str_homestory_812601001_0_dialog_content = "무슨 생각해?",
  str_homestory_812601001_1_dialog_content = "베델?",
  str_homestory_812601001_2_dialog_content = "뭔가 엄청 진지하게 생각하는 것 같은데...",
  str_homestory_812601001_3_dialog_content = "쉿...<sprite=emo_chidai size=60 />",
  str_homestory_812601001_4_dialog_content = "겨우 총상회의 보고를 마치고\n지금 생각하는 중인걸요.",
  str_homestory_812601001_5_dialog_content = "무슨 생각하는데?",
  str_homestory_812601001_6_dialog_content = "제 새로운 시나리오요!",
  str_homestory_812601001_7_dialog_content = "아, 이참에 당신한테 물어보는 게 좋겠네요.",
  str_homestory_812601001_8_dialog_content = "그래. 내가 도움이 된다면야.",
  str_homestory_812601001_9_dialog_content = "크흠, 잘 들으세요.\n줄거리는 이렇게 전개될 거예요.",
  str_homestory_812601001_10_dialog_content = "남주인공과 여주인공이 강가에 가요...",
  str_homestory_812601001_11_dialog_content = "이때 여주인공의 손수건이 갑자기\n물에 빠지는 거죠!",
  str_homestory_812601001_12_dialog_content = "손수건을 여주인공이 건져야 할까요?\n아니면 남주인공이 건져야 할까요?",
  str_homestory_812601001_13_option_content = "(여주인공)",
  str_homestory_812601001_14_dialog_content = "음...",
  str_homestory_812601001_15_dialog_content = "그럼 확실히 「뭐든지 직접 해낸다」는\n여주인공의 자립심이 잘 드러나겠네요.",
  str_homestory_812601001_16_option_content = "(남주인공)",
  str_homestory_812601001_17_dialog_content = "음...",
  str_homestory_812601001_18_dialog_content = "그럼 스토리를 비교적 빠르게 진행할 수 있겠네요.\n그리고 손수건을 가지고 화제를 전개할\n수도 있겠죠.",
  str_homestory_812601001_19_dialog_content = "좋아요, 알겠어요!",
  str_homestory_812601001_20_dialog_content = "그럼 그렇게 써야겠어요!<sprite=emo_yaosu size=60 />",
  str_homestory_812601001_21_dialog_content = "근데 왜 그런 전개를 설정한 건데?",
  str_homestory_812601001_22_dialog_content = "방금 뭔가가 물에 떨어지는 걸 봤거든요.",
  str_homestory_812601001_23_dialog_content = "그래서 이런 전개도 나쁘지 않을 거라고\n생각했어요...",
  str_homestory_812601001_24_dialog_content = "응? 물에 뭐가 빠졌는데?",
  str_homestory_812601001_25_dialog_content = "자세히는 못 봤지만,\n왠지 작고 동그란 물건 같았어요.<sprite=emo_sikao size=60 />",
  str_homestory_812601001_26_dialog_content = "작고 동그란 물건...",
  str_homestory_812601001_27_dialog_content = "뭔지 알 것 같아.",
  str_homestory_816401001_0_dialog_content = "카렌?",
  str_homestory_816401001_1_dialog_content = "PlayerName?",
  str_homestory_816401001_2_dialog_content = "카렌, 뭐 하고 있었어?",
  str_homestory_816401001_3_dialog_content = "생각 중이야.",
  str_homestory_816401001_4_dialog_content = "왠지 조금 우울해 보이는데...?",
  str_homestory_816401001_5_dialog_content = "우울이라...",
  str_homestory_816401001_6_dialog_content = "최근 백야성에 자연재해가 발생했거든.",
  str_homestory_816401001_7_dialog_content = "미안, 카렌...",
  str_homestory_816401001_8_dialog_content = "지금 상황은 어때? 내가 도울 수 있는 일이 있을까?",
  str_homestory_816401001_9_dialog_content = "신경 써 줘서 고마워, PlayerName.",
  str_homestory_816401001_10_dialog_content = "사상자 및 재산 피해 현황 조사는 이미 정상적인\n재난 사후 처리 절차에 들어갔어.",
  str_homestory_816401001_11_dialog_content = "뜻밖의 죽음을 맞이한 사람들을 다시\n가족들에게 「돌려보내는」 것 외에는...",
  str_homestory_816401001_12_dialog_content = "저들의 마음속 고통을 달래줄 다른 방법은\n도저히 떠오르질 않아.",
  str_homestory_816401001_13_dialog_content = "네 심정은 이해해, 카렌.",
  str_homestory_816401001_14_dialog_content = "하아...<sprite=emo_tanqi size=60 />",
  str_homestory_816401001_15_dialog_content = "고민했던 걸 이야기하니까 마음이 한결\n맑아지는 기분이야.",
  str_homestory_816401001_16_dialog_content = "그럼 카렌 넌 재난을 피하는 방법에 대해 생각하고 있었던 거야?",
  str_homestory_816401001_17_dialog_content = "아니야.",
  str_homestory_816401001_18_dialog_content = "약소한 개인으로서 우린 그런 거대한 명제와\n맞설 수 없어.",
  str_homestory_816401001_19_dialog_content = "난 그저 묵묵히 기도하면서,\n스스로에게 한 가지 확인을 하고 있었을 뿐이야...",
  str_homestory_816401001_20_option_content = "자신의 신념?",
  str_homestory_816401001_21_dialog_content = "그래...",
  str_homestory_816401001_22_option_content = "기도의 효과?",
  str_homestory_816401001_23_dialog_content = "음, 뭐랄까...",
  str_homestory_816401001_24_dialog_content = "난 그저 기도가 여전히 내 마음에 위안을\n가져다줄 수 있는지 확인하고 싶었어.",
  str_homestory_816401001_25_dialog_content = "이해했어...",
  str_homestory_816401001_26_dialog_content = "우린 그런 간섭할 수 없는 「무상함」에 대해\n경외감을 느낄 수밖에 없을 거야.",
  str_homestory_816401001_27_dialog_content = "하지만 그런 「무상함」은 어떤 해결책도 없어.\n그저 지켜만 볼 수밖에 없겠지.",
  str_homestory_816401001_28_dialog_content = "그래서 넌 좌절감을 느꼈던 거야?",
  str_homestory_816401001_29_dialog_content = "맞아.",
  str_homestory_816401001_30_dialog_content = "그런 좌절감이 떠오를 때마다,\n난 마음속으로 묵묵히 기도하곤 했어.",
  str_homestory_816401001_31_dialog_content = "그리고 난 기도가 진정으로 내게 가져다\n줄 수 있는 게 뭔지 생각했어.",
  str_homestory_816401001_32_dialog_content = "그건 아마 정신적인 측면의 지지, 그리고...",
  str_homestory_816401001_33_dialog_content = "날 계속 나아가게 하는 일종의 동기부여겠지.",
  str_homestory_816401001_34_dialog_content = "맞아.",
  str_homestory_816401001_35_dialog_content = "기도는 네가 이 우울한 날을 이겨내는 걸 도와줄 수 있을 거야.",
  str_homestory_816401001_36_dialog_content = "응... 그리고 한 가지 사실을 이해할 수 있었어.",
  str_homestory_816401001_37_dialog_content = "왜 우리는 항상 만물에 대응하는\n신을 만들고 싶어 하는지 알아?",
  str_homestory_816401001_38_dialog_content = "그건 어쩌면 우린 이 세상에서 너무나도 많은\n질문이 있지만, 답은 너무나도 적기 때문이겠지.",
  str_homestory_816401001_39_dialog_content = "그러니까 기도는 사실 일종의 타협이겠지.<sprite=emo_sikao size=60 />",
  str_homestory_816401001_40_dialog_content = "기도는 문제를 해결하거나 답을 주지도 않아.",
  str_homestory_816401001_41_dialog_content = "하지만 그건 네게 마음의 평안을 주고,\n네가 남은 인생에 더 힘을 쓸 수 있게 만들어.",
  str_homestory_816401001_42_dialog_content = "음... 그건 확실히 중요한 동기부여인 것 같네.",
  str_homestory_816401001_43_dialog_content = "그럼 다음에 나도 「기도」를 해볼게.",
  str_homestory_816401001_44_dialog_content = "너와 「기도」하는 소감을 함께 나눌 날을\n기대하고 있을게.",
  str_homestory_811101001_0_dialog_content = "베릴...",
  str_homestory_811101001_1_dialog_content = "......",
  str_homestory_811101001_2_dialog_content = "베릴!",
  str_homestory_811101001_3_dialog_content = "아? 무슨 일 있어?",
  str_homestory_811101001_4_dialog_content = "계속 강을 바라보고 있길래... 혹시 무슨 고민 있어?",
  str_homestory_811101001_5_dialog_content = "나 걱정하는 거야?",
  str_homestory_811101001_6_option_content = "그래.",
  str_homestory_811101001_7_dialog_content = "혹시 내가 강가에 서 있으면...\n슬픈 생각을 하는 것처럼 보이는 거야?<sprite=emo_wuzui size=60 />",
  str_homestory_811101001_8_dialog_content = "아, 그건 말이지, 베릴... 그렇게 생각하지 마.",
  str_homestory_811101001_9_dialog_content = "나도 그냥 산책하러 온 거였어. 봐, 오늘 날씨도 좋잖아, 하하...",
  str_homestory_811101001_10_dialog_content = "너 표정이 이상해.",
  str_homestory_811101001_11_option_content = "아니야.",
  str_homestory_811101001_12_dialog_content = "그냥 네가 한참 동안 강가에 서 있길래 뭘 하고 있는 건지 궁금했어.",
  str_homestory_811101001_13_dialog_content = "난 보통 산책을 하거나 낚시를 하러 여기 오거든. 가만히 서 있는 경우는 없어.",
  str_homestory_811101001_14_dialog_content = "그래서... 넌 뭐 하고 있었던 거야?",
  str_homestory_811101001_15_dialog_content = "수정이랑 헤븐즈 가든에 대해 생각하고 있었어.",
  str_homestory_811101001_16_dialog_content = "수정...",
  str_homestory_811101001_17_dialog_content = "응, 전에 바이스한테 들었어.\n넌 요즘 헤븐즈 가든 일로 고민이 많다고 말이야.",
  str_homestory_811101001_18_dialog_content = "특히 자금<sprite=emo_baiyebi size=60 /> 문제로 힘들다고 했어.\n그래서 어떻게 하면 널 부자로 만들어 줄 수 있을지\n생각해 봤어.",
  str_homestory_811101001_19_dialog_content = "그러다 보니 내 능력... 수정이 떠올랐어.",
  str_homestory_811101001_20_dialog_content = "헤븐즈 가든의 돌을 수정으로 만들고,\n움브라톤의 보석상에 파는 건 어떨까?",
  str_homestory_811101001_21_dialog_content = "그게 가능해?",
  str_homestory_811101001_22_dialog_content = "응, 잘 연마해서 보석으로 팔면 꽤 비싸다고 들었어.",
  str_homestory_811101001_23_dialog_content = "지, 진짜?!",
  str_homestory_811101001_24_dialog_content = "농담이야...",
  str_homestory_811101001_25_dialog_content = "...베릴 너도 농담하는 법을 배운 거야?!",
  str_homestory_811101001_26_dialog_content = "어쩌면 여기 온 뒤로 내가 변해서 그런 건지도 몰라.\n헤븐즈 가든은 사람들을 편안하게 만들어 주니까.",
  str_homestory_811101001_27_dialog_content = "특히 이 강의 물고기들을 보면...",
  str_homestory_811101001_28_dialog_content = "잠깐만, 베릴, 혹시 물고기 보는 게 좋으면, 희망의 연못에 가는 것도 괜찮아.",
  str_homestory_811101001_29_dialog_content = "거긴 예쁜 물고기가 꽤 많거든.",
  str_homestory_811101001_30_dialog_content = "여긴... 작은 물고기들밖에 안 보이는 것 같아.",
  str_homestory_811101001_31_dialog_content = "응, 난 저 작은 물고기들을 보려는 거야.",
  str_homestory_811101001_32_dialog_content = "특히 저들이 수초 사이를 다니거나,\n돌 곁에서 쉬는 모습 말이야.",
  str_homestory_811101001_33_dialog_content = "정말 편안해 보이고, 환경과 정말 잘 어울려.",
  str_homestory_811101001_34_dialog_content = "베릴, 넌 시력이 정말 좋네...",
  str_homestory_811101001_35_dialog_content = "수면 아래에서 빠르게 헤엄치는 작은 물고기들을 그렇게 자세하게 볼 수 있구나.",
  str_homestory_811101001_36_dialog_content = "항상 헤엄치고 있는 건 아니야.\n가끔은 강바닥에서 휴식을 취하기도 해.",
  str_homestory_811101001_37_dialog_content = "어떤 물고기는 강바닥의 바위 틈새로 들어가서\n머리만 살짝 내밀기도 하고...",
  str_homestory_811101001_38_dialog_content = "또 어떤 물고기는 수초 사이에서 헤엄치는데,\n무척... 자유로워 보여.",
  str_homestory_811101001_39_dialog_content = "베릴, 넌 물고기를 보는 게 아니라 저들이 살아가는 모습을 보는 거였구나.",
  str_homestory_811101001_40_dialog_content = "살아가는 모습?",
  str_homestory_811101001_41_dialog_content = "응, 저렇게 자유롭고 여유로운 삶의 방식 말이야.",
  str_homestory_811101001_42_dialog_content = "맞아. 다른 곳에선 이런 느낌을 받은 적이 없었어.",
  str_homestory_811101001_43_dialog_content = "헤븐즈 가든에 와서 이 강을 보고 처음 느꼈던 거야.",
  str_homestory_811101001_44_dialog_content = "이게 바로 헤븐즈 가든의 매력일까?",
  str_homestory_811101001_45_dialog_content = "매력이라기보다는 여유 아닐까...",
  str_homestory_811101001_46_dialog_content = "그래... 여유<sprite=emo_pugongying size=60 />...",
  str_homestory_816501001_0_dialog_content = "시엘...",
  str_homestory_816501001_1_dialog_content = "조종사! 혹시 일거리 좀 있어?",
  str_homestory_816501001_2_option_content = "있어.",
  str_homestory_816501001_3_dialog_content = "뭔데? 보수는 얼만데?",
  str_homestory_816501001_4_dialog_content = "근데 왠지 너한테는 안 맞을 것 같아...\n간단한 건물 세우는 일 정도라서...",
  str_homestory_816501001_5_dialog_content = "왠지 그런 사소한 일을 너한테 시키면\n뭔가 인력 낭비를 하는 느낌이잖아.",
  str_homestory_816501001_6_option_content = "없어.",
  str_homestory_816501001_7_dialog_content = "진짜 할 일이 아무것도 없어?",
  str_homestory_816501001_8_dialog_content = "일은 거의 다 츄브들이 해 주거든. 헤븐즈 가든은 원래 좀 한가한 편이야.",
  str_homestory_816501001_9_dialog_content = "그럼 산을 깎는다거나 터널을 뚫는\n그런 대형 공사도 안 하는 거야?",
  str_homestory_816501001_10_dialog_content = "보면 알겠지만 내 메카는\n그런 대형 작업 전문이거든!<sprite=emo_dianzan size=60 />",
  str_homestory_816501001_11_dialog_content = "지금은 없어. 근데 왜 안 쉬고 갑자기 일을 하고 싶어 하는 거야?",
  str_homestory_816501001_12_dialog_content = "돈이 너무 부족해서 쉴 수가 없거든.",
  str_homestory_816501001_13_dialog_content = "돈이 부족해? 일루미나는 배급제라고 들었는데,\n특별히 사고 싶은 거라도 있어?",
  str_homestory_816501001_14_dialog_content = "저번에 연구실에서 딱 한 번 본 거지만...\n계산기가 갖고 싶어.",
  str_homestory_816501001_15_dialog_content = "어차피 헤븐즈 가든에선 꽤 한가할 텐데, 직접 하나 만들어 보는 건 어때?",
  str_homestory_816501001_16_dialog_content = "비표준 규격 부품을 많이 사용한 것도 있고,\n아주 정밀해서 직접 만드는 건 무리야.",
  str_homestory_816501001_17_dialog_content = "직접 그 부품들을 다 만들려면\n시간도 엄청 오래 걸릴 테고...",
  str_homestory_816501001_18_dialog_content = "근데 제작 의뢰를 맡기려면 비용이 많이 들어.",
  str_homestory_816501001_19_dialog_content = "그런데도 자꾸 눈에 아른거리니까\n아르바이트라도 해서 돈을 모으려고 했던 거야.",
  str_homestory_816501001_20_dialog_content = "왜 그렇게까지 그 계산기를 갖고 싶어 하는 건데?",
  str_homestory_816501001_21_dialog_content = "몇 번이나 계산을 해 봐도 안 맞는 곳이 있거든.\n왠지 도면에 문제가 있는 것 같아.",
  str_homestory_816501001_22_dialog_content = "복잡한 계산은 사람 머리로는 오차가 날 수 있어.\n하지만 기계라면 절대 안 그럴 거 같거든.",
  str_homestory_816501001_23_dialog_content = "검증 작업을 하고 있었구나.",
  str_homestory_816501001_24_dialog_content = "응! 전에 이 도면으로 강화복을 하나 만든 적 있어.",
  str_homestory_816501001_25_dialog_content = "근데 내가 실수를 하는 바람에\n강화복은 망가지고 도면은 다 타버릴 뻔했었어.",
  str_homestory_816501001_26_dialog_content = "화재 현장에서 어떻게든 꺼내 오기는 했는데...",
  str_homestory_816501001_27_dialog_content = "지금 계산에 안 맞는 부분이 있는 걸 보니까,\n아무래도 그때 도면의 일부가 없어졌나 봐<sprite=emo_daomei size=60 />.",
  str_homestory_816501001_28_dialog_content = "지금 가지고 있는 도면을 따라 강화복을 만들면\n몇몇 부분의 움직임이 너무 둔해.",
  str_homestory_816501001_29_dialog_content = "근데 보통은... 도면에 빠진 부분이 있으면\n제작 자체가 안 되는 거 아냐?",
  str_homestory_816501001_30_dialog_content = "보통은 그렇지.",
  str_homestory_816501001_31_dialog_content = "그럼 일단 만들 수는 있으니까 관점을 바꿔 보면 되지 않을까?",
  str_homestory_816501001_32_dialog_content = "나도 전에 콜로서스의 배선 쪽에 문제가 생겼을 때,\n반나절을 끙끙댔는데도 못 고치고 있었거든.",
  str_homestory_816501001_33_dialog_content = "근데 파이어플라이가 와서 보고 몇 번 만지니까 바로 고쳐졌었어.",
  str_homestory_816501001_34_dialog_content = "관점을 바꾼다라...",
  str_homestory_816501001_35_dialog_content = "생각났어! 어제 그 동전<sprite=emo_baiyebi size=60 /> 같은 거구나!",
  str_homestory_816501001_36_dialog_content = "동전?",
  str_homestory_816501001_37_dialog_content = "어제 강가에서 동전을 하나 봤거든...\n아, 병뚜껑이나 쇳조각일 수도 있겠지만.",
  str_homestory_816501001_38_dialog_content = "아무튼 중요한 건 그게 수면에서\n자기 혼자 튀어 오르고 있었다는 거야!",
  str_homestory_816501001_39_dialog_content = "그때는 수면이 잔잔한 것처럼 보였지만...\n사실은 급류가 흐르고 있었던 건지도 몰라...",
  str_homestory_816501001_40_dialog_content = "아, 이제야 알겠어... 그런 거였어...\n그 공식은 설계 방향을 암시하는 거였어!",
  str_homestory_816501001_41_dialog_content = "잠깐만, 강가에서 동전을 봤단 말이야?",
  str_homestory_816501001_42_dialog_content = "응? 응, 맞아.\n그럼 난 다시 설계하러 가 볼게. 안녕!",
  str_homestory_816501001_43_dialog_content = "그, 그래...",
  str_homestory_810001001_0_dialog_content = "무슨 생각해?",
  str_homestory_810001001_1_dialog_content = "스칼렛?",
  str_homestory_810001001_2_dialog_content = "아, 흰둥이였구나.\n마침 너한테 물어보려던 게 있어.",
  str_homestory_810001001_3_dialog_content = "말해 봐.",
  str_homestory_810001001_4_dialog_content = "넌 헤븐즈 가든이라는 곳을 어떻게 생각해?",
  str_homestory_810001001_5_dialog_content = "어? 그건 평소에 내가 사람들한테 하던 질문이잖아?\n갑자기 그걸 나한테 물어보면... 생각 좀 해 볼게.",
  str_homestory_810001001_6_option_content = "(고향)",
  str_homestory_810001001_7_dialog_content = "여긴 당연히 내 고향이지.",
  str_homestory_810001001_8_option_content = "(안식처)",
  str_homestory_810001001_9_dialog_content = "아주 훌륭한 안식처라고 생각해.",
  str_homestory_810001001_10_dialog_content = "그렇구나...",
  str_homestory_810001001_11_dialog_content = "그런데 흰둥이 넌 이 헤븐즈 가든이\n새장 같다고 느껴지진 않아?",
  str_homestory_810001001_12_dialog_content = "내가 지키고 있는 밤하늘 무덤처럼...",
  str_homestory_810001001_13_dialog_content = "무슨 말인지 잘 모르겠어.",
  str_homestory_810001001_14_dialog_content = "여긴 정말 너무나도 편안해서,\n다른 생각이 하나도 안 들 정도라는 거야.",
  str_homestory_810001001_15_dialog_content = "왠지 다른 사람들도 그렇게 말했던 거 같아.",
  str_homestory_810001001_16_dialog_content = "이런 편안함은 대륙 곳곳에 전해지는\n그 속담 같다고 생각해.",
  str_homestory_810001001_17_dialog_content = "「좋은 침대야말로 가장 두려운 칼날인 법.\n그것은 수많은 영웅의 무덤이다.」",
  str_homestory_810001001_18_dialog_content = "사람이 너무 편하면 자기 책임을 잊게 돼.\n특히 눈앞밖에 못 보는 저 벌레 녀석들이라면\n더더욱 그렇겠지<sprite=emo_wuyu size=60 />.",
  str_homestory_810001001_19_dialog_content = "갑자기 왜 그런 생각이 든 건데?",
  str_homestory_810001001_20_dialog_content = "어제 강가에서 수초 한 덩어리가\n수면 위를 오르락내리락하는 걸 봤어.",
  str_homestory_810001001_21_dialog_content = "그 수초 덩이 속에 쇳조각 같은 게 들어있어서\n수초가 수면 위아래로 움직이고 있던 거였어.",
  str_homestory_810001001_22_dialog_content = "그걸 본 순간 난 아까 그 속담의 참뜻을\n이해할 수 있었던 거야.",
  str_homestory_810001001_23_dialog_content = "그런 생각이 들었다는 건, 넌 그 쇳조각이 아니라는 거잖아. 걱정하지 마.",
  str_homestory_810001001_24_dialog_content = "어쨌든 우리는 자기 의지대로, 스스로 행동할 수 있잖아. 그렇지?",
  str_homestory_810001001_25_dialog_content = "역시 내가 사람을 제대로 봤네.\n흰둥이 너는 저 벌레 녀석들이랑은 달라.",
  str_homestory_816601001_0_dialog_content = "최고야...",
  str_homestory_816601001_1_dialog_content = "피아는 오늘도 기분이 아주 좋아 보이네.",
  str_homestory_816601001_2_dialog_content = "이젠 완전히 여기 생활에 적응한 모양이구나.",
  str_homestory_816601001_3_dialog_content = "마음대로 환상동물 마스터의 마음을\n추측하지 말아 줄래!",
  str_homestory_816601001_4_dialog_content = "나 아무 얘기도 안 했는데...<sprite=emo_shengqi size=60 />",
  str_homestory_816601001_5_dialog_content = "그렇게 하는 것만 봐도 「기분이 좋다」는 티가 팍팍 나는걸.",
  str_homestory_816601001_6_dialog_content = "어?",
  str_homestory_816601001_7_dialog_content = "아니거든? 안 그러거든.",
  str_homestory_816601001_8_dialog_content = "음... 그래. 아무튼 때마침 전문가한테 물어보고 싶은 게 몇 가지 있었어.",
  str_homestory_816601001_9_dialog_content = "나한테?",
  str_homestory_816601001_10_dialog_content = "흥, 말해 봐.",
  str_homestory_816601001_11_dialog_content = "강아지<sprite=emo_goutou size=60 />들은 기분이 좋을 때 어떻게 표현해?",
  str_homestory_816601001_12_dialog_content = "그런 것도 몰라?",
  str_homestory_816601001_13_dialog_content = "강아지들은 별거 아닌 일에도\n금방 기분이 좋아져. 그리고 기분이 좋을 때는\n꼬리를 흔드니까 알아채기 쉬워.",
  str_homestory_816601001_14_dialog_content = "그럼 고양이<sprite=emo_baimao size=60 />들은 기분이 좋을 때 어떻게 표현하는데?",
  str_homestory_816601001_15_dialog_content = "그것도 엄청나게 쉬운 질문이네.",
  str_homestory_816601001_16_dialog_content = "고양이들은 경계심이 강한 편이지만,\n일단 기분을 좋게만 만들어 주면...",
  str_homestory_816601001_17_dialog_content = "자기들이 먼저 달라붙고 「골골송」까지\n불러 준다구.",
  str_homestory_816601001_18_dialog_content = "그럼 환상동물은 어때? 예를 들면 키아로는...?",
  str_homestory_816601001_19_dialog_content = "키아로도 기분이 좋을 때는 티가 난다구, 아하하.",
  str_homestory_816601001_20_dialog_content = "난 키아로가 기분이 좋은지 나쁜지는\n눈 감고도 다 알 수 있어!",
  str_homestory_816601001_21_dialog_content = "그렇구나. 아무래도 환상동물이든 일반 동물이든...",
  str_homestory_816601001_22_dialog_content = "기분이 좋을 때는 겉으로 어느 정도 표현을 하는 거구나.",
  str_homestory_816601001_23_dialog_content = "...왜 갑자기 네가 뭔가 꿍꿍이가 있어서\n이런 걸 물어봤다는 생각이 드는 거지?",
  str_homestory_816601001_24_dialog_content = "그럴 리가 없잖아.",
  str_homestory_816601001_25_dialog_content = "그냥 내가 피아를 관찰하면서 파악한 게\n맞는지 확인 좀 하고 싶어서 그런 거야.",
  str_homestory_816601001_26_dialog_content = "응...? 나?",
  str_homestory_816601001_27_dialog_content = "피아는 환상동물 마스터야.\n동물을 관찰하는 건 피아가 쭉 해오던 건데...",
  str_homestory_816601001_28_dialog_content = "왜, 왜 네가 피아를 관찰한 거야?",
  str_homestory_816601001_29_dialog_content = "그건 아마...",
  str_homestory_816601001_30_option_content = "(호기심이 생겨서)",
  str_homestory_816601001_31_dialog_content = "피아는 나보다 감정이 풍부하니까 호기심이 생겼거든.",
  str_homestory_816601001_32_option_content = "(심심해서)",
  str_homestory_816601001_33_dialog_content = "피아는 재미있는 아이니까 많이 관찰하고 싶었어.",
  str_homestory_816601001_34_dialog_content = "아무튼 내가 관찰해 본 결과...",
  str_homestory_816601001_35_dialog_content = "피아가 기분이 좋을 때는, 토끼 귀가 쫑긋 서.",
  str_homestory_816601001_36_dialog_content = "으아아아<sprite=emo_hanshui size=60 />... 내, 내 귀 쳐다보지 마!",
  str_homestory_816601001_37_dialog_content = "......",
  str_homestory_816601001_38_dialog_content = "잠깐!",
  str_homestory_816601001_39_dialog_content = "내 토끼 귀는 머리핀이라서 항상 서 있는\n모양일 텐데?",
  str_homestory_816601001_40_dialog_content = "아까 피아가 귀를 감쌌다는 건, 기뻤다는 걸 인정했다는 거지?",
  str_homestory_816601001_41_dialog_content = "짜증 나! 날 놀렸어! PlayerName!",
  str_homestory_816601001_42_dialog_content = "알겠어, 알겠어. 미안해!",
  str_homestory_816601001_43_dialog_content = "사과의 의미로... 같이 미끄럼틀 타러 가 줄게. 어때?",
  str_homestory_816601001_44_dialog_content = "...그 정도면 봐줄게.",
  str_homestory_816701001_0_dialog_content = "...잠들었나?",
  str_homestory_816701001_1_dialog_content = "아주 좋은 질문이군요.",
  str_homestory_816701001_2_dialog_content = "만약 바람이 이 세상의 호흡이라면...",
  str_homestory_816701001_3_dialog_content = "아마 이 세상은 매 순간 단잠에\n빠져 있는 것일지도 모르겠네요<sprite=emo_kun size=60 />.",
  str_homestory_816701001_4_dialog_content = "어? 깨어 있었구나?",
  str_homestory_816701001_5_dialog_content = "난 네가 의자에 누워 있길래 잠든 줄 알았어.",
  str_homestory_816701001_6_dialog_content = "바다는 한 번도 눈 뜬 적 없는 폭군과도 같습니다...",
  str_homestory_816701001_7_dialog_content = "운 좋게 바다에서 미친 듯이 울부짖는\n바람에 머리끝을 베여 본 적이 있다면...",
  str_homestory_816701001_8_dialog_content = "제노?",
  str_homestory_816701001_9_dialog_content = "친애하는 관객님, 왜 그러십니까?",
  str_homestory_816701001_10_dialog_content = "방금 한 말이 무슨 뜻인지 잘 못 알아듣겠어.",
  str_homestory_816701001_11_dialog_content = "아니, 하나도 못 알아듣겠어.",
  str_homestory_816701001_12_dialog_content = "언어는 발화한 순간, 그냥 목소리가 아니게 됩니다.",
  str_homestory_816701001_13_dialog_content = "단어는 귀에 전달되는 순간,\n대뇌에 의해 저 자신이 원하는 모습으로\n이해되지요.",
  str_homestory_816701001_14_dialog_content = "이 세계는 가장 성대한 환상 카니발인 것입니다.",
  str_homestory_816701001_15_dialog_content = "저는 언제나 그렇다고 생각해 왔습니다.",
  str_homestory_816701001_16_option_content = "(무슨 말인지 모르겠다)",
  str_homestory_816701001_17_dialog_content = "너무 심오해서... 제노 네가 뭐라고 하는 건지 이해가 정말 안 돼.",
  str_homestory_816701001_18_option_content = "(무슨 말인지 이해했다)",
  str_homestory_816701001_19_dialog_content = "난 이 세상에서 서로를 진정으로 이해한다는 건\n영원히 불가능한 일이라고 생각해.",
  str_homestory_816701001_20_dialog_content = "친애하는 관객님.",
  str_homestory_816701001_21_dialog_content = "서로를 진정으로 이해한다는 건\n전혀 중요하지 않습니다.\n즐거움을 느끼기만 하면 되는 것이지요.",
  str_homestory_816701001_22_dialog_content = "크흠, 아무튼 내 생각엔...",
  str_homestory_816701001_23_dialog_content = "솔직히 너도 자기가 무슨 말을 하는 건지 잘 모르겠지?",
  str_homestory_816701001_24_dialog_content = "아마도요. 확실히 가끔은 제가 제대로 표현을\n못 할 때도 있습니다.",
  str_homestory_816701001_25_dialog_content = "하지만 제 마술은 절대로 상대를\n실망시키지 않습니다<sprite=emo_mojing size=60 />.",
  str_homestory_816701001_26_dialog_content = "음... 그건 그렇네.",
  str_homestory_816701001_27_dialog_content = "아, 잠깐만!",
  str_homestory_816701001_28_dialog_content = "지금 나한테 마술로 환상을 만들어서 보여 주고 있는 거지?",
  str_homestory_816701001_29_dialog_content = "실제로는 의자에 누워서 자고 있는 거지? 그렇지?!",
  str_homestory_816701001_30_dialog_content = "이런, 들켜 버렸군요.",
  str_homestory_816701001_31_dialog_content = "역시 그런 거야?!",
  str_homestory_816701001_32_dialog_content = "서두르지 마세요. 아직 할 이야기가 남았습니다.",
  str_homestory_816701001_33_dialog_content = "당신은 누군가 여기에서 자고 있다는 사실\n하나만 맞히셨으니까요.",
  str_homestory_816701001_34_dialog_content = "하지만...",
  str_homestory_816701001_35_dialog_content = "그 누군가가 당신이 아니라는 건 어떻게 확신하죠?",
  str_homestory_816701001_36_dialog_content = "난 당연히 아니야!",
  str_homestory_816701001_37_dialog_content = "왜냐하면 아까 저 멀리서 네가 의자에 누워서 자는 모습을 똑똑히 봤는걸.",
  str_homestory_816701001_38_dialog_content = "그럼 그전에는 뭘 했는지 기억이 나십니까?",
  str_homestory_816701001_39_dialog_content = "아까는...",
  str_homestory_816701001_40_dialog_content = "어? 아까 내가 뭘 하고 있었지?",
  str_homestory_816701001_41_dialog_content = "하하하.",
  str_homestory_816701001_42_dialog_content = "설마... 나도 모르게 네 최면에 걸린 거란 말이야?",
  str_homestory_816701001_43_dialog_content = "나 좀 깨줘 주면 안 될까...<sprite=emo_tanqi size=60 />?",
  str_homestory_816701001_44_dialog_content = "간단합니다.\n의자에 누워 잠을 자면 최면에서 깨어날 겁니다.",
  str_homestory_816701001_45_dialog_content = "알겠어...",
  str_homestory_816801001_0_dialog_content = "뭐 하고 있어?",
  str_homestory_816801001_1_dialog_content = "PlayerName, 안녕!",
  str_homestory_816801001_2_dialog_content = "여길 꽤 멋지게 꾸며 놨는걸.\n특히 저쪽에 있는 저건...",
  str_homestory_816801001_3_dialog_content = "쓱싹쓱싹 만지면 서로 다른 소리<sprite=emo_yinfu size=60 />가 나!",
  str_homestory_816801001_4_dialog_content = "정말? 마음에 든다니 다행이네...",
  str_homestory_816801001_5_dialog_content = "자리만 차지하는 게 아닐까 싶었거든.",
  str_homestory_816801001_6_dialog_content = "다들 싫어할까 봐 걱정했었어.",
  str_homestory_816801001_7_dialog_content = "마음에 들어!",
  str_homestory_816801001_8_dialog_content = "진짜 마음에 들어!",
  str_homestory_816801001_9_dialog_content = "PlayerName, 어떻게 사용하면 되는 건지\n알려 줄래?",
  str_homestory_816801001_10_dialog_content = "사실 나도 잘은 몰라.",
  str_homestory_816801001_11_dialog_content = "그럼 설명서 같은 거 없어?",
  str_homestory_816801001_12_dialog_content = "으... 없었던 거 같아...",
  str_homestory_816801001_13_dialog_content = "혼자서 터득하는 수밖에 없겠네.",
  str_homestory_816801001_14_dialog_content = "스스로 기계의 사용법을 탐구해 보면\n훨씬 재미있을 테니까!",
  str_homestory_816801001_15_dialog_content = "레인보우가 이렇게 음악을 좋아하는 줄 몰랐어.",
  str_homestory_816801001_16_dialog_content = "아름다운 걸 싫어하는 사람이 어디 있겠어.\n게다가...",
  str_homestory_816801001_17_dialog_content = "이 기계의 사용법을 완벽히 마스터한 다음에\n공연할 때 사용하면...",
  str_homestory_816801001_18_dialog_content = "더 많은 사람이 서커스의 오프닝 무대를\n즐길 수 있을 거야!",
  str_homestory_816801001_19_dialog_content = "레인보우는 어딜 가든 서커스 생각을 하는구나.",
  str_homestory_816801001_20_dialog_content = "네 직업을 진심으로 좋아하는 거지?",
  str_homestory_816801001_21_dialog_content = "음... 사실 그런 문제는 지금까지 한 번도\n생각해 본 적 없었어<sprite=emo_wuzui size=60 />.",
  str_homestory_816801001_22_dialog_content = "그냥 태어났을 때부터 내가 에메랄드호의\n수호자로 정해져 있던 것 같은 느낌이야.",
  str_homestory_816801001_23_dialog_content = "선박이랑 기계를 수리하고\n유지, 보수하는 일은 에메랄드호를\n지키는 방법 중 하나거든.",
  str_homestory_816801001_24_dialog_content = "배에 올라타서 나쁜 짓을 하려는\n사람들을 워터건으로 저지하는 것도\n에메랄드호를 지키는 방법 중 하나야.",
  str_homestory_816801001_25_dialog_content = "서커스에서 공연을 하고,\n더 많은 사람들한테 에메랄드호를 선보여서\n그 사람들이 좋아하고 즐기게 만드는 것도...",
  str_homestory_816801001_26_dialog_content = "에메랄드호를 지키는 방법 중 하나인 거지.",
  str_homestory_816801001_27_dialog_content = "그랬구나...",
  str_homestory_816801001_28_dialog_content = "뭔가를 「지킨다」는 방법은 여러 가지가 있는 거였네.",
  str_homestory_816801001_29_dialog_content = "PlayerName, 넌 헤븐즈 가든을\n잘 지켜내고 있는걸.",
  str_homestory_816801001_30_dialog_content = "아... 그래도 수로 청소는 좀 자주 하는 게 좋겠어.",
  str_homestory_816801001_31_dialog_content = "아까 워터건에 물을 보충하려고\n강가에 갔었는데...",
  str_homestory_816801001_32_dialog_content = "강바닥에 반짝거리는 물체들이 있더라구.",
  str_homestory_816801001_33_dialog_content = "반짝거리는 물체들...?",
  str_homestory_816801001_34_dialog_content = "말이 나와서 그런데, 좀 시원하게 해 줄까?",
  str_homestory_816801001_35_option_content = "좋아!",
  str_homestory_816801001_36_dialog_content = "반나절 동안 바쁘게 일했더니 지금 좀 덥네.",
  str_homestory_816801001_37_dialog_content = "얼마든지!",
  str_homestory_816801001_38_dialog_content = "자, 시작할게~",
  str_homestory_816801001_39_dialog_content = "뭐?!",
  str_homestory_816801001_40_option_content = "싫어!",
  str_homestory_816801001_41_dialog_content = "서, 설마 물총으로 물 뿌리려는 건 아니지?",
  str_homestory_816801001_42_dialog_content = "헤헤헤, 그게 아니면 뭐겠어?",
  str_homestory_816801001_43_dialog_content = "진짜 안 그래도 돼.",
  str_homestory_816801001_44_dialog_content = "강가에 가서 바람<sprite=emo_pugongying size=60 />이나 쐴게!",
  str_homestory_801602001_0_dialog_content = "카프카?",
  str_homestory_801602001_1_dialog_content = "앗!",
  str_homestory_801602001_2_dialog_content = "PlayerName 너였구나, 깜짝 놀랐잖아.",
  str_homestory_801602001_3_dialog_content = "놀라게 해서 미안...",
  str_homestory_801602001_4_dialog_content = "무슨 일 있어?",
  str_homestory_801602001_5_option_content = "응.",
  str_homestory_801602001_6_dialog_content = "그냥 여기 오래 서 있길래...",
  str_homestory_801602001_7_dialog_content = "더위 먹을까 봐 걱정했어.",
  str_homestory_801602001_8_dialog_content = "걱정하지 마, 그냥 감시 중이었거든.",
  str_homestory_801602001_9_option_content = "아니.",
  str_homestory_801602001_10_dialog_content = "그냥 여기 오래 서 있길래...",
  str_homestory_801602001_11_dialog_content = "뭐 하는 걸까 궁금해졌거든.",
  str_homestory_801602001_12_dialog_content = "딱 보면 알 수 있잖아. 감시 중이지.",
  str_homestory_801602001_13_dialog_content = "감시?",
  str_homestory_801602001_14_dialog_content = "마음은 정말 고마운데, 헤븐즈 가든은 정말 안전해, 카프카...",
  str_homestory_801602001_15_dialog_content = "그렇게 경계하지 않아도 돼.",
  str_homestory_801602001_16_dialog_content = "헤븐즈 가든을 위해서가 아니라...",
  str_homestory_801602001_17_dialog_content = "토끼들을 위해서 감시를 하고 있던 거야.",
  str_homestory_801602001_18_dialog_content = "토끼들? 토끼들이 어디 있어?",
  str_homestory_801602001_19_dialog_content = "다 굴로 돌아가라고 했어.",
  str_homestory_801602001_20_dialog_content = "안심해도 돼. 앞으로 넌 영원히 그 토끼들을\n찾을 수 없을 테니까.",
  str_homestory_801602001_21_dialog_content = "나까지 잠재적 악당으로 생각하는 거네...",
  str_homestory_801602001_22_dialog_content = "그나저나 카프카는 작은 동물들을 정말 좋아하는구나.",
  str_homestory_801602001_23_dialog_content = "크, 크흠. 내, 내가 그랬나?",
  str_homestory_801602001_24_dialog_content = "난 그냥 그 조그만 녀석들이\n들어가지 않아야 할 곳에 들어가는 게\n보기 싫은 것뿐이야.",
  str_homestory_801602001_25_dialog_content = "갑자기 카프카가 좀 양치기 같다는 생각이 들었어.",
  str_homestory_801602001_26_dialog_content = "커다란 개<sprite=emo_goutou size=60 />를 한 마리 데리고\n동물들을 안전한 곳으로 안내해 주잖아...",
  str_homestory_801602001_27_dialog_content = "양치기는 무슨, 그건 내 알 바 아니야.",
  str_homestory_801602001_28_dialog_content = "아, 참. 아까 강가에서 반짝이는 물체를 하나 봤어.",
  str_homestory_801602001_29_dialog_content = "가서 그게 뭔지 확인해 줄래?",
  str_homestory_801602001_30_dialog_content = "그거 때문에 이 근처의 작은 동물들이\n놀라지 않도록 말이야.",
  str_homestory_801602001_31_dialog_content = "알겠어!",
  str_homestory_817001001_0_dialog_content = "신기하네...",
  str_homestory_817001001_1_dialog_content = "누구냐?!",
  str_homestory_817001001_2_dialog_content = "저예요, PlayerName...",
  str_homestory_817001001_3_dialog_content = "어머, 미안. 갑자기 근처에서 발소리가 멈추면\n매번 경계하게 되거든.",
  str_homestory_817001001_4_dialog_content = "안심해요, 헤븐즈 가든은 안전하니까요.",
  str_homestory_817001001_5_dialog_content = "응, 오래전부터 소문은 들었어.",
  str_homestory_817001001_6_dialog_content = "혜성처럼 나타난 아이테르가 헤븐즈 밸리에\n낙원을 재건하고 있다고 말이야.",
  str_homestory_817001001_7_dialog_content = "이 눈으로 직접 안 봤다면,\n그 말을 절대 믿지 못했을 거야.",
  str_homestory_817001001_8_dialog_content = "너처럼 어린 나이에 이만한 관리 능력이\n있다니 정말 의외네.",
  str_homestory_817001001_9_option_content = "(인정한다)",
  str_homestory_817001001_10_dialog_content = "헤헤, 칭찬해줘서 고마워요.",
  str_homestory_817001001_11_dialog_content = "겸손하진 않구나.",
  str_homestory_817001001_12_dialog_content = "하지만 풋내기의 용기도 난 오히려 마음에 들어.",
  str_homestory_817001001_13_option_content = "(부정한다)",
  str_homestory_817001001_14_dialog_content = "사실 친구들도 많이 도와줬어요.",
  str_homestory_817001001_15_dialog_content = "어머, 그래?",
  str_homestory_817001001_16_dialog_content = "너처럼 겸손한 아이는 요즘 정말 드문데 말이야.",
  str_homestory_817001001_17_dialog_content = "헤븐즈 가든이 오랫동안 이런 고요함을\n유지할 수 있는 것도 이해가 가네.",
  str_homestory_817001001_18_dialog_content = "암귀에게 습격당하는 일도,\n암흑가의 조직이 판치는 일도 없어.",
  str_homestory_817001001_19_dialog_content = "생각해보면 이런 식으로 느긋하게,\n햇살이 눈꺼풀에 떨어지는 걸 즐기는 날도...",
  str_homestory_817001001_20_dialog_content = "정말 오래전 일 같네.",
  str_homestory_817001001_21_dialog_content = "그럼 폴룩스 씨도 긴장을 풀고 쉬어요.",
  str_homestory_817001001_22_dialog_content = "긴장을 풀라고?",
  str_homestory_817001001_23_dialog_content = "왠지 처음으로 깨달은 것 같아...",
  str_homestory_817001001_24_dialog_content = "경계심을 유지하는 것은 내게 이미 호흡처럼\n당연한 일이 되어 있었다고 말이야.",
  str_homestory_817001001_25_dialog_content = "이미 유포리아를 떠나긴 했지만...",
  str_homestory_817001001_26_dialog_content = "그곳에서 기른 습관을 몸이 아직 기억하고 있어.",
  str_homestory_817001001_27_dialog_content = "그럼 전망대에서 주변 사람이나 사물을 바라보는 것도...",
  str_homestory_817001001_28_dialog_content = "유포리아에서의 습관인가요?",
  str_homestory_817001001_29_dialog_content = "어머, 손님의 일거수일투족을 관찰하는 것도\n호스트의 예의인 걸까?",
  str_homestory_817001001_30_dialog_content = "훗, 너도 꽤 만만치 않은 사람이었구나.",
  str_homestory_817001001_31_dialog_content = "아... 오해하지 마세요.",
  str_homestory_817001001_32_dialog_content = "우연히 지나가다가 전망대에 있는 걸 봤을 뿐이에요.",
  str_homestory_817001001_33_dialog_content = "후훗, 너무 긴장하지 마.\n나도 룰을 지키지 않는 손님은 아니니까.",
  str_homestory_817001001_34_dialog_content = "난 높은 곳에 서서, 유포리아에서 일어나는\n모든 일들을 바라보는 걸 좋아했어.",
  str_homestory_817001001_35_dialog_content = "그럼 볼 수 있거든...",
  str_homestory_817001001_36_dialog_content = "무겁고 더운 비구름 아래에서,\n갖가지 욕망이 거침없이 펼쳐지는 모습이.",
  str_homestory_817001001_37_dialog_content = "하지만 여긴 아니야.",
  str_homestory_817001001_38_dialog_content = "고요함과 잔잔함이 시선이 닿는 곳까지\n멀리 펼쳐져 있어.",
  str_homestory_817001001_39_dialog_content = "PlayerName, 부탁이 있어.",
  str_homestory_817001001_40_dialog_content = "그렇게 정중하게 부탁할 거 없어요. 뭐든지 말하세요.",
  str_homestory_817001001_41_dialog_content = "다음엔 교회의 아이들도 데리고 와도 될까?",
  str_homestory_817001001_42_dialog_content = "물론이죠!",
  str_homestory_817001001_43_dialog_content = "아, 맞다...",
  str_homestory_817001001_44_dialog_content = "아까 강에서 뭔가를 발견했는데,\n너라면 관심이 있을지도 모르겠네.",
  str_homestory_817001001_45_dialog_content = "지금 가서 찾아보면 발견할 수 있을 거야.",
  str_homestory_817001001_46_dialog_content = "네? 그, 그럼 지금 바로 가 볼게요!",
  str_homestory_817101001_0_dialog_content = "카스타?",
  str_homestory_817101001_1_dialog_content = "아, 너였구나.",
  str_homestory_817101001_2_dialog_content = "헤븐즈 가든 생활에는 좀 익숙해졌어?",
  str_homestory_817101001_3_dialog_content = "익숙하지 않아.",
  str_homestory_817101001_4_dialog_content = "응? 마음에 안 드는 점이라도 있어?",
  str_homestory_817101001_5_dialog_content = "내가 확실하게 개선해 줄게!",
  str_homestory_817101001_6_dialog_content = "여긴...",
  str_homestory_817101001_7_dialog_content = "걷히지 않는 짙은 안개가 없어.",
  str_homestory_817101001_8_dialog_content = "햇빛 때문에 눈이 건조해.",
  str_homestory_817101001_9_dialog_content = "시비를 거는 녀석들도 없어.",
  str_homestory_817101001_10_dialog_content = "평화가 내 손발에서 기운을 뺏어가는 것 같아.",
  str_homestory_817101001_11_dialog_content = "이대로 있다간 사격 솜씨가 나빠질 거야<sprite=emo_daomei size=60 />.",
  str_homestory_817101001_12_option_content = "(사과한다)",
  str_homestory_817101001_13_dialog_content = "미, 미안!",
  str_homestory_817101001_14_dialog_content = "헤븐즈 가든에서의 생활이 너무 지루한 거야?",
  str_homestory_817101001_15_option_content = "(어쩔 줄 몰라 한다)",
  str_homestory_817101001_16_dialog_content = "하지만...",
  str_homestory_817101001_17_dialog_content = "여길 다시 만들 순 없는데...",
  str_homestory_817101001_18_dialog_content = "모르겠어? 지금 내가 너 칭찬하는 거잖아.",
  str_homestory_817101001_19_dialog_content = "뭐?",
  str_homestory_817101001_20_dialog_content = "그냥 내가 시궁창 같은 생활에 익숙해서\n그랬을 뿐이야.",
  str_homestory_817101001_21_dialog_content = "그래서 이런 느긋한 곳은 오히려 익숙하지 않아.",
  str_homestory_817101001_22_dialog_content = "정말 우스운 얘기지.",
  str_homestory_817101001_23_dialog_content = "사실 헤븐즈 가든에서도 여러 가지 재미있는 걸 즐길 수 있어!",
  str_homestory_817101001_24_dialog_content = "응, 나도 방금 알았어.",
  str_homestory_817101001_25_dialog_content = "이 간판 재밌네. 이런 색상과 무늬를 쓴 걸 보면...",
  str_homestory_817101001_26_dialog_content = "카지노 광고가 분명해!",
  str_homestory_817101001_27_dialog_content = "......",
  str_homestory_817101001_28_dialog_content = "왜 그런 표정을 짓는 건데<sprite=emo_baiyan size=60 />?",
  str_homestory_817101001_29_dialog_content = "난 그저 돈을 따서 교회의 아이들한테 선물을\n갖다주고 싶을 뿐이야...",
  str_homestory_817101001_30_dialog_content = "네 헤븐즈 가든을 완전히 털어갈 생각은 없어.",
  str_homestory_817101001_31_dialog_content = "이, 이건 사실 그냥 장식이야.",
  str_homestory_817101001_32_dialog_content = "헤븐즈 가든에는 카지노가 없어...",
  str_homestory_817101001_33_dialog_content = "하아?",
  str_homestory_817101001_34_dialog_content = "그것보단 카스타 너도 낚시를 해 봐!",
  str_homestory_817101001_35_dialog_content = "낚시?",
  str_homestory_817101001_36_dialog_content = "낚싯바늘을 떨어뜨리고 물고기가 걸릴 때까지 차분하게 기다리는 거야.",
  str_homestory_817101001_37_dialog_content = "물고기 낚시도 운을 시험할 수 있어!",
  str_homestory_817101001_38_dialog_content = "운을 시험하는 거라면 내가 절대 놓칠 순 없잖아?",
  str_homestory_817101001_39_dialog_content = "아, 잊을 뻔했네...",
  str_homestory_817101001_40_dialog_content = "카스타는 「행운의 여신의 총애를 받는 자」였지, 참<sprite=emo_dianzan size=60 />!",
  str_homestory_817101001_41_dialog_content = "물고기들... 오늘 큰일이네...",
  str_homestory_813001001_0_dialog_content = "예쁘죠?",
  str_homestory_813001001_1_dialog_content = "흐음?",
  str_homestory_813001001_2_dialog_content = "콜록콜록...",
  str_homestory_813001001_3_dialog_content = "PlayerName... 그대인가.",
  str_homestory_813001001_4_dialog_content = "다음에 인사할 때는 목소리를 낮춰라.\n그런 식으로는 상대를 놀라게 만들 수 있다.",
  str_homestory_813001001_5_dialog_content = "난 분명히 충고했다.",
  str_homestory_813001001_6_dialog_content = "만약 누군가를 놀라게 해서,\n심장 발작이라도 일으킨다면...",
  str_homestory_813001001_7_dialog_content = "종신 금고형에 처할 수 있다!",
  str_homestory_813001001_8_dialog_content = "추, 충고 고마워요...",
  str_homestory_813001001_9_dialog_content = "음, 알면 됐다.\n그래, 내게는 무슨 볼일이지?",
  str_homestory_813001001_10_dialog_content = "헤븐즈 가든에 나의 심판이 필요한\n사건이라도 있는가?",
  str_homestory_813001001_11_dialog_content = "아... 어, 없어요.",
  str_homestory_813001001_12_dialog_content = "그냥 재판관 씨가 조각상 앞에서 뭔가 생각하는 것 같아 보여서요...\n게다가 이리저리 손짓도 하고...",
  str_homestory_813001001_13_dialog_content = "그래서 그냥 좀 궁금했을 뿐이에요.",
  str_homestory_813001001_14_dialog_content = "내, 내가 언제 손짓을 했다는 거냐?!",
  str_homestory_813001001_15_dialog_content = "이 바른 세상에서 근거 없는 모략은\n결코 용납할 수 없다.",
  str_homestory_813001001_16_dialog_content = "《백야성 명예법》 규정에 따라\n근거 없는 중상을 저지른 자는...",
  str_homestory_813001001_17_dialog_content = "100일간의 금고형 또는 100만 나이티움의\n벌금형에 처한다.",
  str_homestory_813001001_18_dialog_content = "하아?",
  str_homestory_813001001_19_option_content = "(반박한다)",
  str_homestory_813001001_20_dialog_content = "근데 여긴 헤븐즈 가든이고 백야성이 아닌데요?",
  str_homestory_813001001_21_dialog_content = "아, 아아아아아니, 어떻게 그런 말을!",
  str_homestory_813001001_22_dialog_content = "헤븐즈 가든에 법률이 존재하지 않음을\n그리 쉽게 인정할 수 있단 말인가!",
  str_homestory_813001001_23_option_content = "(장단을 맞춰준다)",
  str_homestory_813001001_24_dialog_content = "아, 그럼 제가 잘못 본 것 같네요...",
  str_homestory_813001001_25_dialog_content = "PlayerName, 아무래도 그대는 소양을\n조금 더 길러야 할 것 같다.",
  str_homestory_813001001_26_dialog_content = "그렇지 않으면 무엇을 봐도 더럽게 보일 것이다.",
  str_homestory_813001001_27_dialog_content = "그런 상태가 계속되면 헤븐즈 가든도 끝장이다!",
  str_homestory_813001001_28_dialog_content = "음...",
  str_homestory_813001001_29_dialog_content = "아니면...",
  str_homestory_813001001_30_dialog_content = "이렇게 하는 게 어떻겠나!\n이 조각상을 내게 주거라.",
  str_homestory_813001001_31_dialog_content = "그렇다면 우리 사이의 문제도 이걸로\n청산할 수 있을 것이다.",
  str_homestory_813001001_32_dialog_content = "네? 근데...",
  str_homestory_813001001_33_dialog_content = "이 조각상은 저한테 중요한 물건인데요.",
  str_homestory_813001001_34_dialog_content = "이건 어느 아이테르 선조의 모습을 새긴 거예요.\n저한테 굉장히 중요한 의미가 있는 거라구요.",
  str_homestory_813001001_35_dialog_content = "무법지대는 역시 이치가 통하지 않는군.",
  str_homestory_813001001_36_dialog_content = "재판관 씨가 이 조각상이 정말 마음에 든다면...",
  str_homestory_813001001_37_dialog_content = "제가 흙으로 새로 하나 만들어 줄게요.",
  str_homestory_813001001_38_dialog_content = "음...",
  str_homestory_813001001_39_dialog_content = "그것도 안 되는 건 아니다만<sprite=emo_woshou size=60 />.",
  str_homestory_813001001_40_dialog_content = "대신 날 너무 오래 기다리게 만들지 마라.",
  str_homestory_812101001_0_dialog_content = "파로마?",
  str_homestory_812101001_1_dialog_content = "어머, 당신이었구나.",
  str_homestory_812101001_2_dialog_content = "미안...",
  str_homestory_812101001_3_dialog_content = "내가 자는 데 방해됐어?",
  str_homestory_812101001_4_dialog_content = "알잖아, 나랑 얘기할 땐 그런\n허울뿐인 관심은 필요 없다는 거.",
  str_homestory_812101001_5_dialog_content = "확실히 말해줘.",
  str_homestory_812101001_6_dialog_content = "내가 헤븐즈 가든에 만족하는지 묻고 싶은 거지?",
  str_homestory_812101001_7_option_content = "(부정한다)",
  str_homestory_812101001_8_dialog_content = "그런 거 아니야...",
  str_homestory_812101001_9_dialog_content = "그냥 인사하고 싶었을 뿐이야.",
  str_homestory_812101001_10_option_content = "(인정한다)",
  str_homestory_812101001_11_dialog_content = "눈치채버렸네...",
  str_homestory_812101001_12_dialog_content = "파로마의 평가가 궁금했거든.",
  str_homestory_812101001_13_dialog_content = "사실 당신이 인정하든 말든 난 할 말은 할 거야.",
  str_homestory_812101001_14_dialog_content = "......",
  str_homestory_812101001_15_dialog_content = "난 여기가 싫지 않아.",
  str_homestory_812101001_16_dialog_content = "그럼 다행이네!",
  str_homestory_812101001_17_dialog_content = "파로마에게 또 무슨 비판이라도 받을 줄 알았거든...",
  str_homestory_812101001_18_dialog_content = "음? 뭐라고?",
  str_homestory_812101001_19_dialog_content = "아, 내 말은 그러니까...",
  str_homestory_812101001_20_dialog_content = "파로마한테 뭔가 건설적인 의견을 들을 수 있지 않을까 기대했거든!",
  str_homestory_812101001_21_dialog_content = "의견? 없는 건 아니야.",
  str_homestory_812101001_22_dialog_content = "당신이 이렇게 개발이나 건설, 관리를 잘한다면...",
  str_homestory_812101001_23_dialog_content = "백야성의 귀족들을 몰아내고,\n아주라이트를 접수할 생각은 없어?",
  str_homestory_812101001_24_dialog_content = "뭐?!",
  str_homestory_812101001_25_dialog_content = "그런 거 난 생각해 본 적도 없어.",
  str_homestory_812101001_26_dialog_content = "입으로는 그럴 생각이 없다면서,\n뒤에서는 슬금슬금 손을 뻗는 녀석들을...",
  str_homestory_812101001_27_dialog_content = "난 수도 없이 봐왔어.",
  str_homestory_812101001_28_dialog_content = "난... 그저 내 집을 지키고 싶을 뿐이야.",
  str_homestory_812101001_29_dialog_content = "백야성 사람들도 분명히 나처럼 자기 집을 지키고 싶다고 생각할 거잖아?",
  str_homestory_812101001_30_dialog_content = "집?",
  str_homestory_812101001_31_dialog_content = "내가 바로 그 집에서 쫓겨난 사람이잖아.",
  str_homestory_812101001_32_dialog_content = "내게 있어서 「집」은 이미 오래전에\n아무 의미도 없는 공허한 단어가 돼버렸어.",
  str_homestory_812101001_33_dialog_content = "파로마... 잊지 마. 너한테는 헤븐즈 가든이 있잖아.",
  str_homestory_812101001_34_dialog_content = "너만 괜찮다면...",
  str_homestory_812101001_35_dialog_content = "헤븐즈 가든을 자기 집이라고 생각해도 돼!",
  str_homestory_812101001_36_dialog_content = "어머? 남한테 영지를 뺏긴다는 느낌은 안 들어?",
  str_homestory_812101001_37_dialog_content = "오늘의 헤븐즈 가든의 있는 건 모두의 도움 덕분이야...",
  str_homestory_812101001_38_dialog_content = "그러니까 난 헤븐즈 가든이 모두에게 피난처가 될 수 있었으면 좋겠어.",
  str_homestory_812101001_39_dialog_content = "아이테르, 역시 당신은 정말 명성 그대로\n「바보」구나.<sprite=emo_baiyan size=60 />",
  str_homestory_812101001_40_dialog_content = "어쩌면...",
  str_homestory_812101001_41_dialog_content = "내 사전 속 「집」이라는 단어의 뜻을\n하나 추가해볼 수도 있을 것 같아.",
  str_homestory_812101001_42_dialog_content = "어떤 뜻인데?",
  str_homestory_812101001_43_dialog_content = "...헤븐즈 가든.",
  str_homestory_812001001_0_dialog_content = "헤이디, 여기 있었구나.",
  str_homestory_812001001_1_dialog_content = "아...",
  str_homestory_812001001_2_dialog_content = "헤이디, 왜 그래?",
  str_homestory_812001001_3_dialog_content = "만물은 백야 아래에...",
  str_homestory_812001001_4_dialog_content = "이 기계가 절 보고는 계속해서 악의가 담긴\n신음을 내지르고 있어요!",
  str_homestory_812001001_5_dialog_content = "PlayerName 씨, 어서 말해주세요.\n이건 설마 사악한 구시대의 산물인가요?",
  str_homestory_812001001_6_dialog_content = "이대로라면...",
  str_homestory_812001001_7_dialog_content = "「빛의 기사」를 소환해서 파괴할 수밖에 없어요<sprite=emo_shengqi size=60 />.",
  str_homestory_812001001_8_option_content = "(위로한다)",
  str_homestory_812001001_9_dialog_content = "헤이디, 걱정할 거 없어.",
  str_homestory_812001001_10_dialog_content = "이건 그냥 자동 아이스크림 기계일 뿐이야.",
  str_homestory_812001001_11_option_content = "(사과한다)",
  str_homestory_812001001_12_dialog_content = "미안, 미리 말해두는 걸 깜빡했네.",
  str_homestory_812001001_13_dialog_content = "이건 자동 아이스크림 기계야!",
  str_homestory_812001001_14_dialog_content = "자동... 아이스크림 기계요?<sprite=emo_wuzui size=60 />",
  str_homestory_812001001_15_dialog_content = "응, 컵을 놓고 버튼을 누르면...",
  str_homestory_812001001_16_dialog_content = "기계가 자동으로 맛있는 아이스크림을 만드는 거야.",
  str_homestory_812001001_17_dialog_content = "사, 사실 기계에 그려져 있는 눈꽃 무늬를 보고...\n아이스크림 기계라고 추측은 했어요.",
  str_homestory_812001001_18_dialog_content = "그런데 아이스크림이 전혀 나오지 않아서...",
  str_homestory_812001001_19_dialog_content = "아이스크림 기계로 가장한 사악한 과학기술의\n산물이 아닐까 하는 의심을 했던 거예요.",
  str_homestory_812001001_20_dialog_content = "어라? 또 아이스크림이 떨어졌나...?",
  str_homestory_812001001_21_dialog_content = "떨어졌다니요?",
  str_homestory_812001001_22_dialog_content = "이 기계로 만든 아이스크림이 너무 맛있어서...",
  str_homestory_812001001_23_dialog_content = "일찍 와서 줄을 안 서면 먹을 수가 없거든.",
  str_homestory_812001001_24_dialog_content = "요 며칠 날씨가 좀 시원해졌으니까,\n아이스크림 먹는 사람도 좀 줄지 않았을까 싶었는데.",
  str_homestory_812001001_25_dialog_content = "아직도 이렇게 인기가 있을 줄은 몰랐네.",
  str_homestory_812001001_26_dialog_content = "헤이디는 무슨 맛이 좋아?",
  str_homestory_812001001_27_dialog_content = "내가 가서 재료 좀 더 사 올게.",
  str_homestory_812001001_28_dialog_content = "아이스크림의 맛이라면...",
  str_homestory_812001001_29_dialog_content = "크흠, 당신은 무슨 맛을 좋아하죠?",
  str_homestory_812001001_30_dialog_content = "바닐라, 초코, 말차, 오렌지, 팥 등등등등...",
  str_homestory_812001001_31_dialog_content = "난 다 좋아!",
  str_homestory_812001001_32_dialog_content = "그렇게나 다양한 맛이 있었던 건가요...",
  str_homestory_812001001_33_dialog_content = "헤이디는 아이스크림 안 먹어봤어?\n방금 내가 말한 건 다 기본적인 맛인데...",
  str_homestory_812001001_34_dialog_content = "무, 무슨 말을 하는 거죠?",
  str_homestory_812001001_35_dialog_content = "아이스크림 같은 건 물론 먹어봤죠!",
  str_homestory_812001001_36_dialog_content = "그저 당신이 말한 맛들이 너무 평범해서\n놀랐을 뿐이라구요.",
  str_homestory_812001001_37_dialog_content = "전 예전에 「고서」 맛만 먹었어요.",
  str_homestory_812001001_38_dialog_content = "하지만 이 아이스크림 기계로는 만들 수 없겠죠<sprite=emo_emo size=60 />.",
  str_homestory_812001001_39_dialog_content = "「고서」 맛 아이스크림?!",
  str_homestory_812001001_40_dialog_content = "그건 진짜 못 먹어봤네.",
  str_homestory_812001001_41_dialog_content = "그래도 내가 그 맛을 만드는 레시피를 한번 시도해 볼게!",
  str_homestory_812001001_42_dialog_content = "아, 그렇게 수고할 필요는 없어요...",
  str_homestory_812001001_43_dialog_content = "왜?",
  str_homestory_812001001_44_dialog_content = "저도 가끔은...",
  str_homestory_812001001_45_dialog_content = "바닐라, 초코, 말차, 오렌지, 팥 아이스크림이\n어떤 맛인지 한번 먹어보고 싶어요.",
  str_homestory_806801001_0_dialog_content = "웬디?",
  str_homestory_806801001_1_dialog_content = "뭐 하러 가는 거야?",
  str_homestory_806801001_2_dialog_content = "PlayerName 너였구나.",
  str_homestory_806801001_3_dialog_content = "지금 수직 비행 연습이 가능한 곳을 찾는 중이야.",
  str_homestory_806801001_4_dialog_content = "수직 비행?",
  str_homestory_806801001_5_dialog_content = "그래, 똑바로 위로 날아갔다 곧장 내려오는 거야.",
  str_homestory_806801001_6_dialog_content = "비행 기술을 시험할 수 있는 방법이라구.",
  str_homestory_806801001_7_dialog_content = "사실 난 네가 엄청 높이 나는 걸 볼 때마다 떨어질까 걱정된단 말이지...",
  str_homestory_806801001_8_dialog_content = "어라? 그런 걸 걱정했어?",
  str_homestory_806801001_9_dialog_content = "걱정 마. 저 정도 높이는 나한텐 아무것도 아니니까.",
  str_homestory_806801001_10_dialog_content = "설마 잊었어?\n난 사막의 허리케인 미사일이잖아<sprite=emo_mojing size=60 />!",
  str_homestory_806801001_11_option_content = "잊었어.",
  str_homestory_806801001_12_dialog_content = "그럼 다시 말해줄게!",
  str_homestory_806801001_13_option_content = "안 잊었어.",
  str_homestory_806801001_14_dialog_content = "그런 중요한 캐릭터 설정을 잊을 리가 없잖아?",
  str_homestory_806801001_15_dialog_content = "그래도 혹시 모르니까 다시 말해줄게!",
  str_homestory_806801001_16_dialog_content = "웬디는 사막의 허리케인 미사일이야~",
  str_homestory_806801001_17_dialog_content = "속도야말로 내 라벨, 용맹은 내 대명사!",
  str_homestory_806801001_18_dialog_content = "알았어, 알았어.",
  str_homestory_806801001_19_dialog_content = "근데 왜 수직비행 같은 걸 연습하는데?",
  str_homestory_806801001_20_dialog_content = "물론 배달 때문이지!",
  str_homestory_806801001_21_dialog_content = "배달?",
  str_homestory_806801001_22_dialog_content = "PlayerName, 혹시 긴 촉수가 달린\n녀석 못 봤어?",
  str_homestory_806801001_23_dialog_content = "설마 둥둥 해파리 풍선 말하는 거야?",
  str_homestory_806801001_24_dialog_content = "풍선인지 아닌지는 상관없어.",
  str_homestory_806801001_25_dialog_content = "손님이 부탁한 편지는 반드시 배달할 거니까!",
  str_homestory_806801001_26_dialog_content = "아, PlayerName 넌 저 풍선이랑 아는 사이야?",
  str_homestory_806801001_27_dialog_content = "저 가구에 대해서라면 알고 있지... 그럼 「아는 사이」라고 할 수 있으려나?",
  str_homestory_806801001_28_dialog_content = "그럼 저 풍선 이름이 「클레이튼」이야?",
  str_homestory_806801001_29_dialog_content = "으엑, 혹시 네가 편지를 전해야 할 사람이 「클레이튼」이면...",
  str_homestory_806801001_30_dialog_content = "내가 보기엔 뭔가 착오가 있는 것 같아. 클레이튼은 풍선이 아니거든.",
  str_homestory_806801001_31_dialog_content = "으엣?! 진짜?",
  str_homestory_806801001_32_dialog_content = "의뢰인 말로는 「클레이튼」에는 긴 촉수가\n많이 달려 있다고 했거든.",
  str_homestory_806801001_33_dialog_content = "게다가 검은 모자를 자주 쓴대.",
  str_homestory_806801001_34_dialog_content = "저 풍선 머리에 모자가 있나?",
  str_homestory_806801001_35_dialog_content = "아무튼 저 둥둥 해파리 풍선은 수신자가 아냐.",
  str_homestory_806801001_36_dialog_content = "아... 이 편지... 내 「배달 최장 소요 시간」 기록을\n깨버리게 만들 것 같네...",
  str_homestory_806801001_37_dialog_content = "휴, 됐어.",
  str_homestory_806801001_38_dialog_content = "아까 공중에서 날다가 강에 뭔가 빛나는 걸\n봐서 가 보고 싶었는데...",
  str_homestory_806801001_39_dialog_content = "그냥 편지나 배달하러 가야겠어!<sprite=emo_dianzan size=60 />",
  str_homestory_817201001_0_dialog_content = "아, 리리카...",
  str_homestory_817201001_1_dialog_content = "PlayerName, 빨리 와 봐!",
  str_homestory_817201001_2_dialog_content = "왜 그래?",
  str_homestory_817201001_3_dialog_content = "이 장난감! 엄청 재미있어!",
  str_homestory_817201001_4_dialog_content = "배트로 살짝 두드리면...\n리본이 잔뜩 튀어나와!<sprite=emo_caitiao size=60 />",
  str_homestory_817201001_5_dialog_content = "가끔은 사탕이 튀어나올 때도 있어!",
  str_homestory_817201001_6_dialog_content = "이런 장난감은 처음 봐.",
  str_homestory_817201001_7_dialog_content = "당연하지. 오색 인형은 헤븐즈 밸리에만 있는 전통 장식품이니까.",
  str_homestory_817201001_8_dialog_content = "다른 곳에는 없어.",
  str_homestory_817201001_9_dialog_content = "오색 인형? 헤븐즈 밸리의 전통 장식품이라...",
  str_homestory_817201001_10_dialog_content = "그 얘기를 들으니까 왠지 기억이 날 것 같아!",
  str_homestory_817201001_11_dialog_content = "기념일 전에 씨앗을 항아리에 넣어둔 다음에...",
  str_homestory_817201001_12_dialog_content = "기념일 때 「파직」하는 소리와 함께 열어보면...",
  str_homestory_817201001_13_dialog_content = "자연의 축복을 받는 거지!",
  str_homestory_817201001_14_dialog_content = "맞아?",
  str_homestory_817201001_15_dialog_content = "아, 리리카. 네가 헤븐즈 밸리에 대해 그렇게 잘 알고 있을 줄은 몰랐는데?",
  str_homestory_817201001_16_dialog_content = "후후후, 그렇게 잘 아는 편은 아니야.",
  str_homestory_817201001_17_dialog_content = "예전에 영화를 찍은 적이 있거든.\n거기서 난 역사 선생님을 맡았어.",
  str_homestory_817201001_18_dialog_content = "비록 클로즈업 장면은 없었지만,\n그 배경 속에서 수업을 진행해야만 했거든.",
  str_homestory_817201001_19_dialog_content = "그 당시 내 대사가 마침 헤븐즈 밸리의\n전통 장식품에 대한 설명이었어!",
  str_homestory_817201001_20_dialog_content = "아, 그런 영화도 있었어?",
  str_homestory_817201001_21_dialog_content = "영화 제목이 뭔데?",
  str_homestory_817201001_22_dialog_content = "크흠, 내 대사는 정말 단순한 배경음일\n뿐이었다니까.",
  str_homestory_817201001_23_dialog_content = "영화에서는 내가 뭐라고 하는지\n제대로 들리지도 않았어...",
  str_homestory_817201001_24_option_content = "(실망한다)",
  str_homestory_817201001_25_dialog_content = "그렇구나...",
  str_homestory_817201001_26_dialog_content = "헤븐즈 밸리에 대한 영화를 볼 수 있을 줄 알았는데...",
  str_homestory_817201001_27_dialog_content = "기운 내, PlayerName.\n설마 내가 뭐 하는 사람인지 잊은 거야?",
  str_homestory_817201001_28_option_content = "(감격한다)",
  str_homestory_817201001_29_dialog_content = "그저 배경음만이라도 좋아. 헤븐즈 밸리가 영화 화면에 나왔었다니...",
  str_homestory_817201001_30_dialog_content = "그것만으로도 충분히 감동적이야!",
  str_homestory_817201001_31_dialog_content = "크흠... 그정도까지야...\n아무튼 내가 뭐 하는 사람인지 잊지 마!",
  str_homestory_817201001_32_dialog_content = "이래 봬도 난 신예 청년 프로듀서니까!",
  str_homestory_817201001_33_dialog_content = "아니면 이참에...",
  str_homestory_817201001_34_dialog_content = "내가 헤븐즈 밸리에 대한 영화를 찍어도 될까?",
  str_homestory_817201001_35_dialog_content = "아, 그래도 돼?",
  str_homestory_817201001_36_dialog_content = "물론이지!",
  str_homestory_817201001_37_dialog_content = "리리카, 벌써 어떻게 촬영할지 아이디어가 떠오른 거야?",
  str_homestory_817201001_38_dialog_content = "음... 어디 보자...<sprite=emo_sikao size=60 />",
  str_homestory_817201001_39_dialog_content = "아! 생각났어!",
  str_homestory_817201001_40_dialog_content = "리리카가 헤븐즈 밸리에서 춤을 추는 영화를 찍자!",
  str_homestory_817201001_41_dialog_content = "응?",
  str_homestory_817201001_42_dialog_content = "그것도... 헤븐즈 밸리에 대한 영화라고 할 수 있나?",
  str_homestory_817201001_43_dialog_content = "아니야?",
  str_homestory_817201001_44_dialog_content = "골치 아프네.",
  str_homestory_817201001_45_dialog_content = "아니면 PlayerName 네가 헤븐즈 밸리에서\n춤을 추는 영화를 찍는 건 어때?",
  str_homestory_817201001_46_dialog_content = "아무도 안 보지 않을까...",
  str_homestory_817301001_0_dialog_content = "미노스...",
  str_homestory_817301001_1_dialog_content = "PlayerName 님, 안녕하세요<sprite=emo_mojing size=60 />.",
  str_homestory_817301001_2_dialog_content = "미노스, 안녕.",
  str_homestory_817301001_3_dialog_content = "PlayerName 님, 분부하실 일이 있으신지요.",
  str_homestory_817301001_4_option_content = "(인정한다)",
  str_homestory_817301001_5_dialog_content = "음... 미노스에게 부탁하고 싶은 일이 있긴 해.",
  str_homestory_817301001_6_dialog_content = "말씀하십시오.",
  str_homestory_817301001_7_dialog_content = "미노스가 헤븐즈 가든에서는 편하게 있었으면 좋겠어.",
  str_homestory_817301001_8_dialog_content = "계속 날 그렇게 깍듯하게 대할 필요도 없어.",
  str_homestory_817301001_9_option_content = "(부정한다)",
  str_homestory_817301001_10_dialog_content = "어, 없어...",
  str_homestory_817301001_11_dialog_content = "미노스가 헤븐즈 가든에 있을 땐 걱정할 게 없거든.",
  str_homestory_817301001_12_dialog_content = "하지만 그것보다 난 미노스도 여기서 편하게 있었으면 좋겠어.",
  str_homestory_817301001_13_dialog_content = "아무튼 너도 내가 초대한 손님이니까.",
  str_homestory_817301001_14_dialog_content = "네. 그것도 그렇군요.",
  str_homestory_817301001_15_dialog_content = "손님이 주인 노릇을 하면서 손님을 맞이하는\n주인의 즐거움을 빼앗으면 안 되겠죠.",
  str_homestory_817301001_16_dialog_content = "그 분부는 기억해 두겠습니다.",
  str_homestory_817301001_17_dialog_content = "이제 당신의 완벽한 손님으로 거듭나겠습니다.",
  str_homestory_817301001_18_dialog_content = "사실 「완벽」하지 않아도 괜찮아.",
  str_homestory_817301001_19_dialog_content = "「완벽하지 않은 손님」 말입니까?",
  str_homestory_817301001_20_dialog_content = "꽤 어려운 문제 같군요.",
  str_homestory_817301001_21_dialog_content = "아하하, 그건 고민해야 할 문제 같은 게 아니야. 그것보단...",
  str_homestory_817301001_22_dialog_content = "방금 네가 손을 들자마자 양초가 빛나는 걸 봤어.",
  str_homestory_817301001_23_dialog_content = "정말 신기하네. 어떻게 한 거야?",
  str_homestory_817301001_24_dialog_content = "자세하게 관찰하셨군요.",
  str_homestory_817301001_25_dialog_content = "방금은 이 양초들을 길들이고 있었습니다.\n당신이 왔을 때 마침 길들이기를 끝냈습니다.",
  str_homestory_817301001_26_dialog_content = "양초를... 길들인다고...?",
  str_homestory_817301001_27_dialog_content = "그렇습니다.\n오랫동안 일해온 베테랑 집사라면...",
  str_homestory_817301001_28_dialog_content = "얼마나 비싼 가구든...\n아니면 얼마나 정교한 장식품이든...",
  str_homestory_817301001_29_dialog_content = "모두 기술적인 길들이기가 필요하며,\n그래야만 환경과 더욱 어우러질 수\n있다는 걸 알고 있죠.",
  str_homestory_817301001_30_dialog_content = "예를 들어 이 양초 장식품처럼 말입니다.",
  str_homestory_817301001_31_dialog_content = "이 양초 내부에는 자동 발화,\n자동 끄기 기능이 설치되어 있습니다.",
  str_homestory_817301001_32_dialog_content = "방치하고 신경 쓰지 않는다면,\n이 양초들은 멋대로 불이 붙었다가\n꺼지며 불규칙해지겠죠.",
  str_homestory_817301001_33_dialog_content = "하지만 걱정하지 마세요.\n이제 당신은 순서에 따라 양초 앞으로\n가기만 하면 됩니다.",
  str_homestory_817301001_34_dialog_content = "그럼 얌전하게 순차적으로 불이 붙을 테니까요.",
  str_homestory_817301001_35_dialog_content = "대, 대단해...",
  str_homestory_817301001_36_dialog_content = "아, 죄송합니다.",
  str_homestory_817301001_37_dialog_content = "장식품을 길들이는 건 손님으로써 할만한\n일이 아니었던 것 같군요.",
  str_homestory_817301001_38_dialog_content = "괜찮아.",
  str_homestory_817301001_39_dialog_content = "미노스가 아니었다면 이 양초 장식품을 이런 식으로\n다룰 수 있다는 것도 몰랐을걸!",
  str_homestory_817301001_40_dialog_content = "제 실수를 용서해주셔서 감사합니다.",
  str_homestory_817301001_41_dialog_content = "하지만 이 작은 실수 덕에...",
  str_homestory_817301001_42_dialog_content = "저는 완벽하게 「완벽하지 않은 손님」이\n될 수 있었군요.",
  str_homestory_817301001_43_dialog_content = "부디 만족하셨기를<sprite=emo_baimao size=60 />, PlayerName 님.",
  str_homestory_815901001_0_dialog_content = "아, 새디!",
  str_homestory_815901001_1_dialog_content = "너구나. 설마 나한테 의뢰할 거라도 있어?",
  str_homestory_815901001_2_dialog_content = "아니야. 그냥 방금 그 음악<sprite=emo_yinfu size=60 />에 이끌려서 온 거야.",
  str_homestory_815901001_3_dialog_content = "리드미컬한 리듬이랑 신나는 드럼...",
  str_homestory_815901001_4_dialog_content = "음악을 듣다가 나도 모르게 펄쩍 뛰고 싶더라니까!",
  str_homestory_815901001_5_dialog_content = "아무래도 힙합의 매력에 푹 빠졌나 보네.",
  str_homestory_815901001_6_dialog_content = "뭐, 그건 아주 정상적인 반응이야.\n힙합을 싫어하는 사람은 없으니까.",
  str_homestory_815901001_7_dialog_content = "그런 게 힙합이었구나.",
  str_homestory_815901001_8_dialog_content = "PlayerName 너 설마 힙합을 처음\n들어보는 거야?",
  str_homestory_815901001_9_option_content = "(인정한다)",
  str_homestory_815901001_10_dialog_content = "특별히 힙합을 듣는 경우는 드물어. 확실히 힙합에 대해 잘은 몰라.",
  str_homestory_815901001_11_option_content = "(부정한다)",
  str_homestory_815901001_12_dialog_content = "그건 아니야. 난 다양한 종류의 음악을 모두 좋아하거든.",
  str_homestory_815901001_13_dialog_content = "하지만 그전에도 네 랩 공연밖에 못 봤으니까...",
  str_homestory_815901001_14_dialog_content = "힙합 리듬 같은 건 아는 게 별로 없어.",
  str_homestory_815901001_15_dialog_content = "그래서 네가 연주한 게 힙합이라는 것도 몰랐어.",
  str_homestory_815901001_16_dialog_content = "그건 정말 아쉽네.\n마침 나도 처음 헤븐즈 가든에 왔을 때\n뭔가 부족하다고 느꼈거든.",
  str_homestory_815901001_17_dialog_content = "이 드럼을 보고 나서야 생각나지 뭐야.\n이곳엔 힙합이 없어!",
  str_homestory_815901001_18_dialog_content = "드럼 하나로 그렇게 신나는 곡을 연주할 수 있다니...",
  str_homestory_815901001_19_dialog_content = "아무래도 PlayerName 너도 벌써\n푹 빠져버린 모양이네...",
  str_homestory_815901001_20_dialog_content = "그렇다면 의적인 내가 나설 수밖에.",
  str_homestory_815901001_21_dialog_content = "나선다고?",
  str_homestory_815901001_22_dialog_content = "맞아. 내가 드럼 연주하는 방법을 가르쳐 줄게.",
  str_homestory_815901001_23_dialog_content = "그럼 너도 언제든 힙합을 들을 수 있을 거야.",
  str_homestory_815901001_24_dialog_content = "어라? 잠깐만... 만약 내가 널 가르쳐주면...",
  str_homestory_815901001_25_dialog_content = "그럼 헤븐즈 가든에 오는 모든 사람이\n네가 연주하는 힙합을 들을 수 있게\n되는 거잖아?!",
  str_homestory_815901001_26_dialog_content = "아스트라에 힙합 음악을 유행시키는 게\n내가 될 줄이야...",
  str_homestory_815901001_27_dialog_content = "새, 새디... 네 상상을 끊어서 미안하지만...",
  str_homestory_815901001_28_dialog_content = "드럼이든 힙합이든 난 전부 처음이야.",
  str_homestory_815901001_29_dialog_content = "날 가르치는 건 쉽지 않을걸.",
  str_homestory_815901001_30_dialog_content = "그건 걱정하지 않아도 돼.\n흥미야말로 최고의 선생님이니까<sprite=emo_dianzan size=60 />.",
  str_homestory_815901001_31_dialog_content = "힙합에서 가장 중요한 건 바로 드럼과 리듬이야.",
  str_homestory_815901001_32_dialog_content = "드럼에 리듬이 실리면 음악의 멜로디도 살아나.",
  str_homestory_815901001_33_dialog_content = "널 드럼 스틱이라 생각하고,\n마음속의 리듬을 따라 마음껏 뛰놀아 봐.",
  str_homestory_815901001_34_dialog_content = "마음대로 하는 게 바로 가장 순수한 힙합이니까!",
  str_homestory_815901001_35_dialog_content = "마음을 따르기만 하면 너처럼 힙합을\n할 수 있게 되는 거야?",
  str_homestory_815901001_36_dialog_content = "맞아! 한번 해 볼래?",
  str_homestory_815901001_37_dialog_content = "계속해서 드럼을 두드리다 보면\n훌륭한 음악이 돼 있을 거야.",
  str_homestory_815901001_38_dialog_content = "계, 계속해서 말이지...",
  str_homestory_815901001_39_dialog_content = "설마 더 많은 사람에게 힙합의 매력을\n알리고 싶지 않은 거야?",
  str_homestory_815901001_40_dialog_content = "당연히 알리고 싶지. 그냥 지금은 조금 힘들어서...",
  str_homestory_815901001_41_dialog_content = "아무래도 네가 진정한 힙합 음악가가\n되기까지는 아직 갈 길이 먼 것 같네.",
  str_homestory_815901001_42_dialog_content = "그럼 오늘은 여기까지만 하자.",
  str_homestory_815901001_43_dialog_content = "고, 고마워...",
  str_homestory_807901001_0_dialog_content = "미제니...",
  str_homestory_807901001_1_dialog_content = "미제니?",
  str_homestory_807901001_2_dialog_content = "왔군요, PlayerName.",
  str_homestory_807901001_3_dialog_content = "하하, 미제니도 이 장식품을 감상하고 있었어?",
  str_homestory_807901001_4_dialog_content = "이성적인 세무관으로서 「감상」이란 행동은\n제게 너무 감성적이에요.",
  str_homestory_807901001_5_dialog_content = "저는 그저 이 물건의 가치를 측량하고\n있었을 뿐이에요.",
  str_homestory_807901001_6_dialog_content = "아... 그래도 여긴 백야성이 아니니까,\n미제니도 가끔은 긴장을 풀고 있어도 될 것 같은데<sprite=emo_sikao size=60 />.",
  str_homestory_807901001_7_dialog_content = "이성적인 사고를 단련하는 건\n그렇게 쉬운 일이 아니에요.",
  str_homestory_807901001_8_dialog_content = "세법 분야 최고의 학자가 되는 건\n그보다도 더 어려운 일이고요.",
  str_homestory_807901001_9_dialog_content = "잠깐의 태만으로 지금까지 단련해 온\n학문을 낭비할 순 없어요.",
  str_homestory_807901001_10_dialog_content = "게다가 지금 전 어차피 한가하니까,\n한가한 김에 헤븐즈 가든의 세무 업무를\n조금 분담해 드릴 수 있어요.",
  str_homestory_807901001_11_dialog_content = "아직까진 헤븐즈 가든에 그런 업무가 필요한 것 같진 않은데...",
  str_homestory_807901001_12_dialog_content = "상냥한 답변이었어요. 「단호한 태도」와는 10 나이티움<sprite=emo_baiyebi size=60 />정도\n거리가 있는 반응이었네요.",
  str_homestory_807901001_13_dialog_content = "아무튼 그렇게 말하는 걸 보니,\n제 제안은 거절당한 거군요.",
  str_homestory_807901001_14_option_content = "(인정한다)",
  str_homestory_807901001_15_dialog_content = "정말 거절하고 싶진 않은데...\n난 헤븐즈 가든에 세무관을 초빙할 돈이 없어. 진짜야.",
  str_homestory_807901001_16_dialog_content = "주머니 사정 때문이었군요.",
  str_homestory_807901001_17_dialog_content = "괜찮아요. 세무 관련 자문은 무료로 해 드릴게요.",
  str_homestory_807901001_18_dialog_content = "「헤븐즈 가든 가치 평가」도 어느 정도는 제게\n정서적인 가치를 선사해 줄 테니까요.",
  str_homestory_807901001_19_option_content = "(부정한다)",
  str_homestory_807901001_20_dialog_content = "그, 그렇지 않아!",
  str_homestory_807901001_21_dialog_content = "언젠가 헤븐즈 가든에 진짜로 세무관이 필요해질 때가 오면,\n그땐 꼭 미제니한테 부탁할 거야!",
  str_homestory_807901001_22_dialog_content = "거래와 경영이 이루어지고 있는 곳이라면,\n세무가 존재하기 마련이죠.",
  str_homestory_807901001_23_dialog_content = "저를 믿겠다고 하셨으니, 그럼 저는 계속해서\n헤븐즈 가든의 가치를 평가해 보도록 할게요.",
  str_homestory_807901001_24_dialog_content = "그, 그래...",
  str_homestory_807901001_25_dialog_content = "이야기가 조금 옆으로 샜군요.\n다시 돌아와서, 당신은 이 장식품에 대해\n얼마나 알고 있나요?",
  str_homestory_807901001_26_dialog_content = "이 장식품의 가치를 평가하려면 더 많은\n정보가 필요하거든요.",
  str_homestory_807901001_27_dialog_content = "이 장식품은 「윈델리온 둥지」라고 해.",
  str_homestory_807901001_28_dialog_content = "이 커다란 알 껍데기들은 다 그냥 장식에 불과하지만,\n작은 동물들<sprite=emo_gezitou size=60 />이 둥지를 틀고 알을 낳고 싶어지게 만들 수 있어.",
  str_homestory_807901001_29_dialog_content = "아무런 경제적 가치를 생산할 수 없고,\n토지 자원까지 일정량 낭비하게 되는군요.",
  str_homestory_807901001_30_dialog_content = "작은 동물이 부화한 다음에는 한 걸음 더 나가\n헤븐즈 가든의 식량 자원을 소모할 테고요.",
  str_homestory_807901001_31_dialog_content = "제 판단에 따르면 이 장식물과 그 안에 있던\n동물의 알도 아무 가치가 없어요.",
  str_homestory_807901001_32_dialog_content = "이 장식품을 여기에 두는 건 손해예요.",
  str_homestory_807901001_33_dialog_content = "하, 하지만... 그 알들은 다 살아있는 작은 생명들인걸.",
  str_homestory_807901001_34_dialog_content = "어떻게 이성적으로 그 생명들의 가치를 평가할 수 있어?",
  str_homestory_807901001_35_dialog_content = "굳이 평가를 해야 한다면, 이 알들은 나한텐 값을 매길 수 없는 것들이야.",
  str_homestory_807901001_36_dialog_content = "값을 매길 수 없다고요?",
  str_homestory_807901001_37_dialog_content = "아, 좋은 생각이 났어!",
  str_homestory_807901001_38_dialog_content = "미제니! 이 「윈델리온 둥지」의 둥지지기가 되어 줘, 부탁할게!",
  str_homestory_807901001_39_dialog_content = "좋아요. 제가 뭘 해야 하죠?",
  str_homestory_807901001_40_dialog_content = "여기서 작은 동물들이 알을 깨고 나오길 기다렸다가,\n무럭무럭 자랄 수 있도록 지켜 줘.",
  str_homestory_807901001_41_dialog_content = "이따가 어떻게 하면 작은 동물을 부화시킬 수 있는지\n나와 있는 책을 하나 줄게.",
  str_homestory_807901001_42_dialog_content = "교과서가 있다면 더 쉽겠네요.",
  str_homestory_807901001_43_dialog_content = "안심하세요. 절대로 실망시키지 않을게요.",
  str_homestory_817601001_0_dialog_content = "베르타!",
  str_homestory_817601001_1_dialog_content = "베르타, 지금 뭐 해?",
  str_homestory_817601001_2_dialog_content = "PlayerName, 당신이었구나!",
  str_homestory_817601001_3_dialog_content = "방금 체력 단련을 하고 있었거든.",
  str_homestory_817601001_4_dialog_content = "그래서 여기까지 뛰어서 왔는데,\n오는 길에 왠지 라파엘 님이 보인 거 같았어.",
  str_homestory_817601001_5_dialog_content = "그래서 멈춰 서서 자세히 살펴보니까.",
  str_homestory_817601001_6_dialog_content = "이 엽서 위에 라파엘 님의 사진이 붙어 있지 뭐야!",
  str_homestory_817601001_7_dialog_content = "아, 이 선반에 있는 엽서들은 친구들이 나한테 보내 준 거야!",
  str_homestory_817601001_8_dialog_content = "몇 개는 내가 새로운 곳에 갔을 때 기념으로 가지고 돌아온 것들이고.",
  str_homestory_817601001_9_dialog_content = "이 사진은 라파엘이 멀리 외출할 일이 있다면서,\n미카엘을 억지로 끌고 와서 같이 찍었던 걸 거야.",
  str_homestory_817601001_10_dialog_content = "어쩐지 미카엘 님이 다 체념한 얼굴을\n하고 계시더라!<sprite=emo_wuzui size=60 />",
  str_homestory_817601001_11_dialog_content = "그런데 PlayerName 당신 인맥은 정말 굉장하네.",
  str_homestory_817601001_12_dialog_content = "엽서가 정말 엄청 많아.\n게다가 헤이디 님의 서명이 적혀 있는 것도 있었고...",
  str_homestory_817601001_13_dialog_content = "어? 이 엽서에 담긴 풍경은... 레디젤 사막이야?",
  str_homestory_817601001_14_dialog_content = "응, 맞아.",
  str_homestory_817601001_15_dialog_content = "이건 전에 레디젤 렌치에 놀러 갔을 때 기념으로 가져온 거야.",
  str_homestory_817601001_16_option_content = "그리고 북방 것도 있어.",
  str_homestory_817601001_17_dialog_content = "와! 사막과 설원이라니, 정말 예뻐.",
  str_homestory_817601001_18_option_content = "해변 풍경이 담긴 것도 있어.",
  str_homestory_817601001_19_dialog_content = "와! 사막과 해변이라니, 정말 예뻐.",
  str_homestory_817601001_20_dialog_content = "PlayerName 당신은 참 많은 곳에 가 봤구나.\n정말 부럽네!",
  str_homestory_817601001_21_dialog_content = "베르타 넌 평소에 여기저기 여행 안 다녀?",
  str_homestory_817601001_22_dialog_content = "응, 아무래도 일이 일이다 보니까 마음 놓고\n휴가를 낼 기회가 별로 없어.",
  str_homestory_817601001_23_dialog_content = "내가 휴가 중이라고 사람들이 안 아픈 건 아니니까.",
  str_homestory_817601001_24_dialog_content = "평소엔 어디 간다고 해도,\n지원 업무로 출장 나가는 게 전부야.",
  str_homestory_817601001_25_dialog_content = "그건 그렇네. 의사라는 직업은 정말 힘들겠어...",
  str_homestory_817601001_26_dialog_content = "힘들긴 힘들어.",
  str_homestory_817601001_27_dialog_content = "그렇지만 타인이 아픔을 덜 수 있게 돕고,\n목숨을 구할 수 있는 걸 생각하면...",
  str_homestory_817601001_28_dialog_content = "몸이 힘든 것쯤은 아무것도 아니야!",
  str_homestory_817601001_29_dialog_content = "게다가 지금 조금 더 노력해야\n더 빨리 발전할 수 있잖아.",
  str_homestory_817601001_30_dialog_content = "그래야 하루라도 빨리 내 의료팀을 만들어서\n대륙 곳곳을 다니며 사람들을 치료해 줄 수 있어.",
  str_homestory_817601001_31_dialog_content = "그때가 되면 여러 사람을 도와줄 수 있고,\n지금까진 본 적 없는 풍경도 볼 수 있을 거야!",
  str_homestory_817601001_32_dialog_content = "그럼 일석이조잖아~<sprite=emo_guilian size=60 />",
  str_homestory_817601001_33_dialog_content = "...베르타 넌 정말 대단한 것 같아!",
  str_homestory_817601001_34_dialog_content = "그런 얘기를 할 때면 꼭 베르타의 온몸이 반짝반짝 빛나는 느낌이야!",
  str_homestory_817601001_35_dialog_content = "아하하하, 난 아직 멀었어!",
  str_homestory_817601001_36_dialog_content = "내 목표는 라파엘 님과 요하네스 선생님처럼\n훌륭한 의사가 되는 거야.",
  str_homestory_817601001_37_dialog_content = "하지만 아직은 배워야 할 게 많아.",
  str_homestory_817601001_38_dialog_content = "의료 기술은 물론이고, 체력과 정신력도\n두 분을 따라잡아야 하니까.",
  str_homestory_817601001_39_dialog_content = "요하네스 선생님이 내게 수술을 해 주셨을 땐\n사흘 내내 수술대에 서 계셨었거든!",
  str_homestory_817601001_40_dialog_content = "지금 내 수준으론 그렇게까진 못해.",
  str_homestory_817601001_41_dialog_content = "아, 말하고 보니까 빨리 가서 체력 단련을\n마저 해야 할 거 같아. 다음에 다시 이야기하자!",
  str_homestory_817601001_42_dialog_content = "다음에 또 봐, PlayerName.",
  str_homestory_817601001_43_dialog_content = "나중에 대륙을 돌아다니며 사람들을 치료하게 되면,\n나도 당신한테 엽서 보내 줄게!",
  str_homestory_817601001_44_dialog_content = "하하, 역시 베르타는 성격이 급하다니까.",
  str_homestory_817601001_45_dialog_content = "그럼 기대하고 있을게. 힘내, 베르타.",
  str_homestory_817501001_0_dialog_content = "악셀리아?",
  str_homestory_817501001_1_dialog_content = "안녕, 악셀리아.",
  str_homestory_817501001_2_dialog_content = "안녕하세요, PlayerName.",
  str_homestory_817501001_3_dialog_content = "요즘은 몸 상태가 좀 괜찮아?",
  str_homestory_817501001_4_dialog_content = "악셀리아가 헤븐즈 가든에 있는 걸 꽤 자주 본 거 같아서.",
  str_homestory_817501001_5_dialog_content = "음<sprite=emo_chidai size=60 />... 사실 악셀리아는 헤븐즈 가든 탐색을 마친 후\n수면 캡슐로 돌아가 휴식해야 합니다.",
  str_homestory_817501001_6_dialog_content = "하지만 이곳에는 악셀리아의 시선을 사로잡는\n재미있는 것들이 많습니다.",
  str_homestory_817501001_7_dialog_content = "예를 들면 악셀리아가 자주 보러 가는 북처럼 말이지?",
  str_homestory_817501001_8_dialog_content = "크, 크흠.",
  str_homestory_817501001_9_dialog_content = "PlayerName 당신은 제 행동 노선을 계속\n주시하고 있었습니까?",
  str_homestory_817501001_10_option_content = "당연하지!",
  str_homestory_817501001_11_dialog_content = "항상 큐빅이 네 곁에서 같이 다니니까 별일이 안 생기긴 하겠지만.",
  str_homestory_817501001_12_dialog_content = "그래도 역시 내가 악셀리아의 몸 상태에 대해 더 신경을 써야 할 거 같거든.",
  str_homestory_817501001_13_dialog_content = "...신경 써 줘서 고맙습니다.",
  str_homestory_817501001_14_option_content = "아니야.",
  str_homestory_817501001_15_dialog_content = "그냥 네가 매번 보일 때마다 그 북 근처에 있는 것 같길래.",
  str_homestory_817501001_16_dialog_content = "네...",
  str_homestory_817501001_17_dialog_content = "악셀리아는 그런 북에 호기심을 가지고 있습니다.",
  str_homestory_817501001_18_dialog_content = "음, 악셀리아는 음악에 꽤 관심이 있었던 걸로 기억하는데.",
  str_homestory_817501001_19_dialog_content = "근데 기계음 같은 음악을 좋아하는 이유가 뭐야?",
  str_homestory_817501001_20_dialog_content = "이유는...",
  str_homestory_817501001_21_dialog_content = "그런 노래는 가사가 없기 때문인 것 같습니다.<sprite=emo_sikao size=60 />",
  str_homestory_817501001_22_dialog_content = "가사가 없어?",
  str_homestory_817501001_23_dialog_content = "네.",
  str_homestory_817501001_24_dialog_content = "가사가 없으면 청중이 상상의 나래를\n펼칠 수 있습니다.",
  str_homestory_817501001_25_dialog_content = "가사가 없으면 곡에 여분의 감정을 소모하지 않고,\n순수하게 음률만을 느끼면 됩니다.",
  str_homestory_817501001_26_dialog_content = "역시 엄청 「악셀리아」다운 이유네.",
  str_homestory_817501001_27_dialog_content = "아버지께서는 이런 평가를 싫어하시겠지만,\n저는 다른 음악들보다...",
  str_homestory_817501001_28_dialog_content = "전자 음악에서는 창작자와 무감정한 음표가 합쳐진\n이성의 빛이 반짝인다고 생각합니다.",
  str_homestory_817501001_29_dialog_content = "듣고 보니까 확실히 그런 것 같기도 해.",
  str_homestory_817501001_30_dialog_content = "그런 종류의 음악들은 사람들의 감정을\n불러일으키지 않는단 거지?",
  str_homestory_817501001_31_dialog_content = "네.",
  str_homestory_817501001_32_dialog_content = "그래서...",
  str_homestory_817501001_33_dialog_content = "이 북 옆에 항상 있었던 것도 그런 음악엔 북소리가 있어서 그런 거야?",
  str_homestory_817501001_34_dialog_content = "아니면 그 선율들에 북소리를 더하고 싶은 거야?",
  str_homestory_817501001_35_dialog_content = "악셀리아는 그저 그 북들의 소리를\n더 듣고 싶었을 뿐입니다.",
  str_homestory_817501001_36_dialog_content = "하지만 조금 전 PlayerName의 이야기를 듣고\n한 가지 결심을 했습니다.",
  str_homestory_817501001_37_dialog_content = "악셀리아는... 앞으로도 이곳에 자주 머물 겁니다.",
  str_homestory_817501001_38_dialog_content = "응! 다른 필요한 게 생기면 언제든 알려줘.",
  str_homestory_817501001_39_dialog_content = "감사합니다, PlayerName.",
  str_homestory_805401001_0_dialog_content = "나딘?",
  str_homestory_805401001_1_dialog_content = "PlayerName 님, 오셨군요!",
  str_homestory_805401001_2_dialog_content = "나딘, 왜 여기 혼자 서 있어?",
  str_homestory_805401001_3_dialog_content = "다른 사람들이랑 같이 방에 가서 쉬든가, 근처에서 낚시라도 하면 되지 않아?",
  str_homestory_805401001_4_dialog_content = "제 업무를 완수해야 하거든요!",
  str_homestory_805401001_5_dialog_content = "업무?",
  str_homestory_805401001_6_dialog_content = "맞아요, 전 헤븐즈 가든의 첫 번째\n나이트워치니까요...",
  str_homestory_805401001_7_dialog_content = "당연히 보초는 제대로 서야죠!",
  str_homestory_805401001_8_dialog_content = "뭐? 잠깐만...",
  str_homestory_805401001_9_dialog_content = "나딘한테 헤븐즈 가든에서 나이트워치를 맡아 달라고\n부탁했던 기억은 없는데<sprite=emo_yueliang size=60 />?",
  str_homestory_805401001_10_dialog_content = "저는 PlayerName 님의 초대를 받고 헤븐즈 가든에\n손님으로 머물면서 재미있는 시간을 보내고 있어요.",
  str_homestory_805401001_11_dialog_content = "게다가 이곳엔 숙소, 식사 이외에도 여러 재미있는\n가구와 장식품들까지 준비돼 있어서...",
  str_homestory_805401001_12_dialog_content = "전 정말 기뻐요!",
  str_homestory_805401001_13_dialog_content = "제가 PlayerName 님 같은 유명인과 친구가\n되리라곤 정말 생각도 못 했어요.",
  str_homestory_805401001_14_dialog_content = "백야성을 떠나 헤븐즈 가든이라는 먼 곳까지\n나올 수 있을 줄은 더더욱 몰랐고요.",
  str_homestory_805401001_15_dialog_content = "하지만 저는 돈도 없고, 잘하는 것도 없어서...\n어떻게 보답을 해야 할지 잘 모르겠어요.",
  str_homestory_805401001_16_dialog_content = "이래저래 생각해 보니까,\n제가 할 수 있는 건 나이트워치 일밖에 없었죠.",
  str_homestory_805401001_17_dialog_content = "그래서... 이런 방법으로라도 PlayerName 님께\n고마움을 표현하고 싶었어요!",
  str_homestory_805401001_18_option_content = "(고마워한다)",
  str_homestory_805401001_19_dialog_content = "고마워, 나딘. 그렇게 말해 주니까 나도 정말 뿌듯해.",
  str_homestory_805401001_20_dialog_content = "그치만 내 손님이 여기서 날 위해서 일하게 만들 순 없어.",
  str_homestory_805401001_21_option_content = "(위로한다)",
  str_homestory_805401001_22_dialog_content = "나딘이 기뻐해 주는 게 나한텐 가장 큰 선물이야!",
  str_homestory_805401001_23_dialog_content = "그러니까 정말 이렇게 고생할 필요 없어.",
  str_homestory_805401001_24_dialog_content = "괜찮아요. 이미 익숙해져서 하나도\n안 고생스럽거든요.",
  str_homestory_805401001_25_dialog_content = "게다가...",
  str_homestory_805401001_26_dialog_content = "헤븐즈 가든은 정말 아름다워요!",
  str_homestory_805401001_27_dialog_content = "그뿐만 아니라 언제나 모두의 기호에 맞춰\n가구들을 배치해 주시니까...",
  str_homestory_805401001_28_dialog_content = "점점 헤븐즈 가든이 일종의 「집」처럼 느껴져요.",
  str_homestory_805401001_29_dialog_content = "그럼 「집」이니까 나딘도 그렇게 예의 차릴 필요 없어.",
  str_homestory_805401001_30_dialog_content = "항상 어떻게 하면 보답할 수 있을까 고민할 필요도 없고.",
  str_homestory_805401001_31_dialog_content = "바로 「집」이기 때문에 그런 책임감이 든 거예요...",
  str_homestory_805401001_32_dialog_content = "저는 우리 모두의 「집」을 지키고 싶어요.\n헤븐즈 가든이 그 어떤 피해도 받지 않게요.",
  str_homestory_805401001_33_dialog_content = "이런 일들도 사실 제게 말처럼 쉽지는 않아요.",
  str_homestory_805401001_34_dialog_content = "그렇지만 이건...\n지키고 싶다는 제 본능과 사명이에요!",
  str_homestory_805401001_35_dialog_content = "나딘...",
  str_homestory_805401001_36_dialog_content = "고마워!",
  str_homestory_805401001_37_dialog_content = "그럼 내가 방법을 좀 생각해서 나딘한테 보수를 주도록 할게.",
  str_homestory_805401001_38_dialog_content = "네?!",
  str_homestory_817801001_0_dialog_content = "안녕, 비크 씨.",
  str_homestory_817801001_1_dialog_content = "비크 씨가 바깥에 나오다니 별일이네!",
  str_homestory_817801001_2_dialog_content = "오늘은 왜 방에서 술 마시거나 자거나 안 하고 있어<sprite=emo_kun size=60 />?",
  str_homestory_817801001_3_dialog_content = "우와, PlayerName 넌 날 그렇게 생각했던 거야?",
  str_homestory_817801001_4_dialog_content = "속상하네~ 그래도 난 환상동물 마스터라고.",
  str_homestory_817801001_5_dialog_content = "방에서는 자료를 정리하거나 새 책을 쓰기도 해.",
  str_homestory_817801001_6_dialog_content = "아무튼 착실하게 일하고 있다고.\n술은 머리가 잘 돌아가라고 마시는 거야!",
  str_homestory_817801001_7_dialog_content = "그래? 그럼 새 책은 얼마나 썼는데?",
  str_homestory_817801001_8_dialog_content = "그나저나 여긴 갈수록 환경이 좋아진단 말이지.",
  str_homestory_817801001_9_dialog_content = "말도 참 못 돌리네.",
  str_homestory_817801001_10_dialog_content = "아니거든. 지금 내가 뭐 하는지 알아?",
  str_homestory_817801001_11_dialog_content = "음... 산책하면서 멍때리기?",
  str_homestory_817801001_12_dialog_content = "......",
  str_homestory_817801001_13_dialog_content = "난 지금 숲에 어떤 생물종이 얼마나 있는지\n알아보고 있었어.",
  str_homestory_817801001_14_dialog_content = "그런 거 알아봐서 뭐 하는데?",
  str_homestory_817801001_15_dialog_content = "무시하면 안 돼! 얼마나 중요한 정보인데!",
  str_homestory_817801001_16_dialog_content = "생물종의 구성과 개체수는 많은 현상을\n반영하고 있어.",
  str_homestory_817801001_17_dialog_content = "예를 들면 여기가 어떤 생물의 서식에\n적합한 환경인지...",
  str_homestory_817801001_18_dialog_content = "이곳의 동식물들이 어떤 포식 관계를 이루는지\n같은 것들 말이야.",
  str_homestory_817801001_19_dialog_content = "...그리고 방금 난<sprite=emo_wuzui size=60 />──",
  str_homestory_817801001_20_dialog_content = "이곳이 완벽한 연구 장소라는 걸 알게 됐어!",
  str_homestory_817801001_21_dialog_content = "그래서 난 환상동물들을 여기 좀 데려올 생각이야.",
  str_homestory_817801001_22_dialog_content = "그렇게 되면 내가 새로 쓸 책...",
  str_homestory_817801001_23_dialog_content = "잠깐만, 뭘 하겠다고?",
  str_homestory_817801001_24_dialog_content = "아? 데이터를 수집하고 책을 쓸 건데?",
  str_homestory_817801001_25_dialog_content = "아니, 그 전에 했던 말.",
  str_homestory_817801001_26_dialog_content = "여기 숲에서 환상동물을 키우겠다고?",
  str_homestory_817801001_27_dialog_content = "환상동물용 방이면 이미 많이 있잖아! 아직도 부족해?!",
  str_homestory_817801001_28_dialog_content = "아이, 그거랑 이거랑은 다르지~",
  str_homestory_817801001_29_dialog_content = "실내에서는 바깥의 실제 환경과 완전히 같은 건\n만들어낼 수 없잖아.",
  str_homestory_817801001_30_dialog_content = "진짜 생태계 안에서만 실제와 가장 가까운\n모습을 관찰할 수 있거든.",
  str_homestory_817801001_31_dialog_content = "중요한 건 그게 아니잖아!",
  str_homestory_817801001_32_dialog_content = "비크 씨가 콜로서스에서 환상동물을 너무 많이 키워서\n다른 오로리안들한테 민원이 잔뜩 들어왔다고.",
  str_homestory_817801001_33_dialog_content = "아침부터 환상동물들의 울음소리가 다른 오로리안들의 잠을\n방해한다는 문제도 아직 해결되지 않았잖아.",
  str_homestory_817801001_34_dialog_content = "게다가 환상동물들의 대소변이나 털도 비크 씨는 한 번도 청소한 적 없었어.",
  str_homestory_817801001_35_dialog_content = "그런데도 골치 아픈 일을 더 벌이겠다는 거야?!",
  str_homestory_817801001_36_dialog_content = "너무 냉정하잖아, PlayerName~",
  str_homestory_817801001_37_dialog_content = "이게 어떻게 「골치 아픈 일」이야?",
  str_homestory_817801001_38_dialog_content = "이건 아스트라 대륙의 환상동물 연구에\n대한 공헌이야!",
  str_homestory_817801001_39_dialog_content = "억지 부리지 마!<sprite=emo_shengqi size=60 />",
  str_homestory_817801001_40_dialog_content = "아무튼 숲에서 환상동물 키우는 건 안 돼.",
  str_homestory_817801001_41_dialog_content = "잔디도, 계곡도, 강도 안 돼!",
  str_homestory_817801001_42_dialog_content = "휴, 알았어.",
  str_homestory_817801001_43_dialog_content = "정말, 요즘 젊은 애들은 노인네한테\n너무 엄하게 군단 말이지.",
  str_homestory_817701001_0_dialog_content = "골디!",
  str_homestory_817701001_1_dialog_content = "아, 골디를 발견했어!<sprite=emo_yaosu size=60 />",
  str_homestory_817701001_2_dialog_content = "어머, PlayerName 씨.\n나 방금 무대에서 내 신곡 부르고 있었어.",
  str_homestory_817701001_3_dialog_content = "휴~ 왠지 엄청 긴장되네. 다들 마음에 들어 할까?",
  str_homestory_817701001_4_dialog_content = "어떻게 생각해?",
  str_homestory_817701001_5_dialog_content = "정말 듣기 좋았어~",
  str_homestory_817701001_6_dialog_content = "다들 분명히 좋아할 거야!",
  str_homestory_817701001_7_dialog_content = "헤헤, PlayerName 씨가 그렇게\n말해주니 안심이야~",
  str_homestory_817701001_8_dialog_content = "사실 나 계속 고민하고 있는 일이 있어.",
  str_homestory_817701001_9_dialog_content = "그래서 PlayerName 씨 의견을 듣고 싶거든.",
  str_homestory_817701001_10_dialog_content = "무슨 일인데? 네가 고민할 일이라니...",
  str_homestory_817701001_11_dialog_content = "새 앨범의 타이틀곡을 골라야 하거든~",
  str_homestory_817701001_12_dialog_content = "하나는 평소의 나답게 밝고 활기찬 <sprite=emo_taiyang size=60 />곡이야.",
  str_homestory_817701001_13_dialog_content = "그리고 다른 하나는 새롭게 도전해 본\n쿨한 분위기<sprite=emo_mojing size=60 />의 곡이야.",
  str_homestory_817701001_14_dialog_content = "저기, PlayerName 넌 어떻게 생각해?\n나 이미지 바꾸는 게 좋을까?",
  str_homestory_817701001_15_option_content = "바꿔보는 것도 좋아.",
  str_homestory_817701001_16_dialog_content = "가끔 새로운 스타일의 곡을 시도해 보는 것도 좋잖아!",
  str_homestory_817701001_17_option_content = "바꿀 필요 없어.",
  str_homestory_817701001_18_dialog_content = "역시 그렇지? 익숙한 스타일이라면\n더 멋지게 부를 수 있을 거야!",
  str_homestory_817701001_19_dialog_content = "대신 앨범의 전체적인 테마를 생각해야 하지 않을까?",
  str_homestory_817701001_20_dialog_content = "맞아! 이번 새 앨범의 주제는 성장이야.",
  str_homestory_817701001_21_dialog_content = "회사에서 막대한 투자를 해서 제작한 정규 앨범이야~",
  str_homestory_817701001_22_dialog_content = "어라, 그럼 매니저는 뭔가 제안한 거 없어?",
  str_homestory_817701001_23_dialog_content = "매니저는 지금 스타일 그대로가 좋다고 하더라고.",
  str_homestory_817701001_24_dialog_content = "새로운 스타일을 좋아하지 않는 팬들도 있으니까...",
  str_homestory_817701001_25_dialog_content = "보수적인 제안이네.",
  str_homestory_817701001_26_dialog_content = "하지만 난 팬들이 있는 그대로의 골디를 좋아할 거라고 생각해.",
  str_homestory_817701001_27_dialog_content = "그러니까 네가 어떻게 변하든 팬들은 지금까지 해 온 것처럼 응원해 줄 거야!",
  str_homestory_817701001_28_dialog_content = "그러니까 난 네가 마음속으로 원하는 걸 따랐으면 좋겠어.",
  str_homestory_817701001_29_dialog_content = "네가 정말로 원하는 스타일을 선택하는 거야.",
  str_homestory_817701001_30_dialog_content = "응!",
  str_homestory_817701001_31_dialog_content = "나 정했어! 타이틀곡은──",
  str_homestory_817701001_32_dialog_content = "타이틀곡은──",
  str_homestory_817701001_33_dialog_content = "밝고 활기찬 곡으로 할래!",
  str_homestory_817701001_34_dialog_content = "어?",
  str_homestory_817701001_35_dialog_content = "왜냐하면 그게 있는 그대로의 나인걸.",
  str_homestory_817701001_36_dialog_content = "역시 나한테 가장 어울리는 건 밝고 활기찬 곡이야!",
  str_homestory_817701001_37_dialog_content = "아무래도 매니저는 골디를 잘 아는 모양이네...",
  str_homestory_818001001_0_dialog_content = "브랜디?",
  str_homestory_818001001_1_dialog_content = "음... 응원봉은 이쪽에 놓는 게 좋을까?\n음... 왠지 좀 이상한데?",
  str_homestory_818001001_2_dialog_content = "뭐 해?",
  str_homestory_818001001_3_dialog_content = "앗! 마침 잘 오셨어요!",
  str_homestory_818001001_4_dialog_content = "응원봉은 왼쪽에 놓는 게 좋을까요?\n아니면 오른쪽?",
  str_homestory_818001001_5_option_content = "왼쪽이 낫겠네.",
  str_homestory_818001001_6_dialog_content = "역시 오른쪽이 좋을 것 같네요.",
  str_homestory_818001001_7_option_content = "둘 다 똑같지 않아?",
  str_homestory_818001001_8_dialog_content = "하긴 그렇네요. 그럼 오른쪽으로 하죠.",
  str_homestory_818001001_9_dialog_content = "......",
  str_homestory_818001001_10_dialog_content = "뭐 하고 있어?",
  str_homestory_818001001_11_dialog_content = "《골디, 헤븐즈 가든 콘서트 대성공》 기사에\n넣을 사진을 찍고 있어요.",
  str_homestory_818001001_12_dialog_content = "지금은 응원 도구를 촬영하고 있는데요.",
  str_homestory_818001001_13_dialog_content = "형광봉, 조명판, 그리고 스티커, 카드...",
  str_homestory_818001001_14_dialog_content = "게다가 골디 씨 프린트 티셔츠도 있어요!\n진짜 너무 귀여워요!",
  str_homestory_818001001_15_dialog_content = "그러고 보니까 등신대 패널은 없는 것 같네요...",
  str_homestory_818001001_16_dialog_content = "있었으면 몰래 방에 가져가려고\n생각하고 있었는데 말이죠...<sprite=emo_sikao size=60 />",
  str_homestory_818001001_17_dialog_content = "앗! 어쩌면 혹시 처음엔 등신대 패널도\n있었던 건 아닐까요?!",
  str_homestory_818001001_18_dialog_content = "어떤 도덕성이 결여된 팬이 벌써\n가져가 버린 걸지도 모르잖아요...",
  str_homestory_818001001_19_dialog_content = "그런 나쁜! 어떻게 그런 짓을 할 수가 있죠?!",
  str_homestory_818001001_20_dialog_content = "그게 아까 네가 하려고 했던 거잖아...",
  str_homestory_818001001_21_dialog_content = "뭐, 됐어요. 일단 있는 것만 찍어야겠네요.",
  str_homestory_818001001_22_dialog_content = "본인이 옆에 있는데 왜 응원 도구를 찍어?",
  str_homestory_818001001_23_dialog_content = "그거 주객전도 아니야?",
  str_homestory_818001001_24_dialog_content = "잘 모르시네요.\n이런 수법은 돋보이게 하는 효과가 있는데...",
  str_homestory_818001001_25_dialog_content = "앗, 잠깐만요!",
  str_homestory_818001001_26_dialog_content = "갑자기 뭘 놀라고 그래?",
  str_homestory_818001001_27_dialog_content = "지금 나무 그림자가 조명판에 걸려 있네요.",
  str_homestory_818001001_28_dialog_content = "빛과 그림자가 겹치면서 나무 무늬가 희미하게\n생생한 정경을 만들어내고 있어요!",
  str_homestory_818001001_29_dialog_content = "셔터 찬스예요!",
  str_homestory_818001001_30_dialog_content = "멋진 컷이네요~\n이렇게 완벽한 사진은 처음이에요~",
  str_homestory_818001001_31_dialog_content = "이번 기사에 써야겠어요!",
  str_homestory_818001001_32_dialog_content = "그러니까 왜 골디 본인의 사진을 안 쓰는 거냐고!",
  str_homestory_818001001_33_dialog_content = "좋아, 촬영 종료! 이제 현상하러 가야겠네요.",
  str_homestory_818001001_34_dialog_content = "아, 그러고 보니 아까 보니까 강에 뭔가 있던데요.\n한번 보러 가실래요?",
  str_homestory_818001001_35_dialog_content = "내 말... 전혀 안 듣고 있잖아...",
  str_homestory_818101001_0_dialog_content = "종서 씨?",
  str_homestory_818101001_1_dialog_content = "종서 씨, 뭐 보고 있어요?",
  str_homestory_818101001_2_dialog_content = "귀공은 이 선반 안을 한번 보시오.",
  str_homestory_818101001_3_dialog_content = "선반이 뭐가 다른데요?<sprite=emo_sikao size=60 />",
  str_homestory_818101001_4_dialog_content = "아, 봤어요! 일심이 안에 있네요!",
  str_homestory_818101001_5_dialog_content = "잠시 못 본 사이에 안으로 들어가 버렸소.",
  str_homestory_818101001_6_dialog_content = "일심이 그런 개구쟁이인 줄은 몰랐네요.",
  str_homestory_818101001_7_dialog_content = "사실 일몽과 일낙도 안에 있소.",
  str_homestory_818101001_8_dialog_content = "네? 고양이들이 이 선반을 그렇게 좋아해요?",
  str_homestory_818101001_9_dialog_content = "고양이는 좁고 어두운 곳을 선호하는 습성이\n있기 때문일 것이오.",
  str_homestory_818101001_10_dialog_content = "그러고 보니 이 선반 안은 어둡고,\n여러 단으로 나누어져 있소.",
  str_homestory_818101001_11_dialog_content = "음, 아무래도 신식 고양이 집 같네요!",
  str_homestory_818101001_12_dialog_content = "신식 고양이 집? 확실히 일리가 있군.",
  str_homestory_818101001_13_dialog_content = "나중에 장인을 불러 이 모양을 본따\n하나 만들어도 되겠는가?",
  str_homestory_818101001_14_dialog_content = "물론이죠. 언제든지 환영이에요!",
  str_homestory_818101001_15_dialog_content = "저도 이 선반에 그런 쓸모가 있는지는 몰랐네요.",
  str_homestory_818101001_16_dialog_content = "고맙소.",
  str_homestory_818101001_17_dialog_content = "허나 녀석들이 귀공을 번거롭게 만들지는 않았소?",
  str_homestory_818101001_18_option_content = "전혀 그렇지 않아요!",
  str_homestory_818101001_19_option_content = "조금 그렇긴 해요...",
  str_homestory_818101001_20_dialog_content = "미안하군. 이 종 모가 잘 타일러 두겠소.",
  str_homestory_818101001_21_dialog_content = "근데 지금 문제는... 쟤들을 어떻게 밖으로 꺼내죠?",
  str_homestory_818101001_22_dialog_content = "왠지 안에서 기분 좋게 자고 있는 것 같아요.",
  str_homestory_818101001_23_dialog_content = "평소라면 이름만 불러도 나왔을 것이오.\n헌데 오늘은 반응을 보이지 않는군.",
  str_homestory_818101001_24_dialog_content = "음... 어쩌면 고양이들이 종서 씨를 잘 알아서 그런 거겠죠.",
  str_homestory_818101001_25_dialog_content = "그게 무슨 뜻이오?<sprite=emo_wuzui size=60 />",
  str_homestory_818101001_26_dialog_content = "평소 종서 씨가 고양이들을 부르는 건 주로 볼일이 있을 때잖아요.",
  str_homestory_818101001_27_dialog_content = "하지만 오늘 종서 씨는 고양이들을 선반에서 꺼내기 위해서만 불렀죠.",
  str_homestory_818101001_28_dialog_content = "그래서 고양이들은 종서 씨 말을 안 들은 거예요.",
  str_homestory_818101001_29_dialog_content = "세 마리 다 정말 똑똑하네요!",
  str_homestory_818101001_30_dialog_content = "...아무래도 이 선반에는 비범한 마력이 있는 듯하군.",
  str_homestory_818101001_31_dialog_content = "꼭 녀석들에게 하나 만들어 줘야겠소.",
  str_homestory_818101001_32_dialog_content = "그럼 고양이들은 어떡해요?",
  str_homestory_818101001_33_dialog_content = "이렇게 된 이상 깨어날 때까지 기다려야겠지.",
  str_homestory_818101001_34_dialog_content = "그럼 고양이들이 이겼네요!",
  str_homestory_818101001_35_dialog_content = "하지만 정말 기묘한 광경이네요.",
  str_homestory_818101001_36_dialog_content = "모르는 사람은 종서 씨가 또 뭔가 철학적인 문제를 생각하는 줄 알겠죠...",
  str_homestory_818301001_0_dialog_content = "리청?",
  str_homestory_818301001_1_dialog_content = "음, 어디 갔지...",
  str_homestory_818301001_2_dialog_content = "리청? 신기하네, 지금 뭐 해?",
  str_homestory_818301001_3_dialog_content = "아, 안녕, PlayerName.",
  str_homestory_818301001_4_dialog_content = "작은꼬리를 찾고 있어. 혹시 못 봤어?",
  str_homestory_818301001_5_dialog_content = "못 봤어. 무슨 일인데?",
  str_homestory_818301001_6_dialog_content = "흥, 뭐 별일 있겠어?\n또 평소처럼 농땡이 부리는 거겠지!<sprite=emo_shengqi size=60 />",
  str_homestory_818301001_7_dialog_content = "아까 약초 따러 마당에 나갈 때 데려갔거든...",
  str_homestory_818301001_8_dialog_content = "근데 잠깐 못 본 사이에 사라져버렸어!",
  str_homestory_818301001_9_dialog_content = "헤븐즈 가든에도 약초가 있어?",
  str_homestory_818301001_10_dialog_content = "당연하지.",
  str_homestory_818301001_11_dialog_content = "좋은 약이란 건 생각지도 못한 곳에 있는 법이야.",
  str_homestory_818301001_12_dialog_content = "중요한 건 그걸 찾기 위한 안목이라구<sprite=emo_mojing size=60 />.",
  str_homestory_818301001_13_dialog_content = "역시 리청이네!",
  str_homestory_818301001_14_dialog_content = "근데...",
  str_homestory_818301001_15_option_content = "얼마나 찾고 있었어?",
  str_homestory_818301001_16_dialog_content = "그... 음... 한 30분 정도?",
  str_homestory_818301001_17_dialog_content = "그렇게나 오래?",
  str_homestory_818301001_18_dialog_content = "아, 잘못 말했어! 아마 한 10분 정도일 거야!",
  str_homestory_818301001_19_option_content = "그래서 어떤 약초를 구했는데?",
  str_homestory_818301001_20_dialog_content = "그, 그냥... 약초야!",
  str_homestory_818301001_21_dialog_content = "리청, 왜 안절부절못하고 그래?",
  str_homestory_818301001_22_dialog_content = "아니거든!",
  str_homestory_818301001_23_dialog_content = "설마...",
  str_homestory_818301001_24_dialog_content = "리청 너도 농땡이 치는 거였어?",
  str_homestory_818301001_25_dialog_content = "그, 그, 그, 그럴 리가 없잖아!",
  str_homestory_818301001_26_dialog_content = "나랑 작은꼬리는 약초 따러 왔을 뿐이라구!",
  str_homestory_818301001_27_dialog_content = "근데...",
  str_homestory_818301001_28_dialog_content = "근데?",
  str_homestory_818301001_29_dialog_content = "여긴 너무 편안해...",
  str_homestory_818301001_30_dialog_content = "그래서 조금 자버렸어<sprite=emo_kun size=60 />. 아주 조금!",
  str_homestory_818301001_31_dialog_content = "그러다 눈을 떴더니 작은꼬리가 없어져서...",
  str_homestory_818301001_32_dialog_content = "하하하, 너희 형제들은 둘 다 땡땡이들이었구나.",
  str_homestory_818301001_33_dialog_content = "아, 아니라구!",
  str_homestory_818201001_0_dialog_content = "뭐 하고 있어요?",
  str_homestory_818201001_1_dialog_content = "물의 호흡을 느끼고 있어.",
  str_homestory_818201001_2_dialog_content = "의미는 모르겠는데 왠지 대단한 일 같네요.",
  str_homestory_818201001_3_dialog_content = "당신은 물의 호흡을 느껴본 적 있어?",
  str_homestory_818201001_4_option_content = "있어요.",
  str_homestory_818201001_5_dialog_content = "정말? 어땠어?",
  str_homestory_818201001_6_dialog_content = "차갑고, 상쾌하고, 갈증이 사라졌어요.",
  str_homestory_818201001_7_dialog_content = "그건 물의 맛이지 호흡이 아니야.",
  str_homestory_818201001_8_option_content = "없어요.",
  str_homestory_818201001_9_dialog_content = "배우고 싶다면 내가 가르쳐 줄게.",
  str_homestory_818201001_10_dialog_content = "좋아요.",
  str_homestory_818201001_11_dialog_content = "그럼 시작하자.",
  str_homestory_818201001_12_dialog_content = "지금요? 저 수영복 안 가져왔는데요...",
  str_homestory_818201001_13_dialog_content = "오늘은 물가에서 기본 동작을 연습하기만 하면 돼.",
  str_homestory_818201001_14_dialog_content = "바르게 서서 가슴을 펴고, 얼굴을 들고,\n심호흡을 하고, 물의 흐름을 느껴 봐.",
  str_homestory_818201001_15_dialog_content = "어렵지 않을 것 같네요. 해볼게요.",
  str_homestory_818201001_16_dialog_content = "스읍──",
  str_homestory_818201001_17_dialog_content = "후우──",
  str_homestory_818201001_18_dialog_content = "근데 언제까지 이러고 서 있어야 되는데요?",
  str_homestory_818201001_19_dialog_content = "1만 시간.",
  str_homestory_818201001_20_dialog_content = "1만 시간이요?!",
  str_homestory_818201001_21_dialog_content = "평범한 이가 비범해지기 위해서는\n1만 시간의 단련이 반드시 필요해.",
  str_homestory_818201001_22_dialog_content = "그렇긴 해도... 아무리 그래도 1만 시간은 너무 지루하잖아요<sprite=emo_xinsui size=60 />...",
  str_homestory_818201001_23_dialog_content = "그만두고 싶으면 지금 당장 그만둬도 돼.",
  str_homestory_818201001_24_dialog_content = "재미있는 일은 얼마든지 있겠지.\n하지만 성공을 향한 길은 보통 그리 즐거운 게 아냐.",
  str_homestory_818201001_25_dialog_content = "미안해요. 그럼 계속 노력할게요!",
  str_homestory_818201001_26_dialog_content = "월백 씨도 그런 괴로운 수행을 이겨내고, 수영을 잘하게 된 건가요?",
  str_homestory_818201001_27_dialog_content = "수행해본 적 없어. 타고난 거지.",
  str_homestory_818201001_28_dialog_content = "???",
  str_homestory_818201001_29_dialog_content = "그럼 저한테 1만 시간 얘기한 건 절 놀린 건가요?!",
  str_homestory_818201001_30_dialog_content = "아니, 내가 처음 수영을 배웠을 때,\n린 가문의 장로님이 그렇게 가르쳐 주셨어.",
  str_homestory_818201001_31_dialog_content = "그저 난 태어날 때부터 물과 공명할 수 있어서,\n그런 수행을 할 필요가 없었을 뿐이야.",
  str_homestory_818201001_32_dialog_content = "아, 린 가문의 장로님이 그렇게 가르치셨다면, 분명히 의미가 있겠네요.",
  str_homestory_818201001_33_dialog_content = "그럼 계속 서 있을게요...",
  str_homestory_818201001_34_dialog_content = "조금 쉴래요... 다리가 진짜로 저려요...<sprite=emo_tanqi size=60 />",
  str_homestory_818201001_35_dialog_content = "그럼 하지 마.",
  str_homestory_818201001_36_dialog_content = "네? 근데 린 가문 장로님이...",
  str_homestory_818201001_37_dialog_content = "장로님은 수영을 못하셔.\n그건 아마 그냥 한 말씀이었겠지.",
  str_homestory_818201001_38_dialog_content = "!!!",
  str_homestory_818201001_39_dialog_content = "내가 보기에 당신은 물가에 1만 시간을 서 있어도,\n물과 공명할 수 없을 것 같아.",
  str_homestory_818201001_40_dialog_content = "어떤 일은 재능이 필요한 법이야.\n없다면 무리하지 마.",
  str_homestory_818201001_41_dialog_content = "진작 말하지 그랬어요!",
  str_homestory_818201001_42_dialog_content = "당신이 진지하게 하길래 방해할 수가 없었어.",
  str_homestory_818201001_43_dialog_content = "월백 씨!",
  str_homestory_818201001_44_dialog_content = "으아아아... 다리에 쥐가 났어요...",
  str_homestory_818201001_45_dialog_content = "내가 업어줄게.",
  str_homestory_818201001_46_dialog_content = "안 돼요. 사내자식이 돼가지고 어떻게...",
  str_homestory_818201001_47_dialog_content = "그럼 난 갈게.",
  str_homestory_818201001_48_dialog_content = "자, 잠깐만요... 음... 일단 좀 쪼그려 앉아주면 안 돼요?",
  str_homestory_816001001_0_dialog_content = "미카엘?",
  str_homestory_816001001_1_dialog_content = "뭐 보고 있어?",
  str_homestory_816001001_2_dialog_content = "(아, PlayerName, 왔군요.)",
  str_homestory_816001001_3_dialog_content = "(이 촛대를 보고 있었습니다.)",
  str_homestory_816001001_4_dialog_content = "그게 마음에 드나 보네? 선물로 줄까?",
  str_homestory_816001001_5_dialog_content = "(아니요, 제가 살게요. 얼마인가요?)",
  str_homestory_816001001_6_dialog_content = "(지금 1000나이티움이 있어요<sprite=emo_baiyebi size=60 />. 이걸로 되나요?)",
  str_homestory_816001001_7_dialog_content = "아, 아니야, 아니야, 그렇게 많이는 필요 없어.",
  str_homestory_816001001_8_dialog_content = "만약 돈을 내려고 한다면 난 안 팔 거야.",
  str_homestory_816001001_9_dialog_content = "(어째서죠?!)",
  str_homestory_816001001_10_dialog_content = "왜 실망하는 건데?",
  str_homestory_816001001_11_dialog_content = "알았어. 미카엘 넌 예전부터 소품 모으는 게 취미였잖아?",
  str_homestory_816001001_12_dialog_content = "확실히 미카엘네 방에는 이것저것 특이한 게 산더미처럼 쌓여 있었지.",
  str_homestory_816001001_13_dialog_content = "(이 취미가 이상한가요?)",
  str_homestory_816001001_14_option_content = "(인정한다)",
  str_homestory_816001001_15_dialog_content = "사실 어떤 건 딱 봐도 완전히 망가진 물건 같은데, 넌 계속 보관하고 있잖아.",
  str_homestory_816001001_16_dialog_content = "그런 취미는 다른 사람들과는 조금 다르지 않을까?",
  str_homestory_816001001_17_option_content = "(부정한다)",
  str_homestory_816001001_18_dialog_content = "사람마다 다른 취미가 있기 마련이야. 난 이상하다고 생각 안 해.",
  str_homestory_816001001_19_dialog_content = "그저 미카엘이 수집하는 물건의 종류가 좀 다양하다고 생각했을 뿐이야.",
  str_homestory_816001001_20_dialog_content = "(전 그저 그것들이 재미있기 때문에 모으는 겁니다.)",
  str_homestory_816001001_21_dialog_content = "(다만 이 촛대를 사고 싶은 이유가\n따로 있습니다.)",
  str_homestory_816001001_22_dialog_content = "어떤 이유인데?",
  str_homestory_816001001_23_dialog_content = "(촛대의 양초는 인화성 물질입니다.\n화재를 일으킬까 걱정이 됩니다<sprite=emo_nuhuo size=60 />.)",
  str_homestory_816001001_24_dialog_content = "(많은 재앙의 근원은 대부분 작은 것에서\n비롯되는 법입니다.)",
  str_homestory_816001001_25_dialog_content = "(조금... 이해하기 어려운가요?)",
  str_homestory_816001001_26_dialog_content = "음, 이해는 되는데...",
  str_homestory_816001001_27_dialog_content = "그러니까 미카엘 넌 내 안전을 생각해서 그런 거야?",
  str_homestory_816001001_28_dialog_content = "(백야성을 지키는 것은 제 직무입니다.)",
  str_homestory_816001001_29_dialog_content = "(그리고 당신은 제게 많은 도움을 주었습니다.\n당신을 지키는 것은 제 소망이기도 합니다.)",
  str_homestory_816001001_30_dialog_content = "나야말로 미카엘한테 도움을 많이 받았는걸.",
  str_homestory_816001001_31_dialog_content = "근데... 그게 촛대 사려는 핑곗거리는 아니지?",
  str_homestory_816001001_32_dialog_content = "(물론 아닙니다!)",
  str_homestory_816001001_33_dialog_content = "(수호하는 자는 신중해야 하는 법입니다.)",
  str_homestory_816001001_34_dialog_content = "어? 미카엘 너 왜 얼굴이 빨개졌어?",
  str_homestory_816001001_35_dialog_content = "(...촛불의 열기 탓입니다.)",
  str_homestory_816001001_36_dialog_content = "(그러고 보니 아까 제가 강에서 빛나는\n물건을 발견했습니다.)",
  str_homestory_816001001_37_dialog_content = "(마치 이 촛불 같았습니다.)",
  str_homestory_816001001_38_dialog_content = "왠지 말을 돌리려는 느낌인데...",
  str_homestory_818401001_0_dialog_content = "저기, 예리아 씨~",
  str_homestory_818401001_1_dialog_content = "......",
  str_homestory_818401001_2_dialog_content = "예리아 씨? 저기요~",
  str_homestory_818401001_3_dialog_content = "응? 아이테르 군이잖아.",
  str_homestory_818401001_4_dialog_content = "뭔데 그렇게 집중하고 있어요?",
  str_homestory_818401001_5_dialog_content = "아... 그냥 조금 멍하니 있었어.",
  str_homestory_818401001_6_dialog_content = "멍하니 있었다고요?",
  str_homestory_818401001_7_dialog_content = "내가 말했었나?\n전에 난 이 근처의 유적에 간 적 있다고.",
  str_homestory_818401001_8_dialog_content = "그땐 네가 아직 여기 돌아오지 않았을 때였어.",
  str_homestory_818401001_9_dialog_content = "여긴 온통 폐허였고, 암귀뿐이었어<sprite=emo_kulou size=60 />.",
  str_homestory_818401001_10_dialog_content = "휴, 말도 마세요. 여기 청소하느라 얼마나 힘들었는데요!",
  str_homestory_818401001_11_dialog_content = "응, 쉽지 않았겠지.",
  str_homestory_818401001_12_dialog_content = "말이 나온 김에, 하나만 물을게.",
  str_homestory_818401001_13_dialog_content = "넌 헤븐즈 가든을 재건하는 일이\n의미가 있다고 생각하니?",
  str_homestory_818401001_14_dialog_content = "지금 헤븐즈 가든은 이렇게 아름답지만,\n습격을 받는다거나, 백 년 뒤 네가 떠나게 된다면...",
  str_homestory_818401001_15_dialog_content = "이곳의 모든 게 다시 폐허로 변할 거야.",
  str_homestory_818401001_16_option_content = "의미가 있어요.",
  str_homestory_818401001_17_dialog_content = "있죠! 적어도 당장은 다들 신나게 놀고 있잖아요.",
  str_homestory_818401001_18_dialog_content = "적이 온다면 제가 쫓아내면 되고요.",
  str_homestory_818401001_19_dialog_content = "제가 여길 돌볼 수 없게 된다면 믿을 만한 사람한테 맡겨야죠.",
  str_homestory_818401001_20_dialog_content = "방법은 다 있어요!",
  str_homestory_818401001_21_dialog_content = "아이테르 군은 정말 진취적이구나.",
  str_homestory_818401001_22_option_content = "없는 것 같네요.",
  str_homestory_818401001_23_dialog_content = "헤븐즈 가든을 영원히 존재하게 하는 게 목적이라면 별 의미가 없겠죠.",
  str_homestory_818401001_24_dialog_content = "전 제 능력을 잘 알고 있어요...",
  str_homestory_818401001_25_dialog_content = "하지만 적어도 당장은 모두가 즐겁잖아요.",
  str_homestory_818401001_26_dialog_content = "그럼 된 거예요!",
  str_homestory_818401001_27_dialog_content = "「지금을 살아라」라는 건가, 나쁘지 않네.",
  str_homestory_818401001_28_dialog_content = "내가 처음 헤븐즈 밸리에 왔을 땐,\n여기가 참 슬픈 곳이라고 생각했어.",
  str_homestory_818401001_29_dialog_content = "엎어진 식기, 반쯤 열린 집, 어수선한 옷가지.",
  str_homestory_818401001_30_dialog_content = "여기 살던 사람들의 평범하고 행복한 나날들을\n쉽게 떠올릴 수 있었어.",
  str_homestory_818401001_31_dialog_content = "근데 그런 나날들이, 후──\n마치 민들레<sprite=emo_pugongying size=60 />처럼 날아가버렸던 거지.",
  str_homestory_818401001_32_dialog_content = "아...",
  str_homestory_818401001_33_dialog_content = "하지만 민들레도 희망의 씨앗을 더 먼 곳으로 가져갈 수 있어요.",
  str_homestory_818401001_34_dialog_content = "이 모든 게 결코 무의미한 게 아니에요!",
  str_homestory_818401001_35_dialog_content = "그러게, 너라는 작은 씨앗이 이렇게 돌아와서\n다시 싹을 틔웠으니까.",
  str_homestory_818401001_36_dialog_content = "너랑 이야기하면 늘 뭔가 다른 느낌을 받는 것 같아.",
  str_homestory_818401001_37_dialog_content = "헤헤, 과찬이에요.",
  str_homestory_818401001_38_dialog_content = "음... 답례로 재밌는 일을 알려줄게.",
  str_homestory_818401001_39_dialog_content = "아까 강가에 있을 때 물속에서 빛나는 뭔가를 봤어.",
  str_homestory_818401001_40_dialog_content = "한번 가서 봐봐, 「탐험」 한 번 한다고 생각하고.",
  str_homestory_818401001_41_dialog_content = "재밌을 거 같네요... 고마워요, 예리아 씨!",
  str_homestory_818501001_0_dialog_content = "왜 그래?",
  str_homestory_818501001_1_dialog_content = "방금 회전 커피잔을 탔더니...\n머리가 좀 어지러워요<sprite=emo_xuanyun size=60 />...",
  str_homestory_818501001_2_dialog_content = "머리가 어지럽다니? 기구 성능에 문제라도 생겼나?",
  str_homestory_818501001_3_dialog_content = "회전 횟수를 최저로 설정한 걸로 기억하는데, 이따 내가 가서 확인해볼게.",
  str_homestory_818501001_4_dialog_content = "아주 위험한 놀이기구니까, 조심하셔야 해요!",
  str_homestory_818501001_5_dialog_content = "위험?",
  str_homestory_818501001_6_dialog_content = "그거 4세 이상 어린이용 아니었나?",
  str_homestory_818501001_7_dialog_content = "아무래도 20세 어른이한테는 안 맞나 봐요...",
  str_homestory_818501001_8_dialog_content = "회전에 익숙하지 않은 사람도 있는 법이니까.",
  str_homestory_818501001_9_dialog_content = "조금 쉬면 괜찮아질 거야.",
  str_homestory_818501001_10_dialog_content = "네, 전 먼저 가볼게요.\n이따 편지 배달하러 북방에 가야 하거든요...",
  str_homestory_818501001_11_dialog_content = "응? 남쪽... 북쪽...",
  str_homestory_818501001_12_dialog_content = "어떡해요! 방향을 모르겠어요!",
  str_homestory_818501001_13_dialog_content = "제가 자부하는 방향 감각이 없어졌는데요?!",
  str_homestory_818501001_14_dialog_content = "흑흑<sprite=emo_daku size=60 />, 편지를 배달할 수 없다니,\n제 커리어도 이렇게 끝나는 걸까요?",
  str_homestory_818501001_15_dialog_content = "뭐? 그렇게 심각하다고?",
  str_homestory_818501001_16_dialog_content = "PlayerName 씨...\n북쪽이 어딘지 알려주실 수 있나요?",
  str_homestory_818501001_17_option_content = "왼쪽이야.",
  str_homestory_818501001_18_dialog_content = "그런가요? 전혀 모르겠는데요...",
  str_homestory_818501001_19_option_content = "나도 모르겠어.",
  str_homestory_818501001_20_dialog_content = "역시, 당신마저...",
  str_homestory_818501001_21_dialog_content = "그럼 우린 결국 여기 갇혀 죽는 건가요?",
  str_homestory_818501001_22_dialog_content = "???",
  str_homestory_818501001_23_dialog_content = "보통 자기 집에 갇혀 죽진 않잖아?",
  str_homestory_818501001_24_dialog_content = "그러고 보니 이젠 제가 어디 있는지도 모르겠어요...",
  str_homestory_818501001_25_dialog_content = "쿠리어 길드 수칙에 따르면,\n쿠리어는 언제나 방향 감각을 유지해야 해요.",
  str_homestory_818501001_26_dialog_content = "많은 쿠리어가 방향을 잃고 위험에 빠져서\n탈출하지 못한 적이 많았거든요.",
  str_homestory_818501001_27_dialog_content = "그런 경우는 보통 야외나 밀림에 있을 때가 아닐까?",
  str_homestory_818501001_28_dialog_content = "우린 헤븐즈 가든 안에 있어. 저 문 보여?",
  str_homestory_818501001_29_dialog_content = "저쪽으로 몇 걸음만 가면 나갈 수 있어.",
  str_homestory_818501001_30_dialog_content = "하지만 제가 밖에 있을 때도 지금처럼 어지럽다면요?",
  str_homestory_818501001_31_dialog_content = "밖에도 회전 커피잔이 있을까?",
  str_homestory_818501001_32_dialog_content = "아아, 그렇네요...",
  str_homestory_818501001_33_dialog_content = "그리고 진짜 있다고 해도 그냥 안 타면 되지~",
  str_homestory_818501001_34_dialog_content = "맞아요! 당신은 정말 똑똑하네요!",
  str_homestory_818501001_35_dialog_content = "하하하~ 그거 당연하지~",
  str_homestory_818501001_36_dialog_content = "가서 쿠리어 길드 수칙에 추가해야겠어요!",
  str_homestory_818501001_37_dialog_content = "「밖에서 회전 커피잔을 보면 절대 타지 마라!」",
  str_homestory_818501001_38_dialog_content = "그런 걸 볼 확률이 많이 낮지 않나...",
  str_homestory_818501001_39_dialog_content = "「──아이테르의 충고」",
  str_homestory_818501001_40_dialog_content = "!!!",
  str_homestory_818501001_41_dialog_content = "얼마면 돼?! 얼마면 안 적을래?!",
  str_homestory_818501001_42_dialog_content = "네? 이건 아주 유용한 충고인걸요.\n그럼 먼저 갈게요.",
  str_homestory_818501001_43_dialog_content = "제발... 이러다간 쿠리어 길드의 웃음거리가 되고 말 거야...<sprite=emo_tanqi size=60 />",
  str_homestory_802901001_0_dialog_content = "가브리엘?",
  str_homestory_802901001_1_dialog_content = "뭐 하고 있어?",
  str_homestory_802901001_2_dialog_content = "나무 밑에서 쉬면서<sprite=emo_kun size=60 />, 나무의 숨을 느끼고 있었어.",
  str_homestory_802901001_3_dialog_content = "나무의 숨?",
  str_homestory_802901001_4_dialog_content = "그래... 나무에도 생명이 있거든.",
  str_homestory_802901001_5_dialog_content = "너무의 들숨과 날숨의 빈도를 느낄 수 있어.\n넌 느껴지지 않니, PlayerName?",
  str_homestory_802901001_6_option_content = "(인정한다)",
  str_homestory_802901001_7_dialog_content = "응, 나뭇잎이 흔들릴 때마다 나무가 가쁜 숨을 쉬는 것 같아~",
  str_homestory_802901001_8_dialog_content = "아니지, 역시 그냥 바람이 불어서 그런 건가...",
  str_homestory_802901001_9_option_content = "(부정한다)",
  str_homestory_802901001_10_dialog_content = "아, 안 느껴져...",
  str_homestory_802901001_11_dialog_content = "역시 가브리엘에겐 식물을 느끼는 특별한 능력이 있는 거지?",
  str_homestory_802901001_12_dialog_content = "모든 나무는 저마다 달라.\n사람마다 다른 것처럼 말이야.",
  str_homestory_802901001_13_dialog_content = "마음으로 느끼면... 저들의 상태를 알 수 있어.",
  str_homestory_802901001_14_dialog_content = "예를 들어 이 나무는 호흡이 고르지 않은 게,\n왠지 좀 아픈 것 같아...",
  str_homestory_802901001_15_dialog_content = "듣고 보니 다른 나무와 다르게 나뭇잎이 약간 노란 것 같잖아.",
  str_homestory_802901001_16_dialog_content = "확실히 기운이 없어 보이네.",
  str_homestory_802901001_17_dialog_content = "주위의 나무가 너무 무성하게 자라서,\n햇빛을 막아버린 거야<sprite=emo_taiyang size=60 />.",
  str_homestory_802901001_18_dialog_content = "이 아이는 광합성을 제대로 못 한 모양이네~",
  str_homestory_802901001_19_dialog_content = "아, 그럼 나무를 옮겨 심어야 하는 거야?",
  str_homestory_802901001_20_dialog_content = "그럴 필요는 없어~\n식물들도 나름대로 살아가는 방식이 있거든.",
  str_homestory_802901001_21_dialog_content = "이 나무가 노력하지 않은 만큼,\n다른 나무들이 햇빛을 더 가져가는 거지...",
  str_homestory_802901001_22_dialog_content = "결국 스스로 성장해야만 하는 거야...\n너무 안타까워하진 마~",
  str_homestory_802901001_23_dialog_content = "그렇구나. 가브리엘 말이 맞는 거 같아!",
  str_homestory_802901001_24_dialog_content = "음~ PlayerName 네가 이해하지 못할까 봐\n걱정했는데...",
  str_homestory_802901001_25_dialog_content = "아니야! 난 오히려 놀랐어.",
  str_homestory_802901001_26_dialog_content = "평소 멍해 보이던 가브리엘이 그렇게 진지한 말을 하다니 말이야.",
  str_homestory_802901001_27_dialog_content = "어머, 차라리 내가 「운명에 순응한다」고 말해줘...",
  str_homestory_802901001_28_dialog_content = "식물도 자기 「운명」이 있는 거니까...",
  str_homestory_802901001_29_dialog_content = "「운명」이라...",
  str_homestory_802901001_30_dialog_content = "그래, 내가 나무 밑에서 널 만난 것도\n바로 「운명」인 거야~",
  str_homestory_802901001_31_dialog_content = "그러고 보니까 아까 강을 따라 걸어올 때\n빛나는 무언가를 봤어...",
  str_homestory_802901001_32_dialog_content = "뭔지 확인해 보진 않았고?",
  str_homestory_802901001_33_dialog_content = "아, 난 그냥 나무 아래에서 쉬고 싶었거든~",
  str_homestory_802901001_34_dialog_content = "그래서 조사하러 강에 안 갔어.\n이것도 「운명」의 인도인 거겠지~",
  str_homestory_802901001_35_dialog_content = "가브리엘이 말한 「운명」이란 게 어떤 건지 대충 알 것 같아...",
  str_homestory_818901001_0_dialog_content = "레인 씨, 뭐해?",
  str_homestory_818901001_1_dialog_content = "저기── 레인 씨──",
  str_homestory_818901001_2_dialog_content = "와인 초콜릿, 과일 필링 초콜릿<sprite=emo_sikao size=60 />... 으음?",
  str_homestory_818901001_3_dialog_content = "아, 오셨군요.",
  str_homestory_818901001_4_dialog_content = "뭘 그렇게 열심히 하고 있어? 레인 씨.",
  str_homestory_818901001_5_dialog_content = "별거 아닙니다. 초콜릿 상자를 보고 있었습니다.",
  str_homestory_818901001_6_dialog_content = "그거 관월제 신상 초콜릿이야.",
  str_homestory_818901001_7_dialog_content = "레인 씨가 먹고 싶으면 얼마든지 먹어도 돼!",
  str_homestory_818901001_8_dialog_content = "아뇨, 먹고 싶진 않고,\n그저 초콜릿 공법이 좀 궁금합니다.",
  str_homestory_818901001_9_dialog_content = "저도 평소에 집에서 초콜릿 디저트를\n만들곤 하거든요.",
  str_homestory_818901001_10_dialog_content = "그래봤자 녹인 초콜릿을 장식으로\n사용한 정도였지만요.",
  str_homestory_818901001_11_dialog_content = "시중의 디저트 공법이 이렇게 발전했을\n줄은 몰랐습니다...",
  str_homestory_818901001_12_dialog_content = "그나저나 당신은 초콜릿을 좋아하시나요?",
  str_homestory_818901001_13_option_content = "좋아해!",
  str_homestory_818901001_14_dialog_content = "그럼 제가 새로운 공법을 배우면 맛보게 해드리죠.",
  str_homestory_818901001_15_dialog_content = "와인 초콜릿은 당신에겐 아직 이르니까...",
  str_homestory_818901001_16_dialog_content = "과일 필링으로 드리겠습니다.",
  str_homestory_818901001_17_option_content = "안 좋아해...",
  str_homestory_818901001_18_dialog_content = "그렇군요... 아쉽네요.",
  str_homestory_818901001_19_dialog_content = "그럼 다음에 다른 디저트를 가져다 드리죠.",
  str_homestory_818901001_20_dialog_content = "혹시 드시고 싶은 게 있다면 언제든 말씀하세요.",
  str_homestory_818901001_21_dialog_content = "좋지! 고마워, 레인 씨!",
  str_homestory_818901001_22_dialog_content = "으음...",
  str_homestory_818901001_23_dialog_content = "레인 씨, 왜 아직도 초콜릿을 뚫어져라 보고 있어?",
  str_homestory_818901001_24_dialog_content = "설마... 사실은 그냥 초콜릿이 먹고 싶은 거였지?",
  str_homestory_818901001_25_dialog_content = "그, 그냥 맛이 궁금했을 뿐입니다!<sprite=emo_hanshui size=60 />",
  str_homestory_818901001_26_dialog_content = "제가 직접 사서 연구할 겁니다!",
  str_homestory_818901001_27_dialog_content = "에이, 나한테까지 체면 차릴 거 없어.",
  str_homestory_818901001_28_dialog_content = "먹고 싶으면 먹어!",
  str_homestory_818901001_29_dialog_content = "사람은 누구나 당이 떨어질 때가 있다구.",
  str_homestory_818901001_30_dialog_content = "아니, 그...",
  str_homestory_818901001_31_dialog_content = "그럼 사양하지 않고 감사히 먹겠습니다...",
  str_homestory_818601001_0_dialog_content = "티나?",
  str_homestory_818601001_1_dialog_content = "네가 왜 여깄어?",
  str_homestory_818601001_2_dialog_content = "반가워요, PlayerName 씨~",
  str_homestory_818601001_3_dialog_content = "이 의자가 제 궁금증을 자극하네요.",
  str_homestory_818601001_4_dialog_content = "이 비치 선베드 말이야?",
  str_homestory_818601001_5_dialog_content = "네~ 비치 선베드라고 하는군요...",
  str_homestory_818601001_6_dialog_content = "사실 전 대부분의 시간을 백야성 심판소에서\n보내서 해변에 대해서는 잘 몰라요.",
  str_homestory_818601001_7_dialog_content = "PlayerName 씨는 해변에 자주 가나요?",
  str_homestory_818601001_8_option_content = "응.",
  str_homestory_818601001_9_dialog_content = "난 해변에 자주 가는 편이야.",
  str_homestory_818601001_10_dialog_content = "가서 놀면 무척 재밌거든!",
  str_homestory_818601001_11_option_content = "아니.",
  str_homestory_818601001_12_dialog_content = "사실 나도 잘 안 가.",
  str_homestory_818601001_13_dialog_content = "그래도 해변은 재미있어서, 무척 기억에 남는 것 같아.",
  str_homestory_818601001_14_dialog_content = "그렇군요~",
  str_homestory_818601001_15_dialog_content = "다음에 PlayerName 씨와 같이 갈 수\n있으면 좋겠네요~",
  str_homestory_818601001_16_dialog_content = "하지만 지금은 제가 심판소 일이\n많아서 좀 바쁘네요~",
  str_homestory_818601001_17_dialog_content = "언젠가는 기회가 있겠지.",
  str_homestory_818601001_18_dialog_content = "근데 해변은 수영복을 주로 입는데... 정말 괜찮아?",
  str_homestory_818601001_19_dialog_content = "수영복... 책에서 읽어봤어요.\n아주 면적이 작은 옷<sprite=emo_qunzi size=60 /> 맞죠?",
  str_homestory_818601001_20_dialog_content = "맞아, 근데 해변에서 백야성의 귀족 의상을 입으면 조금 더워 보이지 않을까...",
  str_homestory_818601001_21_dialog_content = "상황에 맞는 옷을 입어야죠. 전 괜찮아요~",
  str_homestory_818601001_22_dialog_content = "하지만 가문의 원로들이 절 나무라시진 않을지\n조금 무섭긴 하네요~",
  str_homestory_818601001_23_dialog_content = "크흠, 너무 깊게 생각하진 마...",
  str_homestory_818601001_24_dialog_content = "해변을 언제 갈 수 있을지도 아직 모르니까...",
  str_homestory_818601001_25_dialog_content = "그것도 그렇네요~",
  str_homestory_818601001_26_dialog_content = "아니면 비치 선베드에 누워볼래?",
  str_homestory_818601001_27_dialog_content = "네! 해보고 싶어요~",
  str_homestory_818601001_28_dialog_content = "제 전용 소파에 비해서는 덜 부드럽지만,\n꽤 편하네요~",
  str_homestory_818601001_29_dialog_content = "해변에서는 이런 재질이 더 실용적이거든.",
  str_homestory_818601001_30_dialog_content = "저기, 티나, 듣고 있어?",
  str_homestory_818601001_31_dialog_content = "잠들었잖아...",
  str_homestory_819001001_0_dialog_content = "마티외 씨?",
  str_homestory_819001001_1_dialog_content = "마침 잘 왔다.",
  str_homestory_819001001_2_dialog_content = "이 복고풍 정자는 차를 마시며 독서하기에\n좋아 보이는군.",
  str_homestory_819001001_3_dialog_content = "하지만 아직 부족한 점이 하나 있다──",
  str_homestory_819001001_4_dialog_content = "뭔데?",
  str_homestory_819001001_5_dialog_content = "지금 모습은 너무 단조롭다는 생각 안 드나?",
  str_homestory_819001001_6_option_content = "안 드는데.",
  str_homestory_819001001_7_option_content = "장식이 부족하긴 하네.",
  str_homestory_819001001_8_dialog_content = "나중에 쿠션 두어 개 가져올게, 그럼 괜찮을 거야.",
  str_homestory_819001001_9_dialog_content = "난 고급 화초와 금은 다기를 놓을 생각이다.\n그래야 나 같은 귀족이 쓸 만하지.",
  str_homestory_819001001_10_dialog_content = "고급 화초와 금은 다기... 그건 너무 사치 아니야?",
  str_homestory_819001001_11_dialog_content = "지금 돈 걱정<sprite=emo_baiyebi size=60 />을 하는 건가?\n참으로 알뜰한 아이테르로군.",
  str_homestory_819001001_12_dialog_content = "돈 문제는 걱정하지 마라. 내가 해결하지.",
  str_homestory_819001001_13_dialog_content = "돈 문제가 아니야. 물론 비용이 너무 많이 들면 그것도 문제긴 하겠지만.",
  str_homestory_819001001_14_dialog_content = "뭐 마티외 씨가 해결한다니까 문제는 없겠지. 근데...",
  str_homestory_819001001_15_dialog_content = "그래서 대체 하고 싶은 말이 뭐냐?",
  str_homestory_819001001_16_dialog_content = "여긴 헤븐즈 가든이야. 모두가 함께 사는 곳이잖아.",
  str_homestory_819001001_17_dialog_content = "모든 사람이 고급 화초나 금은 다기 같은 걸 좋아하는 건 아니야.",
  str_homestory_819001001_18_dialog_content = "그래서 난 너무 사치스럽게 만들고 싶지 않아.\n다른 오로리안들이 불편해할 것 같거든.",
  str_homestory_819001001_19_dialog_content = "지금 정상적인 삶을 누린 적 없는 자들을\n고려하고 있는 건가?",
  str_homestory_819001001_20_dialog_content = "꽃과 금은으로 둘러싸였다고 다 정상적인 삶은 아니야...",
  str_homestory_819001001_21_dialog_content = "아무튼 지금 바로 사람을 불러 꾸미겠다.",
  str_homestory_819001001_22_dialog_content = "잠깐만, 여긴 내 영역이야. 뭐든지 내 소관이라고.",
  str_homestory_819001001_23_dialog_content = "우리와 계속 함께 살고 싶다면, 당신도 다른 사람과 공존하는 법을 배워야 해.",
  str_homestory_819001001_24_dialog_content = "뭐야, 왜 갑자기 그런 진지한 말을 하는 거지?",
  str_homestory_819001001_25_dialog_content = "설마... 마티외 씨, 지금 <size=45>슈와브 씨</size>를 모방하는 거야?!",
  str_homestory_819001001_26_dialog_content = "하아? 무슨 소리야?",
  str_homestory_819001001_27_dialog_content = "슈와브 씨는 꽃으로 가득한 정자에서 독서를 즐긴대.\n그래서 많은 소녀들이 그 모습에 반했다고 들었어.",
  str_homestory_819001001_28_dialog_content = "마티외 씨도 그런 식으로 여자애들의 관심을 끌려는 거지?",
  str_homestory_819001001_29_dialog_content = "슈와브 씨처럼 인기 있고 싶으니까 따라하는 거 맞지.",
  str_homestory_819001001_30_dialog_content = "그런 거였어...",
  str_homestory_819001001_31_dialog_content = "뭐라는 거냐! 이해했다는 듯한 표정 짓지 마!<sprite=emo_shengqi size=60 />",
  str_homestory_819001001_32_dialog_content = "전혀 그런 거 아니거든!\n내가 왜 그런 바보를 따라해?",
  str_homestory_819001001_33_dialog_content = "「바보」라는 말은 다들 보통은 욕으로 듣겠지만...",
  str_homestory_819001001_34_dialog_content = "요즘은 호감 있는 사람한테도 쓴다고 들었어!",
  str_homestory_819001001_35_dialog_content = "역겹군...",
  str_homestory_819001001_36_dialog_content = "난 여명 아카데미 역사에 남을 천재다!",
  str_homestory_819001001_37_dialog_content = "그런 내가 어떻게 여자 앞에서 자기 이미지만\n생각하는 바보를 따라하겠냔 말이다!",
  str_homestory_819001001_38_dialog_content = "그럼 왜 복고풍 정자에 굳이 꽃이랑 다기를 두려는 거야?",
  str_homestory_819001001_39_dialog_content = "그건 귀족들의 공통된 취향일 뿐이라고!",
  str_homestory_819001001_40_dialog_content = "됐어, 그냥 네가 꾸미고 싶은 대로 꾸미도록 해.",
  str_homestory_819001001_41_dialog_content = "난 상관 안 할 테니까.",
  str_homestory_819001001_42_dialog_content = "(화가 엄청 난 모양이네. 설마 정말로 책만 볼 생각이었던 건가?)",
  str_homestory_819101001_0_dialog_content = "하티?",
  str_homestory_819101001_1_dialog_content = "뭐 하는 거야?",
  str_homestory_819101001_2_dialog_content = "방금 책장의 책이랑 대화하고 있었어.",
  str_homestory_819101001_3_dialog_content = "하? 책이랑 어떻게 대화하는데?<sprite=emo_yihuo size=60 />",
  str_homestory_819101001_4_dialog_content = "질문을 하면 책장이 그 위에 답을 표시해 줘.\n게다가 무서울 정도로 정확하다고.",
  str_homestory_819101001_5_dialog_content = "무슨 질문을 했는데?",
  str_homestory_819101001_6_dialog_content = "이야기를 듣고 싶어서 책한테\n이야기를 들려달라고 했어.",
  str_homestory_819101001_7_dialog_content = "무서운 이야기야? 어떤 건데?",
  str_homestory_819101001_8_dialog_content = "안 무서워?",
  str_homestory_819101001_9_option_content = "조금 무서워.",
  str_homestory_819101001_10_dialog_content = "하지만 조금 궁금해.",
  str_homestory_819101001_11_option_content = "안 무서워.",
  str_homestory_819101001_12_dialog_content = "사내자식이 책의 이야기 같은 걸 무서워할 리가 없잖아?",
  str_homestory_819101001_13_dialog_content = "방금 어떤 얘기를 해줬냐면...",
  str_homestory_819101001_14_dialog_content = "「추운 겨울밤, 넌 홀로 책장 옆에서\n책을 읽고 있었어.」",
  str_homestory_819101001_15_dialog_content = "「그러다 갑자기 등 뒤에서 인기척이 느껴졌지.\n이때, 네 앞의 책에서 글자가 나타나기 시작했어...」",
  str_homestory_819101001_16_dialog_content = "『고개를 돌리지 마. 네 뒤에 <size=45>누군가가 있어</size>.』",
  str_homestory_819101001_17_dialog_content = "「넌 두려운 마음이 들었지만 참지 못하고\n뒤를 돌아보고 말았지.」",
  str_homestory_819101001_18_dialog_content = "여기까지 읽은 뒤에 난 고개를 돌렸고,\n네가 오는 모습을 발견했던 거야.",
  str_homestory_819101001_19_dialog_content = "하하, 상투적인 미스터리 소설의 도입부잖아.\n근데 그걸 현실에 결합했네. 그리고?",
  str_homestory_819101001_20_dialog_content = "「네 뒤에 있는 건 바로 집주인이었어.」",
  str_homestory_819101001_21_dialog_content = "「넌 안심했어. 집주인은 매우 약한 사람이었거든.\n한 주먹이면 날려버릴 수 있을 정도로 말이야.」",
  str_homestory_819101001_22_dialog_content = "뭐야! 이 책... 이야기가 아주 엉망이잖아!",
  str_homestory_819101001_23_dialog_content = "역시 현실이랑 완벽하게 맞아떨어지네.\n그래서 푹 빠질 수밖에 없었다니까...",
  str_homestory_819101001_24_dialog_content = "「넌 뒤에서 널 깜짝 놀라게 한 집주인을 타박하며\n주먹으로 그를 가볍게 때렸어.」",
  str_homestory_819101001_25_dialog_content = "「집주인은 네 주먹에 쓰러져버렸고,\n넌 그대로 집에서 쫓겨나 거리에 나앉았지.\n그리고 결국 감기에 걸려 죽고 말았어.」",
  str_homestory_819101001_26_dialog_content = "봐, 얼마나 사실적이고 무서운 이야기야.\n집주인님, 때리지 않을게요.",
  str_homestory_819101001_27_dialog_content = "내가 널 쫓아낼 리가 없잖아.\n아니... 애초에 주먹 한 방에 쓰러지지도 않을 거라고!",
  str_homestory_819101001_28_dialog_content = "한번 해 볼래?",
  str_homestory_819101001_29_dialog_content = "물론이지!<sprite=emo_dianzan size=60 />",
  str_homestory_819101001_30_dialog_content = "잠깐만, 손 좀 풀고.",
  str_homestory_819101001_31_dialog_content = "아, 아니... 내 말은 나도 그 책한테 한번 물어보겠다는 말이었어.",
  str_homestory_819101001_32_dialog_content = "뭘 물어볼 건데?",
  str_homestory_819101001_33_dialog_content = "정말 무슨 문제든 답해주는 거야?",
  str_homestory_819101001_34_dialog_content = "요즘 확실히 골치 아픈 일이 있거든.\n바이스가 콜로서스의 이번 달 수입이랑 지출을 계산해보라고 했어...",
  str_homestory_819101001_35_dialog_content = "방금 식당에서 둘이 얘기하는 거 들었어.",
  str_homestory_819101001_36_dialog_content = "그래서 나도 그 문제에 대해 물어봤지. 그랬더니...",
  str_homestory_819101001_37_dialog_content = "「나는 책일 뿐이고 자산 같은 건 없어.\n그러니 장부 정리도 도와줄 수 없지.」",
  str_homestory_819101001_38_dialog_content = "쳇, 대단한 책인 줄 알았는데 별거 아니네.",
  str_homestory_819101001_39_dialog_content = "그 문제는 책을 쓸 필요도 없겠어. 내가 답을 줄게.",
  str_homestory_819101001_40_dialog_content = "답이 뭔데?",
  str_homestory_819101001_41_dialog_content = "콜로서스의 수입과 지출은 심각한 불균형 상태야.\n이제 곧 파산할 거야.\n결국 길거리에 나앉아서 감기에 걸려 죽고 말겠지.",
  str_homestory_819101001_42_dialog_content = "그건 책 내용을 베낀 거잖아!",
  str_homestory_819101001_43_dialog_content = "실제 상황에 딱 맞으니까 그렇지.",
  str_homestory_819101001_44_dialog_content = "전혀 안 맞...을걸? 으흑...",
  str_homestory_817702001_0_dialog_content = "골디, 노래하고 있었구나!",
  str_homestory_817702001_1_dialog_content = "라랄라~♪",
  str_homestory_817702001_2_dialog_content = "...어라? PlayerName 너였구나. 안녕~",
  str_homestory_817702001_3_dialog_content = "안녕, 골디!",
  str_homestory_817702001_4_dialog_content = "미안, 혹시 내가 방해했어?",
  str_homestory_817702001_5_dialog_content = "전혀 아니야!",
  str_homestory_817702001_6_dialog_content = "그냥 이 바이올린이 보여서 나도 모르게\n노래한 거니까.",
  str_homestory_817702001_7_dialog_content = "그나저나 PlayerName,\n너한테 바이올린이 있을 줄은 몰랐어.",
  str_homestory_817702001_8_dialog_content = "혹시... 너도 악기에 관심 있어?",
  str_homestory_817702001_9_option_content = "관심 있어.",
  str_homestory_817702001_10_dialog_content = "응, 나도 악기를 꽤 좋아하거든!",
  str_homestory_817702001_11_dialog_content = "하지만 그냥 흥미 정도야. 애초에 연주할 줄도 모르고 말이야. 하하...",
  str_homestory_817702001_12_dialog_content = "정말 잘됐네~",
  str_homestory_817702001_13_dialog_content = "공통의 화제가 하나 더 생겼잖아!",
  str_homestory_817702001_14_option_content = "그냥 그래.",
  str_homestory_817702001_15_dialog_content = "음, 그냥 조금? 아주 좋아하는 것까지는 아니고...",
  str_homestory_817702001_16_dialog_content = "하지만 배워서 연주할 수 있게 되면... 꼭 골디한테 들려줄게!",
  str_homestory_817702001_17_dialog_content = "정말? 헤헤, 고마워!",
  str_homestory_817702001_18_dialog_content = "근데 사실...",
  str_homestory_817702001_19_dialog_content = "이 바이올린은 보통 바이올린이 아니야.",
  str_homestory_817702001_20_dialog_content = "어떤 유명한 탐정이 가진 거랑 같은 바이올린이거든!",
  str_homestory_817702001_21_dialog_content = "탐정?",
  str_homestory_817702001_22_dialog_content = "맞아. 그 대탐정은 일이 없을 땐 바이올린을 즐겨 연주하곤 했대.",
  str_homestory_817702001_23_dialog_content = "자세한 건 나도 잘 모르지만...",
  str_homestory_817702001_24_dialog_content = "근데 그런 다재다능한 탐정이라니... 정말 낭만적<sprite=emo_aixin size=60 />이잖아!",
  str_homestory_817702001_25_dialog_content = "그렇구나~",
  str_homestory_817702001_26_dialog_content = "이성적이고 냉혹해 보이는 탐정도 깊은 밤에는\n혼자 바이올린을 연주하는 거구나...",
  str_homestory_817702001_27_dialog_content = "그런 장면을 생각하니까... 음, 영감이 떠올랐어!",
  str_homestory_817702001_28_dialog_content = "무슨 영감?",
  str_homestory_817702001_29_dialog_content = "새로운 곡<sprite=emo_yinfu size=60 />에 대한 영감!",
  str_homestory_817702001_30_dialog_content = "새로운 연주복도 만들 수 있을 것 같아.\n거기에 특별한 안무까지 더하는 거지!",
  str_homestory_817702001_31_dialog_content = "생각만 해도 신나!",
  str_homestory_817702001_32_dialog_content = "탐정을 주제로 한 아이돌 콘서트라...",
  str_homestory_817702001_33_dialog_content = "정말 멋질 것 같네!",
  str_homestory_817702001_34_dialog_content = "역시 골디야!",
  str_homestory_817702001_35_dialog_content = "후후, 나중에 너도 꼭 응원하러 와!",
  str_homestory_811602001_0_dialog_content = "플뢰르, 뭐 하고 있어?",
  str_homestory_811602001_1_dialog_content = "저기, 플뢰르! 뭐 해?",
  str_homestory_811602001_2_dialog_content = "아, 조종사!",
  str_homestory_811602001_3_dialog_content = "장식품을 만져보던 중이었어.",
  str_homestory_811602001_4_dialog_content = "방금 잠깐 가지고 놀았는데...",
  str_homestory_811602001_5_dialog_content = "소리가 뭔가 이상하지 뭐야.",
  str_homestory_811602001_6_dialog_content = "소리?",
  str_homestory_811602001_7_dialog_content = "맞아. 나사 하나를 너무 조였거나,\n윤활유가 부족한 걸 수도 있겠지...",
  str_homestory_811602001_8_dialog_content = "바퀴 하나가 자꾸 「삐걱삐걱」 소리를 내더라고.",
  str_homestory_811602001_9_option_content = "그랬구나.",
  str_homestory_811602001_10_dialog_content = "확실히 장식품에 문제가 좀 있는 것 같네...",
  str_homestory_811602001_11_dialog_content = "그런 소리가 난다는 건 부품 상태가 안 좋은 거 아닐까?",
  str_homestory_811602001_12_dialog_content = "맞아!",
  str_homestory_811602001_13_dialog_content = "보통 사람은 이런 문제를 이해하지 못해.\n아무래도 넌 기계 수리에 재능이 있나 보네.",
  str_homestory_811602001_14_dialog_content = "그런가? 헤헤...",
  str_homestory_811602001_15_option_content = "난 잘 모르겠어.",
  str_homestory_811602001_16_dialog_content = "그렇구나...",
  str_homestory_811602001_17_dialog_content = "플뢰르 같은 전문가는 정말 대단하네. 나 같은 문외한은 전혀 모르겠거든.",
  str_homestory_811602001_18_dialog_content = "그래... 난 너랑 기계의 문제에 관해\n얘기할 수 있을 줄 알았는데...",
  str_homestory_811602001_19_dialog_content = "괜찮아. 나 혼자서도 고칠 수 있거든.",
  str_homestory_811602001_20_dialog_content = "음... 확실히 이쪽 나사를 너무 조인 것 같아...",
  str_homestory_811602001_21_dialog_content = "근데 아쉽지만 지금은 적당한 공구가 없어.",
  str_homestory_811602001_22_dialog_content = "공구를 찾은 다음에 다시 와서 고쳐야겠네.",
  str_homestory_811602001_23_dialog_content = "그럼 부탁할게!",
  str_homestory_811602001_24_dialog_content = "별로 큰일도 아니니까.",
  str_homestory_811602001_25_dialog_content = "하지만 이런 사소한 부분을 무시하는 거야말로\n기계한테는 치명적이야.",
  str_homestory_811602001_26_dialog_content = "작은 장식품이라 다행이야. 만약 진짜 카트였으면...",
  str_homestory_811602001_27_dialog_content = "바퀴가 이미 망가졌을지도 모르지. 하하하!",
  str_homestory_811602001_28_dialog_content = "맞아. 우리 같은 보통 사람은 물건이 고장 나고 나서야\n고쳐야 한다는 걸 알아차린다니까.",
  str_homestory_811602001_29_dialog_content = "기계가 전부 스카이워커호처럼 문제를 말해줄 수 있으면 좋겠는데.",
  str_homestory_811602001_30_dialog_content = "그래...?",
  str_homestory_811602001_31_dialog_content = "난 오히려 사람들의 말이야말로 알아듣기\n힘든 것 같은데<sprite=emo_sikao size=60 />.",
  str_homestory_811602001_32_dialog_content = "「인격」을 기계에 부여한다는 건\n정말 위대한 일이지만...",
  str_homestory_811602001_33_dialog_content = "그래도 기계마저 뭔가를 숨기면서 말하는\n악습에 물들진 않았으면 좋겠어!",
  str_homestory_811602001_34_dialog_content = "하하하... 그것도 그렇네.",
  str_homestory_811602001_35_dialog_content = "만약 언젠가 기계에도 개성이 생긴다면 플뢰르 너도 골치가 아파질 테니까!",
  str_homestory_808401001_0_dialog_content = "이스타반 씨도 수수께끼를 좋아하세요?",
  str_homestory_808401001_1_dialog_content = "왔군. 마침 잘 왔다.",
  str_homestory_808401001_2_dialog_content = "자네는 이 단서를 어떻게 생각하지?",
  str_homestory_808401001_3_dialog_content = "어떻게 생각하냐고요? 전...",
  str_homestory_808401001_4_option_content = "갈피가 잡히는 것 같아요.",
  str_homestory_808401001_5_dialog_content = "이 중에 몇몇 단서가 조금 이상한 것 같거든요<sprite=emo_sikao size=60 />.",
  str_homestory_808401001_6_dialog_content = "시간을 조금만 더 주시면 답을 생각해 낼 수 있을지도 몰라요!",
  str_homestory_808401001_7_option_content = "잘 모르겠어요.",
  str_homestory_808401001_8_dialog_content = "음... 전 수수께끼 푸는 건 잘 못해서요<sprite=emo_tanqi size=60 />.",
  str_homestory_808401001_9_dialog_content = "전혀 모르겠어요...",
  str_homestory_808401001_10_dialog_content = "그러한가.",
  str_homestory_808401001_11_dialog_content = "미안하군. 자네가 먼저 물어봤는데\n오히려 질문으로 대답하다니.",
  str_homestory_808401001_12_dialog_content = "그렇다면 이제 내가 의문을 풀어주도록 하지...",
  str_homestory_808401001_13_dialog_content = "난 퍼즐을 좋아하지 않는다.",
  str_homestory_808401001_14_dialog_content = "네? 그럼 이스타반 씨는 왜 추리 칠판을 뚫어져라 보고 계셨던 거죠?",
  str_homestory_808401001_15_dialog_content = "자, 서두르지 마라. 천천히 대답해줄 테니 말이야.",
  str_homestory_808401001_16_dialog_content = "조금 전의 대화에서 자네는 이 단서를\n「퀴즈」로 간주했다.",
  str_homestory_808401001_17_dialog_content = "즉, 자신도 모르게 본인을 「탐정」의\n관점에 대입한 것이지.",
  str_homestory_808401001_18_dialog_content = "네, 맞아요.",
  str_homestory_808401001_19_dialog_content = "하지만 사실상 이 「국면」에는\n다양한 캐릭터가 있다.",
  str_homestory_808401001_20_dialog_content = "「탐정」, 「범죄자」, 「피해자」...",
  str_homestory_808401001_21_dialog_content = "그리고 「주모자」가 있지.",
  str_homestory_808401001_22_dialog_content = "「주모자」요?",
  str_homestory_808401001_23_dialog_content = "주모자는 양치기나 다름없다.\n모든 것을 만든 자이자 모든 것의 수혜자가 되지.",
  str_homestory_808401001_24_dialog_content = "그는 개를 이끌고 양을 치며...\n늑대를 쫓고 양을 지킨다...",
  str_homestory_808401001_25_dialog_content = "좋은 양치기는 목장에서 가만히 있지 않는 법이다.",
  str_homestory_808401001_26_dialog_content = "그러니 주모자는 수수께끼를 풀지 않는다.\n오히려 적극적으로 이익이 되는 답을 찾지.",
  str_homestory_808401001_27_dialog_content = "으음... 엄청 복잡하네요!",
  str_homestory_808401001_28_dialog_content = "이스타반 씨의 말은 그러니까...",
  str_homestory_808401001_29_dialog_content = "이스타반 씨 같은 리더는 진실보다는 결과를 중시한다는 건가요?",
  str_homestory_808401001_30_dialog_content = "맞다. 정확하게 이해했군.",
  str_homestory_808401001_31_dialog_content = "자네는 아직 젊고, 많은 가능성을 가지고 있지.",
  str_homestory_808401001_32_dialog_content = "하지만 난 자네 같은 조종사가 자신을 위해\n말을 움직이는 법을 배웠으면 좋겠군.",
  str_homestory_808401001_33_dialog_content = "새끼 양처럼 잔재주로 인한 즐거움에\n빠지는 게 아니고 말이야.",
  str_homestory_808401001_34_dialog_content = "하하... 하하하... 그런 건... 저한테는 아직 너무 이른 얘기 같아요...",
  str_homestory_808401001_35_dialog_content = "...그것도 그렇군.\n벌써부터 자네의 패기를 꺾을 필요는 없겠지.",
  str_homestory_808401001_36_dialog_content = "그렇다면 역시 소년의 기운으로\n모험을 떠나는 게 좋겠군.",
  str_homestory_808401001_37_dialog_content = "방금 강가를 지나다가 강 중앙에\n반짝이는 동전이 있는 걸 봤다<sprite=emo_baiyebi size=60 />.",
  str_homestory_808401001_38_dialog_content = "제대로 본 건 아니지만,\n내가 보기엔 꽤 희귀한 물건인 것 같더군.",
  str_homestory_808401001_39_dialog_content = "한번 찾아보는 것도 좋겠지.",
  str_homestory_808401001_40_dialog_content = "네, 고마워요, 이스타반 씨!",
  str_homestory_819301001_0_dialog_content = "크리스틴?",
  str_homestory_819301001_1_dialog_content = "크리스틴, 뭐 해?",
  str_homestory_819301001_2_dialog_content = "흐응~ 흥~<sprite=emo_yinfu size=60 />",
  str_homestory_819301001_3_dialog_content = "음악을 듣고 있어요~",
  str_homestory_819301001_4_dialog_content = "당신의 턴테이블이 정말 예쁘더군요.\n그래서 써보고 있었어요.",
  str_homestory_819301001_5_dialog_content = "어떤 것 같아?",
  str_homestory_819301001_6_dialog_content = "엄청 좋아요! 음질도 훌륭하고요.\n정말 좋은 턴테이블이네요.",
  str_homestory_819301001_7_dialog_content = "PlayerName 씨는 언제부터 이런 취미를\n가지게 된 건가요?",
  str_homestory_819301001_8_dialog_content = "그냥 가끔 주변에 보이는 예쁜 것들을 수집하곤 해.",
  str_homestory_819301001_9_dialog_content = "근데 비슷한 턴테이블은 너도 많이 보지 않았어?",
  str_homestory_819301001_10_dialog_content = "맞아요. 가문의 장원에도 턴테이블이 잔뜩 있어요.\n그중엔 아주 특별한 것도 하나 있고요.",
  str_homestory_819301001_11_dialog_content = "아마...",
  str_homestory_819301001_12_dialog_content = "심판소 로비만큼 클걸요.",
  str_homestory_819301001_13_dialog_content = "뭐, 뭐라고?",
  str_homestory_819301001_14_dialog_content = "심판소 로비라니... 그럼 엄청나게 큰 거잖아?",
  str_homestory_819301001_15_dialog_content = "그 정도면 연주 무대로도 쓸 수 있겠네!",
  str_homestory_819301001_16_dialog_content = "아버님 같은 귀족의 취미는\n정말 이해할 수가 없다니까요~",
  str_homestory_819301001_17_dialog_content = "크리스틴도 너도 귀족이잖아...",
  str_homestory_819301001_18_dialog_content = "아, 전 아버님과는 다르니까요~",
  str_homestory_819301001_19_dialog_content = "PlayerName 씨, 제가 다른 나이 든 귀족들과\n똑같아 보이나요?",
  str_homestory_819301001_20_option_content = "다르지.",
  str_homestory_819301001_21_dialog_content = "크리스틴은 새로운 걸 좋아하잖아.",
  str_homestory_819301001_22_dialog_content = "음악 같은 거 말이야.",
  str_homestory_819301001_23_option_content = "가끔은 비슷한 것 같아.",
  str_homestory_819301001_24_dialog_content = "크리스틴은 교양이 넘치잖아. 지금까지 내가 봐왔던 귀족들처럼 말이야.",
  str_homestory_819301001_25_dialog_content = "아~ PlayerName 씨는 그렇게 생각하고 있었군요.",
  str_homestory_819301001_26_dialog_content = "하지만 맞는 말이에요.",
  str_homestory_819301001_27_dialog_content = "비록 제 몸에는 귀족의 피가 흐르고 있지만...",
  str_homestory_819301001_28_dialog_content = "제 마음은 다른 길로 가기를 바라고 있죠.",
  str_homestory_819301001_29_dialog_content = "그럼 새로운 스타일의 음악부터 시작해 볼까요?\n전 새로운 영감을 얻었거든요!",
  str_homestory_819301001_30_dialog_content = "잠깐만!",
  str_homestory_819301001_31_dialog_content = "크리스틴, 여기서 노래할 생각이야?",
  str_homestory_819301001_32_dialog_content = "맞아요. 턴테이블의 음악이 있으니\n노래하기 딱 좋잖아요. 아아~<sprite=emo_yinfu size=60 />",
  str_homestory_819301001_33_dialog_content = "아, 잠깐!",
  str_homestory_819301001_34_dialog_content = "시간 좀 봐... 나 다른 일이 있었던 것 같아... 나 먼저 갈게!",
  str_homestory_819301001_35_dialog_content = "지금 말인가요?",
  str_homestory_819301001_36_dialog_content = "응... 내 신경 쓰지 말고 마음껏 노래해!",
  str_homestory_819201001_0_dialog_content = "레오 씨?",
  str_homestory_819201001_1_dialog_content = "돋보기가 하나 필요하던 참인데, 마침 여기 있었네.",
  str_homestory_819201001_2_dialog_content = "돋보기는 왜?",
  str_homestory_819201001_3_dialog_content = "지도를 살펴보려고.",
  str_homestory_819201001_4_dialog_content = "얼마 전에 휘하 기사들한테 변방 지역에 있는\n각 군사 요새의 위치를 조사해 보라고 해 뒀었거든.",
  str_homestory_819201001_5_dialog_content = "그 조사 내용을 토대로 만든 지도가 오늘 완성돼서,\n곧바로 나한테 보내준 거야.",
  str_homestory_819201001_6_dialog_content = "그런데 글자들이 흘겨 적은 데다가 크기도 작아서,\n보고 있으려니 머리가 아프단 말이지<sprite=emo_xuanyun size=60 />.",
  str_homestory_819201001_7_dialog_content = "지도에 글자가 많이 적혀 있나 보네?",
  str_homestory_819201001_8_dialog_content = "네가 한번 봐 봐.",
  str_homestory_819201001_9_dialog_content = "《더스크 타운 인근 80km 범위의 군사 요새 조사 결과 분석 및...》",
  str_homestory_819201001_10_dialog_content = "밑에 더 있어.",
  str_homestory_819201001_11_dialog_content = "《...분포, 수량, 질적 특성, 상관관계 등 정보에 대한 지도》...",
  str_homestory_819201001_12_dialog_content = "휴우... 휴우...<sprite=emo_kun size=60 />",
  str_homestory_819201001_13_dialog_content = "지, 지도 이름이... 원래 다 이렇게 복잡해?",
  str_homestory_819201001_14_dialog_content = "중간에 안 쉬고 쭉 읽으니까 숨까지 차잖아.",
  str_homestory_819201001_15_dialog_content = "당연히 아니지.\n그저 이번 제작 담당이 유독 빈틈없는 성격이라...",
  str_homestory_819201001_16_dialog_content = "굳이 안 적어도 될 말까지 전부 다 집어넣은 거야.",
  str_homestory_819201001_17_dialog_content = "어쩐지, 군사 전문가들이 항상 돋보기를\n가지고 다니는 이유가 있었구나.",
  str_homestory_819201001_18_dialog_content = "이렇게 「빈틈없는」 지도 담당자가 만든 빼곡한 지도를\n제대로 보려면 아무래도 돋보기가 필요하긴 하겠네.",
  str_homestory_819201001_19_dialog_content = "(근데 잘 보여도 더 짜증 날 것 같지만...)",
  str_homestory_819201001_20_dialog_content = "장교 중에는 돋보기 사용을 좋아하는 사람들이 많긴 해.",
  str_homestory_819201001_21_dialog_content = "그림이든 글자든 크게 확대해 주니까 관찰할 때 좋거든.\n낮엔 불 피우는 데 유용하게 사용할 수도 있고.",
  str_homestory_819201001_22_dialog_content = "여러 가지로 유용한 행군 필수용품이라고 할 수 있겠지.",
  str_homestory_819201001_23_dialog_content = "그런데 내 생각은 조금 달라.",
  str_homestory_819201001_24_dialog_content = "왜?",
  str_homestory_819201001_25_dialog_content = "너도 전투에서 모두를 지휘하는 리더니까,\n그 이유를 한 번 맞춰 보지 않겠어?",
  str_homestory_819201001_26_option_content = "빛에 대한 의존도 때문이야?",
  str_homestory_819201001_27_dialog_content = "시간대가 밤이라거나, 위치가 어둠의 밑바닥이라면\n아무래도 돋보기를 사용하기 많이 어렵잖아.",
  str_homestory_819201001_28_dialog_content = "확실히 그렇긴 해.\n하지만 그 부분은 조명만 준비하면 피할 수 있는 문제야.",
  str_homestory_819201001_29_option_content = "시야가 한정돼서?",
  str_homestory_819201001_30_dialog_content = "나쁘지 않은 답이야.",
  str_homestory_819201001_31_dialog_content = "돋보기는 지도의 일부를 확대해 보여 줄 수 있어.\n그래서 관찰자는 세부적인 부분을 더 자세히 살필 수 있지.",
  str_homestory_819201001_32_dialog_content = "대신 관찰자의 시야 또한 돋보기가 확대해 주는\n범위 안으로 한정되고 말아.",
  str_homestory_819201001_33_dialog_content = "주변을 더 넓게 볼 수 없게 된다는 거지.",
  str_homestory_819201001_34_dialog_content = "하지만 전쟁을 위해서는 넓은 시야가 필요하기 마련이거든.",
  str_homestory_819201001_35_dialog_content = "나도 시야가 너무 한 곳에만 집중되지 않게 하려고\n가끔은 일부러 돋보기를 사용하지 않기도 해.",
  str_homestory_819201001_36_dialog_content = "전략가는 역시 뭐가 달라도 다르구나.",
  str_homestory_819201001_37_dialog_content = "개인적인 습관이 그럴 뿐이지, 지금 같은 상황에선\n나도 돋보기의 힘을 빌릴 수밖에 없어.",
  str_homestory_819201001_38_dialog_content = "여기 있는 돋보기는 언제든 가져다 써도 돼.",
  str_homestory_819201001_39_dialog_content = "대신 쓰고 나면 잊지 말고 꼭 전용 보관함에 넣어 줘.",
  str_homestory_819201001_40_dialog_content = "직사광선 아래에 놔두면 불이 날 수도 있거든<sprite=emo_nuhuo size=60 />.",
  str_homestory_819201001_41_dialog_content = "하하, 화재 예방도 잊지 않았구나.",
  str_homestory_819201001_42_dialog_content = "여긴 내가 심혈을 기울여서 가꾼 터전이니까.",
  str_homestory_819201001_43_dialog_content = "근데 타 버리면 지금까지 내가 들인 돈...\n아니, 피땀이 홀랑 날아가 버리는 거잖아.",
  str_homestory_819901001_0_dialog_content = "잉겔?",
  str_homestory_819901001_1_dialog_content = "왔군요, PlayerName.\n마침 커피를 마시려던 참이었어요.",
  str_homestory_819901001_2_dialog_content = "잉겔 네가 직접 내린 커피야?",
  str_homestory_819901001_3_dialog_content = "맞아요.",
  str_homestory_819901001_4_dialog_content = "조금 전에 이 예쁜 커피잔을 발견한 김에\n커피를 한 잔 내려 봤어요.",
  str_homestory_819901001_5_dialog_content = "향이 정말 좋네~<sprite=emo_dianzan size=60 />",
  str_homestory_819901001_6_dialog_content = "우유 거품 위에 그려진 그림도 봤나요?\n이건 카페 라떼거든요.",
  str_homestory_819901001_7_dialog_content = "아, 그러네! 위에 예쁜 그림이 그려져 있잖아!",
  str_homestory_819901001_8_dialog_content = "근데 이 모양은... 혹시 아오하야?",
  str_homestory_819901001_9_dialog_content = "알아볼 수 있나요? 음, 그럼 이번 시도가 실패하진 않았네요.",
  str_homestory_819901001_10_dialog_content = "당연히 실패일 리가 없지! 이렇게 대단한데!",
  str_homestory_819901001_11_dialog_content = "어떻게 한 거야?",
  str_homestory_819901001_12_dialog_content = "카페 라떼는 제조법이 어렵지 않은 편이에요.\n재료도 무척 간단하죠.",
  str_homestory_819901001_13_dialog_content = "우선 커피잔에 에스프레소 한 샷을 따라 둬요...",
  str_homestory_819901001_14_dialog_content = "그리고 거기에 신선한 우유로 만든 거품을 넣는 거예요.",
  str_homestory_819901001_15_dialog_content = "거품을 넣을 때 잔의 위치를 조정해 가며 그림을 다듬으면...",
  str_homestory_819901001_16_dialog_content = "예쁜 라떼아트가 그려진 카페 라떼를 만들 수 있어요.",
  str_homestory_819901001_17_dialog_content = "엄청 간단한 것처럼 얘기하고 있지만,\n막상 해 보면 절대 그리 쉽지 않을 것 같은데...",
  str_homestory_819901001_18_dialog_content = "실력은 하다 보면 늘어요. 몇 번 연습하면 될 거예요.",
  str_homestory_819901001_19_dialog_content = "전 업무 중에 피곤함을 느끼면 카페 라떼를\n한 잔 내려 마시곤 해요.",
  str_homestory_819901001_20_dialog_content = "크리미한 우유 거품에 커피의 향긋함이\n완벽하게 어우러지거든요.",
  str_homestory_819901001_21_dialog_content = "PlayerName, 한 번 마셔보겠어요?<sprite=emo_yaosu size=60 />",
  str_homestory_819901001_22_option_content = "마셔 볼래!",
  str_homestory_819901001_23_dialog_content = "잉겔이 직접 만든 커피잖아.",
  str_homestory_819901001_24_option_content = "다음에 마셔 볼게!",
  str_homestory_819901001_25_dialog_content = "밤에 잠이 안 올까 봐 걱정돼서.",
  str_homestory_819901001_26_dialog_content = "우유의 비율이 2/3 이상이니까 몇 모금 정도로\n밤에 잠을 못 자는 일이 생기진 않을 거예요.",
  str_homestory_819901001_27_dialog_content = "그래? 그러면 마셔 볼래!",
  str_homestory_819901001_28_dialog_content = "맛이 어때요?",
  str_homestory_819901001_29_dialog_content = "진짜 맛있어!",
  str_homestory_819901001_30_dialog_content = "나도 이렇게 맛있는 카페 라떼를 만들 줄 알면 좋을 텐데.",
  str_homestory_819901001_31_dialog_content = "한 번 배워 보는 것도 나쁘지 않다고 생각해요.\n분명히 잘 배울 수 있을 거예요.",
  str_homestory_819901001_32_dialog_content = "하지만 제가 우유를 다 써 버린 모양이네요...",
  str_homestory_819901001_33_dialog_content = "아, 벌써 다 쓴 거야?",
  str_homestory_819901001_34_dialog_content = "조금 전에 목이 많이 말랐거든요. 그래서 다 마셔 버렸어요.",
  str_homestory_819901001_35_dialog_content = "크, 크흠, 잉겔, 물 대신 우유를 마시고 그러면 안 되는 거야...",
  str_homestory_820001001_0_dialog_content = "랜턴을 보고 있는 건가?",
  str_homestory_820001001_1_dialog_content = "아나톨리 씨, 지금 뭐 해?",
  str_homestory_820001001_2_dialog_content = "랜턴을 관찰하고 있었습니다.",
  str_homestory_820001001_3_option_content = "관찰?",
  str_homestory_820001001_4_dialog_content = "한낮에도 이 랜턴은 여전히 빛나고 있다는\n사실을 발견했습니다.",
  str_homestory_820001001_5_dialog_content = "햇빛만큼 눈이 부실 정도는 아닙니다만,\n대신 지금까지 꺼지질 않더군요.",
  str_homestory_820001001_6_dialog_content = "과연 누가 이 조명에 계속 기름을 보충하고 있는 걸까요?",
  str_homestory_820001001_7_dialog_content = "그건 나도 잘 모르겠네...",
  str_homestory_820001001_8_option_content = "왜?",
  str_homestory_820001001_9_dialog_content = "이 랜턴이 밤이나 낮이나 계속 켜져 있기 때문입니다.",
  str_homestory_820001001_10_dialog_content = "낮엔 그렇게 눈에 띄는 편은 아닙니다만,\n밤이 되면 어둠을 밝혀 주죠<sprite=emo_taiyang size=60 />.",
  str_homestory_820001001_11_dialog_content = "아, 맞아!",
  str_homestory_820001001_12_dialog_content = "밤에 길을 밝혀 주는 랜턴이 있으면 편하지!",
  str_homestory_820001001_13_dialog_content = "그렇지만 낮에도 계속 켜져 있다면 그건 좀 낭비인 것 같아.",
  str_homestory_820001001_14_dialog_content = "음... 일리 있는 의견입니다.",
  str_homestory_820001001_15_dialog_content = "이곳은 영원한 밤의 땅도 아닌 이상,\n계속 조명을 밝혀 둘 필요가 없겠지요.",
  str_homestory_820001001_16_dialog_content = "그렇다면 일단 꺼 두고 밤이 되면 다시 켜자.",
  str_homestory_820001001_17_dialog_content = "그래도 역시 계속 켜 두는 편이 좋을 것 같습니다.",
  str_homestory_820001001_18_dialog_content = "어? 왜?",
  str_homestory_820001001_19_dialog_content = "계속 이 랜턴에 기름을 보충하는 게 누구인진 알 수 없지만,\n아마 자신만의 목적을 가지고 있을 겁니다.",
  str_homestory_820001001_20_dialog_content = "그러니 그 사람을 방해하지 않는 게 좋을 것 같습니다.",
  str_homestory_820001001_21_dialog_content = "그것도 일리가 있네.",
  str_homestory_820001001_22_dialog_content = "근데 누군지 정말 궁금하네!",
  str_homestory_820001001_23_dialog_content = "자주 보러 온다면 언젠가는 만날 수 있을 겁니다.",
  str_homestory_820001001_24_dialog_content = "음, 마침 아나톨리 씨는 추리랑 분석을 잘하잖아?",
  str_homestory_820001001_25_dialog_content = "그럼 이 사람의 정체가 뭐라고 생각해?",
  str_homestory_820001001_26_dialog_content = "확실히 몇 가지 추측을 해 보기는 했습니다.",
  str_homestory_820001001_27_dialog_content = "어떤 건데?",
  str_homestory_820001001_28_dialog_content = "우선 오랜 시간 한 가지 일을 꾸준히 해 오고 있는 걸 보면,\n인내심이 대단한 사람일 겁니다.",
  str_homestory_820001001_29_dialog_content = "게다가 어떻게 보면 사소한 이런 일을 계속 잊지 않으니,\n기억력도 매우 좋은 편이겠죠.",
  str_homestory_820001001_30_dialog_content = "그리고 마지막 추측은, 아마도 이 사람은 빛을 발산하는\n작은 물체를 좋아할 가능성이 매우 크다는 점입니다.",
  str_homestory_820001001_31_dialog_content = "음, 일리가 있네...",
  str_homestory_820001001_32_dialog_content = "그렇게 짚어 주니까 짐작 가는 사람이 몇 명 있어.",
  str_homestory_820001001_33_dialog_content = "아! 알 것 같아!",
  str_homestory_820001001_34_dialog_content = "방금 말한 그 사람, 딱 아나톨리 씨 본인 같은데?!",
  str_homestory_820001001_35_dialog_content = "추측한 그대로입니다.",
  str_homestory_820001001_36_dialog_content = "그럼... 왜 이 랜턴을 계속 밝혀 두는 거야?",
  str_homestory_820001001_37_dialog_content = "지금은 한낮이라 환해서 딱히 필요 없잖아.",
  str_homestory_820001001_38_dialog_content = "커다란 빛에 가려지는 작은 빛이라 해도,\n그 자그마한 빛만이 할 수 있는 일이 있기 마련입니다.",
  str_homestory_820001001_39_dialog_content = "저는 그렇게 믿고 있습니다.",
  str_homestory_802801001_0_dialog_content = "이 소리는... 설마...?",
  str_homestory_802801001_1_dialog_content = "역시 라파엘이었구나!",
  str_homestory_802801001_2_dialog_content = "슈슉! 슝! 슈슈슝!",
  str_homestory_802801001_3_dialog_content = "PlayerName, 마침 잘 왔어!",
  str_homestory_802801001_4_dialog_content = "라파엘이 새로 발명한 「신비한 에너지 조각」 한 번 먹어 봐!",
  str_homestory_802801001_5_dialog_content = "먹는 순간 에너지가 팍 차오를 거야!\n어쩌면 신비한 보물이 있는 곳을 감응해 버릴지도 모른다구!",
  str_homestory_802801001_6_dialog_content = "수량 한정! 딱 한 알밖에 안 남았어!",
  str_homestory_802801001_7_option_content = "나, 난 됐어...",
  str_homestory_802801001_8_dialog_content = "라파엘이 한참을 돌아다니다 드디어 발견한 실험 대상인데!",
  str_homestory_802801001_9_dialog_content = "너도 이렇게 고생한 내가 허탕 치게 만들고 싶진 않잖아?!",
  str_homestory_802801001_10_dialog_content = "뭐... 그럴 생각까진 아니긴 한데...",
  str_homestory_802801001_11_option_content = "그래! 먹어볼게!",
  str_homestory_802801001_12_dialog_content = "헤헷, PlayerName 오늘따라 적극적이네!",
  str_homestory_802801001_13_dialog_content = "그럼 내일 몇 개 더 가져다줄게!",
  str_homestory_802801001_14_dialog_content = "아니, 저기, 라파엘... 너 그렇게 한가한 거야?",
  str_homestory_802801001_15_dialog_content = "빨리 아~ 해 봐. 아~",
  str_homestory_802801001_16_dialog_content = "자, 잠깐만!",
  str_homestory_802801001_17_dialog_content = "이 냄새... 이거 설마 바이스가 한 요리를 만든 건 아니지...?",
  str_homestory_802801001_18_dialog_content = "(으으윽, 다 태워서 냄비 바닥에 눌어붙은 그런 냄새가...<sprite=emo_hanshui size=60 />)",
  str_homestory_802801001_19_dialog_content = "어?! 라파엘이 바이스만큼 믿음직한 사람이란 거야?",
  str_homestory_802801001_20_dialog_content = "아, 그러니까 내 말은... 그게 그러니까...",
  str_homestory_802801001_21_dialog_content = "헤헤, 알고 있다구, PlayerName.\n넌 믿음직한 동료를 좋아하잖아!",
  str_homestory_802801001_22_dialog_content = "그러니까 나도 열심히 노력해서, 그 누구보다도!\n믿음직한! 그런 동료가 될게!",
  str_homestory_802801001_23_dialog_content = "「신비한 에너지 조각」을 만들어 주는 그런 동료 말이야...!",
  str_homestory_802801001_24_dialog_content = "헤헤, 막상 말하고 나니까 조금 부끄럽네.",
  str_homestory_802801001_25_dialog_content = "(정말 낙천적이네...)",
  str_homestory_802801001_26_dialog_content = "라파엘, 그럼 이렇게 하자. 일단 조금 넉넉하게 만들어 놔.\n그리고 나중에 카렌이랑 같이 먹어 보자.",
  str_homestory_802801001_27_dialog_content = "나보단 카렌이 힘들 테니까, 이게 꼭 필요할 수도 있어.",
  str_homestory_802801001_28_dialog_content = "어? 카렌 언니가...?",
  str_homestory_802801001_29_dialog_content = "라파엘은 아닐 것 같은데~",
  str_homestory_802801001_30_dialog_content = "왜 그렇게 생각하는데?",
  str_homestory_802801001_31_dialog_content = "카렌 언니였으면 분명...",
  str_homestory_802801001_32_dialog_content = "「라파엘! 나한테 이상한 사탕은 그만 먹여. 이유도 묻지 마.」\n...이렇게 말할 테니까.",
  str_homestory_802801001_33_dialog_content = "그건 또 왜?",
  str_homestory_802801001_34_dialog_content = "나도 궁금해~<sprite=emo_sikao size=60 />\n근데 카렌 언니가 물어보지 말라고 했는걸.",
  str_homestory_802801001_35_dialog_content = "게다가 말이지~",
  str_homestory_802801001_36_dialog_content = "이건 감응 능력을 가지고 있는 PlayerName 널 위해\n특별히 맞춤 제작한 거야!",
  str_homestory_802801001_37_dialog_content = "그렇구나, 알겠어... 그럼 줘 봐!",
  str_homestory_802801001_38_dialog_content = "(어차피 그냥 사탕이겠지...)",
  str_homestory_802801001_39_dialog_content = "헤헷! 역시 PlayerName 너한테 주면 될 줄 알았다니까!",
  str_homestory_802801001_40_dialog_content = "어때? 어때? 몸에 뭔가 변화가 느껴져?!",
  str_homestory_802801001_41_dialog_content = "반짝거리는 게 보이고 그러지 않아?",
  str_homestory_802801001_42_dialog_content = "눈이 꽤 맑아진 것 같아. 더 멀리까지 보이는 것 같은데...",
  str_homestory_802801001_43_dialog_content = "가, 강 안에! 진짜로 반짝거리는 게 있네?!",
  str_homestory_802801001_44_dialog_content = "그렇지? 내 말이 맞지? 난 다 안다니까!",
  str_homestory_802801001_45_dialog_content = "이걸로 「신비한 에너지 조각」 실험 대성공!<sprite=emo_aixin size=60 />",
  str_homestory_820201001_0_dialog_content = "왜 여기 계세요?",
  str_homestory_820201001_1_dialog_content = "왔군.",
  str_homestory_820201001_2_dialog_content = "이 왕좌는 날 위해 특별히 준비한 건가?",
  str_homestory_820201001_3_dialog_content = "마...맞아요.",
  str_homestory_820201001_4_dialog_content = "음, 그대의 성의는 인정해 주지.",
  str_homestory_820201001_5_dialog_content = "하이가든의 정통 왕좌와는 비할 수 없으나...",
  str_homestory_820201001_6_dialog_content = "이 정도 규격만이 내 신분에 걸맞을 것이다.",
  str_homestory_820201001_7_dialog_content = "마음에 드신다니 다행이네요!",
  str_homestory_820201001_8_dialog_content = "또 뭐 필요하신 게 있으신가요?",
  str_homestory_820201001_9_dialog_content = "이곳에 백야성 같은 궁전을 짓는 것은 어떠한가<sprite=emo_sikao size=60 />.",
  str_homestory_820201001_10_dialog_content = "왕좌에는 그에 걸맞은 궁전이 있어야 마땅하지.",
  str_homestory_820201001_11_dialog_content = "여기다 궁전을 짓고 싶으신 건가요?",
  str_homestory_820201001_12_dialog_content = "여긴 너무 좁지 않을까요?",
  str_homestory_820201001_13_dialog_content = "음... 그렇게 보니 이곳은 허술할 뿐만 아니라\n확실히 넓이가 부족하군.",
  str_homestory_820201001_14_dialog_content = "내가 자금을 투자할 테니 이곳을\n정비해 보는 건 어떤가.",
  str_homestory_820201001_15_option_content = "괜찮아요...",
  str_homestory_820201001_16_dialog_content = "마음만 받을게요.",
  str_homestory_820201001_17_option_content = "정말요?",
  str_homestory_820201001_18_dialog_content = "정비 사업을 하려면 물자도 필요하고 인력도 많이 필요해요...",
  str_homestory_820201001_19_dialog_content = "그냥 잠깐 쉬러 오시는 건데 그렇게까지 하실\n필요는 없다고 생각해요.",
  str_homestory_820201001_20_dialog_content = "내게는 사소한 일일 뿐이다.",
  str_homestory_820201001_21_dialog_content = "허나 그대가 필요하지 않다면 강권하진 않겠다.",
  str_homestory_820201001_22_dialog_content = "잠깐, 이곳은 향이...<sprite=emo_wuzui size=60 />",
  str_homestory_820201001_23_dialog_content = "네? 향이요?",
  str_homestory_820201001_24_dialog_content = "음... 전 아무 냄새도 못 느끼겠는데요.",
  str_homestory_820201001_25_dialog_content = "그렇다. 그게 바로 이곳에 부족한 것이다.",
  str_homestory_820201001_26_dialog_content = "이곳에 우아하고 아름다운 향을 더하도록 해라.\n깨끗하고 질서 있는 향기가 충만하게 하는 것이다.",
  str_homestory_820201001_27_dialog_content = "음... 전 향기에는 딱히 관심이 없는데요...",
  str_homestory_820201001_28_dialog_content = "손님이 이곳을 방문했을 때 가장 먼저\n우아한 향기가 손님을 맞이하지 않는다면...",
  str_homestory_820201001_29_dialog_content = "그것은 체면을 잃는 일이다!",
  str_homestory_820201001_30_dialog_content = "그렇다면 내가 사람을 시켜 가져오게 하도록 하지.",
  str_homestory_820201001_31_dialog_content = "다시 이 땅을 찾았을 때는 변화가 있길 바라겠다.",
  str_homestory_820201001_32_dialog_content = "알겠어요...",
  str_homestory_820301001_0_dialog_content = "쟈키니?",
  str_homestory_820301001_1_dialog_content = "그렇군요...",
  str_homestory_820301001_2_dialog_content = "뭐 해?",
  str_homestory_820301001_3_dialog_content = "으앗! 언제부터 있었어요?",
  str_homestory_820301001_4_dialog_content = "방금 점술 결과 들었어요?",
  str_homestory_820301001_5_dialog_content = "방금 왔거든. 아무것도 못 들었어.",
  str_homestory_820301001_6_dialog_content = "무슨 개인적인 일이라도 점치고 있었던 거야?",
  str_homestory_820301001_7_dialog_content = "미안, 지금 바로 자리를 비켜줄게.",
  str_homestory_820301001_8_dialog_content = "아주 개인적인 일이긴 하지만...",
  str_homestory_820301001_9_dialog_content = "당신과도 관계가 있어요.",
  str_homestory_820301001_10_dialog_content = "어? 나랑?",
  str_homestory_820301001_11_dialog_content = "네, 아까 당신과 바이스가 이야기하는 걸 들었어요.",
  str_homestory_820301001_12_dialog_content = "당신 요즘 주머니 사정이 안 좋은 모양이죠?",
  str_homestory_820301001_13_dialog_content = "그건... 확실히 좀 힘들긴 해.",
  str_homestory_820301001_14_dialog_content = "음, 저도 마침 걱정이 돼서 대신 점을 쳐봤어요.",
  str_homestory_820301001_15_dialog_content = "혹시 신경 쓰인다면 점술 결과는\n영원히 비밀로 덮어둘게요.",
  str_homestory_820301001_16_dialog_content = "아니야, 신경 안 써. 그래서 결과는...",
  str_homestory_820301001_17_dialog_content = "으음, 앞으로 당신의 재운은──",
  str_homestory_820301001_18_dialog_content = "자, 잠깐만, 아직 마음의 준비가 안 됐어...\n혹시나 점이 안 좋게 나왔으면...",
  str_homestory_820301001_19_dialog_content = "당신은 이제 엄청난 부자가 돼서 아무 걱정 없이\n매일 즐겁게 살 수 있어요!<sprite=emo_yaosu size=60 />",
  str_homestory_820301001_20_dialog_content = "진짜?! 그렇게 좋다고?!",
  str_homestory_820301001_21_dialog_content = "믿어요?",
  str_homestory_820301001_22_dialog_content = "어? 그럼 방금 그거 거짓말이었어?",
  str_homestory_820301001_23_dialog_content = "이 결과를 믿는지만 대답해 주면 돼요.",
  str_homestory_820301001_24_option_content = "믿어.",
  str_homestory_820301001_25_dialog_content = "정답이에요!\n그렇게 생각할 수 있다는 게 가장 멋진 거예요!",
  str_homestory_820301001_26_option_content = "안 믿어.",
  str_homestory_820301001_27_dialog_content = "왜 안 믿죠? 저 그럼 화낼 거예요!",
  str_homestory_820301001_28_dialog_content = "「믿음」의 힘은 아주 중요한 거란 말이에요!",
  str_homestory_820301001_29_dialog_content = "당신이 믿기만 하면 어떤 일이든지\n좋은 방향으로 나아간다구요!",
  str_homestory_820301001_30_dialog_content = "근데 그거랑 점이랑 무슨 상관인데?",
  str_homestory_820301001_31_dialog_content = "왜냐하면 점의 결과는──",
  str_homestory_820301001_32_dialog_content = "「이 순간에 충실하라」거든요~",
  str_homestory_820301001_33_dialog_content = "으윽... 아무래도 점술은 그냥 애매모호하게\n말을 잘하는 게 핵심인 모양이네.",
  str_homestory_820301001_34_dialog_content = "인생이란 애초에 머나먼 길이거든요.",
  str_homestory_820301001_35_dialog_content = "그 길에는 여러 갈래의 갈림길이 있어요.",
  str_homestory_820301001_36_dialog_content = "그리고 당신이 내리는 결정은 앞으로의\n길에 영향을 주게 돼요.",
  str_homestory_820301001_37_dialog_content = "아무튼 전 당신의 길에서 빛을 보았어요<sprite=emo_taiyang size=60 />.",
  str_homestory_820301001_38_dialog_content = "이해했어.",
  str_homestory_820301001_39_dialog_content = "미래는 아직 정해지지 않았고,\n그 모든 게 지금 결정된다는 뜻이구나.",
  str_homestory_820301001_40_dialog_content = "우와, 좋은 말이네요! 점술 수첩에 적어 둬야겠어요.",
  str_homestory_820301001_41_dialog_content = "아하하, 어쨌든 너랑 얘기하니까 기분이 좋아졌어.",
  str_homestory_809801001_0_dialog_content = "쿠스쿠타?",
  str_homestory_809801001_1_dialog_content = "쿠스쿠타, 뭐 보고 있어?",
  str_homestory_809801001_2_dialog_content = "꽃이요<sprite=emo_huaduo size=60 />.",
  str_homestory_809801001_3_dialog_content = "꽃밭에는 고개를 들고 하늘을 바라보는 꽃도 있고,\n사람에게 사랑받기를 거절하는 꽃도 있어요.",
  str_homestory_809801001_4_dialog_content = "사람들에게 사랑받는 걸 거부하는 꽃 중에는\n「검은붓꽃」이라는 꽃이 있어요. 들어봤나요?",
  str_homestory_809801001_5_option_content = "들어본 적 있어.",
  str_homestory_809801001_6_dialog_content = "근데... 왜 「사랑받는 걸 거부」하는데?",
  str_homestory_809801001_7_option_content = "들어본 적 없어.",
  str_homestory_809801001_8_dialog_content = "어떤 꽃인데?",
  str_homestory_809801001_9_dialog_content = "「검은붓꽃」은 희귀한 꽃이에요.",
  str_homestory_809801001_10_dialog_content = "그 꽃은 매우 부드럽고,\n색이 깊어서 햇빛을 잘 흡수해요<sprite=emo_taiyang size=60 />.",
  str_homestory_809801001_11_dialog_content = "그러니까 고온에서 상하는 일이 없도록\n항상 잎 밑에 숨어 있어요.",
  str_homestory_809801001_12_dialog_content = "그래서 사랑받기를 거부하는 꽃이 됐어요.",
  str_homestory_809801001_13_dialog_content = "그런 거였구나...",
  str_homestory_809801001_14_dialog_content = "쿠스쿠타 넌 「검은붓꽃」을 좋아하는구나?",
  str_homestory_809801001_15_dialog_content = "좋아한다...?\n어떻게 하면 제가 좋아하는지 알 수 있나요?",
  str_homestory_809801001_16_dialog_content = "음... 쿠스쿠타 넌 「검은붓꽃」에 독특한 평가를 하는구나.\n게다가 그 꽃의 생장 방식도 잘 알고 있네.",
  str_homestory_809801001_17_dialog_content = "아마 그건 그 꽃을 좋아하는 쿠스쿠타만 할 수 있는 일 아닐까?",
  str_homestory_809801001_18_dialog_content = "그런가요...",
  str_homestory_809801001_19_dialog_content = "사실 「검은붓꽃」은 시체에 피는 꽃이에요.",
  str_homestory_809801001_20_dialog_content = "뭐?! 시체?!",
  str_homestory_809801001_21_dialog_content = "네, 그래요. 그러니까...",
  str_homestory_809801001_22_dialog_content = "여긴 곧... 「검은붓꽃」이 필 것 같아요.",
  str_homestory_809801001_23_dialog_content = "그, 그거... 설마 여기 시체가 묻혀있다는 거야?!",
  str_homestory_809801001_24_dialog_content = "걱정하지 마세요. 이미 확인했으니까요.",
  str_homestory_809801001_25_dialog_content = "전... 이제 곧 시들어 버릴 제 몸을 말한 거예요.",
  str_homestory_809801001_26_dialog_content = "전 이제 곧 잠들 거예요.\n그럼 「검은붓꽃」이 피어나겠죠.",
  str_homestory_809801001_27_dialog_content = "그, 그럴 리가 없잖아. 쿠스쿠타!",
  str_homestory_809801001_28_dialog_content = "큐브가 그랬어. 헤븐즈 가든의 토양에는 특수한 물질이 있대.",
  str_homestory_809801001_29_dialog_content = "그러니까... 「검은붓꽃」이 피어도 이상하지 않을 거야...",
  str_homestory_809801001_30_dialog_content = "게다가... 어쩌면 알록달록한 꽃이 필지도 몰라!",
  str_homestory_809801001_31_dialog_content = "「알록달록」...",
  str_homestory_809801001_32_dialog_content = "그 말... 정말인가요?<sprite=emo_yundao size=60 />",
  str_homestory_809801001_33_dialog_content = "응! 그럼 같이 알록달록한 꽃을 키워볼래?",
  str_homestory_809801001_34_dialog_content = "「같이 키운다」... 그건 일인가요?",
  str_homestory_809801001_35_dialog_content = "음, 좀 다른 것 같아...",
  str_homestory_809801001_36_dialog_content = "PlayerName 씨도 꽃을 좋아하나요?",
  str_homestory_809801001_37_dialog_content = "그렇다고 할 수 있겠지!",
  str_homestory_809801001_38_dialog_content = "난 헤븐즈 가든의 경관이 좀 단조롭다고 생각했거든.",
  str_homestory_809801001_39_dialog_content = "근데 네 덕분에 생각났어. 꽃으로 색을 더하면 되는 거잖아!",
  str_homestory_809801001_40_dialog_content = "그럼... 색감을 더하면 사람들이 좋아한다는 건가요?",
  str_homestory_809801001_41_dialog_content = "당연하지! 같이 여기저기 둘러보고 다른 색의 꽃을 찾아볼래?",
  str_homestory_809801001_42_dialog_content = "음... 한번 해 볼게요.",
  str_homestory_809801001_43_dialog_content = "다만, 당신이 말하는 「알록달록」에는\n금색도 포함되나요?",
  str_homestory_809801001_44_dialog_content = "물속에서 금색으로 빛나는 건 꽃일까요?",
  str_homestory_820101001_0_dialog_content = "뭐 보고 있어?",
  str_homestory_820101001_1_dialog_content = "만약...",
  str_homestory_820101001_2_dialog_content = "혹시 내가 방해했어?",
  str_homestory_820101001_3_dialog_content = "아, 아니야. 그저 생각을 좀 하고 있었어.\n결정하기 어려운 일이 있어서...",
  str_homestory_820101001_4_dialog_content = "내가 도울 일이 있을까?",
  str_homestory_820101001_5_dialog_content = "응, 일단 질문 하나만 해도 될까?",
  str_homestory_820101001_6_dialog_content = "당연하지.",
  str_homestory_820101001_7_dialog_content = "만약 하루의 기억을 영원히 간직할 수 있다면,\n넌 어느 날을 선택하고 싶어?",
  str_homestory_820101001_8_dialog_content = "영원히 간직하고 싶은 날이라... 확실히 어렵네.",
  str_homestory_820101001_9_dialog_content = "그래서 고민하고 있었던 거구나.",
  str_homestory_820101001_10_dialog_content = "이걸 보니까 그런 생각이 들어서...",
  str_homestory_820101001_11_dialog_content = "음... 나도 좀 생각해 볼게.",
  str_homestory_820101001_12_option_content = "콜로서스를 가동한 날...",
  str_homestory_820101001_13_dialog_content = "스카이워커를 가동하는 데 성공한 그날의 기억을 간직하고 싶어.",
  str_homestory_820101001_14_dialog_content = "그날 난 처음으로 아스트라 대륙의 모습을 봤어.",
  str_homestory_820101001_15_dialog_content = "어떻게 보면 그건 내 인생의 진짜 시작이라고 할 수 있을 거야.",
  str_homestory_820101001_16_option_content = "귀환의 탑이 나타난 날...",
  str_homestory_820101001_17_dialog_content = "탑이 다시 세상 밖으로 솟아올랐던 그날의 기억을 간직하고 싶어.",
  str_homestory_820101001_18_dialog_content = "그때 내 감응 능력이 강화돼서, 난 아스트라 대륙의 모든 구석을\n내려다볼 수 있었어.",
  str_homestory_820101001_19_dialog_content = "그건 정말 충격적인 경험이었어.",
  str_homestory_820101001_20_dialog_content = "확실히 아주 중요한 날인 것 같네.",
  str_homestory_820101001_21_dialog_content = "PlayerName 넌 그날을 바로 떠올릴 수 있는 거구나.",
  str_homestory_820101001_22_dialog_content = "콜로서스 가동에 성공하기 전까지 내가 보낸 날들은\n매일이 똑같은 반복이었어.",
  str_homestory_820101001_23_dialog_content = "그러다 모두를 만나고 나서야 내 기억은 조금씩 풍부해진 거야.",
  str_homestory_820101001_24_dialog_content = "그래서 난 모든 추억을 소중하게 생각하고 있어.\n내 머릿속엔 모두가 뚜렷하게 떠올라.",
  str_homestory_820101001_25_dialog_content = "난 앞으로도 노력해서 이 모든 걸 기억할 거야.\n하루하루가 영원히 기억에 남도록 말이야.",
  str_homestory_820101001_26_dialog_content = "으음......<sprite=emo_sikao size=60 />",
  str_homestory_820101001_27_dialog_content = "그럼 넌 어떻게 생각하는데, 미아?",
  str_homestory_820101001_28_dialog_content = "난...",
  str_homestory_820101001_29_dialog_content = "한때 중요한 일들을 잊어버렸다가\n최근에서야 생각이 났어...",
  str_homestory_820101001_30_dialog_content = "앞으로 또 잊어버릴까 걱정이 돼.\n그래서 간직하고 싶어...",
  str_homestory_820101001_31_dialog_content = "하지만 아무리 생각해도... 어머님, 여동생...\n추억이 너무 많아서 도저히 결정할 수가 없어.",
  str_homestory_820101001_32_dialog_content = "미아...",
  str_homestory_820101001_33_dialog_content = "아, 미안해. 너까지 곤란하게 해버려서...",
  str_homestory_820101001_34_dialog_content = "사과해야 할 건 나야. 내가 괜한 말을 했네...",
  str_homestory_820101001_35_dialog_content = "으음, 아니야, PlayerName.",
  str_homestory_820101001_36_dialog_content = "네 말을 들으니까 오히려 마음이 많이 편해졌거든.",
  str_homestory_820101001_37_dialog_content = "진짜?",
  str_homestory_820101001_38_dialog_content = "응! 잊을까 봐 걱정하는 것보다는...\n지금을 소중히 여기는 게 중요하니까<sprite=emo_yaosu size=60 />",
  str_homestory_820401001_0_dialog_content = "조슈아 씨?",
  str_homestory_820401001_1_dialog_content = "뭐 하고 계세요?",
  str_homestory_820401001_2_dialog_content = "PlayerName, 이것 좀 봐.",
  str_homestory_820401001_3_dialog_content = "이 화분, 아주 잘 자라고 있잖아~",
  str_homestory_820401001_4_dialog_content = "무슨 품종인지 관찰하고 있었어.",
  str_homestory_820401001_5_dialog_content = "그랬군요. 그래서 무슨 품종인지 알아채셨나요?",
  str_homestory_820401001_6_dialog_content = "아니, 아직은 무슨 식물인지 모르겠어...",
  str_homestory_820401001_7_dialog_content = "넌 알고 있니?",
  str_homestory_820401001_8_option_content = "(끄덕인다)",
  str_homestory_820401001_9_dialog_content = "제가 조금 전에 움브라톤에서 사 왔거든요.",
  str_homestory_820401001_10_dialog_content = "그냥 적당히 몇 개 골라서 사 봤어요.",
  str_homestory_820401001_11_dialog_content = "가게 주인 말로는... 장원 분재라고 했던 것 같은데요?",
  str_homestory_820401001_12_dialog_content = "아무튼 아마 장원 분재가 맞을 거예요.",
  str_homestory_820401001_13_dialog_content = "이름은 평범하지만 아주 잘 돌보고 있구나~",
  str_homestory_820401001_14_dialog_content = "헤헤, 가게 주인이 이 품종은 잘 자란다고 했거든요.",
  str_homestory_820401001_15_option_content = "(고개를 젓는다)",
  str_homestory_820401001_16_dialog_content = "아, 사실 저도 잘 몰라요.",
  str_homestory_820401001_17_dialog_content = "가게 주인이 일 년 내내 푸른 식물이라고 했던 기억은 나요.",
  str_homestory_820401001_18_dialog_content = "심지어 실내에서도 키울 수 있어요.",
  str_homestory_820401001_19_dialog_content = "기르기 좋은 품종인 모양이구나.",
  str_homestory_820401001_20_dialog_content = "PlayerName네에는 푸른 식물이 참 많네.",
  str_homestory_820401001_21_dialog_content = "혹시 꽃을 심을 생각은 없니<sprite=emo_huaduo size=60 />?",
  str_homestory_820401001_22_dialog_content = "그럼 주변 환경도 더는 단조롭지 않게 될 거야.",
  str_homestory_820401001_23_dialog_content = "그거 좋은 생각이네요!",
  str_homestory_820401001_24_dialog_content = "근데 전 꽃은 잘 키울 줄 모르는걸요...",
  str_homestory_820401001_25_dialog_content = "역시 전 초록색 식물이 더 키우기 쉬운 것 같아요.",
  str_homestory_820401001_26_dialog_content = "백야성에 있을 때 난 정원에 다양한 꽃을 심었어.",
  str_homestory_820401001_27_dialog_content = "별일이 없을 땐 꽃에 물을 주고, 가지를 잘라주곤 했어.",
  str_homestory_820401001_28_dialog_content = "그러면 마음이 무척 안정되거든.",
  str_homestory_820401001_29_dialog_content = "꽃을 키우는 게 취미셨군요!",
  str_homestory_820401001_30_dialog_content = "그럼 혹시 저한테 꽃 키우는 법 좀 가르쳐 주실 수 있나요?",
  str_homestory_820401001_31_dialog_content = "물론이지~",
  str_homestory_820401001_32_dialog_content = "꽃을 키우는 건 그렇게 어려운 일이 아니야.\n하지만 인내심이 필요해.",
  str_homestory_820401001_33_dialog_content = "심은 지 얼마 안 됐을 땐 꽃들이 무척 민감하거든.",
  str_homestory_820401001_34_dialog_content = "이 화분은 초기 재배에 쓰기 좋을 거야.",
  str_homestory_820401001_35_dialog_content = "씨를 뿌리고, 정해진 시간에 물을 주고<sprite=emo_hanshui size=60 />, 싹이 트길 기다리면 돼.",
  str_homestory_820401001_36_dialog_content = "대신 물을 너무 많이 주는 건 금물이야.",
  str_homestory_820401001_37_dialog_content = "알겠어요. 그리고 그 다음엔요?",
  str_homestory_820401001_38_dialog_content = "싹이 트고 나면 다시 한 달을 기르면 돼.",
  str_homestory_820401001_39_dialog_content = "그동안에는 새싹들에게 더 많은 영양을 줘도 좋아~",
  str_homestory_820401001_40_dialog_content = "그리고 묘목까지 크고 나면 더 넓은 곳으로\n옮겨 심을 수 있어.",
  str_homestory_820401001_41_dialog_content = "옮겨 심어야 하는 거였군요...",
  str_homestory_820401001_42_dialog_content = "그래, PlayerName 너도 작은 새싹에서\n용감한 아이로 자라서──",
  str_homestory_820401001_43_dialog_content = "여러 곳으로 모험을 떠났잖니?",
  str_homestory_820401001_44_dialog_content = "그게 바로 성장의 일환이란 거야.",
  str_homestory_820401001_45_dialog_content = "그, 그것도 맞는 말이긴 하네요...",
  str_homestory_820401001_46_dialog_content = "조금 쑥스럽지만요...",
  str_homestory_820401001_47_dialog_content = "후훗, PlayerName 넌 역시 착한 아이라니까~",
  str_homestory_820501001_0_dialog_content = "블랑 씨?",
  str_homestory_820501001_1_dialog_content = "방금 눈을 감고 있던 것 같은데, 자고 있었나요<sprite=emo_kun size=60 />?",
  str_homestory_820501001_2_dialog_content = "아니요, 명상을 하고 있었어요.",
  str_homestory_820501001_3_dialog_content = "명상이요?",
  str_homestory_820501001_4_dialog_content = "네, 명상에 대해 아시나요?",
  str_homestory_820501001_5_option_content = "대강 알고는 있어요.",
  str_homestory_820501001_6_dialog_content = "명상을 하면 몸과 마음이 편안해지고\n상처를 치유할 수 있다고 들었어요.",
  str_homestory_820501001_7_dialog_content = "네, 맞아요. 확실히 그런 효과가 있죠.",
  str_homestory_820501001_8_option_content = "잘 모르겠어요.",
  str_homestory_820501001_9_dialog_content = "명상은 정신을 단련하는 일이에요.\n심신을 편안하게 하고 상처를 치유할 수 있답니다.",
  str_homestory_820501001_10_dialog_content = "마음이 안 좋은 건가요?\n무슨 곤란한 일이라도 있었나요?",
  str_homestory_820501001_11_dialog_content = "사실 혼자 명상하는 방법 대신 친구랑 이야기하는\n것도 괜찮다고 생각해요. 저도 있잖아요.",
  str_homestory_820501001_12_dialog_content = "아까 블랑 씨 혼자 있는 모습이 왠지 쓸쓸해 보였거든요.",
  str_homestory_820501001_13_dialog_content = "신경 써 줘서 고마워요.",
  str_homestory_820501001_14_dialog_content = "저도 물론 당신과 이야기하는 건 좋아요.\n다만 지금 명상하던 내용은 당신에게 말해줄 수 없어요.",
  str_homestory_820501001_15_dialog_content = "음, 말해도 의미가 없다고 하는 게 맞을 수도 있겠죠.",
  str_homestory_820501001_16_dialog_content = "그렇게 심각한 문제인가요?\n그럼 저도 뭔가 방법을 생각해 볼게요...",
  str_homestory_820501001_17_dialog_content = "후후. 당신 같은 친구라면 확실히 제가 원하는 것에\n도움이 될지도 모르겠네요.",
  str_homestory_820501001_18_dialog_content = "당신을 만나면 기분이 무척 즐거워지거든요.",
  str_homestory_820501001_19_dialog_content = "그것도 미용의 비결이라 할 수 있겠죠.",
  str_homestory_820501001_20_dialog_content = "미용이요?",
  str_homestory_820501001_21_dialog_content = "맞아요, 방금 명상의 내용은 노화를 막고\n피부 관리를 하는 거였거든요.",
  str_homestory_820501001_22_dialog_content = "그런 게... 명상으로 가능한 건가요?",
  str_homestory_820501001_23_dialog_content = "정신의 힘은 무척 강한 거랍니다.",
  str_homestory_820501001_24_dialog_content = "어때요? 당신도 한번 해 볼래요?",
  str_homestory_820501001_25_dialog_content = "명상으로 아주 아주 강한 전투력을 가질 수도 있을까요?",
  str_homestory_820501001_26_dialog_content = "그게 당신이 원하는 건가요?",
  str_homestory_820501001_27_dialog_content = "맞아요. 그래야 지키고 싶은 사람이나 물건을\n지킬 수 있으니까요.",
  str_homestory_820501001_28_dialog_content = "당신의 생각에는 저도 찬성해요.\n저도 줄곧 「지키기」 위해 싸워 왔으니까요.",
  str_homestory_820501001_29_dialog_content = "다만 「지킨다」는 것에도 여러 가지 형태가 있답니다.",
  str_homestory_820501001_30_dialog_content = "예를 들어, 전 평소엔 가이드일 뿐이지만,\n그것도 다른 방식으로 백야성을 지키고 있는 거예요.",
  str_homestory_820501001_31_dialog_content = "왜 그 얘기를 하는 거죠?\n설마... 제 소망은 이루어질 수 없다는 건가요?",
  str_homestory_820501001_32_dialog_content = "명상으로 근육을 단련하고 키울 수 있을지는\n저도 잘 모르겠어요.",
  str_homestory_820501001_33_dialog_content = "하지만 한번 시도해 봐도 좋을 것 같네요.",
  str_homestory_820501001_34_dialog_content = "음... 역시 무리겠죠...",
  str_homestory_807501001_0_dialog_content = "오디?",
  str_homestory_807501001_1_dialog_content = "이런 곳에 이런 좋은 물건이 있었단 말이야?!",
  str_homestory_807501001_2_dialog_content = "내 렌치 어디 갔지? 지금 당장 분해를 시작해야겠어!",
  str_homestory_807501001_3_dialog_content = "잠깐만, 뭘 분해할 건데?",
  str_homestory_807501001_4_dialog_content = "이 가로등, 안 돼?",
  str_homestory_807501001_5_option_content = "안 돼.",
  str_homestory_807501001_6_option_content = "가로등이 고장 났어?",
  str_homestory_807501001_7_dialog_content = "아니, 그냥 분해하고 싶을 뿐이야.",
  str_homestory_807501001_8_dialog_content = "그럼 안 돼<sprite=emo_shengqi size=60 />.",
  str_homestory_807501001_9_dialog_content = "야! 왜 안 되는데?\n그냥 별거 아닌 가로등일 뿐이잖아!",
  str_homestory_807501001_10_dialog_content = "고장도 안 났는데 분해를 왜 해?",
  str_homestory_807501001_11_dialog_content = "당연히 연구하기 위해서지.",
  str_homestory_807501001_12_dialog_content = "봐, 이 가로등, 다른 조명이랑 완전 다르잖아.",
  str_homestory_807501001_13_dialog_content = "딱히 다르지도 않은데.",
  str_homestory_807501001_14_dialog_content = "난 겉만 봐도 내부의 복잡한 톱니바퀴와\n전기회로가 보인다고.",
  str_homestory_807501001_15_dialog_content = "백야성 가로등은 확실히 그런 구조가 아니겠지...",
  str_homestory_807501001_16_dialog_content = "그러니까 넌 못 알아듣는다고.",
  str_homestory_807501001_17_dialog_content = "너도 제대로 설명 안 했잖아.",
  str_homestory_807501001_18_dialog_content = "헤에~ 너 요즘 디스하는 실력이 좀 늘었는데?",
  str_homestory_807501001_19_dialog_content = "알겠어, 무슨 일이 있어도 이 가로등을 지킨다 이거지?",
  str_homestory_807501001_20_dialog_content = "그럼 지금 여기서 나랑 승부하자.",
  str_homestory_807501001_21_dialog_content = "고장 날 때까지 두들겨 줄 테니까!",
  str_homestory_807501001_22_dialog_content = "난 기계도 아닌데 고장이 왜 나?",
  str_homestory_807501001_23_dialog_content = "고장 날 건 네 개조 케이블이겠지.",
  str_homestory_807501001_24_dialog_content = "지금 나 도발하는 거야?",
  str_homestory_807501001_25_dialog_content = "그냥 사실을 말했을 뿐인데...",
  str_homestory_807501001_26_dialog_content = "우리 기술자들을 바보 취급하지 마!\n아무리 네가 아이테르라도 난...",
  str_homestory_807501001_27_dialog_content = "???",
  str_homestory_807501001_28_dialog_content = "음... 그 뒤에 뭐라고 디스할지 갑자기 안 떠올라<sprite=emo_sikao size=60 />.",
  str_homestory_807501001_29_dialog_content = "푸훕...",
  str_homestory_807501001_30_dialog_content = "야! 또 비웃으면 지금 당장 통신기로\n다른 사람들 부를 거야!",
  str_homestory_807501001_31_dialog_content = "아하하하!",
  str_homestory_807501001_32_dialog_content = "웃어? 사메야마 대장 부를 거야. 무섭지?",
  str_homestory_807501001_33_dialog_content = "사메야마가 네 편일 거라고 확신해?",
  str_homestory_807501001_34_dialog_content = "으음... 그것도 확실히 좀...",
  str_homestory_807501001_35_dialog_content = "그러니까 넌 이 가로등을 연구하고 싶은 거지?",
  str_homestory_807501001_36_dialog_content = "맞아, 이런 정교한 구조를 보면 분해하고 싶어서\n손이 근질거린다구.",
  str_homestory_807501001_37_dialog_content = "근데 이 가로등은 지금 안정적으로 가동되고 있고,\n내부 구조에도 아무 문제 없어.",
  str_homestory_807501001_38_dialog_content = "차라리 고장 났을 때 너한테 수리를 맡기는 건 어때?",
  str_homestory_807501001_39_dialog_content = "그거 좋은 생각이네! 잡동사니 수리는 내 특기니까!",
  str_homestory_807501001_40_dialog_content = "좋아, 오늘은 분해 안 할래.",
  str_homestory_807501001_41_dialog_content = "그럼 나도 가로등 대신 고맙다고 해야겠네.",
  str_homestory_807501001_42_dialog_content = "참, 아까 물속에 반짝반짝 빛나는 걸 봤는데,\n무슨 기계 부품일 수도 있어!",
  str_homestory_807501001_43_dialog_content = "한번 건져서 분해해 봐!",
  str_homestory_807501001_44_dialog_content = "으음... 그럼 일단 물건부터 빨리 건지러 가야겠네.",
  str_homestory_820601001_0_dialog_content = "뭐 하고 있는 거지?",
  str_homestory_820601001_1_dialog_content = "로렐라이, 뭐 보고 있어?<sprite=emo_yihuo size=60 />",
  str_homestory_820601001_2_dialog_content = "위에서 바라보는 경치는 정말 근사하네!",
  str_homestory_820601001_3_dialog_content = "한참 이러고 있었던 거 같은데,\n진짜 경치만 보고 있던 거야?",
  str_homestory_820601001_4_dialog_content = "경치 이야기는 나중에 하자.\n저기, 나랑 같이 일해 보지 않을래?",
  str_homestory_820601001_5_dialog_content = "아이테르가 가지고 있는 섬세한 감각이라면,\n앞으로의 비즈니스 경쟁에 분명 도움이 될 거야!",
  str_homestory_820601001_6_dialog_content = "비즈니스 경쟁? 내가?",
  str_homestory_820601001_7_dialog_content = "「비즈니스 시장은 전쟁터다」라는 말이 있어.\n나한테는 너 같은 인재가 필요해!",
  str_homestory_820601001_8_dialog_content = "인센티브도 지급하고 지분도 나눠 줄게!\n어때? 생각 있어?",
  str_homestory_820601001_9_dialog_content = "그럼 사업 전망이랑 지분이 얼마인지부터 좀 보고...",
  str_homestory_820601001_10_dialog_content = "...잠깐만! 나 아직 하겠다고 안 했어!",
  str_homestory_820601001_11_dialog_content = "아니 근데 갑자기 비즈니스 경쟁 얘긴 왜 나온 거야?\n그거랑 여기서 경치를 보던 거랑은 딱히 상관없지 않아?",
  str_homestory_820601001_12_dialog_content = "실은 아까 기막힌 사업 아이디어가 떠올랐거든.\n다른 사람들한텐 비밀이다...?",
  str_homestory_820601001_13_dialog_content = "아, 알겠어.",
  str_homestory_820601001_14_dialog_content = "그건 바로... 블루 오션에 진출하는 거야!",
  str_homestory_820601001_15_option_content = "블루 오션이라니?",
  str_homestory_820601001_16_dialog_content = "말 그대로 넓고 푸른 바다지!",
  str_homestory_820601001_17_dialog_content = "그럼... 해운 사업하려고?",
  str_homestory_820601001_18_option_content = "조선업?",
  str_homestory_820601001_19_dialog_content = "아니야!",
  str_homestory_820601001_20_dialog_content = "블루 오션은 일종의 비유야! 비유!",
  str_homestory_820601001_21_dialog_content = "...비유?",
  str_homestory_820601001_22_dialog_content = "아직 개척되지 않아서 기회로 가득한 시장이란 거지.\n고기가 잔뜩 잡히는 넓고 푸른 바다처럼 말이야!",
  str_homestory_820601001_23_dialog_content = "근데 그거랑 전망대에서 경치를 구경하고 있던 거랑\n무슨 상관이 있는데?",
  str_homestory_820601001_24_dialog_content = "전망대에서 바다 위에 떠 있는 섬들을 보니까,\n섬들 대부분 개발이 별로 안 된 상태더라고!",
  str_homestory_820601001_25_dialog_content = "그러니까 실제로도, 그리고 사업적인 측면에서도\n블루 오션인 거지!",
  str_homestory_820601001_26_dialog_content = "섬을 찾아서 거길 테마 리조트로 개발할 수 있다면...",
  str_homestory_820601001_27_dialog_content = "바캉스, 어드벤처, 보물찾기,\n레저 스포츠, 수영복, 키즈 파크...",
  str_homestory_820601001_28_dialog_content = "아이디어가 마구마구 샘솟고 있다니까!",
  str_homestory_820601001_29_dialog_content = "그러니까 섬을 개발할 생각이란 거지?\n구체적인 목표는 있어?",
  str_homestory_820601001_30_dialog_content = "있지! 근데 아직 적당한 섬을 못 찾았어.\n그래서 바다에 섬을 찾으러 나갈 때 쓸\n배를 하나 만들어 볼까 해.",
  str_homestory_820601001_31_dialog_content = "이렇게 넓은 바다에 무인도 하나 없는 건 이상하잖아!",
  str_homestory_820601001_32_dialog_content = "어쨌든 남들보다 한발 먼저 발견해 버리기만 한다면\n그 섬은 통째로 우리 소유가 되는 거고,\n그럼 마음대로 개발할 수 있어!",
  str_homestory_820601001_33_dialog_content = "우리? 나도 같이 가는 거야?",
  str_homestory_820601001_34_dialog_content = "응! 넌 눈도, 귀도 평범한 사람보다 훨씬 좋으니까...\n무조건 도움이 될 거라고 생각하거든.",
  str_homestory_820601001_35_dialog_content = "그렇게 얘기해 주니까, 왠지 내가 엄청 대단한 사람 같네.",
  str_homestory_820601001_36_dialog_content = "아무튼, 그 계획의 첫걸음을 떼려면\n우선 적당한 섬을 찾아야 한단 거지?",
  str_homestory_820601001_37_dialog_content = "정확해. 그래서 배에다 이 전망대를 가져다 두면,\n더 멀리까지 볼 수 있을지 확인해 보고 싶거든.",
  str_homestory_820601001_38_dialog_content = "마침 네가 온 김에 가격도 좀 물어볼게.",
  str_homestory_820601001_39_dialog_content = "팔 생각은 없는데...<sprite=emo_tanqi size=60 />",
  str_homestory_820601001_40_dialog_content = "그럼 이 전망대로 현물 출자를 하려는 거지?\n너도 이 사업 아이템이 꽤 마음에 든 모양이네?",
  str_homestory_820601001_41_dialog_content = "그런 얘기가 아니야.",
  str_homestory_820601001_42_dialog_content = "조금 더 생각해 보고 싶어? 그럼 그렇게 해.\n어차피 사업 제안서도 아직 안 적었거든.\n서류에 서명하기 전까진 뭐든 조정할 수 있어.",
  str_homestory_820601001_43_dialog_content = "최대한 빨리 구체적인 계획을 세워 둘 테니까,\n너도 되도록 빨리 결정해 줘!",
  str_homestory_820601001_44_dialog_content = "...안녕.",
  str_homestory_820701001_0_dialog_content = "...놀고 있는 건가?",
  str_homestory_820701001_1_dialog_content = "재밌게 타고 있는 거 같네요.",
  str_homestory_820701001_2_dialog_content = "아이테르 동생, 이제 보니 얼리어답터였군!\n헤븐즈 가든에 벌써 새 아이템을 들여오다니!\n아주 자극적이야!",
  str_homestory_820701001_3_dialog_content = "근데 이건 원래 둘이서 타는 거라고 하던데요.",
  str_homestory_820701001_4_dialog_content = "확실히 이걸로 두 사람을 테스트할 수 있다고 하더군. 특히 연인들 말이야...<sprite=emo_sikao size=60 />",
  str_homestory_820701001_5_dialog_content = "테스트요?",
  str_homestory_820701001_6_dialog_content = "두 사람이 확실히 연인이 되고 나서,\n이걸 타고 몇 바퀴 돌고...",
  str_homestory_820701001_7_dialog_content = "내리고 나서도 서로 상대가 어땠는지를 묻거나,\n상대를 배려하는 말을 한다면...",
  str_homestory_820701001_8_dialog_content = "그 두 사람의 관계는 아무 문제도 없는 거지.\n하지만 그렇지 못했다면... 쯧쯧.",
  str_homestory_820701001_9_dialog_content = "그렇다면 세나 씨는 왜 혼자서 이걸 타는 건데요?\n미래에 있을 테스트에 대비하는 건가요?",
  str_homestory_820701001_10_dialog_content = "아니지, 동생!",
  str_homestory_820701001_11_dialog_content = "이걸 타면 온 세상이 빙글빙글 도는 것처럼 어지럽고,\n무척이나 자극적이야.",
  str_homestory_820701001_12_dialog_content = "지나간 옛날 일들 생각이 날 정도로 말이야...",
  str_homestory_820701001_13_dialog_content = "무슨 일이었는데요? ...왠지 긴 얘기가 될 거 같네요.",
  str_homestory_820701001_14_dialog_content = "난 한때 「사냥꾼」이었어.\n악당들만 골라서 손을 봐줬었지.",
  str_homestory_820701001_15_dialog_content = "치안관 같은 건가요?\n근데 세나 씨는 레디젤 사막 출신 아니었어요...?",
  str_homestory_820701001_16_dialog_content = "거긴 레디젤 렌치처럼 몰려다니는 녀석들은 있어도,\n악당은 없지 않나요?",
  str_homestory_820701001_17_dialog_content = "내가 개인적으로 했던 행동이야.\n그래서 「치안관」이 아니라 「사냥꾼」이라고 한 거고.",
  str_homestory_820701001_18_dialog_content = "그럼 어떤 악당들을 손 봐줬단 거예요?\n설마 세나 씨 과거랑 관련된 건가요?",
  str_homestory_820701001_19_dialog_content = "데누오 계곡의 마을이 파괴됐던 거랑 관계가 있나요?",
  str_homestory_820701001_20_dialog_content = "어디부터 시작해야 할까...\n좋아, 이야기를 하나 들려주지.",
  str_homestory_820701001_21_dialog_content = "네.",
  str_homestory_820701001_22_dialog_content = "옛날 옛적에, 아주 대단한 어부가 하나 살고 있었는데,\n물고기를 잡는 능력이 정말 엄청났지.",
  str_homestory_820701001_23_dialog_content = "중요한 건 그 어부가 짠 그물은 굉장히 촘촘해서,\n결려 든 물고기는 절대로 도망치지 못했단 거야.",
  str_homestory_820701001_24_dialog_content = "그래서 바다로 나갈 때마다 고기를 많이 잡아 왔고,\n그렇게 그 어부는 부자가 됐다.",
  str_homestory_820701001_25_dialog_content = "그런데... 점점 고기가 잡히지 않게 된 거야.",
  str_homestory_820701001_26_dialog_content = "물고기들이 사라진 건가요?",
  str_homestory_820701001_27_dialog_content = "그렇지! 그물이 너무 촘촘해서,\n치어들까지 족족 잡아들여 버렸으니까.",
  str_homestory_820701001_28_dialog_content = "고기들은 점차 사라졌고, 어부도 배를 곯을 정도로\n가난해졌다. 그러던 어느 날...",
  str_homestory_820701001_29_dialog_content = "여기서부터 전개가 달라지는 거군요.<sprite=emo_yaosu size=60 />",
  str_homestory_820701001_30_dialog_content = "어부의 아들이 비밀스러운 암초들 사이에서\n아름다운 물고기 한 마리를 잡은 거다!",
  str_homestory_820701001_31_dialog_content = "몸집으로 보면 아직 어린 물고기인 거 같았지만,\n생김새만큼은 정말 아름다웠지.",
  str_homestory_820701001_32_dialog_content = "그리고 집으로 돌아가선 그만 어부한테,\n그러니까 자기 아버지한테 그 사실을 전하고 말았다.",
  str_homestory_820701001_33_dialog_content = "어부는 그 얘길 들고 바로 그 물고기를 잡으러 갔겠네요.",
  str_homestory_820701001_34_dialog_content = "어부는 어떻게든 그걸 잡아 오겠다면서\n가장 튼튼하고 촘촘한 그물을 챙겨 떠났지.",
  str_homestory_820701001_35_dialog_content = "왜냐하면 어부는 그 물고기가 시장에 내놓으면\n비싼 값에 팔릴 관상어라는 걸 알고 있었거든.",
  str_homestory_820701001_36_dialog_content = "그래서 아들한테 거기까지 안내하라고 하고,\n둘이서 같이 그 비밀스러운 암초로 향했는데...",
  str_homestory_820701001_37_dialog_content = "이제부터 일이 제대로 꼬일 거 같네요.",
  str_homestory_820701001_38_dialog_content = "맞아! 아닌 게 아니라, 그 둘이 발견한 물고기는\n저번 녀석보다 훨씬 크고 아름다웠어!",
  str_homestory_820701001_39_dialog_content = "어부 아들이 처음에 봤던 물고기의 부모인 걸까요?",
  str_homestory_820701001_40_dialog_content = "아마 그렇겠지.",
  str_homestory_820701001_41_dialog_content = "아무튼 그 아름답고 커다란 물고기는 배를 보자마자\n암초 속을 헤엄치며 도망 다니기 시작했다.",
  str_homestory_820701001_42_dialog_content = "어부도 배로 그 뒤를 따라다니면서\n쫓고 쫓기는 추격전을 벌이고 있었는데...",
  str_homestory_820701001_43_dialog_content = "결국엔 암초에 부딪히고 만 거군요.",
  str_homestory_820701001_44_dialog_content = "그래. 배는 가라앉았고, 어부도, 아들도 목숨을 잃었지.",
  str_homestory_820701001_45_dialog_content = "음...",
  str_homestory_820701001_46_dialog_content = "그럼 아까 말한 악당은 누구예요?\n이 이야기에 나온 어부랑 아들은 둘 다 이미 목숨을 잃었잖아요.",
  str_homestory_820701001_47_dialog_content = "그러니까 그냥 옛날이야기라고 했잖아.\n억지로 꿰맞추면 안 되지.",
  str_homestory_820801001_0_dialog_content = "한참을 저러고 있네...",
  str_homestory_820801001_1_dialog_content = "뭐 해?",
  str_homestory_820801001_2_dialog_content = "어? 너였구나!\n내가 여기 있는 걸 어떻게 알았어?!<sprite=emo_wuzui size=60 />",
  str_homestory_820801001_3_dialog_content = "보프 네가 여기서 비석을 한참 보고 있길래.\n계속 보고 있으면 눈 안 아파?",
  str_homestory_820801001_4_dialog_content = "그렇게 물어보니까 좀 아픈 것도 같아...",
  str_homestory_820801001_5_dialog_content = "...가 아니라!\n중요한 건 내가 여기 있단 걸 어떻게 알았냐는 거야!",
  str_homestory_820801001_6_dialog_content = "설마 그게 바로 이 기념비가 지닌 힘이야?\n존재감이 없는 사람도 주목받게 해 주는 거?!",
  str_homestory_820801001_7_dialog_content = "아니, 진짜로 네가 여기 되게 오래 서 있길래 안 거야.",
  str_homestory_820801001_8_dialog_content = "이 기념비에 그려진 것들 좀 봐!\nPlayerName, 무슨 의미인지 알아?",
  str_homestory_820801001_9_dialog_content = "잘 모르겠는데... 엄청 오래전에 남겨진 거 같아.",
  str_homestory_820801001_10_dialog_content = "너무 오래돼서 이젠 원래 무슨 뜻이었는지\n확실하게 알아내기 어려울걸.",
  str_homestory_820801001_11_dialog_content = "그러려나... 에휴...",
  str_homestory_820801001_12_dialog_content = "갑자기 표정이 왜 그래? 실망한 것 같네.",
  str_homestory_820801001_13_dialog_content = "난 지금 레디젤 렌치의 미래를 생각하고 있었거든...",
  str_homestory_820801001_14_option_content = "무슨 미래?",
  str_homestory_820801001_15_dialog_content = "아직 구체적으로 떠오른 건 없어. 그래도 장기적인 목표는 꼭 필요해... 계속 지금처럼 되는대로 건들거리고 다닐 순 없으니까.",
  str_homestory_820801001_16_dialog_content = "레디젤 렌치는 원래 그런 스타일인걸.\n그게 마음에 들어서 합류한 사람들도 많잖아.",
  str_homestory_820801001_17_dialog_content = "맞는 말이긴 한데... 계획은 있는 게 좋잖아!\n지금 딱히 떠오르는 건 없지만, 계획은 꼭 있어야 해!",
  str_homestory_820801001_18_option_content = "생각이 너무 많은 거 아니야?",
  str_homestory_820801001_19_dialog_content = "......",
  str_homestory_820801001_20_dialog_content = "보프?",
  str_homestory_820801001_21_dialog_content = "이유는 모르겠지만, 적어도 누군가는 생각이 많을\n필요가 있단 느낌이 든단 말이야!",
  str_homestory_820801001_22_dialog_content = "맨날 껄렁껄렁 쏘다니고, 되는대로 대충 하는 건...\n믿음직한 구석이 하나도 없잖아.",
  str_homestory_820801001_23_dialog_content = "너 진지하게 고민하고 있었구나... 고생이 많네...",
  str_homestory_820801001_24_dialog_content = "근데 사메야마가 딱히 그런 고민을 할 거 같진 않은데.",
  str_homestory_820801001_25_dialog_content = "알아. 근데 난 대장은 언제나 지금처럼 털털한 리더로\n있어 주면 그걸로 된다고 생각해.",
  str_homestory_820801001_26_dialog_content = "그런 계획은 책사인 내가 생각해 내야 하는 거니까.",
  str_homestory_820801001_27_dialog_content = "근데 그거랑 비석이랑 무슨 상관인데?",
  str_homestory_820801001_28_dialog_content = "그냥 갑자기 떠오른 거야!",
  str_homestory_820801001_29_dialog_content = "누가 말해줬거든. 백야성이랑 일루미나 연방, 심지어는 북방에도 이런 기념비가 있다고 말이야.",
  str_homestory_820801001_30_dialog_content = "자기네 지역 출신인 유명한 사람이나, 거기서 있었던 엄청 대단한 일이라든가 큰 사건을 기리기 위해 이런 걸 만든댔어.",
  str_homestory_820801001_31_dialog_content = "근데 우리 레디젤 렌치엔 이런 게 없어...",
  str_homestory_820801001_32_dialog_content = "게다가 우린 다른 곳들처럼 우리 땅이라고\n할 만한 곳도 없고...",
  str_homestory_820801001_33_dialog_content = "혹시라도 나중에 일이 영 안 풀리거나 서로 싸워서,\n홧김에 레디젤 렌치가 해산돼 버리면 어떡해!",
  str_homestory_820801001_34_dialog_content = "그것도 일리는 있네.",
  str_homestory_820801001_35_dialog_content = "그렇지? 내 말 맞지?",
  str_homestory_820801001_36_dialog_content = "그치만 기념비의 형식은 어떻게 할 건지 생각해 본 적 있어?",
  str_homestory_820801001_37_dialog_content = "형식이라니?",
  str_homestory_820801001_38_dialog_content = "굳이 꼭 기념비라는 형태가 아니더라도,\n레디젤 렌치를 대표할 수 있는 거라면 괜찮지 않겠냐는 거야.",
  str_homestory_820801001_39_dialog_content = "그러니까...",
  str_homestory_820801001_40_dialog_content = "차에 그려진 그라피티들 같은 거?",
  str_homestory_820801001_41_dialog_content = "그게 바로 너희만의 스타일이야.\n어디에 가든 한눈에 레디젤 렌치 사람이란 걸 알 수 있는걸.",
  str_homestory_820801001_42_dialog_content = "예를 들면, 커다란 샌드버그를 처치한 적이 있다면,\n차에 샌드버그를 그린 다음에 거기에 X표를 해 두는 거지.",
  str_homestory_820801001_43_dialog_content = "그러네! 좋은 아이디어야!",
  str_homestory_820801001_44_dialog_content = "게다가 레디젤 렌치엔 그라피티 실력자들이\n발에 챌 정도로 많은걸!",
  str_homestory_820801001_45_dialog_content = "지금 당장 「레디젤 렌치 차량 그라피티 대회」를\n열 방법을 생각해 봐야겠어!<sprite=emo_yaosu size=60 />",
  str_homestory_820901001_0_dialog_content = "뭘 보고 계신 거지?",
  str_homestory_820901001_1_dialog_content = "레이스 씨, 여기서 뭐 해요?",
  str_homestory_820901001_2_dialog_content = "딱히, 그냥 재미있는 걸 하나 봤거든.",
  str_homestory_820901001_3_dialog_content = "일루미나의 병사 모집 방식은 이랬구나 싶어서.",
  str_homestory_820901001_4_dialog_content = "레이스 씨는 이제 대원수시잖아요.\n그걸 왜 이제야 알았다는 느낌인 거죠...",
  str_homestory_820901001_5_dialog_content = "병사 모집 같은 일은 대원수의 직무 범위가 아니니까.",
  str_homestory_820901001_6_dialog_content = "아마 그럴걸?",
  str_homestory_820901001_7_option_content = "하긴 그렇네요.",
  str_homestory_820901001_8_dialog_content = "대원수가 그런 일까지 신경 쓸 시간은 없을 테니까요.",
  str_homestory_820901001_9_option_content = "왜 의문형인 건데요?!",
  str_homestory_820901001_10_dialog_content = "자기 직무 범위에 대한 건데 「아마 그럴걸?」이라 하면 어떡해요?!",
  str_homestory_820901001_11_dialog_content = "내가 대원수가 되고 나서 맡은 첫 번째 임무는\n병사들을 이끌고 전쟁터에 나가는 거였으니까.",
  str_homestory_820901001_12_dialog_content = "그렇지만 이제부터 다른 업무는 뭐가 있는지\n알아봐야 할 것 같긴 해.",
  str_homestory_820901001_13_dialog_content = "그나저나 이건 어디서 난 거야?",
  str_homestory_820901001_14_dialog_content = "움브라톤에서요... 아마 영화 찍었을 때쯤인 것 같아요.",
  str_homestory_820901001_15_dialog_content = "영화? 음, 마침 아이디어가 하나 떠올랐어.<sprite=emo_sikao size=60 />",
  str_homestory_820901001_16_dialog_content = "뭔데요?",
  str_homestory_820901001_17_dialog_content = "징병 광고를 찍는 거지.\n고작 이런 판때기로 어떻게 사람들을 끌어모으겠어?",
  str_homestory_820901001_18_dialog_content = "내가 대원수로 재임하는 동안 일루미나는\n반드시 더 강해져야만 해.",
  str_homestory_820901001_19_dialog_content = "그래서요...?",
  str_homestory_820901001_20_dialog_content = "일루미나의 군인을 주제로 선전 영화를 찍는 게 어때?",
  str_homestory_820901001_21_option_content = "진심이에요?",
  str_homestory_820901001_22_dialog_content = "말은 그렇게 하셔도...\n일루미나는 영화를 찍을 만한 곳으론 안 보이는데요.",
  str_homestory_820901001_23_dialog_content = "맞아. 일루미나의 교육은 공학과 전술 지식 위주고,\n예술 쪽은 깊게 다루지 않거든.",
  str_homestory_820901001_24_dialog_content = "그러니까요.",
  str_homestory_820901001_25_dialog_content = "그래서 감독 역할은 너한테 맡기려고 해.",
  str_homestory_820901001_26_option_content = "...좋아요!",
  str_homestory_820901001_27_dialog_content = "아무리 좋은 선전 문구를 쓴다고 해도,\n영화보다 더 효과적일 순 없잖아요.",
  str_homestory_820901001_28_dialog_content = "일루미나 전사들의 용맹한 모습을 커다란 스크린에서\n볼 수 있게 된다면 더 엄청난 전율이 느껴질 거예요.",
  str_homestory_820901001_29_dialog_content = "정말 기대돼요!",
  str_homestory_820901001_30_dialog_content = "아주 좋아. 그럼 이 임무는 너한테 맡길게.\n보수도 준비해 두겠어.",
  str_homestory_820901001_31_dialog_content = "저요? 저 영화 찍을 줄 몰라요!",
  str_homestory_820901001_32_dialog_content = "넌 꽤 창의적이잖아? 시도 써본 적 있지 않았나?",
  str_homestory_820901001_33_dialog_content = "시랑 영화를 찍는 건 서로 전혀 상관없잖아요!\n그리고 제가 시를 뭐 잘 쓰는 것도 아니고요.",
  str_homestory_820901001_34_dialog_content = "예술이란 건 어쨌든 다 통하기 마련이잖아.",
  str_homestory_820901001_35_dialog_content = "그건 좀 아니죠!",
  str_homestory_820901001_36_dialog_content = "게다가 일루미나는 애초에 영화관도 없잖아요!",
  str_homestory_820901001_37_dialog_content = "시청각실 정도는 있어. 휴일에만 영업하지만.",
  str_homestory_820901001_38_dialog_content = "그럼 영화를 찍어도 다들 보러 갈 시간이 없겠네요.",
  str_homestory_820901001_39_dialog_content = "일루미나 사람들은 다 군인이야.\n그러니까 징병 광고는 당연히 외부인용이지.",
  str_homestory_820901001_40_dialog_content = "근데 네 얘길 듣고 보니까, 우리 군인들한테 보여 주면\n사기 진작에 도움이 될 것 같아.",
  str_homestory_820901001_41_dialog_content = "그렇다면... 몇 없는 기회니까 나도 출연해야겠어.",
  str_homestory_820901001_42_dialog_content = "뭐하면 라인하르트도 불러서 누가 스크린 위에서\n병사들의 마음을 더 뜨겁게 만드는지 겨뤄 봐야겠는걸.",
  str_homestory_820901001_43_dialog_content = "군단장들까지 출연한다면 군단들의 경쟁의식에\n불이 붙을지도 몰라.",
  str_homestory_820901001_44_dialog_content = "일을 그렇게까지 크게 벌일 필요는 없지 않아요?!",
  str_homestory_820901001_45_dialog_content = "아, 너도 감독 겸 배우로 출연해도 돼.",
  str_homestory_820901001_46_dialog_content = "유일한 아이테르이자 감독이란 것만으로도\n캐릭터성은 충분하니까.",
  str_homestory_820901001_47_dialog_content = "내 말을 하나도 안 듣고 있는 것 같은데...\n그냥 그러려니 하고 받아들여야 하는 건가...<sprite=emo_yundao size=60 />",
  str_homestory_820901001_48_dialog_content = "영화 제목도 생각해 뒀어.",
  str_homestory_820901001_49_dialog_content = "《아이테르 PlayerName 구하기》 어때?",
  str_homestory_821001001_0_dialog_content = "조셀린이 깃발 앞에서 기도하고 있네...",
  str_homestory_821001001_1_dialog_content = "조셀린?",
  str_homestory_821001001_2_dialog_content = "다음부턴 서서 오래 기다릴 필요 없이,\n바로 절 불러도 괜찮아요.",
  str_homestory_821001001_3_dialog_content = "방해될까 봐 그랬어.",
  str_homestory_821001001_4_dialog_content = "빛의 신께선 기도가 중간에 끊겼다고\n신앙심을 의심하진 않으신답니다.",
  str_homestory_821001001_5_dialog_content = "물론 저도 그런 일로 화를 내진 않아요.\n그나저나 제 도움이 필요한 건가요?",
  str_homestory_821001001_6_dialog_content = "아니, 그냥 깃발 앞에 한참 서 있길래 와 봤어.",
  str_homestory_821001001_7_dialog_content = "아깐 기도하고 있던 거지? 근데 기도를 깃발에 한 거야?",
  str_homestory_821001001_8_dialog_content = "기도요? 맞아요. 특별한 매개체를 정해서 기도하면\n신의 음성이 더 맑게 들리거든요.",
  str_homestory_821001001_9_option_content = "깃발도 매개체인 거지?",
  str_homestory_821001001_10_dialog_content = "빛의 신을 믿는 건 백야성의 오랜 관습이잖아?",
  str_homestory_821001001_11_dialog_content = "생각해 보니까 백야성 깃발을 매개체로 삼아서\n기도를 하는 건 아주 적절한 선택인 것 같아.",
  str_homestory_821001001_12_option_content = "성물 같은 거?",
  str_homestory_821001001_13_dialog_content = "신이랑 소통을 할 땐 성물을 매개체로 삼는 경우가 많잖아?",
  str_homestory_821001001_14_dialog_content = "성물은 신이랑 마주 보고 있단 느낌이니까\n효과도 엄청 좋을 것 같거든.",
  str_homestory_821001001_15_dialog_content = "사실 매개체가 될 수 있는 대상이 딱히\n정해져 있진 않아요.",
  str_homestory_821001001_16_dialog_content = "빛<sprite=emo_taiyang size=60 />의 은혜는 대지를 비추죠.\n빛 아래 만물은 신의 빛과 연결돼 있는 거예요.",
  str_homestory_821001001_17_dialog_content = "그래서 텃밭을 가꿀 때면 토마토꽃을 보며\n기도를 드리곤 한답니다.",
  str_homestory_821001001_18_dialog_content = "그런 것도 가능하다고?",
  str_homestory_821001001_19_dialog_content = "하지만 특별한 기도를 드릴 땐 아무래도 매개체로\n적합한 대상을 골라야 하긴 해요.",
  str_homestory_821001001_20_dialog_content = "그럼 백야성 깃발을 향해선 어떤 기도를 드렸는데?",
  str_homestory_821001001_21_dialog_content = "......",
  str_homestory_821001001_22_dialog_content = "미안, 그냥 궁금해서 물어본 거였어.",
  str_homestory_821001001_23_dialog_content = "혹시 내가 물어봐선 안 될 걸 물어봤다면 무시해도 돼.",
  str_homestory_821001001_24_dialog_content = "그런 건 아니에요.\n모두에게 빛의 신의 은혜를 전하는 게 제 사명인걸요.",
  str_homestory_821001001_25_dialog_content = "신앙에 대해선 제가 알고 있는 건 모두 대답해 줄게요.",
  str_homestory_821001001_26_dialog_content = "다만 방금 대답이 없었던 건 그저...",
  str_homestory_821001001_27_dialog_content = "그저...?",
  str_homestory_821001001_28_dialog_content = "이 깃발에 담긴 바느질 솜씨를 조금 더 가까이서\n보고 싶어서였어요.",
  str_homestory_821001001_29_dialog_content = "백야성은 신앙과 관련된 물건들은\n아주 세심하게 제작해요.",
  str_homestory_821001001_30_dialog_content = "특히 깃발은 민중을 이끄는 신앙의 증표니까\n그만큼 튼튼해야 하죠.",
  str_homestory_821001001_31_dialog_content = "제 바느질 솜씨가 늘면 사람들을 더 많이\n도울 수 있을 거예요.",
  str_homestory_821001001_32_dialog_content = "왠지 머릿속에 조셀린이 늠름하게 깃발을 들고\n서 있는 모습이 그려지는 것 같아!",
  str_homestory_821001001_33_dialog_content = "깃발을 지탱하는 건 쉬운 일이 아닌걸요.\n제겐 무리예요.",
  str_homestory_821001001_34_dialog_content = "주민들은 절 「성녀」라는 호칭으로 부르긴 하지만,\n아직 제겐 모두를 이끌 만한 능력이 없어요.",
  str_homestory_821001001_35_dialog_content = "그래서 지금 전, 강철가시 기사단의 깃발을 기우고\n꿰매는 일부터 차근차근 해 나가야 하는 거예요.",
  str_homestory_821001001_36_dialog_content = "음, 난 깃발을 만드는 일도 휘두르는 일만큼 중요하다고 생각해.\n나도 조셀린을 도와줄게.",
  str_homestory_821001001_37_dialog_content = "당신 바느질도 할 줄 아나요?",
  str_homestory_821001001_38_dialog_content = "어렸을 때 스카이워커호한테 조금 배운 적 있거든...",
  str_homestory_821001001_39_dialog_content = "제가 아는 것도 가르쳐 줄게요.\n그렇게 하면 제 실력에도 도움이 되겠죠.",
  str_homestory_821001001_40_dialog_content = "그럼 우선, 당신이 가지고 있는 옷을 다 가지고 오세요.",
  str_homestory_821001001_41_dialog_content = "저, 전부 다...?",
  str_homestory_821001001_42_dialog_content = "연습을 많이 해야 기본기가 다져지는 법이니까요.",
  str_homestory_821001001_43_dialog_content = "게다가 말만 하고 실천하지 않으면 빛의 신께서도\n손 쓸 도리가 없어지시잖아요.",
  str_homestory_821001001_44_dialog_content = "전 당신이 말만 하는 사람은 아니라고 믿어요.",
  str_homestory_821001001_45_dialog_content = "알겠어! 지금 바로 가서 가져올게!",
  str_homestory_821201001_0_dialog_content = "안토니?",
  str_homestory_821201001_1_dialog_content = "저기, 「뼈의 회랑」 옆에 서 있은 지 벌써 30분이나 됐는데.",
  str_homestory_821201001_2_dialog_content = "그런 거에 관심이 많나 봐?",
  str_homestory_821201001_3_dialog_content = "아, PlayerName, 안녕.",
  str_homestory_821201001_4_dialog_content = "맞아, 확실히 아주 관심이 많아.",
  str_homestory_821201001_5_dialog_content = "처음에 보자마자 확신이 왔거든.",
  str_homestory_821201001_6_dialog_content = "이건 분명히 연구 가치가 있다고 말이야!",
  str_homestory_821201001_7_dialog_content = "혹시 이게 어떤 생물의 뼈인지 물어봐도 될까?",
  str_homestory_821201001_8_dialog_content = "대답하기 엄청 어려운 질문이네...",
  str_homestory_821201001_9_dialog_content = "아직까진 사람마다 의견이 다 다르거든.\n별의별 주장이 다 있어.",
  str_homestory_821201001_10_dialog_content = "네 개인적인 관점으론 어떤데?",
  str_homestory_821201001_11_dialog_content = "난 네 판단을 믿어.",
  str_homestory_821201001_12_dialog_content = "생각 좀 해 볼게<sprite=emo_sikao size=60 />...\n내 생각엔 아마도...",
  str_homestory_821201001_13_option_content = "어떤 동물의 뼈일걸.",
  str_homestory_821201001_14_dialog_content = "동물의 뼈?",
  str_homestory_821201001_15_dialog_content = "난 지금까지 많은 곳을 다녀 봤지만,\n이런 뼈를 본 건 처음이야.",
  str_homestory_821201001_16_dialog_content = "그럼 어쩌면 이 뼈는 이미 멸종한 생물의\n유해일 가능성이 있어!",
  str_homestory_821201001_17_dialog_content = "진짜 그럴까...?",
  str_homestory_821201001_18_option_content = "콜로서스의 용골이야.",
  str_homestory_821201001_19_dialog_content = "뭐?!",
  str_homestory_821201001_20_dialog_content = "거짓말은 안 좋은 거야, PlayerName!",
  str_homestory_821201001_21_dialog_content = "이, 이, 이게 진짜 콜로서스를 제작할 때\n사용한 용골이라고?!",
  str_homestory_821201001_22_dialog_content = "나도 그냥 주워들은 얘기야.",
  str_homestory_821201001_23_dialog_content = "아니, 그렇지 않아. 넌 아이테르니까!\n네 이야기가 잘못됐을 리 없어!",
  str_homestory_821201001_24_dialog_content = "어쨌거나, 「뼈의 회랑」을 제대로 조사해 봐야겠어!",
  str_homestory_821201001_25_dialog_content = "일부라도 좋으니까 방에 조금 가져가서\n연구해도 괜찮을까?!",
  str_homestory_821201001_26_dialog_content = "방에 뭐든 닥치는 대로 가지고 들어가는 건 안 돼!",
  str_homestory_821201001_27_dialog_content = "어쨌든, 이건 전부 다 공공재거든...",
  str_homestory_821201001_28_dialog_content = "근데 나도 이 뼈의 정체가 좀 궁금하긴 해.",
  str_homestory_821201001_29_dialog_content = "그럼 이렇게 하자. 연구는 해도 좋지만, 여기서만 해.\n일손이 모자랄 땐 조수를 찾아도 되고.",
  str_homestory_821201001_30_dialog_content = "걱정 마!",
  str_homestory_821201001_31_dialog_content = "내가 반드시 이 녀석의 정체를 밝혀내 줄게!<sprite=emo_dianzan size=60 />",
  str_homestory_821101001_0_dialog_content = "자리야? 뭐 해?",
  str_homestory_821101001_1_dialog_content = "어? PlayerName, 이게 뭔지 알아?",
  str_homestory_821101001_2_dialog_content = "「셜록 승용차」라고 적혀 있긴 한데.",
  str_homestory_821101001_3_dialog_content = "「승용차」라는 건... 뭐야?",
  str_homestory_821101001_4_dialog_content = "쉽게 설명하면, 엄청 편리한 교통수단이야.",
  str_homestory_821101001_5_dialog_content = "이게 교통수단이라고?",
  str_homestory_821101001_6_dialog_content = "이제 마차 같은 건 다들 안 타고 다니는 건가...",
  str_homestory_821101001_7_dialog_content = "아직도 마차를 교통수단으로 사용하는 곳이 있긴 해.\n그치만 일부 지역의 부자들은 승용차를 타고 다녀.",
  str_homestory_821101001_8_dialog_content = "그렇구나...",
  str_homestory_821101001_9_dialog_content = "관심 있어?",
  str_homestory_821101001_10_dialog_content = "처음 보는 거라 관심이 좀 가긴 해.",
  str_homestory_821101001_11_dialog_content = "그럼 이따가 「진짜 승용차」가 있는 데 데려가서\n구경 좀 시켜 줄 수 있을까?",
  str_homestory_821101001_12_option_content = "물론이지!",
  str_homestory_821101001_13_dialog_content = "근데 뒤에 얌전히 앉아 있기만 해야 돼.",
  str_homestory_821101001_14_dialog_content = "움직여 보려고 하면 절대 안 돼.",
  str_homestory_821101001_15_option_content = "그건 좀 곤란해.",
  str_homestory_821101001_16_dialog_content = "어? 왜...?<sprite=emo_yihuo size=60 />",
  str_homestory_821101001_17_dialog_content = "아무래도 네가 위험한 일을 할 것 같단 느낌이 들거든.",
  str_homestory_821101001_18_dialog_content = "예를 들면 승용차를 움직여 보려고 한다거나 그런 거.",
  str_homestory_821101001_19_dialog_content = "눈치도 빠르네, PlayerName!",
  str_homestory_821101001_20_dialog_content = "내가 그 「기계 마차」를 몰고 싶다고\n생각하는 줄 어떻게 알았어?",
  str_homestory_821101001_21_dialog_content = "몰다니?",
  str_homestory_821101001_22_dialog_content = "승용차는 마차처럼 교통수단이라면서?",
  str_homestory_821101001_23_dialog_content = "그럼 원리는 똑같지 않아?",
  str_homestory_821101001_24_dialog_content = "몸통 중 한 곳을 채찍질하면 움직이기 시작하는 거지?",
  str_homestory_821101001_25_dialog_content = "아니면 무슨 명령 같은 걸 내리면 돼?",
  str_homestory_821101001_26_dialog_content = "내가 루미나틱스 제어 기술은 영 아니지만,\n말 모는 건 엄청 잘해~",
  str_homestory_821101001_27_dialog_content = "......",
  str_homestory_821101001_28_dialog_content = "어? 왜 갑자기 말이 없어?",
  str_homestory_821101001_29_dialog_content = "아무래도 너한테 현대 사회의 지식을\n꼭 알려줄 필요가 있을 것 같아...",
  str_homestory_821101001_30_dialog_content = "응?",
  str_homestory_821301001_0_dialog_content = "33호?",
  str_homestory_821301001_1_dialog_content = "피크닉 가려는 거야?",
  str_homestory_821301001_2_dialog_content = "보시는 대로 그렇습니다.",
  str_homestory_821301001_3_dialog_content = "현재 준비 중입니다.",
  str_homestory_821301001_4_dialog_content = "설마 혼자 가려는 건 아니지?",
  str_homestory_821301001_5_dialog_content = "다소 오해가 있으신 것으로 파악됩니다.",
  str_homestory_821301001_6_dialog_content = "물론 다른 오로리안 친구들에게 동행을 요청했습니다.",
  str_homestory_821301001_7_dialog_content = "그 요청 대상에는 당신 역시 포함되어 있습니다.",
  str_homestory_821301001_8_dialog_content = "그거 영광이네!",
  str_homestory_821301001_9_dialog_content = "......",
  str_homestory_821301001_10_dialog_content = "근데 있잖아, 왜 아직 바이스랑 카렌한텐 같이 가자고 안 했어?",
  str_homestory_821301001_11_dialog_content = "현재 중요한 분석 작업을 진행 중입니다.",
  str_homestory_821301001_12_dialog_content = "다른 사람들을 통해 당신 일행이 지금까지\n피크닉에 어떤 음식을 준비했는지 파악했습니다.",
  str_homestory_821301001_13_dialog_content = "그리고 그들이 보내온 피크닉 음식을 참조해\n다음과 같은 위험한 결론을 얻었습니다.",
  str_homestory_821301001_14_dialog_content = "열량 과잉으로 건강을 해칠 가능성이 매우 높습니다.",
  str_homestory_821301001_15_dialog_content = "하아?",
  str_homestory_821301001_16_dialog_content = "PlayerName 님의 생각은 어떻습니까?",
  str_homestory_821301001_17_option_content = "맞는 말인 것 같아.",
  str_homestory_821301001_18_dialog_content = "영양학적으론 이거 전부 다 열량이 엄청 높은 건 사실이거든.",
  str_homestory_821301001_19_dialog_content = "당신이 제 의견에 전면적으로 동의해 주다니,\n드문 일이군요.",
  str_homestory_821301001_20_dialog_content = "그치만...",
  str_homestory_821301001_21_option_content = "그렇진 않아.",
  str_homestory_821301001_22_dialog_content = "어떻게 「그렇진 않다」는 결론이 도출되었는지\n설명해 주실 수 있습니까?",
  str_homestory_821301001_23_dialog_content = "저는 조금 전에 제가 내린 판단이\n합리적이라고 생각합니다.",
  str_homestory_821301001_24_dialog_content = "피크닉이면 마음 편히 느긋함을 즐기는 게 가장 중요해.",
  str_homestory_821301001_25_dialog_content = "융통성 하나 없이 따지고 들면,\n느긋함을 즐기겠단 목표는 이루기 힘들어.",
  str_homestory_821301001_26_dialog_content = "융통성? 느긋함?",
  str_homestory_821301001_27_dialog_content = "33호 네가 우릴 생각하는 마음에 그러는 건 다 알지만,\n그래도 가끔은 그렇게까지 철저할 필요는 없어.",
  str_homestory_821301001_28_dialog_content = "철저해야 할 땐 철저하게, 느긋해야 할 땐 느긋하게 해야\n널 좋아하는 사람도 더 많아질 거야.",
  str_homestory_821301001_29_dialog_content = "정보를 습득했습니다. 정보를 분석합니다.",
  str_homestory_821301001_30_dialog_content = "이해했습니다.",
  str_homestory_821301001_31_dialog_content = "다시 메뉴 조정 작업을 진행하겠습니다.",
  str_homestory_821301001_32_dialog_content = "부디 제 초대를 기다려 주시기 바랍니다.",
  str_homestory_821401001_0_dialog_content = "레베카?",
  str_homestory_821401001_1_dialog_content = "조종사 씨...",
  str_homestory_821401001_2_dialog_content = "그네의자 타고 싶어?",
  str_homestory_821401001_3_dialog_content = "아니... 그냥, 조금 옛날 생각이 나서...",
  str_homestory_821401001_4_dialog_content = "전에... 우리집 마당에도 비슷한 그네의자가 있었거든.",
  str_homestory_821401001_5_dialog_content = "그때 나랑 언니, 그리고 엘리노어까지 종종\n그 그네의자 위에서 같이 놀곤 했어.",
  str_homestory_821401001_6_dialog_content = "하지만 그네의자가 너무 작아서...\n많아야 두 명밖에 못 탔어.",
  str_homestory_821401001_7_dialog_content = "그래서 늘 한 사람이 내려야 했어...",
  str_homestory_821401001_8_dialog_content = "오? 그럼 누가 내릴지 어떻게 결정했는데?",
  str_homestory_821401001_9_dialog_content = "가위바위보.",
  str_homestory_821401001_10_dialog_content = "그런데 지금 생각해 보니까 이상하네.\n그때 난 가위바위보를 한 번도 진 적이 없었어.",
  str_homestory_821401001_11_dialog_content = "그럼 둘이 미리 짰다는 거야?",
  str_homestory_821401001_12_dialog_content = "아마 아닐걸. 언니랑 엘리노어는 사이가...\n사실 쭉 좋지 않았거든...",
  str_homestory_821401001_13_dialog_content = "한 번은 내가 나서서 그네의자에서 내렸던\n적이 있었는데...",
  str_homestory_821401001_14_dialog_content = "그랬더니 언니랑 엘리노어는 그네의자 위에서\n싸우기 시작했어.",
  str_homestory_821401001_15_dialog_content = "그때 그네의자가 부서질 뻔했다니까...",
  str_homestory_821401001_16_dialog_content = "그 시절이 정말 그리운 모양이네<sprite=emo_sikao size=60 />.",
  str_homestory_821401001_17_dialog_content = "한번 앉아 볼래?",
  str_homestory_821401001_18_dialog_content = "응? 내가? 음... 그러면...",
  str_homestory_821401001_19_dialog_content = "...아니야, 그냥 안 할래.",
  str_homestory_821401001_20_option_content = "왜?",
  str_homestory_821401001_21_option_content = "한번 타 봐.",
  str_homestory_821401001_22_dialog_content = "사실... 요즘 내 몸의 독이 좀 불안정해졌거든...",
  str_homestory_821401001_23_dialog_content = "만약 내가 그네의자에 앉아 있다가 깜빡 잠들면,\n흘러나온 독액 때문에 그네의자가 망가질지도 몰라.",
  str_homestory_821401001_24_dialog_content = "그러니까 난 보기만 해도 괜찮아.",
  str_homestory_821401001_25_dialog_content = "여기 서서 눈을 감고 있으면...\n모든 게 과거로 돌아간 듯한 느낌이 들거든...",
  str_homestory_821401001_26_dialog_content = "걱정 마, 여긴 내가 있잖아.",
  str_homestory_821401001_27_dialog_content = "잠들면 내가 제때 깨워줄게.",
  str_homestory_821401001_28_dialog_content = "당신을 너무 번거롭게 만드는 건 아닐까...",
  str_homestory_821401001_29_dialog_content = "에이, 아니야.",
  str_homestory_821401001_30_dialog_content = "그럼... 조금만 더 기다려 줄 수 있어?",
  str_homestory_821401001_31_dialog_content = "진료소에 아직 할 일이 남아 있거든. 끝나면 올게.",
  str_homestory_821401001_32_dialog_content = "고마워, 조종사 씨.",
  str_homestory_821501001_0_dialog_content = "이사?",
  str_homestory_821501001_1_dialog_content = "아, 너였어?",
  str_homestory_821501001_2_dialog_content = "그 차는 왜? 계속 보고 있길래.",
  str_homestory_821501001_3_dialog_content = "음! 좋은 질문이야.",
  str_homestory_821501001_4_dialog_content = "이 차... 너무 잘생기지 않았어?",
  str_homestory_821501001_5_option_content = "별로?",
  str_homestory_821501001_6_dialog_content = "아름답다고 말하는 게 맞지 않을까?",
  str_homestory_821501001_7_option_content = "확실히 그렇지.",
  str_homestory_821501001_8_dialog_content = "어떤 의미에선 잘생겼다고 할 수 있겠네.",
  str_homestory_821501001_9_dialog_content = "이 차 나랑 완전 잘 어울리는데?",
  str_homestory_821501001_10_dialog_content = "내가 이 차를 몰고 레베카를 데리러 간다면...",
  str_homestory_821501001_11_dialog_content = "레베카는 분명히 엄청 좋아하겠지?!",
  str_homestory_821501001_12_dialog_content = "이 차를 몰고 레베카를 데리러 간다고?",
  str_homestory_821501001_13_dialog_content = "응, 레베카는 몸이 좋지 않잖아.",
  str_homestory_821501001_14_dialog_content = "근데 레베카는 매일 걸어서 일하러 가니까,\n조금 무리라는 생각 안 들어?",
  str_homestory_821501001_15_dialog_content = "확실히 고생이긴 하지.",
  str_homestory_821501001_16_dialog_content = "그치? 이건 내가 신중하게 고민해서 생각한 거라구.",
  str_homestory_821501001_17_dialog_content = "레베카는 맨날 자기가 뭘 원하는지 내가 모른대.\n흠, 이번엔 분명히 맞을 거야.",
  str_homestory_821501001_18_dialog_content = "근데... 이 차는 너무 튀어서 레베카가 안 좋아할 것 같은데.",
  str_homestory_821501001_19_dialog_content = "걱정 마, 난 레베카의 언니잖아.\n레베카가 뭘 좋아하는지 내가 모르겠어?.",
  str_homestory_821501001_20_dialog_content = "레베카는 꽃을 가장 좋아해.\n이 차는 곳곳에 꽃이 있는데 싫어할 리가 없잖아?",
  str_homestory_821501001_21_dialog_content = "...아... 그럼 한번 해 볼래?",
  str_homestory_821501001_22_dialog_content = "좋아, 지금 당장 가서 레베카한테 말할게.",
  str_homestory_821501001_23_dialog_content = "분명히 엄청 좋아하겠지?",
  str_homestory_821501001_24_dialog_content = "힘내.",
  str_homestory_821601001_0_dialog_content = "선극 씨, 이 기계는 왜?",
  str_homestory_821601001_1_dialog_content = "이거 아이테르가 옛날에 쓰던 건데, 혹시 관심 있어?",
  str_homestory_821601001_2_dialog_content = "음... 이거 직조기지?",
  str_homestory_821601001_3_dialog_content = "맞아, 스카이워커에 기록이 남아 있었어.",
  str_homestory_821601001_4_dialog_content = "헤븐즈 밸리에선 이런 기계로 천을 만들고,\n자급자족하는 생활을 했었다고 해.",
  str_homestory_821601001_5_dialog_content = "근데 유지 보수가 번거롭다고 하더라고.\n그래서 거의 안 썼어...",
  str_homestory_821601001_6_dialog_content = "선극 씨가 써 볼래?",
  str_homestory_821601001_7_dialog_content = "그럴 필요는 없어.",
  str_homestory_821601001_8_dialog_content = "그냥 이런 설계를 보니까 추억이 좀 떠올랐거든~",
  str_homestory_821601001_9_dialog_content = "추억?",
  str_homestory_821601001_10_dialog_content = "응, 어릴 적에 공부할 때 쓰던 기관이 생각났어.",
  str_homestory_821601001_11_dialog_content = "종문의 사부님이 어린 제자들한테 제작법을 가르칠 땐 우선 원형 기관부터 시작하거든.",
  str_homestory_821601001_12_dialog_content = "이런 직조기는 교재로 자주 쓰였어.\n그러니까 내 두 번째 선생님인 셈이야.",
  str_homestory_821601001_13_dialog_content = "어쩐지, 선극 씨가 흥미를 보이는 이유가 있었구나.",
  str_homestory_821601001_14_dialog_content = "게다가 원형 기관들은 대부분 내구성이 약했어.",
  str_homestory_821601001_15_dialog_content = "내가 받은 직조기도 그랬고 말이야.\n일부는 지금 이 기계랑 구조가 완전히 똑같았어...",
  str_homestory_821601001_16_dialog_content = "사부님은 그걸로 우리한테 늘 물건을\n소중히 여기라고 가르치셨어.",
  str_homestory_821601001_17_dialog_content = "근데 나도 그러고 싶었는데,\n툭하면 부서졌지 뭐야... 아하하.",
  str_homestory_821601001_18_option_content = "선극 씨가 개조해서?",
  str_homestory_821601001_19_dialog_content = "맞췄어.",
  str_homestory_821601001_20_option_content = "진짜 약했던 모양이네.",
  str_homestory_821601001_21_dialog_content = "아니, 대체로 내가 개조를 자주 한 탓이었어...",
  str_homestory_821601001_22_dialog_content = "그래서 그 기관은 내 수행에 끝까지 함께하지 못했어.",
  str_homestory_821601001_23_dialog_content = "내가 성장해서 그걸 잘 다루게 됐을 땐,\n이미 수리가 불가능한 상태가 돼버렸고 말이야.",
  str_homestory_821601001_24_dialog_content = "...그렇구나.",
  str_homestory_821601001_25_dialog_content = "어때? 이 직조기, 내가 고쳐줄까?",
  str_homestory_821601001_26_dialog_content = "지금의 나라면 이런 걸 정상적으로 움직이게\n만드는 일 정도는 간단해.",
  str_homestory_821601001_27_dialog_content = "그리고 구조를 개선해서, 최대한 스스로 작업하고\n유지 보수도 가능하게 만들 수 있어.",
  str_homestory_821601001_28_dialog_content = "...음<sprite=emo_sikao size=60 />... 역시 그럴 필요는 없을 것 같아.",
  str_homestory_821601001_29_dialog_content = "고쳐봤자 이걸로 뭘 만들 재료도 구하기 힘들어서,\n딱히 써 먹을 데가 없을 것 같거든.",
  str_homestory_821601001_30_dialog_content = "게다가 요즘은 가게만 가면 훨씬 더 예쁜 천을\n싸게 살 수 있으니까.",
  str_homestory_821601001_31_dialog_content = "맞아... 용주의 도시도 그래.",
  str_homestory_821601001_32_dialog_content = "이제 보통 사람들한테는 장인보다 상인이\n더 중요한 시대가 돼버렸어.",
  str_homestory_821601001_33_dialog_content = "그것도 시대의 발전 아닐까?",
  str_homestory_821601001_34_dialog_content = "반박할 순 없겠네. 이 기관의 사명은 이미 끝난 거야.",
  str_homestory_821601001_35_dialog_content = "그럼 이제 푹 쉬게 해 주자.",
  str_homestory_818702001_0_dialog_content = "천간 씨?\n...이 대사님?",
  str_homestory_818702001_1_dialog_content = "왜 여기 서서 자고 있어요?",
  str_homestory_818702001_2_dialog_content = "일어나요! 방에 가서 자야죠.",
  str_homestory_818702001_3_dialog_content = "어이쿠야!",
  str_homestory_818702001_4_dialog_content = "소생, 빙금 구름 속 궁전에서 천계의 장졸과\n담소를 나누고 있었는데 말입니다.",
  str_homestory_818702001_5_dialog_content = "헌데 어찌 이리도 빨리 속세로 돌아온 것인지...",
  str_homestory_818702001_6_dialog_content = "아무래도 소생의 수행이 아직 부족했던 모양입니다.",
  str_homestory_818702001_7_dialog_content = "진짜 천간 씨한텐 두 손 두 발 다 들겠네요.\n아직도 정신이 안 들어요?",
  str_homestory_818702001_8_dialog_content = "천간 씨는 이런 곳에 기대서 잠들 뻔했다구요...",
  str_homestory_818702001_9_dialog_content = "이 시계 말이에요.",
  str_homestory_818702001_10_dialog_content = "이렇게 커다란 시계 옆에서 엄청 잘 자길래 좀 놀랐어요.",
  str_homestory_818702001_11_dialog_content = "아니, 그게 무슨 말씀이십니까.",
  str_homestory_818702001_12_dialog_content = "소생이 알기로 이 아스트라 대륙에선 많은 사람들이\n머리맡에 자명종을 두고 잔다고 하던데 말입니다.",
  str_homestory_818702001_13_dialog_content = "허나 소생은 하늘을 이불 삼고, 땅을 자리로 삼기에\n해시계에 기대어 잠을 잔 것뿐입니다.",
  str_homestory_818702001_14_dialog_content = "이는 이곳의 관습을 따른 것이라 할 수 있지요.",
  str_homestory_818702001_15_dialog_content = "근데 사람들은 알람을 듣고 일어나려고 하는 거지만,\n천간 씨는 그냥 꾸벅꾸벅<sprite=emo_kun size=60 /> 졸려는 거잖아요.",
  str_homestory_818702001_16_dialog_content = "설마 천간 씨는 시간이 너무 빨리 가는 게\n하나도 안 불안한 건가요...",
  str_homestory_818702001_17_dialog_content = "바로 그런 긴박함 때문에 인생이 짧은 것입니다.\n그리고 그것이 바로 잠을 빨리 자야 하는 이유지요.",
  str_homestory_818702001_18_dialog_content = "나른하다면 억지로 기지개를 켜며 버틸 게 아니라,\n바로 눈을 붙여야 하는 겁니다.",
  str_homestory_818702001_19_dialog_content = "소생처럼 여기 몸을 기대 살짝 눈을 붙여 보시면\n공도 바로 알게 되실 겁니다.",
  str_homestory_818702001_20_option_content = "전 안 잘래요.",
  str_homestory_818702001_21_dialog_content = "역시 젊은이답군요.",
  str_homestory_818702001_22_dialog_content = "소생은 오랫동안 방방곡곡을 다녀서 그런지,\n잘 기회가 있거든 절대 포기하지 않습니다.",
  str_homestory_818702001_23_option_content = "한번 해 볼게요.",
  str_homestory_818702001_24_dialog_content = "이제야 깨달으셨군요!",
  str_homestory_818702001_25_dialog_content = "근데 여기서 자려면 준비가 좀 필요해요.",
  str_homestory_818702001_26_dialog_content = "제 침낭이랑, 피크닉 돗자리, 장비도 이것저것\n다 가지고 와야 하거든요.",
  str_homestory_818702001_27_dialog_content = "역시 풍류를 아시는군요.\n소생에게는 이 새 두 마리뿐입니다만,\n도통 쓸모가 없습니다.",
  str_homestory_818702001_28_dialog_content = "흐음, 가만 보니 역시 해시계 형씨 팔자가 좋군요.",
  str_homestory_818702001_29_dialog_content = "용주에서든 아스트라에서든 역할이 같지 않습니까.",
  str_homestory_818702001_30_dialog_content = "게다가 해만 안 뜨면 언제든 쉴 수 있고 말이지요.",
  str_homestory_818702001_31_dialog_content = "이젠 그런 돌멩이까지 부러워하는 거예요?!",
  str_homestory_818702001_32_dialog_content = "결코 돌멩이를 얕보시면 안 됩니다.\n돌멩이 안에서 대영웅이 나올 수도 있으니 말입니다!",
  str_homestory_818702001_33_dialog_content = "아쉽게도 소생이 돌로 변하는 건\n꿈에서나 가능한 일이지요.",
  str_homestory_818702001_34_dialog_content = "이런, 담소를 나누다 보니 또 잠이 몰려오는군요.",
  str_homestory_818702001_35_dialog_content = "진짜 긴장감이라곤 하나도 없네요...",
  str_homestory_818702001_36_dialog_content = "PlayerName 공, 세상을 꼭 정신 바짝 차리고\n살 필요는 없는 겁니다.",
  str_homestory_818702001_37_dialog_content = "덧없는 인생, 열심히도 했다가 쉬기도 했다가,\n게으름 좀 부리면 안 될 이유가 있겠습니까?<sprite=emo_qingsong size=60 />",
  str_homestory_818702001_38_dialog_content = "듣고 보니 그렇네요...\n역시 제가 아는 천간 씨답다니까요.",
  str_homestory_818802001_0_dialog_content = "단당 씨?",
  str_homestory_818802001_1_dialog_content = "이 연은 만듦새가... 참으로 좋구나.",
  str_homestory_818802001_2_dialog_content = "게다가 모가 난 무늬며, 색상도 수수한 것이...",
  str_homestory_818802001_3_dialog_content = "용주 대륙에서 흔히 볼 수 있는 연과 흡사하구나.",
  str_homestory_818802001_4_dialog_content = "공자도 이런 수수함이 마음에 드는 게냐?\n참으로 드문 일이로구나...",
  str_homestory_818802001_5_option_content = "용주 사람들은 연날리기를 좋아하나요?",
  str_homestory_818802001_6_dialog_content = "당연하지.",
  str_homestory_818802001_7_option_content = "단당 씨도 연을 날려 보셨나요?",
  str_homestory_818802001_8_dialog_content = "보았지. 나는 연을 무척 좋아하느니라.",
  str_homestory_818802001_9_dialog_content = "연날리기는 용주의 아이들이 무척 좋아하는\n놀이 중 하나다.",
  str_homestory_818802001_10_dialog_content = "내 어렸을 적 몇 안 되는 재미 중 하나가 바로\n형님, 아우와 함께 연을 날리는 것이었다.",
  str_homestory_818802001_11_dialog_content = "그 무렵엔 셋이 연을 날리면 연줄이 곧잘\n하나로 엉켜 버리곤 했었지.",
  str_homestory_818802001_12_dialog_content = "이따금 서로 실랑이를 벌이기도 했고 말이야, 후훗.",
  str_homestory_818802001_13_dialog_content = "그래도 돌아서면 언제 그랬냐는 듯\n다시금 사이가 돈독해졌느니라.",
  str_homestory_818802001_14_dialog_content = "단당 씨가 날렸던 연은 어떻게 생긴 거였는데요?",
  str_homestory_818802001_15_dialog_content = "내 연 말이냐?\n음... 참으로 많은 연을 날려 보았지.",
  str_homestory_818802001_16_dialog_content = "형님과 아우는 새 모양의 연을 선호한다만,\n나는 꽃 모양 연이 훨씬 마음에 들더구나.",
  str_homestory_818802001_17_dialog_content = "그러고 보니까 저 아직 새나 꽃 모양 연은 본 적이 없어요.",
  str_homestory_818802001_18_dialog_content = "그러한가, 용주의 연은 생김새가 무척 다양하느니라.",
  str_homestory_818802001_19_dialog_content = "일례로 업나라의 연은 복잡한 장치를\n여럿 가미하는 방식을 선호하지.",
  str_homestory_818802001_20_dialog_content = "그리하면 연의 각 부위가 제각기 춤추듯\n움직이게 되는 게다.",
  str_homestory_818802001_21_dialog_content = "그 무렵 내가 날리던 연은 모두 궁궐의\n솜씨 좋은 장인이 만든 연이었다.",
  str_homestory_818802001_22_dialog_content = "단아하면서도 기품이 느껴졌지.",
  str_homestory_818802001_23_dialog_content = "참으로 그리운지고...\n한 번 더 연을 날릴 수 있다면 좋으련만.",
  str_homestory_818802001_24_dialog_content = "이 연들은 단당 씨가 날렸던 연들이랑은\n비교할 수 없는 수준이겠네요.",
  str_homestory_818802001_25_dialog_content = "무방하다. 내 그리워하는 것은 연이 아니라\n아무 근심도 없던 그 시절이니 말이야.",
  str_homestory_818802001_26_dialog_content = "어떤 연을 날릴지는 차치해 두어도 되는 게다.",
  str_homestory_818802001_27_dialog_content = "으음, 근래 주변의 번거로운 일들도\n마침 해결했고 하니...",
  str_homestory_818802001_28_dialog_content = "나도 잠시 여유를 가질 수 있겠구나.\n하면 이 연을 날려 보는 것도 좋겠지.",
  str_homestory_818802001_29_dialog_content = "공자, 그대는 어떠한가.\n나와 함께 연을 날려 주겠느냐.",
  str_homestory_818802001_30_dialog_content = "이 연은 홀로 날리면 흥이 나질 않느니라.",
  str_homestory_818802001_31_dialog_content = "아쉽지만 이 선반엔 연이 하나밖에 없는걸요...",
  str_homestory_818802001_32_dialog_content = "그거야 문제도 아니지. 공자와 내가 번갈아 하거나,\n내가 손수 하나 만들면 그만 아니겠느냐.",
  str_homestory_822001001_0_dialog_content = "버질?",
  str_homestory_822001001_1_dialog_content = "버질, 왜 계속 허수아비만 보고 있어?",
  str_homestory_822001001_2_dialog_content = "이 허수아비...<sprite=emo_sikao size=60 />",
  str_homestory_822001001_3_dialog_content = "왜? 설마 이것도 골동품이야?",
  str_homestory_822001001_4_dialog_content = "한눈에 봐도 알겠어. 확실히 골동품 같아...",
  str_homestory_822001001_5_dialog_content = "정말? 이게 무슨 특별한 점이라도 있어?",
  str_homestory_822001001_6_dialog_content = "이 허수아비에 쓴 물건들...\n어쩌면 골동품일지도 몰라.",
  str_homestory_822001001_7_dialog_content = "진짜?!",
  str_homestory_822001001_8_dialog_content = "응, 이 조끼는 아마 어느 움브라톤 명품의\n한정판 제품일 거야.",
  str_homestory_822001001_9_dialog_content = "무려 50년 전에 유행했던 디자인이고.",
  str_homestory_822001001_10_dialog_content = "이 한정판의 가장 큰 특징은...",
  str_homestory_822001001_11_dialog_content = "검은 천에 흰 줄무늬를 염색해서 만든 형태야.",
  str_homestory_822001001_12_dialog_content = "보통은 흰 천에 검은 선 무늬를 인쇄해서 만들거든.",
  str_homestory_822001001_13_dialog_content = "심지어 옷깃 뒤엔 금실로 숫자가 꿰매져 있어.",
  str_homestory_822001001_14_dialog_content = "진짜네...<sprite=emo_wuzui size=60 />",
  str_homestory_822001001_15_dialog_content = "그리고 이 허수아비의 눈은 자세히 봐.\n이건 흑요석이야.",
  str_homestory_822001001_16_dialog_content = "이 광택과 색깔은 흑요석 중에서도 보석 등급에 속해.",
  str_homestory_822001001_17_dialog_content = "백야성 귀족들은 수십 년 전에 이 보석으로\n자주 단추를 만들었거든.",
  str_homestory_822001001_18_dialog_content = "이것들도 비슷한 셈이야.",
  str_homestory_822001001_19_dialog_content = "네가 말 안 했으면 진짜 몰랐을 거야.",
  str_homestory_822001001_20_dialog_content = "마지막으로는 허수아비를 받치고 있는 이 나무인데...",
  str_homestory_822001001_21_dialog_content = "재질은 아마 향나무일 거야.",
  str_homestory_822001001_22_dialog_content = "목재가 비교적 얇은 편이지만,\n다가가면 은은하게 좋은 향기가 날 거야.",
  str_homestory_822001001_23_dialog_content = "이 향나무로 만든 지팡이는 아주 비싸다구.",
  str_homestory_822001001_24_dialog_content = "우와... 그럼 이 허수아비, 엄청 가치가 있다는 거 아냐?",
  str_homestory_822001001_25_dialog_content = "안타깝지만... 골동품이라는 건\n전체적인 완성도를 봐야 해.",
  str_homestory_822001001_26_dialog_content = "한 세트인 물건들은 다 같이 있으면 가치가 높아져.\n하지만 하나라도 빠지면 가치가 많이 떨어져.",
  str_homestory_822001001_27_dialog_content = "그치만 반대로도 마찬가지야.\n이 허수아비는 관계없는 것들끼리 모여 있을 뿐이야.",
  str_homestory_822001001_28_dialog_content = "예술품의 관점으로 보더라도...",
  str_homestory_822001001_29_dialog_content = "현대의 3류 작품이라고밖에 말할 수 없겠어.\n가치는 없어.",
  str_homestory_822001001_30_dialog_content = "그렇구나, 아쉽네...<sprite=emo_tanqi size=60 />",
  str_homestory_822001001_31_dialog_content = "대신...",
  str_homestory_822001001_32_dialog_content = "대신...?",
  str_homestory_822001001_33_dialog_content = "분해해 버리면 얘기가 다를 거야.\n형아는 그러고 싶어?",
  str_homestory_822001001_34_dialog_content = "음... 그건 됐어.",
  str_homestory_822001001_35_dialog_content = "난 그냥 이 허수아비가 이 모습 그대로\n우리 곁에 있었으면 좋겠어.",
  str_homestory_822001001_36_dialog_content = "에헤헤, 역시 PlayerName 형아라면\n그럴 줄 알았다니까.",
  str_homestory_821901001_0_dialog_content = "무슨 일이세요?",
  str_homestory_821901001_1_dialog_content = "이스타반 씨... 혹시...",
  str_homestory_821901001_2_dialog_content = "그 시계가 마음에 드시나요?",
  str_homestory_821901001_3_dialog_content = "이런 양식의 시계는 처음 보는군.",
  str_homestory_821901001_4_dialog_content = "아이테르의 것인가?",
  str_homestory_821901001_5_dialog_content = "아마 그럴걸요.",
  str_homestory_821901001_6_dialog_content = "여기 있는 건 전부 아이테르 양식이니까요.",
  str_homestory_821901001_7_dialog_content = "이건 기계가 아니라 그림자를 이용한 시계로군.",
  str_homestory_821901001_8_dialog_content = "이 설계는...",
  str_homestory_821901001_9_dialog_content = "그림자의 예술이라 말할 수 있겠어.",
  str_homestory_821901001_10_dialog_content = "정말 마음에 드신 모양이네요.",
  str_homestory_821901001_11_dialog_content = "흘러간 시간에는 경외심을 품지 않을 수 없지.",
  str_homestory_821901001_12_dialog_content = "그래서 난 다양한 시계를 모으고 있다.",
  str_homestory_821901001_13_dialog_content = "어? 외부 세계에는 시계도 여러 종류가 있는 건가요?",
  str_homestory_821901001_14_dialog_content = "백야성의 시계는 고전적이고 낭만적이지.",
  str_homestory_821901001_15_dialog_content = "북방의 시계는 소박하고 실용적이다.",
  str_homestory_821901001_16_dialog_content = "레디젤 사막의 시계는 기계적 감성이 충만하다.",
  str_homestory_821901001_17_dialog_content = "그리고 움브라톤의 시계는\n조심스러우면서도 사치스럽지.",
  str_homestory_821901001_18_dialog_content = "그렇군요.\n이스타반 씨는 정말 수집을 좋아하시네요.",
  str_homestory_821901001_19_dialog_content = "일용품에도 그렇게 많은 종류가 있는 줄은 몰랐어요.",
  str_homestory_821901001_20_dialog_content = "공부가 많이 됐네요.",
  str_homestory_821901001_21_dialog_content = "그 시계들은 모두 현대의 산물이다.",
  str_homestory_821901001_22_dialog_content = "하지만 아이테르의 시계는\n시간의 무게를 느끼게 해 주지.",
  str_homestory_821901001_23_dialog_content = "세상에 단 하나라는 이 감각은 참 독특하군.",
  str_homestory_821901001_24_dialog_content = "음, 그럼...<sprite=emo_sikao size=60 />",
  str_homestory_821901001_25_dialog_content = "이거 선물로 드릴게요.",
  str_homestory_821901001_26_dialog_content = "어째서지?",
  str_homestory_821901001_27_option_content = "우린 친구니까요.",
  str_homestory_821901001_28_dialog_content = "우정의 선물이라는 건가?",
  str_homestory_821901001_29_dialog_content = "진지한 대답이군.",
  str_homestory_821901001_30_option_content = "좋아하시는 것 같아서요.",
  str_homestory_821901001_31_dialog_content = "그렇다 해도 남의 소중한 물건을 빼앗을 생각은 없다.",
  str_homestory_821901001_32_dialog_content = "마음만 받도록 하지.",
  str_homestory_821901001_33_dialog_content = "이 시계는 이대로 「집」에 두는 게 좋겠군.",
  str_homestory_821901001_34_dialog_content = "잘 모르겠어요... 마음에 안 드세요?",
  str_homestory_821901001_35_dialog_content = "여긴 다른 시계도 있거든요. 그러니까...",
  str_homestory_821901001_36_dialog_content = "아낌없이 친구와 나누는 자네 마음은 기쁘게 생각한다.",
  str_homestory_821901001_37_dialog_content = "허나 이 세상에는 이 시계에 더 어울리는 장소는 없다.",
  str_homestory_821901001_38_dialog_content = "지나간 시간은 기억이 되고,\n기억은 역사를 담고 있지.",
  str_homestory_821901001_39_dialog_content = "PlayerName, 아이테르의 역사는\n바로 이런 사소한 것들 사이에 있는 것이다.",
  str_homestory_821901001_40_dialog_content = "이곳의 모든 것이 자네에게 그만한 의미가 있다.",
  str_homestory_821901001_41_dialog_content = "그러니 난 그 무엇도 가져갈 생각이 없다.",
  str_homestory_821901001_42_dialog_content = "이스타반 씨...",
  str_homestory_821901001_43_dialog_content = "그럼 다음에 또 보도록 하지.\n그림자는 언제나 널 지켜볼 것이다.",
  str_homestory_821801001_0_dialog_content = "샤엘 씨?",
  str_homestory_821801001_1_dialog_content = "신기하네, 여기서 만나다니.\n오늘 분명히 좋은 일이 생기겠는걸?",
  str_homestory_821801001_2_dialog_content = "너도 그렇게 생각하지 않아? PlayerName.",
  str_homestory_821801001_3_dialog_content = "신기한가요? 샤엘 씨, 여긴 헤븐즈 가든인데요...",
  str_homestory_821801001_4_dialog_content = "물론 알고 있지.",
  str_homestory_821801001_5_dialog_content = "하지만 무슨 일이든지 우연이 겹쳐야 잘 되는 거야.\n장사도, 생활도.",
  str_homestory_821801001_6_dialog_content = "미안하지만 잘 이해가 안 돼요...",
  str_homestory_821801001_7_dialog_content = "괜찮아, 그럼 내가 설명해 줄게.",
  str_homestory_821801001_8_dialog_content = "예를 들어, 헤븐즈 가든은 지금 개조가 필요해 보여.\n그리고 마침 공중상회도...",
  str_homestory_821801001_9_dialog_content = "그런 계획을 하고 있어.",
  str_homestory_821801001_10_dialog_content = "신기하지 않아?",
  str_homestory_821801001_11_dialog_content = "그렇다는 건...",
  str_homestory_821801001_12_dialog_content = "헤븐즈 가든은 참 특별한 곳이야.\n근데 숙소는 좀 평범하지 않니?",
  str_homestory_821801001_13_option_content = "그런가요?",
  str_homestory_821801001_14_dialog_content = "물론이지, 아니면 내가 뭐 하러 이런 말을 꺼내겠어?",
  str_homestory_821801001_15_dialog_content = "어쩌면 넌 이미 익숙해져서 못 느끼는 건지도 몰라.",
  str_homestory_821801001_16_dialog_content = "이 숙소는 너무 평범해서 헤븐즈 가든과 맞지 않아.",
  str_homestory_821801001_17_option_content = "저도 그렇게 생각해요.",
  str_homestory_821801001_18_dialog_content = "역시 잘 아는구나!",
  str_homestory_821801001_19_dialog_content = "그럼 뭔가 해 볼 생각 없니?",
  str_homestory_821801001_20_dialog_content = "예를 들어 숙소를 개조하는 건 어때?",
  str_homestory_821801001_21_dialog_content = "내가 숙소를 더 호화롭게 만드는 걸 도와줄게.",
  str_homestory_821801001_22_dialog_content = "더... 호화롭게요?",
  str_homestory_821801001_23_dialog_content = "좋은 생각 같긴 한데요... 예산<sprite=emo_baiyebi size=60 />에 한계가 있어서...",
  str_homestory_821801001_24_dialog_content = "걱정할 거 없어! 개조를 내 공중상회에 의뢰해 줘!",
  str_homestory_821801001_25_dialog_content = "그럼 내가 무료로 이 숙소를 헤븐즈 가든에\n걸맞은 숙소로 바꿔줄게.",
  str_homestory_821801001_26_dialog_content = "무, 무무... 무료요?!",
  str_homestory_821801001_27_dialog_content = "그건 좀 곤란하지 않나요?",
  str_homestory_821801001_28_dialog_content = "아무리 친구라도 그러면 샤엘 씨가 너무 손해잖아요.",
  str_homestory_821801001_29_dialog_content = "알잖아, 난 손해 보는 장사는 안 하는 거.",
  str_homestory_821801001_30_dialog_content = "숙소 개조가 끝나면. 헤븐즈 가든 전체를\n테마파크 호텔로 만들 거야.",
  str_homestory_821801001_31_dialog_content = "테마파크 호텔이요?!",
  str_homestory_821801001_32_dialog_content = "넌 아무것도 안 해도 돼. 나한테 다 맡겨주면 돼.",
  str_homestory_821801001_33_dialog_content = "아니면 네가 재무 담당을 맡아도 돼.\n팔이 저릴 만큼 돈을 세게 될 테니까!",
  str_homestory_821801001_34_dialog_content = "팔이 저릴 만큼요?!",
  str_homestory_821801001_35_dialog_content = "서, 설마 그게 아까 말한 샤엘 씨 계획인가요?!",
  str_homestory_821801001_36_dialog_content = "으... 진짜 흔들리는 제안이긴 하네요<sprite=emo_aixin size=60 />!",
  str_homestory_821801001_37_dialog_content = "그렇지? 그럼 지금 바로...",
  str_homestory_821801001_38_dialog_content = "자, 잠깐만요!",
  str_homestory_821801001_39_dialog_content = "미안해요... 그래도 전 되도록 헤븐즈 가든의\n지금 모습을 지켜주고 싶어요.",
  str_homestory_821801001_40_dialog_content = "그리고 그런 개발이 이곳 환경에 영향이 없는지도\n아직 모르니까요...",
  str_homestory_821801001_41_dialog_content = "테마파크 호텔 같은 걸 지었다간...",
  str_homestory_821801001_42_dialog_content = "그렇구나. 이해했어.",
  str_homestory_821801001_43_dialog_content = "아무튼 언젠가는 관광사업을 펼칠 생각이 있다는 거지?",
  str_homestory_821801001_44_dialog_content = "네? 과, 관광사업이요?!",
  str_homestory_821801001_45_dialog_content = "그럼 참을성 있게 기다리고 있을게~",
  str_homestory_822101001_0_dialog_content = "관심 있어요?",
  str_homestory_822101001_1_dialog_content = "흥미진진한 모습으로 여기 한참 서 계시길래요.",
  str_homestory_822101001_2_dialog_content = "이 가구, 설마<sprite=emo_sikao size=60 />...",
  str_homestory_822101001_3_dialog_content = "자동으로 분리수거하는 휴지통이야?",
  str_homestory_822101001_4_dialog_content = "엥?! 어떻게 알았어요?",
  str_homestory_822101001_5_dialog_content = "이건 아이테르식 쓰레기통이에요.\n일반 쓰레기통과는 다르거든요.",
  str_homestory_822101001_6_dialog_content = "그렇게 쉽게 못 알아볼 줄 알았어요.",
  str_homestory_822101001_7_dialog_content = "후후, 나 무시하는 거야?",
  str_homestory_822101001_8_dialog_content = "그럼 분석 과정을 설명해 줄게.",
  str_homestory_822101001_9_dialog_content = "일단 아까 이 가구 제어 프로그램에\n침입해서 대충 봤는데...",
  str_homestory_822101001_10_dialog_content = "...지금 남의 가구에 뭘 했다고요?!",
  str_homestory_822101001_11_dialog_content = "우리랑 다른 프로그래밍 언어를 썼더라고.\n간결하고 우수해. 역시 아이테르의 첨단 기술이라니까!",
  str_homestory_822101001_12_dialog_content = "근데 기능상으론 일루미나 식당의 자동 배식 시스템과\n유사성이 있다고 할 수 있겠어.",
  str_homestory_822101001_13_dialog_content = "이 가구에도 같은 「분류」 기능이 탑재되어 있었거든.",
  str_homestory_822101001_14_dialog_content = "참고로 일루미나 식당의 프로그램은 내가 짠 거야.",
  str_homestory_822101001_15_dialog_content = "영양성분에 따라 자동으로 음식을 분류할 수 있어!",
  str_homestory_822101001_16_dialog_content = "그거 대단하네요.",
  str_homestory_822101001_17_dialog_content = "그럼 혹시 친구의 가구에 대한 파괴 욕구를 낮춰주는\n영양성분은 없을까요?",
  str_homestory_822101001_18_dialog_content = "...아무튼 「분류」에서 쓰레기통을 연상할 수 있는\n것만으로도 대단하네요.",
  str_homestory_822101001_19_dialog_content = "또 하나 결정적인 이유가 있어.",
  str_homestory_822101001_20_dialog_content = "어?",
  str_homestory_822101001_21_dialog_content = "이 가구엔 큰 쓰레기통 마크가 그려져 있거든.",
  str_homestory_822101001_22_dialog_content = "......",
  str_homestory_822101001_23_dialog_content = "진짜 신기하다니까!",
  str_homestory_822101001_24_dialog_content = "사실 「자동 분류」는 그렇게 대단한 기술은 아니긴 해.",
  str_homestory_822101001_25_dialog_content = "하지만, 이렇게 콤팩트한 바디에\n자동 분류 시스템을 탑재하고...",
  str_homestory_822101001_26_dialog_content = "게다가 이렇게 세세하게 분류할 수 있다니...\n지금 일루미나의 기술로는 해낼 수 없는 일이야.",
  str_homestory_822101001_27_dialog_content = "아이테르는 정말 대단한 종족이네!",
  str_homestory_822101001_28_dialog_content = "...으음.",
  str_homestory_822101001_29_option_content = "정말 그렇게 대단해요?",
  str_homestory_822101001_30_dialog_content = "그냥 쓰레기통일 뿐이잖아요.",
  str_homestory_822101001_31_dialog_content = "「그냥 쓰레기통」, 제일 대단한 게 바로 그 부분이야.",
  str_homestory_822101001_32_option_content = "그렇게 「자동 수거함」을 좋아할 줄은 몰랐네요.",
  str_homestory_822101001_33_dialog_content = "덕분에 저까지 뿌듯해졌어요, 헤헤.",
  str_homestory_822101001_34_dialog_content = "얼마든지 자랑스러워해도 돼!",
  str_homestory_822101001_35_dialog_content = "첨단 과학기술은 탄생 초기엔 모두\n군사 분야에 응용되기 마련이거든.",
  str_homestory_822101001_36_dialog_content = "그게 최대한 보급돼서 당연한 게 돼버린 뒤에야\n민간에 그 혜택이 돌아가게 돼.",
  str_homestory_822101001_37_dialog_content = "근데 이... 「자동 수거함」이라고 했나?\n이건 그냥 쓰레기통이니까...",
  str_homestory_822101001_38_dialog_content = "그 자체만으로 아이테르 문명의 위대함을\n마음껏 보여주고 있잖아!",
  str_homestory_822101001_39_dialog_content = "오...! 그렇게 보면 일리가 있네요!",
  str_homestory_822101001_40_dialog_content = "알골 씨가 백그라운드에 침입한 건 조금 마음에 걸리지만...",
  str_homestory_822101001_41_dialog_content = "그래도 알골 씨랑 이야기할 때마다\n참 배우는 게 많은 것 같아요.",
  str_homestory_822101001_42_dialog_content = "고마워요, 알골 씨.",
  str_homestory_822101001_43_dialog_content = "천만에. 그럼 답례로 이걸 분해해서 철저하게\n연구할 수 있는 권한을 주지 않을래?",
  str_homestory_822101001_44_dialog_content = "그런 건 꿈도 꾸지 마세요!",
  str_homestory_822301001_0_dialog_content = "이 석상...",
  str_homestory_822301001_1_dialog_content = "PlayerName의 거처에서도 이러한 조각상은 흔치 않던 것 같구나.",
  str_homestory_822301001_2_dialog_content = "이 석상은 PlayerName 그대에게 특별한 의미가 있는 것이냐?",
  str_homestory_822301001_3_dialog_content = "눈치챘구나... 이건 한 아이테르 여성을 조각한 거야.",
  str_homestory_822301001_4_dialog_content = "아이테르라면... PlayerName 그대의 동족이었던가. 아주 오래전의 종족이었다지.",
  str_homestory_822301001_5_dialog_content = "조각상에 남은 흔적에서 긴 세월의 숨결이 느껴지더구나.",
  str_homestory_822301001_6_dialog_content = "전설에 따르면, 이 사람은 대륙 곳곳의 산과 강을 누빈 여행가라고 해.",
  str_homestory_822301001_7_dialog_content = "네가 아까 말한 것처럼, 그건 아주 오래전 일이지만...",
  str_homestory_822301001_8_dialog_content = "암귀<sprite=emo_kulou size=60 />가 잔뜩인 이 세상에서, 아이테르가 또 그때처럼 혼자 여기저기 여행을 다니긴 엄청 위험할 거야...",
  str_homestory_822301001_9_dialog_content = "이 몸이 곁에 있거늘, 어찌 두려워하는 게냐?",
  str_homestory_822301001_10_dialog_content = "언젠가는 그대의 모습 역시 조각상으로 만들어져 후대에 전해질지도 모르는 일이거늘.",
  str_homestory_822301001_11_dialog_content = "어?! 내, 내가? 그건 불가능할걸. 내가 그렇게 대단한 능력을 가진 것도 아니고...",
  str_homestory_822301001_12_dialog_content = "어찌 불가능하다는 것이냐? 가령 천하에 큰 가뭄이 들면, 이 몸은 비와 번개를 불러 백성들에게 은혜를 내릴 것이다.",
  str_homestory_822301001_13_dialog_content = "그리고 PlayerName 그대는 옆에서 길 안내를 하며, 이 몸을 데리고 엿을 사러 가는 것이지...",
  str_homestory_822301001_14_dialog_content = "그리하면 그대는 「용신의 동자」로 여겨져 이 몸과 함께 조각상으로 만들어질 것이 아니겠느냐!",
  str_homestory_822301001_15_dialog_content = "엄청 구체적이네. 꼭 진짜 있었던 일처럼...",
  str_homestory_822301001_16_dialog_content = "또, 이 몸이 겨울에 바다에서 조난을 당한 서른여덟 명을 단번에 구해내었다고 가정해 보거라.",
  str_homestory_822301001_17_dialog_content = "그대는 선하고 다정한 사람이니, 그들이 얼어 죽지 않도록 불을 피우고, 담요를 덮어 주겠지...",
  str_homestory_822301001_18_dialog_content = "그리하면 그대의 조각상 역시 이 몸의 옆에 세워져 후대 사람들에게 기림을 받을 것이다.",
  str_homestory_822301001_19_dialog_content = "......",
  str_homestory_822301001_20_dialog_content = "어찌 그러느냐? 이 이야기들이 재미있지 않은 게야?",
  str_homestory_822301001_21_option_content = "재미있어!",
  str_homestory_822301001_22_dialog_content = "근데 좀 슬프기도 해.",
  str_homestory_822301001_23_option_content = "글쎄...",
  str_homestory_822301001_24_dialog_content = "재미가 있다거나 없다거나 판단할 일은 아닌 것 같아.",
  str_homestory_822301001_25_dialog_content = "그거, 다 진짜로 있었던 일들이지?",
  str_homestory_822301001_26_dialog_content = "용주에서 지내는 동안 여러 곳에서 네 조각상을 본 적 있거든.",
  str_homestory_822301001_27_dialog_content = "네가 용주의 여러 지역에서 얼마나 많은 사람을 도왔고, 아까 말한 그런 전설을 남겼는지 짐작할 수 있었어.",
  str_homestory_822301001_28_dialog_content = "그런데 그 이야기들 속에서 너한테 엿을 사 줬던 사람도, 네가 사람들을 구할 때 힘을 보태 줬던 사람도...",
  str_homestory_822301001_29_dialog_content = "너 말고는 다들 이젠 이 세상에 없을지도 모르니까...",
  str_homestory_822301001_30_dialog_content = "PlayerName, 설마 이 몸을 연민하는 게냐?",
  str_homestory_822301001_31_dialog_content = "만약 내가... 네가 겪었을 이별을 생각하면 가슴이 조금 시리다고 말한다면...",
  str_homestory_822301001_32_dialog_content = "내가 너무 오만하고, 용신에게 무례를 범한 셈일까?",
  str_homestory_822301001_33_dialog_content = "인간의 육신을 지닌 그대에게 그런 마음이 이는 것은, 무척 자연스러운 일이니라.",
  str_homestory_822301001_34_dialog_content = "허나 이 몸이 그대에게 감명받은 점 역시 그러한 점이니라.",
  str_homestory_822301001_35_dialog_content = "세월이라는 것은 길고도 길어, 결국에는 모든 것을 데려가 버리지.",
  str_homestory_822301001_36_dialog_content = "이 몸이 오래 살았다 한들, 천지에 비하면 한낱 하루살이에 지나지 않느니라.",
  str_homestory_822301001_37_dialog_content = "무릇 중생의 삶은 모두 하루살이 인생일지니, 잠시나마 동행하였다는 것도 인연인 게지. 소중히 여겨야 마땅하다.",
  str_homestory_822301001_38_dialog_content = "인간이 단명하는 것을 이 몸이 가엾이 여긴다면, 외려 그것이야말로 교만의 우를 범하는 것이니라.",
  str_homestory_822301001_39_dialog_content = "나름대로 일리가 있는 것 같아... 답답했던 마음이 순식간에 뻥 뚫렸어.",
  str_homestory_822301001_40_dialog_content = "「마음이 이어져 있다면, 몇 년 만의 상봉에도 무엇이 두려우리」... 용주 속담에 이런 게 있었지?",
  str_homestory_822301001_41_dialog_content = "토씨 하나 틀리지 않았구나! PlayerName, 근래 그대는 실로 많은 성장을 이루었다.",
  str_homestory_822301001_42_dialog_content = "세월은 잔혹하지만, 좋은 면도 가지고 있는 게지.",
  str_homestory_822301001_43_dialog_content = "헤헤<sprite=emo_qingsong size=60 />... 당연하지, 나도 시간을 헛되게 쓰면서, 제자리걸음만 하면 안 되잖아.",
  str_homestory_822301001_44_dialog_content = "게다가 세월이 흐르지 않았다면, 이 몸이 어찌 그대와 만날 수 있었겠으며...",
  str_homestory_822301001_45_dialog_content = "또 어찌 이곳에서 그대와 과거의 일을 이야기할 수 있었겠느냐.",
  str_homestory_822401001_0_dialog_content = "나송?",
  str_homestory_822401001_1_dialog_content = "이거 쓰고 싶어?",
  str_homestory_822401001_2_dialog_content = "당연하지! 이거 굉장히 정교하게 만들어져 있는데?",
  str_homestory_822401001_3_dialog_content = "저, 정교하다고...?",
  str_homestory_822401001_4_dialog_content = "당연하지. 이거 좀 봐, 억누르고 있던 욕망을 끌어내는 표정이잖아.",
  str_homestory_822401001_5_dialog_content = "그리고 딱딱함이랑 부드러움이 절묘하게 균형을 이룬 이 촉감.",
  str_homestory_822401001_6_dialog_content = "게다가 어떻게 때리든 원위치로 되돌아오는 신기한 효과까지...",
  str_homestory_822401001_7_dialog_content = "주먹 단련용 도구로 정말 완벽하다고!",
  str_homestory_822401001_8_option_content = "이해는 되네.",
  str_homestory_822401001_9_dialog_content = "역시<sprite=emo_guilian size=60 />, PlayerName 넌 이해할 줄 알았다니까.",
  str_homestory_822401001_10_option_content = "잘 모르겠는데...",
  str_homestory_822401001_11_dialog_content = "나도 제대로 설명을 못 하겠네<sprite=emo_sikao size=60 />. 아무튼 무예를 익히는 사람의 직감이랄까?",
  str_homestory_822401001_12_dialog_content = "내가 용주 여행을 처음 시작했을 무렵엔 매일 훈련 때문에 고민이 많았었어.",
  str_homestory_822401001_13_dialog_content = "단련, 수행, 권무 이런 건 말이지.",
  str_homestory_822401001_14_dialog_content = "하루라도 연습을 거르면 실력이 녹슬 수도 있거든.",
  str_homestory_822401001_15_dialog_content = "그렇긴 해도 단련은 어쨌든 단련이니까, 목적은 몸을 건강하게 만드는 거야.",
  str_homestory_822401001_16_dialog_content = "하지만 단련할 때 참고 견뎌야 한다는 말을 입에 달고 살면서, 일부러 자기를 괴롭히는 사람들도 있거든.",
  str_homestory_822401001_17_dialog_content = "그럼 주객전도 아냐?",
  str_homestory_822401001_18_dialog_content = "맞아!",
  str_homestory_822401001_19_dialog_content = "예를 들면, 「철산고」라는 기술을 연습한답시고 커다란 나무에 계속 몸을 부딪치는 사람들이 있어.",
  str_homestory_822401001_20_dialog_content = "사실 그러면 다치거나 병이 나기 쉬워. 지혜롭지 못한 행동이란 거지.",
  str_homestory_822401001_21_dialog_content = "그렇구나. 새로운 걸 알게 됐어...",
  str_homestory_822401001_22_dialog_content = "그런데 여행을 다니던 무렵엔 나도 적당한 도구를 못 찾아서 나무에다 연습하고 그랬어.",
  str_homestory_822401001_23_dialog_content = "젊어서 그런지 별 느낌은 없었지만.",
  str_homestory_822401001_24_dialog_content = "그러나 나중엔 아정이랑 다른 애들한테 무술을 가르쳐 주기 시작했는데.",
  str_homestory_822401001_25_dialog_content = "아정이랑 다른 애들이 내 방식대로 훈련을 하면 쉽게 다치더라고.",
  str_homestory_822401001_26_dialog_content = "그제서야 내가 써 왔던 도구랑 방식이 너무 거칠었단 걸 깨달았던 거야.",
  str_homestory_822401001_27_dialog_content = "그때부터는 나도 보호구 같은 장비에도 더 신경 쓰고, 안전을 따지기 시작했어.",
  str_homestory_822401001_28_dialog_content = "심지어는 아정이랑 다른 애들이 쓸 전용 훈련 도구까지 만들어 줬고 말이야...",
  str_homestory_822401001_29_dialog_content = "걔들 건 우리 걸 만들 때랑 다른 논리를 적용해 설계해야 하니까, 공을 꽤 많이 들였어.",
  str_homestory_822401001_30_dialog_content = "특히 매화장이라는 훈련 도구가 있는데, 그걸 만들 땐 걔들 다리가 짧으니까 적당한 간격을 찾으려고 몇 번이나 새로 만들었다니까.",
  str_homestory_822401001_31_dialog_content = "나송 넌 그런 쪽에 정말 정성이구나.",
  str_homestory_822401001_32_dialog_content = "당연하지. 난 신체를 단련하는 걸 좋아하고, 다른 취미는 딱히 없거든.",
  str_homestory_822401001_33_dialog_content = "게다가 친구가 쓸 도구를 골라 주는 건데, 대충 하면 안 되잖아?",
  str_homestory_822401001_34_dialog_content = "다음에 기회가 되면 PlayerName 너한테 맞는 도구도 만들어 줄게.",
  str_homestory_822501001_0_dialog_content = "저 등불...",
  str_homestory_822501001_1_dialog_content = "티아라 넌 그 가로등이 마음에 들어?",
  str_homestory_822501001_2_dialog_content = "좀 더 가까이서 봐도 돼.",
  str_homestory_822501001_3_dialog_content = "...이 정도 거리가 딱 좋아.",
  str_homestory_822501001_4_dialog_content = "여기서 보고 있으면 북방의 「등대」가 생각나거든.",
  str_homestory_822501001_5_dialog_content = "그렇게 말하니까 확실히 좀 비슷하네.",
  str_homestory_822501001_6_dialog_content = "근데 아쉽지만 저건 그냥 평범한 등불이야.\n「등대」처럼 북방의 생명들을 지키진 않아.",
  str_homestory_822501001_7_dialog_content = "......",
  str_homestory_822501001_8_dialog_content = "어렸을 때 난 눈소나무 숲 꼭대기에서\n「등대」를 자주 봤었어.",
  str_homestory_822501001_9_dialog_content = "등대는 정말 밝아...",
  str_homestory_822501001_10_dialog_content = "어떤 깊은 밤이든, 아무리 안개가 짙든\n그 빛은 사방을 비추고 있었어.",
  str_homestory_822501001_11_dialog_content = "그 빛이 지켜준 눈소나무 숲은 무척 조용했어.",
  str_homestory_822501001_12_dialog_content = "암귀의 포효도, 오로리안의 비명도 없는...\n그 고요함은 정말 귀중해.",
  str_homestory_822501001_13_dialog_content = "그건 우리 북방 사람들만이 가진 특별한 「등대」야.",
  str_homestory_822501001_14_dialog_content = "북방 사람들이 「등대」에 진심으로 감사하고\n존경하는 건 나도 느꼈어.",
  str_homestory_822501001_15_dialog_content = "하지만 모두가 감사하고 존경하는 건...\n그 「등대」가 아니야.",
  str_homestory_822501001_16_dialog_content = "어느 날 난 교활한 사냥감을 쫓다가 나도 모르게\n멀리까지 가 버리고 말았어...",
  str_homestory_822501001_17_dialog_content = "어둠 속에서 암귀의 외침이 들렸을 때야 알았지.\n내가 이미 집에서 엄청 멀리 와버렸다고 말이야...",
  str_homestory_822501001_18_dialog_content = "바로 그때 등대의 불빛이 보였어.",
  str_homestory_822501001_19_dialog_content = "아주 먼 곳이었는데... 거기서도 「등대」가 보였어?",
  str_homestory_822501001_20_dialog_content = "...아니, 내가 본 건 우릴 지키는 그 「등대」가 아니었어.",
  str_homestory_822501001_21_dialog_content = "그냥 해안에 서 있는 평범한 등대였어...",
  str_homestory_822501001_22_dialog_content = "밤이 되면 거긴 암귀의 소굴이 되곤 했어.",
  str_homestory_822501001_23_dialog_content = "세상에...",
  str_homestory_822501001_24_dialog_content = "난 나무 사이에 숨어서 꼼짝도 할 수 없었어.",
  str_homestory_822501001_25_dialog_content = "등대의 불빛이 계속 날 스쳐지나갔고...",
  str_homestory_822501001_26_dialog_content = "암귀들은 그 아래를 돌아다니고 있었어.",
  str_homestory_822501001_27_dialog_content = "그때 내가 뭘 눈치챘는지 알아?",
  str_homestory_822501001_28_dialog_content = "뭔데?",
  str_homestory_822501001_29_dialog_content = "사실 그 등대는 내가 감사하고 존경하던 「등대」랑\n똑같이 생겼던 거야.",
  str_homestory_822501001_30_dialog_content = "......",
  str_homestory_822501001_31_dialog_content = "똑같은 밝은 빛으로, 가장 어두운 어둠을 밝히고,\n가장 짙은 안개를 꿰뚫고 있는 거야...",
  str_homestory_822501001_32_dialog_content = "하지만 그 등대가 날 지켜주진 못해.\n만약 그날 밤 내가 조금이라도 움직였다면...",
  str_homestory_822501001_33_dialog_content = "난 암귀 무리한테 갈기갈기 찢어졌을 거야.",
  str_homestory_822501001_34_dialog_content = "티아라...",
  str_homestory_822501001_35_dialog_content = "그리고 그날 밤 난 이해했어.",
  str_homestory_822501001_36_dialog_content = "「등대」 그 자체만으로는 사실 딱히 특별할 것도 없어.",
  str_homestory_822501001_37_dialog_content = "우리 눈앞의 저 등불이 그저 평범한 등불인 것처럼,\n그 등대도 아주 평범한 등대였어.",
  str_homestory_822501001_38_dialog_content = "불을 밝히고, 유지하고, 신념으로 그 빛을 이루는\n사람이 없다면, 그건 아무것도 아냐.",
  str_homestory_822501001_39_dialog_content = "우리 북방 사람들을 지키고 있는 건,\n애초부터 북방의 「등대」가 아니라...",
  str_homestory_822501001_40_dialog_content = "베들레헴 여왕 폐하니까.",
  str_homestory_822501001_41_dialog_content = "......",
  str_homestory_822501001_42_option_content = "폐하의 신념은 정말 존경스러워.",
  str_homestory_822501001_43_dialog_content = "설령 「등대」가 없더라도, 폐하는 전력을 다해\n북방 백성들을 지켜주실 거야.",
  str_homestory_822501001_44_option_content = "그날은 분명히 티아라 네 인생에 있어 중요한 밤이었겠네.",
  str_homestory_822501001_45_dialog_content = "그날 밤 넌 자신의 신념을 세운 거야.",
  str_homestory_822501001_46_dialog_content = "맞아.",
  str_homestory_822501001_47_dialog_content = "비록 여왕 폐하의 발끝조차 따라잡을 수 없겠지만,\n난 그래도 폐하의 발걸음을 따라갈 거야.",
  str_homestory_822501001_48_dialog_content = "지키기 위해 살고, 지키기 위해 싸우겠어.",
  str_homestory_822501001_49_dialog_content = "그래? 나도 같은 생각이었는데.",
  str_homestory_822501001_50_dialog_content = "특히 「발끝조차 따라잡을 수 없다」는 점 말이야.",
  str_homestory_822501001_51_dialog_content = "아하하, 여왕 폐하를 누가 따라잡을 수 있어?",
  str_homestory_822501001_52_dialog_content = "하지만 폐하의 뒷모습만이라도 보인다면,\n난 영원히 길을 잃지 않을 거야.",
  str_homestory_822601001_0_dialog_content = "저기...",
  str_homestory_822601001_1_dialog_content = "레이첼, 이 목마에 관심 있어?",
  str_homestory_822601001_2_dialog_content = "좀 유치하긴 해도 타고 흔들어보면 의외로 재밌어.",
  str_homestory_822601001_3_dialog_content = "한번 타 볼래? 타 봐!",
  str_homestory_822601001_4_dialog_content = "됐어...",
  str_homestory_822601001_5_dialog_content = "난 이제 그럴 나이도 아니니까.",
  str_homestory_822601001_6_dialog_content = "넌 목마를 자주 타고 놀았어?",
  str_homestory_822601001_7_dialog_content = "자, 자주까진 아니긴 한데...",
  str_homestory_822601001_8_dialog_content = "(레이첼이 목마 타는 걸 부끄러워할 줄 알았는데,\n결국 나만 폭로당했잖아!)",
  str_homestory_822601001_9_dialog_content = "하지만 이건 확실히 좋은 장난감이네.",
  str_homestory_822601001_10_dialog_content = "보기엔 간단해 보이지만, 디자인은 합리적이고,\n만듦새도 정교해.",
  str_homestory_822601001_11_dialog_content = "구조역학적으로나 인체공학적으로도\n귀감이 된다고 할 수 있어.",
  str_homestory_822601001_12_dialog_content = "그래서 나도 모르게 계속 살펴보고 있었던 거야.",
  str_homestory_822601001_13_dialog_content = "와... 그런 생각은 한 번도 못 해봤는데.",
  str_homestory_822601001_14_dialog_content = "넌 잠깐 보기만 해도 그렇게 많은 게 보이는 거야?",
  str_homestory_822601001_15_dialog_content = "이건 공학 전공자의 기본 소양이야.",
  str_homestory_822601001_16_dialog_content = "난 어떤 물체든 한눈만 보고도 3면도를 그릴 수 있어.",
  str_homestory_822601001_17_dialog_content = "이 목마가 어떻게 만들어졌는지 거의 알 것 같아.",
  str_homestory_822601001_18_dialog_content = "그 정도면 거의 초능력 아닌가...",
  str_homestory_822601001_19_dialog_content = "...좋아, 그럼 이 목마는 너한테 줄게!",
  str_homestory_822601001_20_dialog_content = "어?",
  str_homestory_822601001_21_option_content = "가지고 가면 연구하기 더 편하잖아.",
  str_homestory_822601001_22_dialog_content = "알겠어, 내가 여기 계속 있는 게 곤란한 거지?",
  str_homestory_822601001_23_dialog_content = "그럴 리가 없잖아!",
  str_homestory_822601001_24_option_content = "네가 그렇게 좋아하는 것도 흔한 일은 아니니까.",
  str_homestory_822601001_25_dialog_content = "하지만 내가 가장 마음에 드는 건 네 콜로서스야.",
  str_homestory_822601001_26_dialog_content = "스카이워커는 안 돼!",
  str_homestory_822601001_27_dialog_content = "후훗... 농담이야.",
  str_homestory_822601001_28_dialog_content = "네 마음은 고마워. 하지만...",
  str_homestory_822601001_29_dialog_content = "여동생한테 줄 선물은 가능하면 직접 만들고 싶어.",
  str_homestory_822601001_30_dialog_content = "...여동생?",
  str_homestory_822601001_31_dialog_content = "응, 이 목마를 보니까 여동생한테\n똑같은 걸 만들어 주고 싶어졌거든.",
  str_homestory_822601001_32_dialog_content = "내가 어렸을 땐 이런 장난감을 볼 일이 없었으니까,\n적어도 여동생한테는...",
  str_homestory_822601001_33_dialog_content = "뭐, 이것도 결국 내 자기만족일지도 모르겠지만.",
  str_homestory_822601001_34_dialog_content = "레이첼...",
  str_homestory_822601001_35_dialog_content = "아까 내가 한 말은 진짜야.",
  str_homestory_822601001_36_dialog_content = "목마는... 정말 재미있어.\n네가 상상도 못 할 정도로 재미있다구!",
  str_homestory_822601001_37_dialog_content = "어... 그래?",
  str_homestory_822601001_38_dialog_content = "그러니까 한번 타 봐! 여동생을 위해서 말이야!\n직접 안 타 보고 어떻게 최고의 선물을 줄 수 있겠어?",
  str_homestory_822601001_39_dialog_content = "자, 사양하지 말고!",
  str_homestory_822601001_40_dialog_content = "그...그럼... 한번 타 볼게.",
  str_homestory_822601001_41_dialog_content = "분명히 푹 빠질걸.",
  str_homestory_822701001_0_dialog_content = "제타?",
  str_homestory_822701001_1_dialog_content = "이게 대체 뭐야...?",
  str_homestory_822701001_2_dialog_content = "귀여워서 터질 것 같은 날개, 멋진 세공...",
  str_homestory_822701001_3_dialog_content = "이 용사 제타의 감정에 의하면,\n이건 분명히 어떤 고대의 보물 같은데?",
  str_homestory_822701001_4_dialog_content = "이건 오색 인형이야.",
  str_homestory_822701001_5_dialog_content = "오! 아이테르! 정말 공교롭네!",
  str_homestory_822701001_6_dialog_content = "네가 이 물건의 이름을 안다는 건...\n이 물건에 대해 잘 알고 있다는 뜻이겠지?",
  str_homestory_822701001_7_dialog_content = "이건 윈델리온 장식이야.",
  str_homestory_822701001_8_dialog_content = "윈델리온?",
  str_homestory_822701001_9_dialog_content = "오로리안한테는 성자를 추모하고 빛을 기념하는\n명절이라고 들었어.",
  str_homestory_822701001_10_dialog_content = "성자를 추모하고 빛을 기념해? 뭔가 되게 멋있는걸!",
  str_homestory_822701001_11_dialog_content = "난 왜 그런 멋진 명절이 세상에 있는 줄 몰랐지?",
  str_homestory_822701001_12_dialog_content = "내 친구도 책에서 이 명절을 알았다고 해.",
  str_homestory_822701001_13_dialog_content = "그리고 우리 아이테르한테는 매우 중요한 명절이야.",
  str_homestory_822701001_14_dialog_content = "그래서 이날 우린 대자연을 기념하고\n성대한 파티를 열어.",
  str_homestory_822701001_15_dialog_content = "음... 명절을 보내는 방법 치곤 뭔가 평범하네.",
  str_homestory_822701001_16_dialog_content = "크흠... 아무튼 이건 우리가 윈델리온을\n위해서 만든 인형이야.",
  str_homestory_822701001_17_dialog_content = "그리고 이 오색 인형의 뱃속에는\n축복과 사탕을 채울 거야.",
  str_homestory_822701001_18_dialog_content = "축복... 그리고... 사탕!",
  str_homestory_822701001_19_dialog_content = "당장 축제를 열자!\n지금 바로 윈델리온을 시작하는 거야!",
  str_homestory_822701001_20_dialog_content = "뭐야? 갑자기 흥분하고.",
  str_homestory_822701001_21_dialog_content = "나도 오색 인형 만들고 싶다구!",
  str_homestory_822701001_22_option_content = "축제 날이 아니더라도 오색 인형은 만들 수 있어.",
  str_homestory_822701001_23_dialog_content = "그렇지? 그럼 오색 인형 만드는 법 좀 알려줘.",
  str_homestory_822701001_24_option_content = "좋아, 알려줄게.",
  str_homestory_822701001_25_dialog_content = "정말?! 아이테르, 넌 정말 좋은 사람이야!",
  str_homestory_822701001_26_dialog_content = "헤헤, 완성되면 안에 내 걸작을 넣고...",
  str_homestory_822701001_27_dialog_content = "사람들이 안에 뭐가 들어있는지 궁금해할 때...",
  str_homestory_822701001_28_dialog_content = "퍼엉! 콰앙! 푸슈슈! 연기랑 사탕을 선보이는 거지!",
  str_homestory_822701001_29_dialog_content = "하아? 안에 폭탄을 넣을 생각은 아니지?",
  str_homestory_822701001_30_dialog_content = "물론 다 넣진 않아.\n그냥 사탕이 사방으로 날리는 정도면 돼!",
  str_homestory_822801001_0_dialog_content = "바티아!",
  str_homestory_822801001_1_dialog_content = "드디어 나왔네!",
  str_homestory_822801001_2_dialog_content = "음... 너였구나...",
  str_homestory_822801001_3_dialog_content = "무슨 일 있어?",
  str_homestory_822801001_4_dialog_content = "아니, 그냥 네가 계속 텐트 안에서 게임만 하길래.",
  str_homestory_822801001_5_dialog_content = "나와서 바람 좀 쐬라고 부를까 했거든.",
  str_homestory_822801001_6_dialog_content = "휴우... 하아...",
  str_homestory_822801001_7_dialog_content = "다 됐어. 그럼 돌아갈게.",
  str_homestory_822801001_8_dialog_content = "잠깐만! 최소한 밖에서 산책 정도는 하고\n\n들어가야 되는 거 아냐?!",
  str_homestory_822801001_9_dialog_content = "어... 바깥은...",
  str_homestory_822801001_10_dialog_content = "바티아 넌 바깥이 그렇게 싫어?",
  str_homestory_822801001_11_dialog_content = "여기 환경도... 안 되는 거야?",
  str_homestory_822801001_12_dialog_content = "아니야! 절대 여기가 싫다는 건 아냐...",
  str_homestory_822801001_13_dialog_content = "여, 여긴 움브라톤 거리보다 훨씬 좋아!",
  str_homestory_822801001_14_dialog_content = "아... 비교 대상이 움브라톤 거리구나...",
  str_homestory_822801001_15_dialog_content = "으앗... 미, 미안... 내가 뭔가 말실수한 거야?!",
  str_homestory_822801001_16_dialog_content = "근데 난 움브라톤 거리밖에 몰라서...",
  str_homestory_822801001_17_dialog_content = "그럼 다른 곳도 많이 가보면 되는 거야.",
  str_homestory_822801001_18_option_content = "PlayerName 넌... 어디 가고 싶은데?",
  str_homestory_822801001_19_dialog_content = "강가",
  str_homestory_822801001_20_dialog_content = "강에 가면 물고기도 잡을 수 있어.",
  str_homestory_822801001_21_dialog_content = "아하, 「낚시의 달인」 실전판이구나.",
  str_homestory_822801001_22_dialog_content = "근데... 내가 진짜 물고기를 잡을 수 있을까...",
  str_homestory_822801001_23_dialog_content = "하하, 확실히 게임 규칙이랑은 다르긴 해.",
  str_homestory_822801001_24_option_content = "숲",
  str_homestory_822801001_25_dialog_content = "숲에서 캠핑하자. 밥도 해 먹고 야생 과일도 먹을 수 있어!",
  str_homestory_822801001_26_dialog_content = "아, 왠지 전략을 잘 세워야 할 것 같은 놀이네.",
  str_homestory_822801001_27_dialog_content = "미리 장소와 동선을 정하고 효율을 높여야...",
  str_homestory_822801001_28_dialog_content = "이런 건 업적이나 포인트 같은 건 없다구!",
  str_homestory_822801001_29_dialog_content = "그래, 알겠어. 그럼 해 볼게...",
  str_homestory_822801001_30_dialog_content = "그럼 혹시 이 텐트도 가져가도 돼?",
  str_homestory_822801001_31_dialog_content = "피곤하면 안에 들어가서 게임할 수도 있으니까...",
  str_homestory_822801001_32_dialog_content = "음... 그래도 될 것 같긴 한데...",
  str_homestory_822901001_0_dialog_content = "빅토리아 씨? 왜 계속 그네의자를 쳐다보는 거야?",
  str_homestory_822901001_1_dialog_content = "뭐 이상한 데라도 있어?",
  str_homestory_822901001_2_dialog_content = "진리의 결사에도 비슷한 그네의자가 있거든.\n",
  str_homestory_822901001_3_dialog_content = "그들이 가장 마음에 들어 했던 의자야.",
  str_homestory_822901001_4_dialog_content = "그들?",
  str_homestory_822901001_5_dialog_content = "내가 그 그네의자를 지나갈 때면, 열 번 중 여덟 번은\n베릴이 거기 웅크려서 책을 읽고 있었어.",
  str_homestory_822901001_6_dialog_content = "나머지 두 번은 베릴이 책을 베고 잠들어 있었고.",
  str_homestory_822901001_7_dialog_content = "그럼 그냥 베릴이 혼자 점거하고 있는 거잖아!",
  str_homestory_822901001_8_dialog_content = "그리고 가끔씩 엘시가 주변을 맴도는 걸 봤어.",
  str_homestory_822901001_9_dialog_content = "그리고 보통 사람들은 이해하기 힘든 말을\n중얼거리고 있지. 예를 들면...",
  str_homestory_822901001_10_dialog_content = "「쿠션이랑 등받이에 쇠 가시를 달면\n완벽한 고문 도구가 될 거야!」",
  str_homestory_822901001_11_dialog_content = "...걔가 행동에 옮기기 전에, 그 그네의자...\n그리고 베릴을 지켜줘!",
  str_homestory_822901001_12_dialog_content = "엘시가 그렇게 생각하는 걸 탓할 순 없어.",
  str_homestory_822901001_13_dialog_content = "그네의자에 나일즈의 피가 튀었을 땐,\n확실히... 고문도구로 보였으니까.",
  str_homestory_822901001_14_dialog_content = "나일즈까지?!",
  str_homestory_822901001_15_dialog_content = "나일즈도 탓할 수 없어.\n확실히 쾌적한 의자인 건 맞잖니.",
  str_homestory_822901001_16_dialog_content = "우리의 경건한 고행자들도 가끔은\n앉고 싶다는 생각이 들 거야.",
  str_homestory_822901001_17_dialog_content = "......",
  str_homestory_822901001_18_dialog_content = "결국... 빅토리아 씨만 한 번도 못 앉아본 거네?",
  str_homestory_822901001_19_dialog_content = "돌이켜보면 확실히 그렇네.",
  str_homestory_822901001_20_dialog_content = "...어쩌면 내가 의식해서 그 의자를\n피하고 있었는지도 모르겠네.",
  str_homestory_822901001_21_dialog_content = "피한다고...? 의자를?",
  str_homestory_822901001_22_dialog_content = "왈라키아의 옛집에도 그네의자가 있었어.\n전에는 우리 아버지의 소유였지.",
  str_homestory_822901001_23_dialog_content = "어느 날 파우스트가 무슨 생각인지 특별히 그걸\n가지고 와서 내게 돌려줬어.",
  str_homestory_822901001_24_dialog_content = "그걸 보면 난 부모님이나 내 어린 시절,\n그리고 왈라키아의 피할 수 없는 운명이 떠올라.",
  str_homestory_822901001_25_dialog_content = "난... 그것들을 계속 떠올리고 싶진 않아.",
  str_homestory_822901001_26_dialog_content = "파우스트도 참견이 너무 심하네.",
  str_homestory_822901001_27_dialog_content = "운명을 마주하는 것도 진리의 일환이라고\n내게 말하고 싶었던 걸지도 모르지.",
  str_homestory_822901001_28_dialog_content = "그래도 어린 시절의 추억이잖아.",
  str_homestory_822901001_29_dialog_content = "추억엔 고통도 있지만, 즐거웠던 기억도 있을 거잖아.",
  str_homestory_822901001_30_dialog_content = "훗, 맞아. 아버지가 날 안고 그네의자에 앉아서\n책을 읽어주셨던 건 확실히 멋진 추억이야.",
  str_homestory_822901001_31_dialog_content = "하지만 최근 여러 일들을 겪으면서 나도 깨달았단다.",
  str_homestory_822901001_32_dialog_content = "과거의 고통은 내 마음속에만 존재하는 거야.",
  str_homestory_822901001_33_dialog_content = "내가 그걸 극복하면, 그네의자는 그저\n그네의자일 뿐인 거지.",
  str_homestory_822901001_34_dialog_content = "네 천연의 지혜가 보여주는 대로──",
  str_homestory_822901001_35_dialog_content = "난 이걸 보고만 있을 게 아니라 편안하게 앉아야 해.",
  str_homestory_822901001_36_dialog_content = "...마, 맞아! 그게 바로 내가 하고 싶었던 말이야!",
  str_homestory_822901001_37_dialog_content = "자, 앉아. 내 그네의자는 언제든지\n빅토리아 씨를 환영할 테니까.",
  str_homestory_822901001_38_dialog_content = "그럼 나도 먼저 감사 인사를 해 둘게, PlayerName.",
  str_homestory_823001001_0_dialog_content = "이 건물, 생김새가 기괴하지?",
  str_homestory_823001001_1_dialog_content = "이래 봬도 안은 의외로 쾌적해!",
  str_homestory_823001001_2_dialog_content = "「기괴」? 그럴 리가요...",
  str_homestory_823001001_3_dialog_content = "탑과 같은 구조고, 창문의 배열이 마치\n작은 성 같습니다.",
  str_homestory_823001001_4_dialog_content = "만약 허락해 주신다면 가끔 여기서\n수행하고 싶습니다.",
  str_homestory_823001001_5_dialog_content = "얼마든지!",
  str_homestory_823001001_6_dialog_content = "언제든지 와도 돼.",
  str_homestory_823001001_7_dialog_content = "그거야 괜찮지만...",
  str_homestory_823001001_8_dialog_content = "대신 집에서는 유혈 사건을 일으키지\n않겠다고 약속해 줘...",
  str_homestory_823001001_9_dialog_content = "당신의 관대함에 진심으로 감사드립니다.",
  str_homestory_823001001_10_dialog_content = "그나저나 빌헬름 씨도 계속 성 안에서\n수행을 하시지 않아?",
  str_homestory_823001001_11_dialog_content = "...! 그, 그렇습니다...\n그런데 멘토님 이야기는 갑자기 왜 하시는지...",
  str_homestory_823001001_12_dialog_content = "생각해 보니까 네가 「성 같은」 방에서\n수행하고 싶은 건...",
  str_homestory_823001001_13_dialog_content = "빌헬름 씨의 영향을 받아서 그런 거야?",
  str_homestory_823001001_14_dialog_content = "......",
  str_homestory_823001001_15_dialog_content = "거짓말을 하는 건 죄입니다.\n간파된 이상 인정할 수밖에 없겠지요.",
  str_homestory_823001001_16_dialog_content = "확실히 조금... 아주 조금 멘토님을...\n따라 하고 싶다고... 생각했습니다.",
  str_homestory_823001001_17_dialog_content = "전 멘토님께 더는 그런 짓을\n하지 않겠다고 약속했습니다.",
  str_homestory_823001001_18_dialog_content = "저와 같은 미미한 자가 멘토님처럼 되고 싶어 하는\n것은 크나큰 죄입니다! 전──",
  str_homestory_823001001_19_dialog_content = "아니야! 존경하는 사람을 따라하는 건\n자연스러운 일이잖아?",
  str_homestory_823001001_20_dialog_content = "그래서 넌 뭘 따라 했는데?",
  str_homestory_823001001_21_dialog_content = "전...",
  str_homestory_823001001_22_dialog_content = "...머리카락을... 길러 보았습니다.",
  str_homestory_823001001_23_dialog_content = "......",
  str_homestory_823001001_24_dialog_content = "하지만 제 머릿결은 장발에 적합하지 않은 듯합니다.\n참새들이 둥지라고 착각해 버렸습니다...",
  str_homestory_823001001_25_dialog_content = "참회를 마칠 무렵엔 제 머리에서 아기새가 부화하고 있었습니다.",
  str_homestory_823001001_26_dialog_content = "참회를 얼마나 길게 한 거냐고...",
  str_homestory_823001001_27_dialog_content = "머리를 자른 후엔 멘토님처럼 잠을 안 자고,\n밤새 공부하려고 했습니다.",
  str_homestory_823001001_28_dialog_content = "그 결과, 걸으면서 잠들어 버려서,\n계단에서 굴러떨어졌습니다...",
  str_homestory_823001001_29_dialog_content = "뭐?!",
  str_homestory_823001001_30_dialog_content = "그리고 전 멘토님의 검 「적류」가 무척\n멋있다고 생각했습니다.",
  str_homestory_823001001_31_dialog_content = "어느 날 제 피로 「적류」를 흉내 내려고 할 때\n마침내 멘토님께서는 절 말리셨습니다.",
  str_homestory_823001001_32_dialog_content = "오! 그럼 빌헬름 씨도 너한테\n「너다운 게 좋은 거야」라고 말했겠지?",
  str_homestory_823001001_33_dialog_content = "멘토님은 「나일즈, 고개를 들어라. 무엇이 보이지?」라고 자상하게 물으셨습니다.",
  str_homestory_823001001_34_dialog_content = "저는 「하늘입니다. 멘토님, 진리의 주인께서 우리를 지켜보고 계십니다」라고 대답했습니다.",
  str_homestory_823001001_35_dialog_content = "멘토님은 이어서 「왜 우리에게 하늘이 보이는지 아느냐?」라고 물으셨습니다.",
  str_homestory_823001001_36_dialog_content = "저는 「주께서 그것을 창조하셨기 때문입니다」라고 대답했습니다.",
  str_homestory_823001001_37_dialog_content = "그러자 멘토님은 「네 그 『적류』가 우리 지붕을 부수었기 때문이다」라고 말씀하셨습니다.",
  str_homestory_823001001_38_dialog_content = "......",
  str_homestory_823001001_39_dialog_content = "저는 제 죄를 깊이 참회했습니다.",
  str_homestory_823001001_40_dialog_content = "그리고 깨달았습니다. 저는 멘토님에게서 가장 배워야 할 걸 배우지 않았습니다.",
  str_homestory_823001001_41_dialog_content = "멘토님은 줄곧 자신의 신념을 관철하셨고,\n결코 굽히지 않으셨습니다.",
  str_homestory_823001001_42_dialog_content = "저도 멘토님처럼 본래의 제 모습으로 세상을 살아야 했습니다.",
  str_homestory_823001001_43_dialog_content = "방금 그 일련의 재앙... 아니지, 사건에서 그런 결론을 얻은 거구나...",
  str_homestory_823001001_44_dialog_content = "넌 어쩌면 이해 능력이 무척 강한지도 모르겠네...",
  str_homestory_823001001_45_dialog_content = "따뜻한 말씀 감사합니다, PlayerName.",
  str_homestory_823001001_46_dialog_content = "답례로 저 또한 언제든지 이 작은 성에서\n당신의 참회를 듣겠습니다.",
  str_homestory_823001001_47_dialog_content = "크흠, 생각나면 얘기할게!",
  str_homestory_823101001_0_dialog_content = "빌헬름 씨, 왜 계속 이 정자를 보고 계시는 거죠? 안엔 아무것도 없는데요.",
  str_homestory_823101001_1_dialog_content = "이 아래에도 수수께끼가 숨겨져 있는 건 아닐까 생각하고 있었다.",
  str_homestory_823101001_2_dialog_content = "수수께끼요? 서, 설마요... 왜 그렇게 생각하시는 건데요?",
  str_homestory_823101001_3_dialog_content = "황야에 덩그러니 서 있는 정자는 마치 모험이나 수수께끼와 천성적인 연관이 있는 것처럼 보이지.",
  str_homestory_823101001_4_dialog_content = "많은 전설 이야기에도 비슷한 내용이 있다.",
  str_homestory_823101001_5_dialog_content = "나는 그 점에 깨달음을 얻고 한때 빅토리아에게 수수께끼를 낸 적이 있었다.",
  str_homestory_823101001_6_dialog_content = "저, 정자에서요?",
  str_homestory_823101001_7_dialog_content = "우선, 나는 그녀를 조금 화나게 만들었다.",
  str_homestory_823101001_8_dialog_content = "왜 그런 짓을 하는 건데요?!",
  str_homestory_823101001_9_dialog_content = "그거야 간단하지. 그녀는 원래부터 내게 적의를 품고 있었기 때문이다.",
  str_homestory_823101001_10_dialog_content = "그러나 그녀가 「악마, 지옥에나 떨어져!」라고 외치면서 눈을 붉히고 달려간 것을 보면...",
  str_homestory_823101001_11_dialog_content = "내가 조금 과했는지도 모르겠군.",
  str_homestory_823101001_12_dialog_content = "빅토리아 씨도... 옛날엔 꽤... 활발했네요.",
  str_homestory_823101001_13_dialog_content = "그리고 나는 고의로 몇 가지 단서를 남겨 그녀에게 왈라키아 가문에 대대로 전해지는 보물이 있다고 생각하게 만들었다.",
  str_homestory_823101001_14_dialog_content = "그것을 찾기만 하면 날 쓰러트리고 당주의 자리를 빼앗을 수 있게 된다는 생각을 심은 것이지.",
  str_homestory_823101001_15_dialog_content = "당신들의 관계는 대체 얼마나 왜곡돼 있는 건가요...",
  str_homestory_823101001_16_dialog_content = "그녀는 내가 생각한 대로 단서를 해독하고, 올바른 결론을 이끌어 냈다.",
  str_homestory_823101001_17_dialog_content = "대대로 내려오는 보물의 위치에 대한 정보는 화원 깊은 곳의 정자에 새겨져 있다는 것이었다.",
  str_homestory_823101001_18_dialog_content = "그리고요...?",
  str_homestory_823101001_19_dialog_content = "물론 정자를 찾은 것만으로 끝이 아니다.",
  str_homestory_823101001_20_dialog_content = "그녀는 정자의 석판에 새겨진 수수께끼를 풀고, 마지막으로 보물이 있는 장소를 찾아야만 했다.",
  str_homestory_823101001_21_dialog_content = "첨언하자면, 나는 그 석판을 낡아 보이게 만든 솜씨에 무척 만족했었지.",
  str_homestory_823101001_22_dialog_content = "......",
  str_homestory_823101001_23_dialog_content = "그 석판의 수수께끼는... 빌헬름 씨가 낸 건가요? 어떤 수수께끼였죠?",
  str_homestory_823101001_24_dialog_content = "별것 아니다. 역사 상식이나 신화, 그리고 몇 가지 수학 문제였다.",
  str_homestory_823101001_25_dialog_content = "그녀가 집에서 일주일 정도 책을 읽으면 쉽게 풀 수 있는 것이었지.",
  str_homestory_823101001_26_dialog_content = "왠지 이 이야기의 결말이 좋지 않을 것 같은데요...",
  str_homestory_823101001_27_dialog_content = "그것은 네 견해에 달려 있겠지. 그녀는 성공했고, 난 그 문제들이 그녀에게 어렵지 않다는 것을 알고 있었다.",
  str_homestory_823101001_28_dialog_content = "하지만 「보물」을 발견한 후, 어째서 그녀가 그토록 화를 냈는지는 도저히 이해할 수 없었지...",
  str_homestory_823101001_29_dialog_content = "일단 그것부터 먼저 물어볼게요. 대체 뭘 묻은 거죠?",
  str_homestory_823101001_30_dialog_content = "빅토리아가 가장 좋아하는 꿀이었다. 그해에 새로 채취한 꿀을 한 통 가득 담은 병이었지.",
  str_homestory_823101001_31_dialog_content = "그게 다라고요?!",
  str_homestory_823101001_32_dialog_content = "그것으로 부족한가? 《반항기 소녀를 대하는 법》에는 분명히 그렇게 쓰여 있었단 말이다.",
  str_homestory_823101001_33_dialog_content = "「그녀가 좋아하는 물건을 준비하라. 단 음식이라면 절대 틀릴 일이 없다.」",
  str_homestory_823101001_34_dialog_content = "대체 어디에 문제가 있었던 건지 모르겠군.",
  str_homestory_823101001_35_dialog_content = "그럼 왜 그냥 직접 꿀을 안 주신 건데요?!",
  str_homestory_823101001_36_dialog_content = "그녀가 내게 적의를 품고 있었다는 것을 잊었나?",
  str_homestory_823101001_37_dialog_content = "그녀와 서로 도발하는 것은 지루하지 않지만, 피곤할 것은 사실이다.",
  str_homestory_823101001_38_dialog_content = "다른 일로 그녀의 주의력을 분산시키는 것은 나쁘지 않은 선택이지.",
  str_homestory_823101001_39_dialog_content = "빅토리아 씨는 일주일이나 역사, 신화, 수학을 공부하고, 힘들게 생각도 하고, 기대에 차 있었는데...",
  str_homestory_823101001_40_dialog_content = "마지막으로 발견한 게 고작 꿀이라니, 마치 속은 걸 비웃는 느낌이잖아요...",
  str_homestory_823101001_41_dialog_content = "왜 빅토리아 씨가 화가 났었는지 아직도 모르겠어요?",
  str_homestory_823101001_42_dialog_content = "...확실히 네 말에도 일리가 있군.",
  str_homestory_823101001_43_dialog_content = "그렇다고 해서 가주 집회 때 내 의자 위에 몰래 꿀을 쏟아둘 필요는 없는 것 아니냐.",
  str_homestory_823101001_44_dialog_content = "그날 난 오전 내내 아무 일도 없는 척하며 앉아서 회의를 해야만 했다!",
  str_homestory_823101001_45_dialog_content = "이 문제는 어떻게 생각하지?",
  str_homestory_823101001_46_dialog_content = "자업자득이네요.",
  str_homestory_823101001_47_dialog_content = "인과응보네요.",
  str_homestory_823101001_48_dialog_content = "쳇..."
}
